/**
 * Dock-panel state slice — Phase 9-B.
 *
 * Every Phase 9 floating panel (Sat Catalog, Sat Detail, Panorama, Time
 * Machine, Camera Detail, Coverage, Triangulate) registers a DockId here.
 * Position / size / open-state / z-order persist to localStorage under
 * `akom:dock:v1`.
 *
 * Pattern follows src/store/entities.ts: pure helper functions over the
 * immutable DockState map, an initial slice constant, and an action
 * surface exposed on the main store. Persistence is wired by the host
 * after store creation via `bindDockPersistence(store)`.
 */

import type { StoreApi } from 'zustand';

export type DockId =
  | 'feed-inspector'
  | 'sat-catalog'
  | 'sat-detail'
  | 'panorama'
  | 'time-machine'
  | 'camera-detail'
  | 'coverage'
  | 'triangulate'
  | 'sitrep'
  | 'osint'
  | 'datasources'
  | 'scenario';

export interface DockPosition {
  /** Visible on screen? `false` = collapsed to the launcher pill. */
  open: boolean;
  /** Pixel x of the top-left corner. */
  x: number;
  /** Pixel y of the top-left corner. */
  y: number;
  /** Width in pixels. */
  w: number;
  /** Height in pixels. */
  h: number;
  /** Z-order index — higher = on top. */
  z: number;
}

export type DockState = Record<DockId, DockPosition>;

const STORAGE_KEY = 'akom:dock:v1';

/** Default positions — non-overlapping, sensible for 1920×1080+. */
const DEFAULTS: DockState = {
  'feed-inspector':  { open: false, x: 80,   y: 80,   w: 420, h: 320, z: 1 },
  'sat-catalog':     { open: false, x: 1200, y: 100,  w: 360, h: 520, z: 1 },
  'sat-detail':      { open: false, x: 1200, y: 640,  w: 360, h: 220, z: 1 },
  panorama:          { open: false, x: 540,  y: 120,  w: 640, h: 420, z: 1 },
  'time-machine':    { open: false, x: 580,  y: 160,  w: 640, h: 420, z: 1 },
  'camera-detail':   { open: false, x: 60,   y: 200,  w: 440, h: 360, z: 1 },
  coverage:          { open: false, x: 60,   y: 580,  w: 380, h: 220, z: 1 },
  triangulate:       { open: false, x: 460,  y: 580,  w: 380, h: 220, z: 1 },
  sitrep:            { open: false, x: 860,  y: 120,  w: 460, h: 540, z: 1 },
  osint:             { open: false, x: 100,  y: 120,  w: 460, h: 320, z: 1 },
  datasources:       { open: false, x: 480,  y: 80,   w: 400, h: 480, z: 1 },
  scenario:          { open: false, x: 980,  y: 120,  w: 420, h: 520, z: 1 },
};

export interface DockSliceState {
  dock: DockState;
  /** Highest z assigned so far — bringToFront mints `dockZTop + 1`. */
  dockZTop: number;
}

export const initialDockSlice: DockSliceState = (() => {
  const dock = loadFromStorage() ?? DEFAULTS;
  return { dock, dockZTop: highestZ(dock) };
})();

/* — Pure helpers (used by the store actions below) — */

export function setDockPosition(
  state: DockState,
  id: DockId,
  partial: Partial<DockPosition>,
): DockState {
  return { ...state, [id]: { ...state[id], ...partial } };
}

export function openDockHelper(
  state: DockState,
  zTop: number,
  id: DockId,
): { dock: DockState; dockZTop: number } {
  const newZ = zTop + 1;
  return {
    dock: { ...state, [id]: { ...state[id], open: true, z: newZ } },
    dockZTop: newZ,
  };
}

export function closeDockHelper(state: DockState, id: DockId): DockState {
  return { ...state, [id]: { ...state[id], open: false } };
}

export function toggleDockHelper(
  state: DockState,
  zTop: number,
  id: DockId,
): { dock: DockState; dockZTop: number } {
  return state[id].open
    ? { dock: closeDockHelper(state, id), dockZTop: zTop }
    : openDockHelper(state, zTop, id);
}

export function bringToFrontHelper(
  state: DockState,
  zTop: number,
  id: DockId,
): { dock: DockState; dockZTop: number } {
  const newZ = zTop + 1;
  return {
    dock: { ...state, [id]: { ...state[id], z: newZ } },
    dockZTop: newZ,
  };
}

export function resetDocksHelper(): { dock: DockState; dockZTop: number } {
  return { dock: { ...DEFAULTS }, dockZTop: highestZ(DEFAULTS) };
}

/* — Persistence — */

export function bindDockPersistence(
  store: StoreApi<{ dock: DockState }>,
): () => void {
  return store.subscribe((s) => {
    try {
      if (typeof localStorage === 'undefined') return;
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ dock: s.dock }));
    } catch {
      // Storage may be unavailable (private mode); silently degrade.
    }
  });
}

function loadFromStorage(): DockState | null {
  if (typeof localStorage === 'undefined') return null;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null || !('dock' in parsed)) {
      return null;
    }
    const stored = (parsed as { dock: Partial<DockState> }).dock;
    const merged: DockState = { ...DEFAULTS };
    for (const k of Object.keys(DEFAULTS) as DockId[]) {
      const cur = stored[k];
      if (cur && typeof cur === 'object') {
        merged[k] = { ...DEFAULTS[k], ...cur };
      }
    }
    return merged;
  } catch {
    return null;
  }
}

function highestZ(s: DockState): number {
  let z = 0;
  for (const id of Object.keys(s) as DockId[]) {
    if (s[id].z > z) z = s[id].z;
  }
  return z;
}

/* — Test/utility exports — */

export const DOCK_DEFAULTS = DEFAULTS;
export const DOCK_STORAGE_KEY = STORAGE_KEY;
