/**
 * DockLauncher — bottom-center floating pill strip showing all closed
 * docks as chip buttons. Click → reopens the dock at its last position.
 *
 * Hidden when every dock is open (or when no dock has been opened yet on
 * this user's first install).
 */

import { useMemo, type ReactNode } from 'react';
import { useStore } from '../../store';
import type { DockId } from '../../store/dock';

interface DockChip {
  readonly id: DockId;
  readonly label: string;
  readonly glyph: string;
}

/**
 * Display catalog for every dock. Glyphs are 1-2 ASCII chars (no emoji per
 * doctrine §4); labels are short Turkish or English per the cockpit's
 * existing convention.
 */
const CHIPS: ReadonlyArray<DockChip> = [
  { id: 'feed-inspector', label: 'BESLEME', glyph: 'BES' },
  { id: 'sat-catalog', label: 'UYDU KAT', glyph: 'SAT' },
  { id: 'sat-detail', label: 'UYDU DET', glyph: 'SAD' },
  { id: 'panorama', label: 'PANORAMA', glyph: 'PAN' },
  { id: 'time-machine', label: 'ZAMAN', glyph: 'ZAM' },
  { id: 'camera-detail', label: 'KAMERA', glyph: 'KAM' },
  { id: 'coverage', label: 'KAPSAMA', glyph: 'KAP' },
  { id: 'triangulate', label: 'TRIANG', glyph: 'TRI' },
  { id: 'sitrep', label: 'SITREP', glyph: 'SIT' },
  { id: 'osint', label: 'OSINT', glyph: 'OSI' },
  { id: 'datasources', label: 'KAYNAK', glyph: 'KAY' },
  { id: 'scenario', label: 'SENARYO', glyph: 'SEN' },
];

export function DockLauncher(): ReactNode {
  const dock = useStore((s) => s.dock);
  const openDock = useStore((s) => s.openDock);
  const setActiveTab = useStore((s) => s.setActiveTab);

  const closed = useMemo(() => CHIPS.filter((c) => !dock[c.id].open), [dock]);
  if (closed.length === 0) return null;

  return (
    <div className="dock-launcher" role="toolbar" aria-label="Closed docks">
      {closed.map((c) => (
        <button
          key={c.id}
          type="button"
          className="dock-launcher__chip"
          title={c.label}
          onClick={() => {
            // The sat docks mount only inside GlobeHost (the KÜRE tab), so
            // switch there first or they open invisibly on another tab.
            if (c.id === 'sat-catalog' || c.id === 'sat-detail') setActiveTab('kure');
            openDock(c.id);
          }}
        >
          <span className="dock-launcher__glyph">{c.glyph}</span>
          <span className="dock-launcher__label">{c.label}</span>
        </button>
      ))}
    </div>
  );
}
