/**
 * District damage choropleth (v10 P5 / E4).
 *
 * Tints Istanbul district polygons by scenario damage [0..1], green → klaxon.
 * Bottom-most map layer (pushed first), pickable:false so it never steals
 * clicks from units/cameras/incidents above it. Returns null when there is no
 * district geometry (district fetch blocked) — the scenario still runs.
 */
import { GeoJsonLayer } from '@deck.gl/layers';
import type { Layer } from '@deck.gl/core';
import type { FeatureCollection } from 'geojson';

const GREEN: [number, number, number] = [46, 204, 113];
const KLAXON: [number, number, number] = [230, 57, 70];

/** Lerp green→klaxon by damage; alpha grows with damage but stays <= 150. */
export function damageColor(d: number): [number, number, number, number] {
  const t = Math.max(0, Math.min(1, d));
  const r = Math.round(GREEN[0] + (KLAXON[0] - GREEN[0]) * t);
  const g = Math.round(GREEN[1] + (KLAXON[1] - GREEN[1]) * t);
  const b = Math.round(GREEN[2] + (KLAXON[2] - GREEN[2]) * t);
  const a = Math.round(Math.min(150, 30 + t * 120));
  return [r, g, b, a];
}

export function buildDistrictDamageLayer(opts: {
  districts: FeatureCollection | null;
  damage: Array<{ name: string; damage: number }>;
}): Layer | null {
  const { districts, damage } = opts;
  if (!districts || districts.features.length === 0) return null;
  const byName = new Map(damage.map((d) => [d.name, d.damage]));
  return new GeoJsonLayer({
    id: 'district-damage',
    data: districts,
    pickable: false,
    stroked: true,
    filled: true,
    getLineColor: [120, 130, 150, 90],
    lineWidthMinPixels: 1,
    getFillColor: (f: unknown) => {
      const name = String(
        (f as { properties?: { name?: unknown } }).properties?.name ?? '',
      );
      return damageColor(byName.get(name) ?? 0);
    },
    updateTriggers: { getFillColor: [byName] },
  });
}
