/**
 * Common feed runner — periodic poll with backoff, health reporting, and
 * AbortController hookup so React effects clean up cleanly.
 *
 * All feeds in src/feeds/ build on this pattern.
 */

import type { SourceTag } from '../types/entity';
import { useStore } from '../store';

export interface FeedSpec<T> {
  source: SourceTag;
  /** Polling cadence in ms. */
  intervalMs: number;
  /** Network or simulated fetch. Receives an AbortSignal. */
  fetch(signal: AbortSignal): Promise<T>;
  /** Apply the result into the entity store via the runner's handles. */
  apply(result: T): void;
  /** Optional: log decorator. */
  label?: string;
}

export interface FeedHandle {
  stop(): void;
}

export function startFeed<T>(spec: FeedSpec<T>): FeedHandle {
  let cancelled = false;
  const controller = new AbortController();
  let failureStreak = 0;

  const tick = async () => {
    if (cancelled) return;
    try {
      const result = await spec.fetch(controller.signal);
      if (cancelled) return;
      spec.apply(result);
      useStore.getState().markFeedTick(spec.source, true);
      failureStreak = 0;
    } catch (err) {
      if (cancelled) return;
      failureStreak += 1;
      useStore.getState().markFeedTick(spec.source, false);
      // Quiet first failure (network blip); log from second onward.
      if (failureStreak >= 2 && spec.label) {
        console.warn(`[feed:${spec.label}] failure streak=${failureStreak}`, err);
      }
    }
  };

  // Fire once immediately, then schedule.
  void tick();
  const id = window.setInterval(() => {
    // Simple linear backoff: 1× normal interval up to 5× on repeated failure.
    const backoff = Math.min(failureStreak, 5);
    if (backoff > 0 && Date.now() % spec.intervalMs > spec.intervalMs / (1 + backoff)) {
      return;
    }
    void tick();
  }, spec.intervalMs);

  return {
    stop() {
      cancelled = true;
      controller.abort();
      window.clearInterval(id);
    },
  };
}
