/**
 * Embedded live-camera feed for the OPS right sidebar (bottom slot).
 *
 * 2026-05-28 — replaced the prior VenuesPanel (concert-hall venue cards) with
 * a compact İBB camera picker.
 * 2026-05-30 — the iframe embed was retired (İBB blocks it via XFO + CSP, see
 * CctvFeed). The selected camera now renders a SIM-tagged preview with a
 * `CANLI ↗` link; the camera list filters off the OPS SearchBar query.
 *
 * Reacts to `selectedCameraId` so map-dot clicks change the previewed feed.
 */
import { useEffect, useMemo } from 'react';
import { ExternalLink, Radio } from 'lucide-react';
import { useStore } from '../store';
import { IBB_CAMERAS, IBB_KAMERALAR_URL } from '../feeds/ibb-mobese';
import { CctvFeed } from './cameras/CctvFeed';
import { SourceChip } from '../lib/sourceTag';

export function CameraFeedPanel() {
  const selectedId = useStore((s) => s.selectedCameraId);
  const selectCamera = useStore((s) => s.selectCamera);
  const query = useStore((s) => s.searchQuery).trim().toLowerCase();
  const cameras = IBB_CAMERAS;

  // Default-select the first camera the moment the panel mounts so the
  // operator sees a preview without having to click anything.
  useEffect(() => {
    if (!selectedId && cameras.length > 0) {
      selectCamera(cameras[0]!.id);
    }
  }, [selectedId, cameras, selectCamera]);

  const active = useMemo(
    () => cameras.find((c) => c.id === selectedId) ?? cameras[0]!,
    [cameras, selectedId],
  );

  const filtered = useMemo(() => {
    if (!query) return cameras;
    return cameras.filter(
      (c) =>
        c.name.toLowerCase().includes(query) || c.district.toLowerCase().includes(query),
    );
  }, [cameras, query]);

  return (
    <section className="ops-panel ops-panel--camera glass-panel glass-panel--deep">
      <div className="ops-panel__title">
        <Radio size={12} style={{ verticalAlign: '-2px', marginRight: 6 }} />
        Canlı Kamera &middot; İBB
        <a
          href={IBB_KAMERALAR_URL}
          target="_blank"
          rel="noopener noreferrer"
          className="ops-panel__title-link"
          title="İBB tüm kameralar dizini"
        >
          TÜMÜ ↗
        </a>
      </div>

      <div className="camera-feed">
        <CctvFeed camera={active} />

        <div className="camera-feed__meta">
          <div className="camera-feed__name">{active.name}</div>
          <div className="camera-feed__sub">
            <span>{active.district}</span>
            <span>·</span>
            <span>{active.type}</span>
            <span
              style={{
                marginLeft: 'auto',
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
              }}
            >
              <SourceChip source="SIM" />
              <a
                href={active.pageUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="camera-feed__open"
                title="Yeni sekmede aç"
                aria-label="Yeni sekmede aç"
              >
                <ExternalLink size={11} />
              </a>
            </span>
          </div>
        </div>

        <ul className="camera-feed__list" role="listbox" aria-label="Kamera seç">
          {filtered.map((c) => (
            <li key={c.id}>
              <button
                type="button"
                role="option"
                aria-selected={c.id === active.id}
                data-active={c.id === active.id || undefined}
                className="camera-feed__list-row"
                onClick={() => selectCamera(c.id)}
              >
                <span className="camera-feed__list-name">{c.name}</span>
                <span className="camera-feed__list-district">{c.district}</span>
              </button>
            </li>
          ))}
          {filtered.length === 0 && (
            <li>
              <div className="camera-feed__empty">Eşleşen kamera yok</div>
            </li>
          )}
        </ul>
      </div>
    </section>
  );
}
