/**
 * CctvFeed — the 16:9 camera preview tile, reused by the OPS sidebar
 * (CameraFeedPanel) and the multi-sensor Feed Inspector dock.
 *
 * Honesty note (2026-05-30): İBB live CCTV cannot play in a browser today —
 * `istanbuluseyret.ibb.gov.tr/{slug}/` is `X-Frame-Options: SAMEORIGIN` +
 * CSP `frame-ancestors 'self'` (iframe blocked), and the public HLS hosts
 * either 404 (`livestream.ibb.gov.tr`) or are unreachable (`hls.ibb.gov.tr`).
 * So the DEFAULT state is an honest, SIM-tagged synthetic preview plus a
 * `CANLI ↗` link that opens the real İBB page in a new tab.
 *
 * hls.js stays wired behind an on-demand "CANLI DENE" button: in a Tauri
 * shell (which bypasses browser CORS) or once a valid manifest URL is
 * supplied, a click plays the real stream with zero further code changes.
 */
import Hls from 'hls.js';
import { useEffect, useRef, useState } from 'react';
import { ExternalLink } from 'lucide-react';
import type { MobeseCamera } from '../../feeds/ibb-mobese';
import { useCameraMedia, cameraMediaUrl } from '../../lib/cameraMedia';

type CctvStatus = 'sim' | 'connecting' | 'live' | 'failed';

function captureLabel(iso?: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleString('tr-TR', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function hostOf(url: string): string {
  try {
    return new URL(url).host;
  } catch {
    return url;
  }
}

export function CctvFeed({ camera }: { camera: MobeseCamera }) {
  const [status, setStatus] = useState<CctvStatus>('sim');
  const [clock, setClock] = useState(() => new Date().toLocaleTimeString('tr-TR'));
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const hlsRef = useRef<Hls | null>(null);

  // Tear down any live attempt and reset to SIM whenever the camera changes.
  useEffect(() => {
    setStatus('sim');
    return () => teardown();
  }, [camera.id]);

  // 1 s clock for the overlay timestamp — sells the "feed" read.
  useEffect(() => {
    const id = window.setInterval(
      () => setClock(new Date().toLocaleTimeString('tr-TR')),
      1000,
    );
    return () => window.clearInterval(id);
  }, []);

  function teardown() {
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }
    const v = videoRef.current;
    if (v) {
      v.pause();
      v.removeAttribute('src');
      v.load();
    }
  }

  function attempt(url: string, isMirror: boolean) {
    const video = videoRef.current;
    if (!video) return;
    // Native HLS (Safari / some Chromium).
    if (video.canPlayType('application/vnd.apple.mpegurl')) {
      video.src = url;
      video.play().then(() => setStatus('live')).catch(() => onFatal(isMirror));
      return;
    }
    // hls.js (Chrome / Firefox / Tauri WebView2).
    if (Hls.isSupported()) {
      const hls = new Hls({ manifestLoadingTimeOut: 8000, manifestLoadingMaxRetry: 0 });
      hlsRef.current = hls;
      hls.loadSource(url);
      hls.attachMedia(video);
      hls.on(Hls.Events.MANIFEST_PARSED, () => {
        setStatus('live');
        void video.play().catch(() => {});
      });
      hls.on(Hls.Events.ERROR, (_evt, data) => {
        if (data.fatal) {
          hls.destroy();
          hlsRef.current = null;
          onFatal(isMirror);
        }
      });
    } else {
      setStatus('failed');
    }
  }

  function onFatal(wasMirror: boolean) {
    if (!wasMirror) attempt(camera.streamMirror, true);
    else setStatus('failed');
  }

  function tryLive() {
    setStatus('connecting');
    // The <video> is only mounted once status leaves 'sim'; defer a frame so
    // the ref is populated before we attach hls.js.
    requestAnimationFrame(() => attempt(camera.streamUrl, false));
  }

  const media = useCameraMedia();
  const rec = media[camera.id];
  const isStandIn = rec?.provenance === 'stand-in';

  const showVideo = status === 'live' || status === 'connecting';
  const simLabel = rec ? (isStandIn ? '● TEMSİLİ' : '● KAYIT') : '● SİM';
  const recLabel =
    status === 'live' ? '● CANLI' : status === 'connecting' ? '● BAĞLANIYOR' : simLabel;

  return (
    <div className="cctv camera-feed__media" data-status={status}>
      {showVideo ? (
        <video ref={videoRef} className="cctv__video" muted playsInline autoPlay />
      ) : rec ? (
        rec.clip ? (
          <video
            className="cctv__rec-media"
            src={cameraMediaUrl(rec.clip)}
            poster={cameraMediaUrl(rec.image)}
            muted
            playsInline
            autoPlay
            loop
          />
        ) : (
          <img
            className="cctv__rec-media"
            src={cameraMediaUrl(rec.image)}
            alt={`${camera.name} — kayıtlı kare`}
            loading="lazy"
          />
        )
      ) : (
        <div className="cctv__sim" aria-hidden="true">
          <span className="cctv__sim-bg" />
          <span className="cctv__sim-scan" />
          <span className="cctv__sim-shape cctv__sim-shape--a" />
          <span className="cctv__sim-shape cctv__sim-shape--b" />
          <span className="cctv__sim-shape cctv__sim-shape--c" />
        </div>
      )}

      {status === 'connecting' && (
        <div className="cctv__overlay">
          <span className="cctv__overlay-title">HLS bağlanıyor…</span>
          <span className="cctv__overlay-sub">{hostOf(camera.streamUrl)}</span>
        </div>
      )}
      {status === 'failed' && (
        <div className="cctv__overlay">
          <span className="cctv__overlay-title">Tarayıcıda yayın alınamadı</span>
          <span className="cctv__overlay-sub">
            İBB · X-Frame / CORS — masaüstü (Tauri) kabuğu gerekir
          </span>
          <a
            className="cctv__canli"
            href={camera.pageUrl}
            target="_blank"
            rel="noopener noreferrer"
          >
            <ExternalLink size={12} /> {camera.name} · CANLI
          </a>
        </div>
      )}

      <span className="cctv__rec" data-status={status}>
        {recLabel}
      </span>
      <span className="cctv__ts">
        {camera.id} · {clock}
      </span>

      {status === 'sim' && rec && (
        <span className="cctv__rec-note" title={rec.sourceUrl ?? undefined}>
          {isStandIn ? 'TEMSİLİ GÖRSEL' : 'KAYITLI ÖRNEK'}
          {rec.capturedAt ? ` · ${captureLabel(rec.capturedAt)}` : ''}
        </span>
      )}

      {status === 'sim' && (
        <div className="cctv__controls">
          <button type="button" className="cctv__try" onClick={tryLive}>
            CANLI DENE
          </button>
          <a
            className="cctv__canli"
            href={camera.pageUrl}
            target="_blank"
            rel="noopener noreferrer"
          >
            CANLI ↗
          </a>
        </div>
      )}
    </div>
  );
}
