/**
 * Minimal HLS m3u8 parser — Phase 9 Leap Step 6.
 *
 * Parses just enough of the IBB-flavored playlist to drive an MSE pump:
 *   - #EXT-X-TARGETDURATION (max segment duration in seconds)
 *   - #EXT-X-MEDIA-SEQUENCE (starting media sequence number)
 *   - #EXTINF:duration[,title] before each segment URI
 *   - segment URIs (.ts or .m4s)
 *
 * Resolves relative URIs against the manifest URL.
 *
 * Why hand-rolled: hls.js is ~70 KB gz. We only need the manifest fields for
 * the Tauri pump; the segments feed MSE directly. Defending the bundle.
 */

export interface HlsSegment {
  /** Duration in seconds. */
  duration: number;
  /** Resolved absolute URL. */
  url: string;
  /** Media sequence number. */
  sequence: number;
}

export interface HlsManifest {
  targetDuration: number;
  mediaSequence: number;
  segments: HlsSegment[];
  /** true if this is a "live" playlist (no #EXT-X-ENDLIST). */
  isLive: boolean;
}

export function parseM3U8(text: string, manifestUrl: string): HlsManifest {
  const lines = text.split(/\r?\n/);
  let targetDuration = 0;
  let mediaSequence = 0;
  let isLive = true;
  const segments: HlsSegment[] = [];
  let pendingDuration: number | null = null;
  let seqCursor = 0;

  for (const raw of lines) {
    const line = raw.trim();
    if (line.length === 0) continue;
    if (line.startsWith('#EXT-X-TARGETDURATION:')) {
      targetDuration = parseFloat(line.slice('#EXT-X-TARGETDURATION:'.length)) || 0;
    } else if (line.startsWith('#EXT-X-MEDIA-SEQUENCE:')) {
      mediaSequence = parseInt(line.slice('#EXT-X-MEDIA-SEQUENCE:'.length), 10) || 0;
      seqCursor = mediaSequence;
    } else if (line.startsWith('#EXTINF:')) {
      const after = line.slice('#EXTINF:'.length);
      const comma = after.indexOf(',');
      pendingDuration = parseFloat(comma >= 0 ? after.slice(0, comma) : after) || 0;
    } else if (line === '#EXT-X-ENDLIST') {
      isLive = false;
    } else if (!line.startsWith('#')) {
      // Segment URI line.
      const url = resolveRelative(manifestUrl, line);
      segments.push({
        duration: pendingDuration ?? 0,
        url,
        sequence: seqCursor++,
      });
      pendingDuration = null;
    }
  }

  return { targetDuration, mediaSequence, segments, isLive };
}

function resolveRelative(base: string, uri: string): string {
  try {
    return new URL(uri, base).toString();
  } catch {
    return uri;
  }
}
