/**
 * Road-graph snapshot loader.
 *
 * Reads /public/data/road-graph.json (baked by scripts/build-road-graph.mjs
 * from the IBB CKAN emergency-road + main-artery datasets) and hands the raw
 * graph to src/sim/RoadGraph.ts for routing.
 *
 * Memoized per page lifetime. Returns null on failure so the patrol engine
 * can fall back to legacy beat-loop movement.
 */

export interface RoadGraphData {
  generated: string;
  source: string;
  nodeCount: number;
  edgeCount: number;
  /** Flat [lng0, lat0, lng1, lat1, ...]. */
  nodes: number[];
  /** Flat [a0, b0, w0(m), a1, b1, w1, ...] — undirected edges. */
  edges: number[];
  /** Indices (into edges/3) that came from the emergency-road set. */
  emergency: number[];
  /** Connectivity metadata emitted by the stitching pass (optional). */
  components?: number;
  largestComponent?: number;
  stitchedEdges?: number[];
  snapM?: number;
}

let cached: RoadGraphData | null = null;
let inFlight: Promise<RoadGraphData | null> | null = null;

export async function loadRoadGraph(): Promise<RoadGraphData | null> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = (async () => {
    try {
      const base = import.meta.env.BASE_URL || '/';
      const res = await fetch(`${base}data/road-graph.json`);
      if (!res.ok) return null;
      const data = (await res.json()) as RoadGraphData;
      if (!data.nodes?.length || !data.edges?.length) return null;
      cached = data;
      return cached;
    } catch {
      return null;
    } finally {
      inFlight = null;
    }
  })();
  return inFlight;
}
