/**
 * Blind-spot complement layer — Phase 9 Leap Step 2.
 *
 * Renders the polygon-with-hole produced by the coverage Worker (bbox outer
 * ring + covered-union as hole). Fill is red-faint so the operator's eye
 * jumps to uncovered area.
 *
 * Note: Phase A uses a bbox proxy for "mahalle boundaries" — Session 2 will
 * replace with the real mahalle FeatureCollection per doctrine §6.4.
 */
import { GeoJsonLayer } from '@deck.gl/layers';
import type { FeatureCollection } from 'geojson';

export interface BlindSpotLayerOpts {
  data: FeatureCollection;
  opacity?: number;
}

export function buildBlindSpotLayer(opts: BlindSpotLayerOpts): GeoJsonLayer | null {
  if (opts.data.features.length === 0) return null;
  const opacity = opts.opacity ?? 0.3;
  return new GeoJsonLayer({
    id: 'fov-blind-spots',
    data: opts.data,
    getFillColor: [220, 38, 38, Math.floor(255 * opacity)],
    getLineColor: [220, 38, 38, 180],
    getLineWidth: 1,
    lineWidthUnits: 'pixels',
    stroked: true,
    filled: true,
    pickable: false,
  });
}
