/**
 * Building-occluded viewshed layer — the lit ground polygon a single selected
 * camera actually sees, with streets shadowed by buildings left dark.
 *
 * This is the deck.gl adapter over src/lib/viewshed.ts (pure geometry, unit-
 * tested). It runs for ONE camera at a time — the one in the detail dock — so
 * the per-ray building scan stays cheap. The lit fill is warm; everything the
 * camera cannot see is simply not drawn (the dark basemap shows through),
 * matching the CCTV-centre reference snapshots.
 *
 * Cadence: `computeViewshedDatum` is the expensive part (per-ray building
 * scan) — the caller memoises it on camera-id / bearing / building-set so it
 * does NOT run per animation frame. `buildViewshedLayer` over the precomputed
 * ring is cheap and can run inside the layer list.
 */
import { PolygonLayer } from '@deck.gl/layers';
import { computeViewshed, type ViewshedObstacle } from '../../lib/viewshed';
import { lensProfileFromName } from '../../lib/fov';
import type { PtzCamera } from '../../types/ptz';
import type { BuildingFeature } from './buildings3dLayer';

export interface ViewshedDatum {
  camId: number;
  polygon: Array<[number, number]>;
}

/**
 * Collect the building footprints whose bounding box falls within `rFarM`
 * metres of the camera, as viewshed obstacles. Cheap lng/lat box test before
 * the per-ray scan does the precise work.
 */
function nearbyObstacles(
  cam: PtzCamera,
  buildings: ReadonlyArray<BuildingFeature>,
  rFarM: number,
): ViewshedObstacle[] {
  const mPerDegLat = (Math.PI / 180) * 6378137;
  const mPerDegLng = mPerDegLat * Math.cos(cam.lat * (Math.PI / 180));
  const dLat = rFarM / mPerDegLat;
  const dLng = rFarM / mPerDegLng;
  const minLng = cam.lng - dLng;
  const maxLng = cam.lng + dLng;
  const minLat = cam.lat - dLat;
  const maxLat = cam.lat + dLat;

  const out: ViewshedObstacle[] = [];
  for (const b of buildings) {
    const ring = b.geometry.coordinates[0] as Array<[number, number]>;
    if (!ring || ring.length < 3) continue;
    let hit = false;
    for (const [lng, lat] of ring) {
      if (lng >= minLng && lng <= maxLng && lat >= minLat && lat <= maxLat) {
        hit = true;
        break;
      }
    }
    if (!hit) continue;
    out.push({ ring, heightM: b.properties.height_m });
  }
  return out;
}

/**
 * Compute the lit-viewshed ring for one selected camera. Expensive (per-ray
 * building scan) — memoise on `[camId, bearingDeg, buildings]`. Returns `null`
 * when there's no camera. With no nearby buildings the polygon degenerates to
 * the plain FOV sector (computeViewshed handles that).
 */
export function computeViewshedDatum(
  camera: PtzCamera | null,
  bearingDeg: number,
  buildings: ReadonlyArray<BuildingFeature>,
): ViewshedDatum | null {
  if (!camera) return null;
  const lens = lensProfileFromName(camera.name);
  const obstacles = nearbyObstacles(camera, buildings, lens.rFarDefault);
  const polygon = computeViewshed(
    {
      lat: camera.lat,
      lng: camera.lng,
      bearingDeg,
      hfovDeg: lens.hfovDeg,
      rFarM: lens.rFarDefault,
    },
    obstacles,
  );
  return { camId: camera.id, polygon };
}

/**
 * Build the lit-viewshed PolygonLayer from a precomputed datum. Cheap — safe to
 * call inside the per-frame layer list.
 */
export function buildViewshedLayer(
  datum: ViewshedDatum | null,
  opacity = 1.0,
): PolygonLayer<ViewshedDatum> | null {
  if (!datum) return null;
  return new PolygonLayer<ViewshedDatum>({
    id: 'viewshed-lit',
    data: [datum],
    getPolygon: (d) => d.polygon,
    // Warm amber lit area — what the camera genuinely sees on the ground.
    getFillColor: [250, 204, 21, Math.floor(120 * opacity)],
    getLineColor: [250, 204, 21, 235],
    getLineWidth: 1.6,
    lineWidthUnits: 'pixels',
    stroked: true,
    filled: true,
    pickable: false,
    updateTriggers: {
      getPolygon: datum.camId,
      getFillColor: opacity,
    },
  });
}
