import { ScatterplotLayer, IconLayer } from '@deck.gl/layers';
import type { UnitState } from '../../types/venue';
import { getSpriteAtlas } from '../../lib/symbology';
import type { SpriteId } from '../../lib/symbology';
import { realSymbolForUnit, type RealSymbolAtlas } from '../../lib/realSymbols';

const MODALITY_COLOR: Record<UnitState['modality'], [number, number, number]> = {
  ground: [255, 176, 0],
  heli: [255, 220, 110],
  fixed: [200, 180, 255],
  naval: [107, 182, 255],
};

/** Map unit type strings to geometric-atlas sprite IDs (fallback path). */
const TYPE_SPRITE: Record<string, SpriteId> = {
  AMB: 'amb',
  POL: 'pol',
  ITFK: 'fire',
  SAR: 'sar',
  UAV: 'uav',
  HEMS: 'hems',
  K9: 'k9',
  UMKE: 'amb',
  TEDAS: 'fire',
  AFAD: 'sar',
};

function unitSprite(type: string): SpriteId {
  return TYPE_SPRITE[type] ?? 'pol';
}

interface PatrolsArgs {
  data: UnitState[];
  selectedId?: string | null;
  onClick?: (id: string) => void;
  /** Fires on hover with the unit id and screen coords. */
  onHover?: (h: { unitId: string; x: number; y: number } | null) => void;
  /**
   * Composited real-symbol atlas (ambulance / police / fire / SAR / heli /
   * plane / HAZMAT / AFAD). When provided, units render with the project's
   * vector symbol set on a high-contrast disc. Falls back to the geometric
   * canvas atlas while this is still loading (or in test envs).
   */
  realSprites?: RealSymbolAtlas | null;
}

export function buildPatrolsLayer({
  data,
  selectedId = null,
  onClick,
  onHover,
  realSprites = null,
}: PatrolsArgs): (ScatterplotLayer<UnitState> | IconLayer<UnitState>)[] {
  const useReal = !!realSprites;
  const { atlas, mapping } = useReal
    ? { atlas: realSprites!.atlas, mapping: realSprites!.mapping }
    : getSpriteAtlas();

  // Modality-coloured ring framing each unit — bigger + brighter than before so
  // units read clearly against satellite imagery and dense road networks.
  const ringRadius = useReal ? 21 : 14;
  const halo = new ScatterplotLayer<UnitState>({
    id: 'patrols-halo',
    data,
    pickable: false,
    stroked: true,
    filled: true,
    radiusUnits: 'pixels',
    lineWidthUnits: 'pixels',
    getPosition: (u) => [u.lon, u.lat],
    getRadius: (u) => (selectedId === u.id ? ringRadius + 4 : ringRadius),
    getLineWidth: (u) => (selectedId === u.id ? 3 : 2),
    getLineColor: (u) => {
      const c = MODALITY_COLOR[u.modality] ?? [255, 176, 0];
      return selectedId === u.id ? [255, 255, 255, 255] : [c[0], c[1], c[2], 235];
    },
    getFillColor: (u) => {
      const c = MODALITY_COLOR[u.modality] ?? [255, 176, 0];
      return [c[0], c[1], c[2], 60];
    },
    updateTriggers: {
      getPosition: data,
      getRadius: [selectedId],
      getLineColor: [selectedId],
      getLineWidth: [selectedId],
    },
  });

  const iconSize = useReal ? 38 : 24;
  const icons = new IconLayer<UnitState>({
    id: 'patrols-icons',
    data,
    pickable: true,
    iconAtlas: atlas,
    iconMapping: mapping,
    getIcon: (u) => (useReal ? realSymbolForUnit(u.type, u.modality) : unitSprite(u.type)),
    getPosition: (u) => [u.lon, u.lat],
    getSize: (u) => (selectedId === u.id ? iconSize + 6 : iconSize),
    sizeUnits: 'pixels',
    // Real symbols carry their own colour (mask:false) — leave them untinted.
    // The geometric fallback atlas IS tinted by modality colour.
    getColor: (u) => {
      if (useReal) return [255, 255, 255, 255];
      const c = MODALITY_COLOR[u.modality] ?? [255, 176, 0];
      return selectedId === u.id ? [255, 255, 255, 255] : [c[0], c[1], c[2], 255];
    },
    onClick: (info) => {
      const id = info.object?.id;
      if (id) onClick?.(id);
    },
    onHover: onHover
      ? (info) => {
          if (info.object) {
            onHover({ unitId: info.object.id, x: info.x, y: info.y });
          } else {
            onHover(null);
          }
        }
      : undefined,
    updateTriggers: {
      getPosition: data,
      getIcon: [useReal],
      getColor: [selectedId, useReal],
      getSize: [selectedId],
    },
  });

  return [halo, icons];
}
