/**
 * Camera demo-media loader.
 *
 * Reads `public/data/camera-media/manifest.json` (produced out-of-band by the
 * hermes acquisition pass) and exposes recorded still frames / short clips per
 * camera id. The browser cannot pull İBB streams live (X-Frame + CSP + CORS),
 * so these are server-side captures served as static files — clearly labelled
 * as recorded samples in the UI, never as a live feed.
 *
 * Degrades cleanly: if the manifest is absent (404) the map and tiles keep
 * their current SIM behaviour, so this is safe to ship before the media lands.
 */
import { useEffect, useState } from 'react';
import { dataUrl } from './paths';

export type CameraMediaProvenance = 'live-frame' | 'page-poster' | 'stand-in';

export interface CameraMediaItem {
  name: string;
  /** Filename of the still image, relative to the camera-media folder. */
  image: string;
  /** Optional short clip filename. */
  clip?: string;
  /** ISO timestamp of capture. */
  capturedAt?: string;
  provenance?: CameraMediaProvenance;
  sourceUrl?: string;
  note?: string;
}

interface CameraMediaManifest {
  generated?: string;
  generator?: string;
  items: Record<string, CameraMediaItem>;
}

export type CameraMediaMap = Record<string, CameraMediaItem>;

/** Resolve a media filename to a base-path-safe URL. */
export function cameraMediaUrl(file: string): string {
  return dataUrl(`camera-media/${file}`);
}

let cached: CameraMediaMap | null = null;
let inFlight: Promise<CameraMediaMap> | null = null;

/** Load (once) the camera-media manifest. Returns an empty map on any failure. */
export async function loadCameraMedia(): Promise<CameraMediaMap> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = (async () => {
    try {
      const res = await fetch(cameraMediaUrl('manifest.json'));
      if (!res.ok) {
        cached = {};
        return cached;
      }
      const data = (await res.json()) as CameraMediaManifest;
      cached = data && typeof data.items === 'object' && data.items ? data.items : {};
      return cached;
    } catch {
      cached = {};
      return cached;
    } finally {
      inFlight = null;
    }
  })();
  return inFlight;
}

/** React hook — loads the manifest once and returns the id→item map. */
export function useCameraMedia(): CameraMediaMap {
  const [map, setMap] = useState<CameraMediaMap>(() => cached ?? {});
  useEffect(() => {
    let alive = true;
    void loadCameraMedia().then((m) => {
      if (alive) setMap(m);
    });
    return () => {
      alive = false;
    };
  }, []);
  return map;
}
