/**
 * Deterministic Mw 7.5 Marmara earthquake scenario (v10 P5).
 *
 * Pure class — no React, no DOM (PatrolEngine style). ALL randomness is
 * consumed at construction (per-district soil factors via a seeded hash, and
 * the infrastructure-failure pick), so `tick(simMs)` is a pure threshold
 * crossing: replayable, scrub-safe, and identical for identical seeds.
 *
 * Timeline (sim ms): 0 quake · 5 000 damage ready · 30 000 surge ·
 * 90 000 dispatch wave · 150 000 cascade · 300 000 steady state.
 */
import type { FeatureCollection, Geometry } from 'geojson';

export type ScenarioEventKind =
  | 'quake'
  | 'damage-ready'
  | 'surge'
  | 'dispatch'
  | 'cascade'
  | 'steady';

export interface ScenarioEvent {
  kind: ScenarioEventKind;
  simMs: number;
}

export type ScenarioPhase =
  | 'pre'
  | 'quake'
  | 'damage'
  | 'surge'
  | 'dispatch'
  | 'cascade'
  | 'steady';

export interface DistrictDamage {
  name: string;
  damage: number;
}

interface DistrictRec {
  name: string;
  centroid: [number, number];
  soil: number;
}

interface ScenarioOptions {
  seed?: number;
  epicenter?: [number, number];
  mw?: number;
}

const THRESHOLDS: ReadonlyArray<[ScenarioEventKind, number]> = [
  ['quake', 0],
  ['damage-ready', 5_000],
  ['surge', 30_000],
  ['dispatch', 90_000],
  ['cascade', 150_000],
  ['steady', 300_000],
];

const SURGE_MS = 30_000;
const DISPATCH_MS = 90_000;
const CASCADE_MS = 150_000;
const STEADY_MS = 300_000;

// Distance-attenuation constants (visual-spread tuned, EST-chipped at the UI).
const ATTEN_A = 1.0; // peak damage factor at the epicentre
const ATTEN_B = 22; // km e-folding falloff scale

// Distribution nodes the quake can knock out (real ids from the utilities feed).
const INFRA_CANDIDATES = [
  'TRAFO-A',
  'TRAFO-B',
  'TRAFO-C',
  'TRAFO-D',
  'RMS-W',
  'RMS-C',
  'RMS-E',
  'POMP-W',
  'POMP-E',
  'DEPO-W',
  'DEPO-E',
  'BTS-W',
  'BTS-C',
  'BTS-E',
];

const EARTH_R_KM = 6371;
function haversineKm(aLng: number, aLat: number, bLng: number, bLat: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(bLat - aLat);
  const dLng = toRad(bLng - aLng);
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_R_KM * Math.asin(Math.min(1, Math.sqrt(s)));
}

/** Deterministic [0,1) hash of a string under a seed (FNV-ish). */
function hash01(s: string, seed: number): number {
  let h = seed >>> 0;
  for (let i = 0; i < s.length; i++) {
    h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  }
  return h / 4294967296;
}

function clamp01(x: number): number {
  return Math.max(0, Math.min(1, x));
}

export class ScenarioEngine {
  private readonly seed: number;
  private readonly epicenter: [number, number];
  readonly mw: number;
  private districts: DistrictRec[] = [];
  private readonly infraDown: string[];
  private lastSimMs = -1;

  constructor(opts: ScenarioOptions = {}) {
    this.seed = opts.seed ?? 1907;
    this.epicenter = opts.epicenter ?? [28.95, 40.81];
    this.mw = opts.mw ?? 7.5;
    // Construction-time infra pick: deterministic subset of the candidates.
    this.infraDown = INFRA_CANDIDATES.filter(
      (id) => hash01(id, this.seed ^ 0x9e3779b9) < 0.6,
    );
  }

  setDistricts(fc: FeatureCollection | null): void {
    if (!fc) {
      this.districts = [];
      return;
    }
    this.districts = fc.features.map((f) => {
      const name = String((f.properties as { name?: unknown } | null)?.name ?? 'Bilinmeyen');
      return {
        name,
        centroid: centroidOf(f.geometry),
        soil: 0.6 + hash01(name, this.seed) * 0.7, // [0.6, 1.3]
      };
    });
  }

  /** Events newly crossed since the previous tick. */
  tick(simMs: number): ScenarioEvent[] {
    const out: ScenarioEvent[] = [];
    for (const [kind, threshold] of THRESHOLDS) {
      if (this.lastSimMs < threshold && simMs >= threshold) {
        out.push({ kind, simMs });
      }
    }
    this.lastSimMs = simMs;
    return out;
  }

  phaseAt(simMs: number): ScenarioPhase {
    if (simMs >= STEADY_MS) return 'steady';
    if (simMs >= CASCADE_MS) return 'cascade';
    if (simMs >= DISPATCH_MS) return 'dispatch';
    if (simMs >= SURGE_MS) return 'surge';
    if (simMs >= 5_000) return 'damage';
    if (simMs >= 0) return 'quake';
    return 'pre';
  }

  damageByDistrict(): DistrictDamage[] {
    return this.districts.map((d) => {
      const distKm = haversineKm(this.epicenter[0], this.epicenter[1], d.centroid[0], d.centroid[1]);
      const base = ATTEN_A * Math.exp(-distKm / ATTEN_B);
      return { name: d.name, damage: clamp01(base * d.soil) };
    });
  }

  surgeMultiplier(simMs: number): number {
    if (simMs < SURGE_MS) return 1;
    const t = (simMs - SURGE_MS) / 1000; // seconds since surge began
    const peak = 8;
    const floor = 3;
    if (t < 20) return 1 + (peak - 1) * (t / 20);
    return Math.max(floor, peak - (peak - floor) * Math.min(1, (t - 20) / 120));
  }

  /** Centroids of the top-6 most-damaged districts (emitted once at dispatch). */
  dispatchTargets(): Array<{ lng: number; lat: number }> {
    return [...this.damageByDistrict()]
      .sort((a, b) => b.damage - a.damage)
      .slice(0, 6)
      .map((d) => {
        const rec = this.districts.find((r) => r.name === d.name)!;
        return { lng: rec.centroid[0], lat: rec.centroid[1] };
      });
  }

  /** Distribution node ids that go down at cascade (chosen at construction). */
  infraFailures(): string[] {
    return this.infraDown;
  }

  reset(): void {
    this.lastSimMs = -1;
  }
}

/** Rough centroid: mean of the first polygon's exterior ring. */
function centroidOf(geom: Geometry): [number, number] {
  let ring: number[][] = [];
  if (geom.type === 'Polygon') ring = geom.coordinates[0] ?? [];
  else if (geom.type === 'MultiPolygon') ring = geom.coordinates[0]?.[0] ?? [];
  if (ring.length === 0) return [28.95, 41.0];
  let sx = 0;
  let sy = 0;
  for (const p of ring) {
    sx += p[0]!;
    sy += p[1]!;
  }
  return [sx / ring.length, sy / ring.length];
}
