/**
 * CANLI İHBAR · OLAY AKIŞI — live incident + citizen report feed for the
 * OPS tab. Ticks new rows every few seconds, driven by a local interval.
 *
 * Each row: 2525D symbol chip, color-coded type chip, district, Turkish
 * report line, source tag, status badge. Click selects + fly-to on the map.
 * Pulsing "● CANLI" indicator. Respects prefers-reduced-motion.
 */
import { useEffect, useMemo, useState, useRef } from 'react';
import { useStore } from '../store';
import type { IncidentFeature } from '../types/venue';
import { spriteHref, resolveSprite, spriteColor } from '../lib/symbology';
import type { SourceTag } from '../types/entity';

/** Tuple shape for a report template: [label, category, rgb, sprite, reports]. */
type ReportTemplate = [string, string, [number, number, number], ReturnType<typeof resolveSprite>, string[]];

/* ── Simulated İhbar generator ── */

interface IhbarRow {
  id: string;
  ts: number;
  /** 2525D sprite id for type chip */
  sprite: ReturnType<typeof resolveSprite>;
  /** RGB triple for the type chip */
  rgb: [number, number, number];
  /** Turkish type label */
  typeLabel: string;
  /** İstanbul district */
  district: string;
  /** Turkish report line */
  report: string;
  /** Source tag */
  source: SourceTag;
  /** Status step */
  status: 'YENİ' | 'ATANDI' | 'MÜDAHALE' | 'TAMAMLANDI';
  /** Lng/lat for map fly-to */
  lng: number;
  lat: number;
  /** Linked incident id if matched */
  incidentId?: string;
}

const DISTRICTS = [
  'Fatih', 'Beyoğlu', 'Kadıköy', 'Üsküdar', 'Beşiktaş', 'Şişli',
  'Bakırköy', 'Zeytinburnu', 'Eyüp', 'Sarıyer', 'Maltepe', 'Pendik',
  'Kartal', 'Tuzla', 'Bağcılar', 'Bahçelievler', 'Esenler', 'Avcılar',
];

const REPORT_TEMPLATES: ReportTemplate[] = [
  ['Çöküntü', 'collapse', [230, 57, 70], 'fire', ['Bina çökme ihbarı alındı — enkaz altında tahmini 5-10 kişi', 'Apartman kısmı çökme — komşular mahsur kalanlar olduğunu bildirdi', 'Okul binasında kısmı çökme — tahliye başlatıldı']],
  ['Yangın', 'fire', [255, 138, 0], 'fire', ['Sanayi bölgesinde yangın çıktı — itfaiye sevk edildi', 'Orman yangını — rüzgar nedeniyle yayılıyor', 'Konut yangını — 3 katlı bina etkilendi']],
  ['Sel', 'flood', [107, 182, 255], 'fire', ['Dere taştı — alt geçit su altında kaldı', 'Şiddetli yağış sonrası cadde göle döndü', 'Bodrum katları su bastı — tahliye gerekli']],
  ['Gaz Kaçağı', 'leak', [255, 220, 100], 'fire', ['Doğalgaz kaçağı ihbarı — bölge tahliye ediliyor', 'Patlama riski — cadde trafiğe kapatıldı', 'Kanalizasyondan gaz kokusu geliyor']],
  ['HAZMAT', 'hazmat', [200, 180, 255], 'fire', ['Kimyasal sızıntı — AFAD ekipleri bölgede', 'Sanayi kazası — tehlikeli madde yayılımı', 'Tanker devrildi — HAZMAT protokolü başlatıldı']],
];

const SOURCE_TAGS: SourceTag[] = ['İHBAR-112' as SourceTag, 'MOBESE' as SourceTag, 'AFAD' as SourceTag, 'KRDAE' as SourceTag, 'CV' as SourceTag];

function randomFrom<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)]!;
}

function randomAroundIstanbul(): [number, number] {
  return [
    28.5 + Math.random() * 1.2,
    40.8 + Math.random() * 0.5,
  ];
}

let _seq = 0;
function generateIhbar(incidents: IncidentFeature[]): IhbarRow {
  const tmpl = randomFrom(REPORT_TEMPLATES);
  const [typeLabel, , rgb, sprite] = tmpl;
  const report = randomFrom(tmpl[4]);
  const district = randomFrom(DISTRICTS);
  const source = randomFrom(SOURCE_TAGS);
  const statuses: IhbarRow['status'][] = ['YENİ', 'ATANDI', 'MÜDAHALE'];
  const [lng, lat] = randomAroundIstanbul();

  // 30% chance to link to an existing incident
  const linkedIncident = Math.random() < 0.3 ? randomFrom(incidents) : undefined;

  return {
    id: `ihbar-${Date.now()}-${++_seq}`,
    ts: Date.now(),
    sprite,
    rgb,
    typeLabel,
    district,
    report,
    source,
    status: randomFrom(statuses),
    lng,
    lat,
    incidentId: linkedIncident?.properties.id,
  };
}

/* ── Component ── */

const TICK_MS = 3500;

export function IhbarFeed(): React.ReactNode {
  const incidents = useStore((s) => s.incidents);
  const selectIncident = useStore((s) => s.selectIncident);
  const setFlyTarget = useStore((s) => s.setFlyTarget);
  const reducedMotion = useStore((s) => s.reducedMotion);

  const [rows, setRows] = useState<IhbarRow[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Bootstrap with a few initial rows
  const booted = useRef(false);
  useEffect(() => {
    if (booted.current) return;
    booted.current = true;
    const initial: IhbarRow[] = [];
    for (let i = 0; i < 6; i++) {
      initial.push(generateIhbar(incidents));
    }
    setRows(initial);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Tick new rows
  useEffect(() => {
    const intervalMs = reducedMotion ? 8000 : TICK_MS;
    const id = window.setInterval(() => {
      setRows((prev) => {
        const next = [generateIhbar(incidents), ...prev];
        // Keep last 50 rows
        if (next.length > 50) next.length = 50;
        return next;
      });
    }, intervalMs);
    return () => window.clearInterval(id);
  }, [reducedMotion, incidents]);

  const handleClick = (row: IhbarRow) => {
    if (row.incidentId) {
      selectIncident(row.incidentId);
    }
    setFlyTarget({ lng: row.lng, lat: row.lat, zoom: 14 });
  };

  const rowsToShow = useMemo(() => rows.slice(0, 20), [rows]);

  return (
    <section
      className="ops-panel glass-panel glass-panel--deep ihbar-feed"
      data-testid="ihbar-feed"
      style={{ maxHeight: 420, display: 'flex', flexDirection: 'column' }}
    >
      {/* Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '8px 10px',
          borderBottom: '1px solid rgba(56,189,248,0.18)',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <span
            className={reducedMotion ? '' : 'ihbar-live-dot'}
            style={{
              width: 8,
              height: 8,
              borderRadius: '50%',
              background: '#22c55e',
              display: 'inline-block',
            }}
          />
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: 11,
              fontWeight: 700,
              letterSpacing: '0.08em',
              color: '#22c55e',
            }}
          >
            CANLI İHBAR · OLAY AKIŞI
          </span>
        </div>
        <span
          style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 9,
            color: '#64748b',
            letterSpacing: '0.05em',
          }}
        >
          {rows.length} kayıt · simüle
        </span>
      </div>

      {/* Rows */}
      <div ref={scrollRef} style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden' }}>
        {rowsToShow.length === 0 && (
          <div style={{ padding: 12, color: 'var(--bone-faint)', fontSize: 'var(--t-tiny)', textAlign: 'center' }}>
            İhbar akışı başlatılıyor...
          </div>
        )}
        {rowsToShow.map((row) => (
          <div
            key={row.id}
            data-testid="ihbar-row"
            className="incident-row glass-panel glass-panel--card glass-panel--interactive"
            style={{
              cursor: 'pointer',
              padding: '5px 8px',
              margin: '2px 4px',
              borderRadius: 4,
              borderLeft: `3px solid rgb(${row.rgb[0]}, ${row.rgb[1]}, ${row.rgb[2]})`,
              fontSize: 'var(--t-tiny)',
              display: 'grid',
              gridTemplateColumns: 'auto 1fr auto auto',
              gap: 6,
              alignItems: 'center',
            }}
            onClick={() => handleClick(row)}
          >
            {/* 2525D symbol */}
            <svg
              width={18}
              height={14}
              style={{ color: spriteColor('friend', 'operational'), flex: '0 0 auto' }}
            >
              <use href={spriteHref(row.sprite)} />
            </svg>

            {/* Type chip + report */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 5, minWidth: 0 }}>
              <span
                style={{
                  background: `rgb(${row.rgb[0]}, ${row.rgb[1]}, ${row.rgb[2]})`,
                  color: '#fff',
                  padding: '1px 5px',
                  borderRadius: 3,
                  fontSize: 9,
                  fontWeight: 600,
                  letterSpacing: '0.04em',
                  whiteSpace: 'nowrap',
                  flex: '0 0 auto',
                }}
              >
                {row.typeLabel}
              </span>
              <span style={{ color: '#94a3b8', fontSize: 9, whiteSpace: 'nowrap', flex: '0 0 auto' }}>
                {row.district}
              </span>
              <span style={{ color: '#cbd5e1', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', fontSize: 10 }}>
                {row.report}
              </span>
            </div>

            {/* Source tag */}
            <span
              style={{
                color: '#64748b',
                fontSize: 8,
                letterSpacing: '0.04em',
                whiteSpace: 'nowrap',
              }}
            >
              {row.source}
            </span>

            {/* Status badge */}
            <span
              style={{
                color:
                  row.status === 'YENİ'
                    ? '#22c55e'
                    : row.status === 'ATANDI'
                      ? '#fbbf24'
                      : '#ef4444',
                fontSize: 9,
                fontWeight: 600,
                letterSpacing: '0.04em',
                whiteSpace: 'nowrap',
              }}
            >
              {row.status}
            </span>
          </div>
        ))}
      </div>

      {/* CSS animation for the live dot */}
      <style>{`
        .ihbar-live-dot {
          animation: ihbar-pulse 1.6s ease-in-out infinite;
        }
        @keyframes ihbar-pulse {
          0%, 100% { opacity: 1; box-shadow: 0 0 4px rgba(34,197,94,0.6); }
          50% { opacity: 0.35; box-shadow: 0 0 0px rgba(34,197,94,0); }
        }
        @media (prefers-reduced-motion: reduce) {
          .ihbar-live-dot { animation: none; opacity: 1; }
        }
      `}</style>
    </section>
  );
}
