/**
 * Camera detail dock — Phase 9 Leap Step 2.
 *
 * Renders when the operator clicks a PTZ FOV cone in the GÖRÜ map view.
 * Session 1 ships:
 *   - 3-preset JPEG carousel (snapshot URLs from the camera registry)
 *   - FOV inspector (HFOV / bearing / rFar / confidence / phase)
 *
 * Session 1 Step 6 adds Tauri-only branch:
 *   - In Tauri desktop builds, renders <video> with MediaSource + reqwest
 *     stream for live HLS playback. Web builds keep the JPEG carousel.
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { useStore } from '../../store';
import { DockPanel } from '../dock/DockPanel';
import { loadPtzCameras } from '../../feeds/ptz';
import { lensProfileFromName } from '../../lib/fov';
import { isTauri, fetchManifest } from '../../lib/hls/tauriHls';
import type { PtzCamera } from '../../types/ptz';

export interface CameraDetailContext {
  camId: number;
  preset: 0 | 1 | 2;
  bearingDeg: number;
  confidence: number;
  phase: 'A' | 'B' | 'C' | 'SIM';
}

interface Props {
  context: CameraDetailContext | null;
}

export function CameraDetailDock({ context }: Props): ReactNode {
  const dock = useStore((s) => s.dock['camera-detail']);
  const closeDock = useStore((s) => s.closeDock);
  const [cam, setCam] = useState<PtzCamera | null>(null);
  const [activePreset, setActivePreset] = useState<0 | 1 | 2>(0);
  const [hlsUrl, setHlsUrl] = useState<string | null>(null);
  const [hlsErr, setHlsErr] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  useEffect(() => {
    if (!context) {
      setCam(null);
      return;
    }
    setActivePreset(context.preset);
    void loadPtzCameras().then((cams) => {
      const found = cams.find((c) => c.id === context.camId) ?? null;
      setCam(found);
    });
  }, [context]);

  // Tauri path: try the HLS pipeline. Browsers without native HLS support
  // (Chromium-based, which is what WebView2 uses) require hls.js or MSE
  // transmuxing — Session 2 wire-up. Session 1 attempts direct <video src>
  // and falls back to JPEG carousel on error.
  useEffect(() => {
    if (!cam || !isTauri()) {
      setHlsUrl(null);
      return;
    }
    let cancelled = false;
    void (async () => {
      try {
        const manifest = await fetchManifest(cam.id);
        if (cancelled) return;
        if (!manifest || manifest.segments.length === 0) {
          setHlsErr('No live manifest');
          return;
        }
        // Native <video src=manifestUrl> works if the WebView supports HLS.
        // Chromium WebView2 doesn't natively; we'd need hls.js. Session 2.
        // For Session 1, expose the manifest URL — the operator can hit it
        // externally if needed.
        setHlsUrl(manifest.segments[0]!.url);
        setHlsErr(null);
      } catch (err) {
        setHlsErr((err as Error).message);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [cam]);

  if (!dock.open) return null;

  // Opened from the launcher with no camera selected: show guidance instead
  // of stranding an empty invisible panel.
  if (!context || !cam) {
    return (
      <DockPanel id="camera-detail" title="PTZ Kamera">
        <div className="camera-detail camera-detail--empty" style={{ color: 'var(--ink-mute)', padding: 12 }}>
          Haritada bir kamera seçin
        </div>
      </DockPanel>
    );
  }

  const lens = lensProfileFromName(cam.name);
  const snapshotUrl = cam.snapshotUrls[activePreset];
  const tauriMode = isTauri();

  return (
    <DockPanel id="camera-detail" title={`PTZ · ${cam.name}`}>
      <div className="camera-detail">
        <div className="camera-detail__media">
          {tauriMode && hlsUrl && !hlsErr ? (
            <video
              ref={videoRef}
              controls
              autoPlay
              muted
              playsInline
              onError={() => setHlsErr('Native HLS playback failed; use Session 2 hls.js path')}
            >
              <source src={hlsUrl} type="application/vnd.apple.mpegurl" />
            </video>
          ) : snapshotUrl ? (
            <img
              src={snapshotUrl}
              alt={`${cam.name} preset ${activePreset}`}
              loading="lazy"
              onError={(e) => {
                (e.currentTarget as HTMLImageElement).style.display = 'none';
              }}
            />
          ) : (
            <div className="camera-detail__media-empty">snapshot unavailable</div>
          )}
        </div>
        {tauriMode && hlsErr && (
          <div className="camera-detail__hls-warn">
            HLS: {hlsErr} · using JPEG fallback (Session 2 adds hls.js MSE pump)
          </div>
        )}
        <div className="camera-detail__presets" role="tablist" aria-label="Preset">
          {[0, 1, 2].map((p) => (
            <button
              key={p}
              type="button"
              role="tab"
              aria-selected={activePreset === p}
              data-active={activePreset === p || undefined}
              onClick={() => setActivePreset(p as 0 | 1 | 2)}
              className="camera-detail__preset-btn"
            >
              P{p}
            </button>
          ))}
        </div>
        <dl className="camera-detail__inspector">
          <dt>HFOV</dt>
          <dd>{lens.hfovDeg.toFixed(0)}°</dd>
          <dt>Range</dt>
          <dd>{lens.rFarDefault} m</dd>
          <dt>Bearing</dt>
          <dd>{context.bearingDeg.toFixed(1)}°</dd>
          <dt>Phase</dt>
          <dd>{context.phase}</dd>
          <dt>Confidence</dt>
          <dd>{(context.confidence * 100).toFixed(0)}%</dd>
          <dt>Lens</dt>
          <dd>{lens.type}</dd>
          <dt>Cam ID</dt>
          <dd>{cam.id}</dd>
          <dt>Group</dt>
          <dd>{cam.groupId}</dd>
        </dl>
        <button
          type="button"
          className="camera-detail__close"
          onClick={() => closeDock('camera-detail')}
        >
          KAPAT
        </button>
      </div>
    </DockPanel>
  );
}
