/**
 * Resolve a path under public/ that survives the production base path.
 * Vite injects import.meta.env.BASE_URL ('/' in dev, '/akom-cockpit-live/' in
 * the GitHub Pages build), so prefixing it keeps every asset fetch correct in
 * both environments.
 */
export function assetUrl(relative: string): string {
  const base = import.meta.env.BASE_URL || '/';
  const cleanRelative = relative.startsWith('/') ? relative.slice(1) : relative;
  return `${base}${cleanRelative}`;
}

/**
 * Resolve a path under public/data/ that survives the production base path.
 * Mirrors the pattern in src/feeds/roadGraph.ts.
 */
export function dataUrl(relative: string): string {
  const cleanRelative = relative.startsWith('/') ? relative.slice(1) : relative;
  return assetUrl(`data/${cleanRelative}`);
}
