/**
 * Theme mode registry — dual-skin switcher (v10 P2).
 *
 *  • pristine — the current pristine-white chrome (default).
 *  • tactical — amber-on-black command palette (design brief), selected at
 *               runtime via data-theme='tactical' on <html>.
 *
 * Mirrors the proven src/map/basemap.ts pattern: a mode union, a storage key,
 * loadThemeMode, bindThemePersistence. applyThemeToDom flips the
 * documentElement attribute + the theme-color meta. Persistence:
 * localStorage under key `akom:theme:v1`.
 */
import type { StoreApi } from 'zustand';

export type ThemeMode = 'pristine' | 'tactical';
export const THEME_MODES: ReadonlyArray<ThemeMode> = ['pristine', 'tactical'];
export const THEME_STORAGE_KEY = 'akom:theme:v1';

const THEME_COLOR: Record<ThemeMode, string> = {
  pristine: '#ffffff',
  tactical: '#0a0e13',
};

/** The basemap mode that visually pairs with each theme (names align by design). */
export function pairedBasemap(mode: ThemeMode): 'pristine' | 'tactical' {
  return mode === 'tactical' ? 'tactical' : 'pristine';
}

export function loadThemeMode(fallback: ThemeMode = 'pristine'): ThemeMode {
  if (typeof localStorage === 'undefined') return fallback;
  try {
    const raw = localStorage.getItem(THEME_STORAGE_KEY);
    if (!raw) return fallback;
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && 'mode' in parsed) {
      const m = (parsed as { mode: unknown }).mode;
      if (m === 'pristine' || m === 'tactical') return m;
    }
  } catch {
    // Corrupted storage; fall back silently.
  }
  return fallback;
}

export function applyThemeToDom(mode: ThemeMode): void {
  if (typeof document === 'undefined') return;
  if (mode === 'pristine') delete document.documentElement.dataset.theme;
  else document.documentElement.dataset.theme = mode;
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', THEME_COLOR[mode]);
}

export function bindThemePersistence(
  store: StoreApi<{ themeMode: ThemeMode }>,
): () => void {
  return store.subscribe((s) => {
    try {
      if (typeof localStorage === 'undefined') return;
      localStorage.setItem(THEME_STORAGE_KEY, JSON.stringify({ mode: s.themeMode }));
    } catch {
      // Silently degrade.
    }
  });
}
