/**
 * Tab 02 — GÖRÜ Görüntüleme.
 *
 * Phase 9 Leap Step 2 — four-mode toolbar:
 *   TILES        — existing 26-tile MOBESE tourism grid (default)
 *   COVERAGE     — map view with 632 PTZ FOV cones + coverage union
 *   BLIND-SPOTS  — map view with blind-spot complement overlay
 *   REDUNDANCY   — map view with per-cell cone-count heatmap
 *
 * In all non-TILES modes, this tab renders the cockpit's MapHost behind a
 * floating toolbar. The fovLayer + coverage worker + GeoJsonLayers are
 * mounted from MapHost (driven by `goruntuMode` + `activeTab` selectors).
 */
import { useEffect, useMemo, useState } from 'react';
import { IBB_CAMERAS, IBB_KAMERALAR_URL, type MobeseCamera } from '../../feeds/ibb-mobese';
import { useStore, type GoruntuMode } from '../../store';
import { CameraTile } from '../cameras/CameraTile';
import { MapHost } from '../../map/MapHost';
import type { UnitState } from '../../types/venue';

interface GoruntulemeProps {
  unitSnapshot?: UnitState[];
  pulseT?: number;
}

interface ModeButton {
  id: GoruntuMode;
  label: string;
  hint: string;
}

const MODES: ReadonlyArray<ModeButton> = [
  { id: 'tiles', label: 'TILES', hint: '26 MOBESE turist kamerası tile grid' },
  { id: 'coverage', label: 'COVERAGE', hint: '632 PTZ FOV birleşim örtüsü' },
  { id: 'blind-spots', label: 'BLIND-SPOTS', hint: 'Kapsanmamış alan tamamlayıcı' },
  { id: 'redundancy', label: 'REDUNDANCY', hint: 'Kamera çakışma sayısı ısı haritası' },
];

export function Goruntuleme({ unitSnapshot = [], pulseT = 0 }: GoruntulemeProps) {
  const mode = useStore((s) => s.goruntuMode);
  const setMode = useStore((s) => s.setGoruntuMode);

  if (mode !== 'tiles') {
    return (
      <section className="hud-pane hud-pane--map">
        <div className="map-host">
          <MapHost unitSnapshot={unitSnapshot} pulseT={pulseT} />
          <GoruntuToolbar mode={mode} setMode={setMode} variant="floating" />
        </div>
      </section>
    );
  }

  return <TilesView mode={mode} setMode={setMode} />;
}

function TilesView({ mode, setMode }: { mode: GoruntuMode; setMode: (m: GoruntuMode) => void }) {
  const cameras = IBB_CAMERAS;
  const selectedId = useStore((s) => s.selectedCameraId);
  const selectCamera = useStore((s) => s.selectCamera);
  const [filter, setFilter] = useState<string>('');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), 5000);
    return () => window.clearInterval(id);
  }, []);

  const filtered = useMemo(() => {
    const q = filter.trim().toLowerCase();
    if (!q) return cameras;
    return cameras.filter(
      (c) =>
        c.name.toLowerCase().includes(q) ||
        c.district.toLowerCase().includes(q) ||
        c.type.toLowerCase().includes(q),
    );
  }, [cameras, filter]);

  return (
    <div className="hud-pane goruntuleme-tab">
      <header className="goruntuleme-toolbar glass-panel glass-panel--float">
        <span className="goruntuleme-toolbar__title">GÖRÜ · İBB MOBESE</span>
        <span className="goruntuleme-toolbar__sub">{cameras.length} kamera</span>
        <span className="goruntuleme-toolbar__spacer" />
        <ModeButtons mode={mode} setMode={setMode} compact />
        <span className="goruntuleme-toolbar__chip">SİM ÖNİZLEME · {cameras.length}</span>
        <input
          type="search"
          className="goruntuleme-toolbar__search"
          placeholder="İlçe veya kamera ara…"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
        />
        <a
          href={IBB_KAMERALAR_URL}
          target="_blank"
          rel="noopener noreferrer"
          className="goruntuleme-toolbar__all"
          title="İBB tüm canlı kamera dizinini yeni sekmede aç"
        >
          TÜM KAMERALAR ↗
        </a>
      </header>
      <div className="goruntuleme-grid">
        {filtered.map((cam: MobeseCamera) => (
          <CameraTile
            key={cam.id}
            camera={cam}
            selected={selectedId === cam.id}
            lastFrameTs={-1}
            now={now}
            onSelect={() => selectCamera(cam.id)}
          />
        ))}
      </div>
    </div>
  );
}

function GoruntuToolbar({
  mode,
  setMode,
  variant,
}: {
  mode: GoruntuMode;
  setMode: (m: GoruntuMode) => void;
  variant: 'floating' | 'inline';
}) {
  return (
    <header
      className={
        variant === 'floating'
          ? 'goruntuleme-toolbar goruntuleme-toolbar--floating glass-panel glass-panel--float'
          : 'goruntuleme-toolbar glass-panel glass-panel--float'
      }
    >
      <span className="goruntuleme-toolbar__title">GÖRÜ · 632 PTZ</span>
      <span className="goruntuleme-toolbar__sub">{MODES.find((m) => m.id === mode)?.hint ?? ''}</span>
      <span className="goruntuleme-toolbar__spacer" />
      <ModeButtons mode={mode} setMode={setMode} />
    </header>
  );
}

function ModeButtons({
  mode,
  setMode,
  compact = false,
}: {
  mode: GoruntuMode;
  setMode: (m: GoruntuMode) => void;
  compact?: boolean;
}) {
  return (
    <div className="goruntuleme-modes" role="tablist" aria-label="GÖRÜ mode">
      {MODES.map((m) => (
        <button
          key={m.id}
          type="button"
          role="tab"
          aria-selected={mode === m.id}
          data-active={mode === m.id || undefined}
          onClick={() => setMode(m.id)}
          title={m.hint}
          className="goruntuleme-modes__btn"
        >
          {compact ? m.label.slice(0, 4) : m.label}
        </button>
      ))}
    </div>
  );
}
