/**
 * IBB hosted style URL. MapLibre will fetch the style.json + tiles directly.
 * If IBB is offline the basemap renders empty until the operator switches
 * back — no fallback wiring at this layer (graceful degradation handled by
 * the BasemapSwitcher click handler).
 */
const IBB_STYLE_URL = 'https://basemap.ibb.gov.tr/static/rehber_altlik.json';

export function styleFor(mode: BasemapMode): StyleSpecification | string {
  switch (mode) {
    case 'tactical':
      return tacticalStyle();
    case 'pristine':
      return pristineStyle();
    case 'ibb-official':
      return IBB_STYLE_URL;
    case 'satellite':
      return satelliteStyle();
  }
}

/* — Persistence — */

const STORAGE_KEY = 'akom:basemap:v1';

export function loadBasemapMode(fallback: BasemapMode = 'pristine'): BasemapMode {
  if (typeof localStorage === 'undefined') return fallback;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return fallback;
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && 'mode' in parsed) {
      const m = (parsed as { mode: unknown }).mode;
      if (m === 'tactical' || m === 'pristine' || m === 'ibb-official' || m === 'satellite') return m;
    }
  } catch {
    // Storage corrupted; fall back silently.
  }
  return fallback;
}

export function bindBasemapPersistence(
  store: StoreApi<{ basemapMode: BasemapMode }>,
): () => void {
  return store.subscribe((s) => {
    try {
      if (typeof localStorage === 'undefined') return;
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ mode: s.basemapMode }));
    } catch {
      // Silently degrade.
    }
  });
}

/** Cycle helper for keyboard shortcut: tactical → pristine → ibb-official → tactical */
export function cycleBasemap(mode: BasemapMode, forward = true): BasemapMode {
  const idx = BASEMAP_MODES.indexOf(mode);
  const next = forward ? (idx + 1) % BASEMAP_MODES.length : (idx + BASEMAP_MODES.length - 1) % BASEMAP_MODES.length;
  return BASEMAP_MODES[next]!;
}

export const BASEMAP_STORAGE_KEY = STORAGE_KEY;
