/**
 * Instant, seamless camera hover preview — Phase 2 (spatial-intelligence).
 *
 * A single persistent portal that NEVER remounts. When the operator hovers a
 * 3D camera body on the map, the store's `hoveredCamera` updates and this
 * component swaps a pooled <img> to the camera's pre-decoded snapshot — so the
 * frame appears with zero network/decode latency. All preset-0 snapshots are
 * preloaded into an in-memory cache during browser idle time.
 *
 * Positioning is transform-only (no layout thrash); the card is clamped to the
 * viewport and offset from the cursor.
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { useStore } from '../../store';
import { loadPtzCameras } from '../../feeds/ptz';
import { findCameraById, type MobeseCamera } from '../../feeds/ibb-mobese';
import type { PtzCamera } from '../../types/ptz';

const CARD_W = 280;
const CARD_H = 188;
const OFFSET = 18;

/** Module-level decode cache: camId → decoded <img> (survives remounts). */
const decoded = new Map<number, HTMLImageElement>();

function preloadAll(cams: ReadonlyArray<PtzCamera>): void {
  type IdleWindow = Window & {
    requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => void;
  };
  const w = window as IdleWindow;
  let i = 0;
  const step = () => {
    const budgetEnd = performance.now() + 8;
    while (i < cams.length && performance.now() < budgetEnd) {
      const cam = cams[i++]!;
      const url = cam.snapshotUrls[0];
      if (url && !decoded.has(cam.id)) {
        const img = new Image();
        img.decoding = 'async';
        img.src = url;
        decoded.set(cam.id, img);
      }
    }
    if (i < cams.length) {
      if (typeof w.requestIdleCallback === 'function') w.requestIdleCallback(step, { timeout: 2000 });
      else setTimeout(step, 200);
    }
  };
  if (typeof w.requestIdleCallback === 'function') w.requestIdleCallback(step, { timeout: 2000 });
  else setTimeout(step, 400);
}

export function CameraHoverPreview() {
  const hovered = useStore((s) => s.hoveredCamera);
  const [ptzIndex, setPtzIndex] = useState<Map<number, PtzCamera>>(new Map());
  const imgRef = useRef<HTMLImageElement | null>(null);
  const [broken, setBroken] = useState(false);
  const [mobeseCam, setMobeseCam] = useState<MobeseCamera | null>(null);

  // Load PTZ registry once, build id→camera index, kick off idle preloading.
  useEffect(() => {
    let cancelled = false;
    void loadPtzCameras().then((cams) => {
      if (cancelled) return;
      setPtzIndex(new Map(cams.map((c) => [c.id, c])));
      preloadAll(cams);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // Resolve camId to either a PTZ camera (numeric) or MOBESE camera (string slug).
  const camId = hovered?.camId;
  const camIdNum = typeof camId === 'number' ? camId : undefined;
  const camIdStr = typeof camId === 'string' ? camId : undefined;

  const ptzCam = camIdNum !== undefined ? (ptzIndex.get(camIdNum) ?? null) : null;

  // Look up MOBESE camera when we have a string id.
  useEffect(() => {
    if (!camIdStr) {
      setMobeseCam(null);
      return;
    }
    const found = findCameraById(camIdStr);
    setMobeseCam(found ?? null);
  }, [camIdStr]);

  const snapshotUrl = ptzCam?.snapshotUrls[0];
  const cam = ptzCam;

  // Swap the pooled <img> src instantly from the decode cache (or the URL).
  useEffect(() => {
    setBroken(false);
    const el = imgRef.current;
    if (!el || !snapshotUrl) return;
    const cached = cam ? decoded.get(cam.id) : undefined;
    el.src = cached?.src ?? snapshotUrl;
  }, [cam, snapshotUrl]);

  const pos = useMemo(() => {
    if (!hovered) return null;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let x = hovered.x + OFFSET;
    let y = hovered.y + OFFSET;
    if (x + CARD_W > vw) x = hovered.x - CARD_W - OFFSET;
    if (y + CARD_H > vh) y = vh - CARD_H - 8;
    if (y < 8) y = 8;
    return { x: Math.max(8, x), y };
  }, [hovered]);

  // Visible when we have either a PTZ camera with snapshot or a MOBESE camera.
  const visible = !!(hovered && pos && (ptzCam || mobeseCam));

  return (
    <div
      role="tooltip"
      aria-hidden={!visible}
      style={{
        position: 'fixed',
        left: 0,
        top: 0,
        width: CARD_W,
        zIndex: 1400,
        pointerEvents: 'none',
        transform: pos ? `translate(${pos.x}px, ${pos.y}px)` : 'translate(-9999px,-9999px)',
        opacity: visible ? 1 : 0,
        transition: 'opacity 90ms ease-out',
        willChange: 'transform, opacity',
        background: 'rgba(8, 13, 22, 0.92)',
        border: '1px solid rgba(56, 189, 248, 0.55)',
        borderRadius: 6,
        boxShadow: '0 8px 28px rgba(0,0,0,0.55)',
        overflow: 'hidden',
        fontFamily: 'var(--font-mono, monospace)',
      }}
    >
      <div
        style={{
          width: CARD_W,
          height: CARD_H,
          background: '#05080d',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {broken || !snapshotUrl ? (
          <span style={{ color: '#64748b', fontSize: 11, letterSpacing: '0.08em' }}>
            ÖNİZLEME YOK
          </span>
        ) : (
          <img
            ref={imgRef}
            alt=""
            decoding="async"
            onError={() => setBroken(true)}
            style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
          />
        )}
      </div>
      <div
        style={{
          padding: '5px 8px',
          fontSize: 10.5,
          letterSpacing: '0.06em',
          color: '#cbd5e1',
          display: 'flex',
          justifyContent: 'space-between',
          gap: 8,
          borderTop: '1px solid rgba(56,189,248,0.25)',
        }}
      >
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {cam?.name ?? mobeseCam?.name ?? ''}
        </span>
        <span style={{ color: '#38bdf8', flex: '0 0 auto' }}>
          #{typeof camId === 'number' ? camId : camIdStr ?? ''}
        </span>
      </div>
    </div>
  );
}
