/**
 * TriangulateDock — dock slot 'triangulate', title "Kestirme / DOA".
 *
 * Two observer rows (lat / lng / bearing), defaulting to Şişli. KESTİR solves
 * the two-bearing direction-of-arrival fix via triangulateTwoCams; the result
 * renders in a mono block, and HARİTADA GÖSTER flies the map to the fix.
 */
import { useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { triangulateTwoCams, type DoaInput, type DoaFix } from '../../lib/geo/doa';

interface ObserverState {
  lat: number;
  lng: number;
  bearingDeg: number;
}

const DEFAULT_A: ObserverState = { lat: 41.0598, lng: 28.9883, bearingDeg: 120 };
const DEFAULT_B: ObserverState = { lat: 41.0598, lng: 28.9883, bearingDeg: 210 };

function ObserverRow({
  label,
  value,
  onChange,
}: {
  label: string;
  value: ObserverState;
  onChange: (next: ObserverState) => void;
}) {
  const field = (key: keyof ObserverState, step: number) => (
    <label style={{ display: 'flex', flexDirection: 'column', fontSize: 10, color: 'var(--ink-mute)' }}>
      {key === 'bearingDeg' ? 'yön°' : key}
      <input
        type="number"
        step={step}
        value={value[key]}
        onChange={(e) => onChange({ ...value, [key]: Number(e.target.value) })}
        style={{
          width: 72,
          fontFamily: 'var(--font-mono)',
          fontSize: 11,
          background: 'var(--bg-panel-soft)',
          color: 'var(--ink-strong)',
          border: '1px solid var(--bg-rule)',
          padding: '2px 4px',
        }}
      />
    </label>
  );
  return (
    <div style={{ marginBottom: 8 }}>
      <div style={{ fontSize: 11, color: 'var(--ink-strong)', marginBottom: 2 }}>{label}</div>
      <div style={{ display: 'flex', gap: 6 }}>
        {field('lat', 0.0001)}
        {field('lng', 0.0001)}
        {field('bearingDeg', 1)}
      </div>
    </div>
  );
}

export function TriangulateDock(): ReactNode {
  const dock = useStore((s) => s.dock['triangulate']);
  const setFlyTarget = useStore((s) => s.setFlyTarget);
  const [obsA, setObsA] = useState<ObserverState>(DEFAULT_A);
  const [obsB, setObsB] = useState<ObserverState>(DEFAULT_B);
  const [fix, setFix] = useState<DoaFix | null>(null);
  const [solved, setSolved] = useState(false);

  if (!dock.open) return null;

  const solve = () => {
    const a: DoaInput = obsA;
    const b: DoaInput = obsB;
    setFix(triangulateTwoCams(a, b));
    setSolved(true);
  };

  return (
    <DockPanel id="triangulate" title="Kestirme / DOA">
      <div className="triangulate-dock">
        <ObserverRow label="GÖZLEMCİ A" value={obsA} onChange={setObsA} />
        <ObserverRow label="GÖZLEMCİ B" value={obsB} onChange={setObsB} />
        <button
          type="button"
          onClick={solve}
          style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 11,
            background: 'var(--accent)',
            color: 'var(--bg-void)',
            border: 'none',
            padding: '4px 10px',
            cursor: 'pointer',
          }}
        >
          KESTİR
        </button>
        {solved && (
          <div style={{ marginTop: 8 }}>
            {fix ? (
              <>
                <pre
                  style={{
                    fontFamily: 'var(--font-mono)',
                    fontSize: 11,
                    color: 'var(--ink-strong)',
                    background: 'var(--bg-panel-soft)',
                    padding: 6,
                    margin: 0,
                    whiteSpace: 'pre-wrap',
                  }}
                >
                  {`lat ${fix.lat.toFixed(5)}\nlng ${fix.lng.toFixed(5)}\nA ${Math.round(fix.distAm)} m · B ${Math.round(fix.distBm)} m\n± ${Math.round(fix.uncertaintyM)} m`}
                </pre>
                <button
                  type="button"
                  onClick={() => setFlyTarget({ lng: fix.lng, lat: fix.lat, zoom: 14 })}
                  style={{
                    marginTop: 6,
                    fontFamily: 'var(--font-mono)',
                    fontSize: 11,
                    background: 'var(--bg-panel-soft)',
                    color: 'var(--ink-mid)',
                    border: '1px solid var(--bg-rule)',
                    padding: '4px 10px',
                    cursor: 'pointer',
                  }}
                >
                  HARİTADA GÖSTER
                </button>
              </>
            ) : (
              <div style={{ fontSize: 11, color: 'var(--klaxon)' }}>
                Kesişim yok (paralel veya çok uzak)
              </div>
            )}
          </div>
        )}
      </div>
    </DockPanel>
  );
}
