import { useEffect, useMemo, useRef, useState } from 'react';
import type { Map as MapLibreMap } from 'maplibre-gl';
import type { Layer } from '@deck.gl/core';
import { createMap, flyToVenue } from './mapController';
import { DeckOverlay } from './deckOverlay';
import { buildVenuesLayer } from './layers/venuesLayer';
import { buildBufferLayer } from './layers/bufferLayer';
import { buildHeliPadsLayer } from './layers/heliPadsLayer';
import { buildPortsLayer } from './layers/portsLayer';
import { buildAirfieldsLayer } from './layers/airfieldsLayer';
import { buildAirCorridorsLayer } from './layers/airCorridorsLayer';
import { buildSeaLanesLayer } from './layers/seaLanesLayer';
import { buildIncidentsLayers } from './layers/incidentsPulseLayer';
import { buildPatrolsLayer } from './layers/patrolsLayer';
import { buildCamerasLayer } from './layers/camerasLayer';
import { buildBuildings3dLayer } from './layers/buildings3dLayer';
import { buildFlightsLayer } from './layers/flightsLayer';
import { buildCameraMeshLayers } from './layers/cameraMeshLayer';
import { buildCoverageLayer } from './layers/coverageLayer';
import { buildBlindSpotLayer } from './layers/blindSpotLayer';
import { buildRedundancyLayer } from './layers/redundancyLayer';
import { buildViewshedLayer, computeViewshedDatum } from './layers/viewshedLayer';
import { buildOsintLayers } from './layers/osintLayer';
import { buildDistrictDamageLayer } from './layers/districtDamageLayer';
import { useStore } from '../store';
import { dataUrl } from '../lib/paths';
import type { FeatureCollection } from 'geojson';
import { bufferAroundPoint } from '../lib/bufferTool';
import { entitiesByKind } from '../store/selectors';
import { osintObservations } from '../feeds/osint';
import { OsintMapOverlay } from '../ui/osint/OsintMapOverlay';
import type { UnitState } from '../types/venue';
import { BasemapSwitcher } from '../ui/map/BasemapSwitcher';
import { MapLegend } from '../ui/map/MapLegend';
import { CockpitRecorder } from '../ui/recorder/CockpitRecorder';
import { loadPtzCameras } from '../feeds/ptz';
import { loadOsmRoads, type RoadFc } from '../feeds/osm';
import type { PtzCamera, PresetBearing } from '../types/ptz';
import { getCoverageWorker } from '../workers/coverageProxy';
import type { CoverageOutput } from '../workers/coverage.worker';
import { fovFootprint, lensProfileFromName, liveBearing, presetBearingsFromOsm } from '../lib/fov';
import { CameraDetailDock, type CameraDetailContext } from '../ui/cameras/CameraDetailDock';
import { CameraHoverPreview } from '../ui/cameras/CameraHoverPreview';
import { UnitHoverPreview } from '../ui/cameras/UnitHoverPreview';
import { IncidentHoverPreview } from '../ui/cameras/IncidentHoverPreview';
import { loadRealSymbolAtlas, type RealSymbolAtlas } from '../lib/realSymbols';

interface MapHostProps {
  unitSnapshot: UnitState[];
  pulseT: number;
}

export function MapHost({ unitSnapshot, pulseT }: MapHostProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [mapReady, setMapReady] = useState<MapLibreMap | null>(null);

  const venues = useStore((s) => s.venues);
  const incidents = useStore((s) => s.incidents);
  const staticGeo = useStore((s) => s.staticGeo);
  const entities = useStore((s) => s.entities);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const selectEntity = useStore((s) => s.selectEntity);
  const selectedId = useStore((s) => s.selectedVenueId);
  const selectVenue = useStore((s) => s.selectVenue);
  const selectIncident = useStore((s) => s.selectIncident);
  const selectUnit = useStore((s) => s.selectUnit);
  const selectCamera = useStore((s) => s.selectCamera);
  const selectedUnitId = useStore((s) => s.selectedUnitId);
  const selectedIncidentId = useStore((s) => s.selectedIncidentId);
  const selectedCameraId = useStore((s) => s.selectedCameraId);
  const buildings3dEnabled = useStore((s) => s.buildings3dEnabled);
  const camerasEnabled = useStore((s) => s.camerasEnabled);
  const bufferEnabled = useStore((s) => s.bufferEnabled);
  const incidentsEnabled = useStore((s) => s.incidentsEnabled);
  const patrolsEnabled = useStore((s) => s.patrolsEnabled);
  const flightsEnabled = useStore((s) => s.flightsEnabled);
  const osintEnabled = useStore((s) => s.osintEnabled);
  const bufferRadiusKm = useStore((s) => s.bufferRadiusKm);
  const searchQuery = useStore((s) => s.searchQuery);
  const basemapMode = useStore((s) => s.basemapMode);
  const activeTab = useStore((s) => s.activeTab);
  const goruntuMode = useStore((s) => s.goruntuMode);
  const openDock = useStore((s) => s.openDock);
  const setHoveredCamera = useStore((s) => s.setHoveredCamera);
  const setHoveredUnit = useStore((s) => s.setHoveredUnit);
  const setHoveredIncident = useStore((s) => s.setHoveredIncident);
  const scenarioDamage = useStore((s) => s.scenarioDamage);

  const [districts, setDistricts] = useState<FeatureCollection | null>(null);
  const [ptzCameras, setPtzCameras] = useState<PtzCamera[]>([]);
  const [osmRoads, setOsmRoads] = useState<RoadFc | null>(null);
  const [osmPresets, setOsmPresets] = useState<ReadonlyArray<PresetBearing> | null>(null);
  const [coverage, setCoverage] = useState<CoverageOutput | null>(null);
  const [cameraDetail, setCameraDetail] = useState<CameraDetailContext | null>(null);
  const [realSprites, setRealSprites] = useState<RealSymbolAtlas | null>(null);

  // Composited first-responder symbol atlas (ambulance / police / fire / SAR /
  // heli / plane / HAZMAT / AFAD). Built once; units fall back to the geometric
  // atlas until this resolves.
  useEffect(() => {
    let cancelled = false;
    void loadRealSymbolAtlas().then((a) => {
      if (!cancelled) setRealSprites(a);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // Load the 632-camera PTZ registry + OSM roads snapshot in parallel.
  useEffect(() => {
    let cancelled = false;
    void loadPtzCameras().then((cams) => {
      if (!cancelled) setPtzCameras(cams);
    });
    void loadOsmRoads().then((fc) => {
      if (!cancelled) setOsmRoads(fc);
    });
    // District polygons for the scenario damage choropleth (null-tolerant).
    void fetch(dataUrl('istanbul-districts.geojson'))
      .then((r) => (r.ok ? r.json() : null))
      .then((fc) => {
        if (!cancelled) setDistricts((fc as FeatureCollection | null) ?? null);
      })
      .catch(() => {
        if (!cancelled) setDistricts(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // Snap-to-road preset bearings (Phase-B) whenever roads + cameras are both loaded.
  useEffect(() => {
    if (!osmRoads || ptzCameras.length === 0) {
      setOsmPresets(null);
      return;
    }
    const presets: PresetBearing[] = [];
    for (const cam of ptzCameras) {
      const out = presetBearingsFromOsm({ id: cam.id, lat: cam.lat, lng: cam.lng }, osmRoads);
      if (out) presets.push(...out);
    }
    setOsmPresets(presets);
  }, [osmRoads, ptzCameras]);

  // Run coverage analysis when GÖRÜ is active in coverage/blind-spots/redundancy
  // mode and the camera registry has loaded.
  useEffect(() => {
    if (activeTab !== 'goruntuleme') return;
    if (goruntuMode === 'tiles') return;
    if (ptzCameras.length === 0) return;
    let cancelled = false;
    void (async () => {
      const cones = buildAllConePolygons(ptzCameras);
      if (cones.length === 0) return;
      const worker = getCoverageWorker();
      try {
        const result = await worker.computeCoverage({
          cones,
          bbox: [28.45, 40.75, 29.95, 41.40],
          gridSize: 256,
        });
        if (!cancelled) setCoverage(result);
      } catch (err) {
        console.warn('[coverage] worker failure', err);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [activeTab, goruntuMode, ptzCameras]);

  useEffect(() => {
    if (!containerRef.current) return undefined;
    const map = createMap({ container: containerRef.current, basemap: basemapMode });
    mapRef.current = map;
    map.once('load', () => setMapReady(map));
    // DEV-only handle for the run-akom-cockpit skill driver: lets it project
    // camera lng/lat to screen pixels for deterministic hover/click probing.
    if (import.meta.env.DEV) {
      (window as unknown as { __akomMap?: MapLibreMap }).__akomMap = map;
    }
    return () => {
      map.remove();
      mapRef.current = null;
      setMapReady(null);
    };
    // Map is fully recreated when basemapMode changes — the deckOverlay re-mounts
    // automatically via its dependency on `map`. Acceptable cost for a manual UI action.
  }, [basemapMode]);

  useEffect(() => {
    if (!mapReady || !selectedId) return;
    const v = venues.find((f) => f.properties.id === selectedId);
    if (v) {
      const coords = v.geometry.coordinates as [number, number];
      flyToVenue(mapReady, coords[0], coords[1]);
    }
  }, [mapReady, selectedId, venues]);

  // Imperative "Haritada Göster" fly target (C2 detail drawer / OSINT cards).
  const flyTarget = useStore((s) => s.flyTarget);
  useEffect(() => {
    if (!mapReady || !flyTarget) return;
    mapReady.flyTo({
      center: [flyTarget.lng, flyTarget.lat],
      zoom: flyTarget.zoom ?? 15,
      duration: 900,
    });
  }, [mapReady, flyTarget]);

  const filteredVenueIds = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return null;
    return new Set(
      venues.filter((v) => v.properties.name.toLowerCase().includes(q)).map((v) => v.properties.id),
    );
  }, [venues, searchQuery]);

  const bufferPolygon = useMemo(() => {
    if (!bufferEnabled || !selectedId) return null;
    const v = venues.find((f) => f.properties.id === selectedId);
    if (!v) return null;
    const coords = v.geometry.coordinates as [number, number];
    return bufferAroundPoint(coords[0], coords[1], bufferRadiusKm);
  }, [bufferEnabled, selectedId, bufferRadiusKm, venues]);

  // DEV-only deterministic camera selector for the verification driver — sets
  // the same cameraDetail the mesh onClick would, so the viewshed can be probed
  // without GPU picking. Bearing comes from the snapped OSM preset when known.
  useEffect(() => {
    if (!import.meta.env.DEV) return;
    (window as unknown as { __akomSelectCamera?: (id: number) => void }).__akomSelectCamera = (
      id: number,
    ) => {
      const preset = (osmPresets ?? []).find((p) => p.camId === id);
      setCameraDetail({
        camId: id,
        preset: 0,
        bearingDeg: preset?.bearingDeg ?? (id * 37) % 360,
        confidence: preset ? 0.7 : 0.4,
        phase: preset ? 'A' : 'SIM',
      });
      openDock('camera-detail');
    };
  }, [osmPresets, openDock]);

  // Building-occluded viewshed for the selected camera. The per-ray building
  // scan is the expensive bit, so it's memoised on the camera id + bearing +
  // building-set — NOT pulseT — keeping it off the 10 Hz render path.
  const viewshedDatum = useMemo(() => {
    if (activeTab !== 'goruntuleme' || !cameraDetail) return null;
    const cam = ptzCameras.find((c) => c.id === cameraDetail.camId);
    if (!cam) return null;
    return computeViewshedDatum(cam, cameraDetail.bearingDeg, staticGeo.buildings);
  }, [activeTab, cameraDetail, ptzCameras, staticGeo.buildings]);

  const layers = useMemo<Layer[]>(() => {
    const out: Layer[] = [];

    // Scenario damage choropleth — bottom-most so everything draws above it.
    const dmg = buildDistrictDamageLayer({ districts, damage: scenarioDamage });
    if (dmg) out.push(dmg);

    // 3D buildings first - extruded under everything else
    if (buildings3dEnabled && staticGeo.buildings.length > 0) {
      out.push(buildBuildings3dLayer({ data: staticGeo.buildings }));
    }

    // Lanes / corridors / districts
    out.push(buildAirCorridorsLayer(staticGeo.airCorridors));
    out.push(buildSeaLanesLayer(staticGeo.seaLanes));
    out.push(buildHeliPadsLayer(staticGeo.pads));
    out.push(buildPortsLayer(staticGeo.ports));
    out.push(buildAirfieldsLayer(staticGeo.airfields));

    // Cameras
    if (camerasEnabled && staticGeo.cameras.length > 0) {
      out.push(
        ...buildCamerasLayer({
          data: staticGeo.cameras,
          selectedId: selectedCameraId,
          onClick: selectCamera,
          onHover: (h) =>
            setHoveredCamera(
              h ? { camId: h.camId, x: h.x, y: h.y } : null,
            ),
        }),
      );
    }

    // Buffer + venues
    const buf = buildBufferLayer(bufferPolygon);
    if (buf) out.push(buf);
    out.push(
      buildVenuesLayer({
        venues,
        selectedId,
        onClick: selectVenue,
        filterIds: filteredVenueIds,
      }),
    );

    // Incidents (pulse + core)
    if (incidentsEnabled) {
      out.push(
        ...buildIncidentsLayers({
          data: incidents,
          pulseT,
          selectedId: selectedIncidentId,
          onClick: selectIncident,
          onHover: (h) =>
            setHoveredIncident(
              h ? { incidentId: h.incidentId, x: h.x, y: h.y } : null,
            ),
        }),
      );
    }

    // Patrols (halo + core)
    if (patrolsEnabled) {
      out.push(
        ...buildPatrolsLayer({
          data: unitSnapshot,
          selectedId: selectedUnitId,
          onClick: selectUnit,
          onHover: (h) =>
            setHoveredUnit(
              h ? { unitId: h.unitId, x: h.x, y: h.y } : null,
            ),
          realSprites,
        }),
      );
    }

    // Live OpenSky flights (Phase 2 — spatial-intelligence open-feed substrate)
    if (flightsEnabled) {
      const flightEntities = entitiesByKind(entities, 'flight');
      if (flightEntities.length > 0) {
        out.push(
          ...buildFlightsLayer({
            data: flightEntities,
            selectedId: selectedEntityId,
            onClick: selectEntity,
            now: pulseT,
          }),
        );
      }
    }

    // OSINT geolocated impact observations (Phase 3). Markers ride on the
    // operational map; click selects the entity + opens the feed inspector.
    if (osintEnabled) {
      const osintEntities = osintObservations(entities);
      if (osintEntities.length > 0) {
        out.push(
          ...buildOsintLayers({
            data: osintEntities,
            pulseT,
            selectedId: selectedEntityId,
            onClick: (id) => {
              selectEntity(id);
              openDock('feed-inspector');
            },
          }),
        );
      }
    }

    // 3D PTZ camera bodies + FOV frustums — Phase 2. Visible on the GÖRÜ tab in
    // every mode; clickable (detail dock) and hoverable (instant preview).
    if (activeTab === 'goruntuleme' && ptzCameras.length > 0) {
      const bearingByCam = new Map<number, number>();
      for (const p of osmPresets ?? []) {
        if (!bearingByCam.has(p.camId)) bearingByCam.set(p.camId, p.bearingDeg);
      }
      out.push(
        ...buildCameraMeshLayers({
          cameras: ptzCameras,
          presets: osmPresets,
          selectedId: cameraDetail?.camId ?? null,
          onClick: (camId) => {
            const snapped = bearingByCam.has(camId);
            setCameraDetail({
              camId,
              preset: 0,
              bearingDeg: bearingByCam.get(camId) ?? (camId * 37) % 360,
              confidence: snapped ? 0.7 : 0.4,
              phase: snapped ? 'A' : 'SIM',
            });
            openDock('camera-detail');
          },
          // Hover only drives the preview portal (separate component) so the
          // layer list doesn't rebuild on every pointer move.
          onHover: (h) => setHoveredCamera(h),
        }),
      );

      if (coverage && goruntuMode !== 'tiles') {
        if (goruntuMode === 'coverage') {
          const cov = buildCoverageLayer({ data: coverage.coveredFc });
          if (cov) out.push(cov);
        }
        if (goruntuMode === 'blind-spots') {
          const blind = buildBlindSpotLayer({ data: coverage.blindSpotsFc });
          if (blind) out.push(blind);
        }
        if (goruntuMode === 'redundancy') {
          const red = buildRedundancyLayer({ grid: coverage.redundancy });
          if (red) out.push(red);
        }
      }

      // Lit viewshed for the selected camera — pushed LAST so it sits above the
      // city-wide coverage/blind-spot overlays. It's the precise ground that
      // one camera sees past nearby buildings (the dark gaps are occluded).
      const vs = buildViewshedLayer(viewshedDatum);
      if (vs) out.push(vs);
    }

    return out;
  }, [
    buildings3dEnabled,
    camerasEnabled,
    incidentsEnabled,
    patrolsEnabled,
    flightsEnabled,
    osintEnabled,
    realSprites,
    bufferPolygon,
    venues,
    selectedId,
    selectVenue,
    selectCamera,
    selectedCameraId,
    filteredVenueIds,
    staticGeo,
    incidents,
    pulseT,
    selectedIncidentId,
    selectIncident,
    unitSnapshot,
    selectedUnitId,
    selectUnit,
    entities,
    selectedEntityId,
    selectEntity,
    activeTab,
    goruntuMode,
    ptzCameras,
    osmPresets,
    coverage,
    openDock,
    cameraDetail,
    setHoveredCamera,
    setHoveredUnit,
    setHoveredIncident,
    viewshedDatum,
    districts,
    scenarioDamage,
  ]);

  return (
    <>
      <div ref={containerRef} className="map-canvas" />
      <DeckOverlay map={mapReady} layers={layers} />
      <BasemapSwitcher />
      <CockpitRecorder />
      <CameraDetailDock context={cameraDetail} />
      <CameraHoverPreview />
      <UnitHoverPreview />
      <IncidentHoverPreview />
      <OsintMapOverlay map={mapReady} />
      <MapLegend />
      <div className="map-watermark">
        AKOM · MAPLIBRE · DECK.GL · {unitSnapshot.length} BİRİM · {staticGeo.buildings.length}{' '}
        BİNA · {staticGeo.cameras.length} KAMERA
      </div>
    </>
  );
}

/**
 * Build a flat array of FOV cone polygons (one per camera, using the current
 * synthetic sweep bearing) for the coverage Worker. Cheap; ~20 KB of arrays
 * for 632 cones.
 */
function buildAllConePolygons(cams: ReadonlyArray<PtzCamera>): Array<Array<[number, number]>> {
  const nowMs = Date.now();
  const out: Array<Array<[number, number]>> = [];
  for (const cam of cams) {
    const lens = lensProfileFromName(cam.name);
    const seed = (cam.id * 37) % 360;
    const bearings = [seed, (seed + 130) % 360, (seed + 240) % 360];
    const bearing = liveBearing(bearings, nowMs);
    out.push(
      fovFootprint({
        lat: cam.lat,
        lng: cam.lng,
        bearingDeg: bearing,
        hfovDeg: lens.hfovDeg,
        rFarM: lens.rFarDefault,
      }),
    );
  }
  return out;
}
