/**
 * Bare-bones HTML5 drag-and-drop hook for the C2 Kanban.
 *
 * We don't pull in @dnd-kit because the board has <30 cards and 6 columns;
 * native DnD is sufficient and ships zero JS overhead. If the board grows to
 * hundreds of cards or needs touch + keyboard reorder, swap to @dnd-kit/core.
 */

import { useCallback, useState } from 'react';

export interface DndHandlers {
  draggingId: string | null;
  onDragStart(e: React.DragEvent, cardId: string): void;
  onDragEnd(e: React.DragEvent): void;
  onDragOver(e: React.DragEvent): void;
  onDrop(e: React.DragEvent, columnId: string, onCommit: (cardId: string) => void): void;
}

export function useDnd(): DndHandlers {
  const [draggingId, setDraggingId] = useState<string | null>(null);

  const onDragStart = useCallback((e: React.DragEvent, cardId: string) => {
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', cardId);
    setDraggingId(cardId);
  }, []);

  const onDragEnd = useCallback(() => {
    setDraggingId(null);
  }, []);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent, _columnId: string, onCommit: (cardId: string) => void) => {
      e.preventDefault();
      const cardId = e.dataTransfer.getData('text/plain');
      if (cardId) onCommit(cardId);
      setDraggingId(null);
    },
    [],
  );

  return { draggingId, onDragStart, onDragEnd, onDragOver, onDrop };
}
