/**
 * Cockpit MediaRecorder — Phase 9 Leap Step 5.
 *
 * Captures the MapLibre canvas (deck.gl renders interleaved into it) as a
 * 30 s WebM via MediaRecorder + canvas.captureStream. Addresses the 2026-05-18
 * handover §3.4 limitation that Cowork couldn't encode video.
 *
 * Codec preference: VP9 → VP8 → H.264 (probed via MediaRecorder.isTypeSupported).
 *
 * Session 1 scope: map canvas only. Dock panels overlay HTML on top — they
 * will NOT appear in the recording. Session 2 enhancement: html2canvas
 * compositing per frame at 15 fps (more CPU expensive).
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';

const DURATION_MS = 30_000;
const FPS = 30;

const CODEC_PRIORITY = [
  'video/webm;codecs=vp9',
  'video/webm;codecs=vp8',
  'video/webm',
  'video/mp4;codecs=h264',
];

function pickMimeType(): string | null {
  if (typeof MediaRecorder === 'undefined') return null;
  for (const t of CODEC_PRIORITY) {
    if (MediaRecorder.isTypeSupported(t)) return t;
  }
  return null;
}

function findMapCanvas(): HTMLCanvasElement | null {
  // MapLibre injects its WebGL canvas as the first descendant of `.maplibregl-canvas-container`.
  // We grab the canvas directly via the DOM.
  const node = document.querySelector<HTMLCanvasElement>('.maplibregl-canvas');
  return node ?? document.querySelector<HTMLCanvasElement>('canvas');
}

export function CockpitRecorder(): ReactNode {
  const [recording, setRecording] = useState(false);
  const [remaining, setRemaining] = useState(DURATION_MS);
  const [error, setError] = useState<string | null>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const tickRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (recorderRef.current && recorderRef.current.state !== 'inactive') {
        recorderRef.current.stop();
      }
      if (tickRef.current !== null) window.clearInterval(tickRef.current);
    };
  }, []);

  const start = (): void => {
    setError(null);
    if (recording) return;
    const canvas = findMapCanvas();
    if (!canvas) {
      setError('Map canvas not found');
      return;
    }
    const mime = pickMimeType();
    if (!mime) {
      setError('MediaRecorder unsupported in this browser');
      return;
    }
    let stream: MediaStream;
    try {
      stream = canvas.captureStream(FPS);
    } catch (err) {
      setError(`captureStream failed: ${(err as Error).message}`);
      return;
    }
    let recorder: MediaRecorder;
    try {
      recorder = new MediaRecorder(stream, { mimeType: mime });
    } catch (err) {
      setError(`MediaRecorder ctor failed: ${(err as Error).message}`);
      return;
    }
    recorderRef.current = recorder;
    chunksRef.current = [];
    recorder.ondataavailable = (e: BlobEvent) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: mime });
      downloadBlob(blob, `akom-cockpit-${Date.now()}.${extFor(mime)}`);
      setRecording(false);
      setRemaining(DURATION_MS);
      if (tickRef.current !== null) {
        window.clearInterval(tickRef.current);
        tickRef.current = null;
      }
    };
    recorder.start(250);
    setRecording(true);
    setRemaining(DURATION_MS);
    const startedAt = Date.now();
    tickRef.current = window.setInterval(() => {
      const left = Math.max(0, DURATION_MS - (Date.now() - startedAt));
      setRemaining(left);
    }, 100);
    window.setTimeout(() => {
      if (recorder.state !== 'inactive') recorder.stop();
    }, DURATION_MS);
  };

  const stop = (): void => {
    if (!recorderRef.current) return;
    if (recorderRef.current.state !== 'inactive') recorderRef.current.stop();
  };

  return (
    <div className="cockpit-recorder">
      {!recording ? (
        <button
          type="button"
          className="cockpit-recorder__btn"
          onClick={start}
          title="Record 30s WebM of map canvas"
        >
          ● REC 30s
        </button>
      ) : (
        <button
          type="button"
          className="cockpit-recorder__btn cockpit-recorder__btn--active"
          onClick={stop}
          title="Stop recording"
        >
          ■ {(remaining / 1000).toFixed(1)}s
        </button>
      )}
      {error && <span className="cockpit-recorder__err">{error}</span>}
    </div>
  );
}

function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  // Give the browser a moment to dispatch the download before freeing.
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function extFor(mime: string): string {
  if (mime.startsWith('video/webm')) return 'webm';
  if (mime.startsWith('video/mp4')) return 'mp4';
  return 'bin';
}
