/**
 * Satellite catalog dock — Phase 9 Leap Step 3.
 *
 * 10 category rows with MIL glyph + name + live count + checkbox + opacity
 * slider. Search-by-NORAD-ID input. Bitmask state lives in `useStore`
 * (satCatBitmask) so the SGP4 worker can read it via the same selector.
 */
import { useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { SAT_CATEGORIES } from '../../satellites/symbology';

export function SatCatalogDock(): ReactNode {
  const dock = useStore((s) => s.dock['sat-catalog']);
  const closeDock = useStore((s) => s.closeDock);
  const satCatBitmask = useStore((s) => s.satCatBitmask);
  const setSatCatBitmask = useStore((s) => s.setSatCatBitmask);
  const satOpacity = useStore((s) => s.satOpacity);
  const setSatOpacity = useStore((s) => s.setSatOpacity);
  const satCounts = useStore((s) => s.satCounts);
  const selectSatByNorad = useStore((s) => s.selectSatByNorad);
  const openDock = useStore((s) => s.openDock);
  const [search, setSearch] = useState('');

  if (!dock.open) return null;

  const onToggleCat = (code: number): void => {
    setSatCatBitmask(satCatBitmask ^ (1 << code));
  };

  const onSearch = (): void => {
    const n = parseInt(search.trim(), 10);
    if (!Number.isFinite(n)) return;
    // Mirror a globe click: select the NORAD and surface its detail dock so
    // FIND produces a visible result instead of a silent state change.
    selectSatByNorad(n);
    openDock('sat-detail');
  };

  const totalActive = SAT_CATEGORIES.reduce(
    (acc, spec) => acc + ((satCatBitmask & (1 << spec.code)) !== 0 ? satCounts[spec.code] ?? 0 : 0),
    0,
  );

  return (
    <DockPanel id="sat-catalog" title="Satellite Catalog">
      <div className="sat-catalog">
        <div className="sat-catalog__header">
          <span className="sat-catalog__count">{totalActive.toLocaleString()} active</span>
          <button type="button" className="sat-catalog__close" onClick={() => closeDock('sat-catalog')}>
            KAPAT
          </button>
        </div>
        <div className="sat-catalog__search">
          <input
            type="text"
            inputMode="numeric"
            placeholder="NORAD ID…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') onSearch();
            }}
          />
          <button type="button" onClick={onSearch}>
            FIND
          </button>
        </div>
        <div className="sat-catalog__list" role="list">
          {SAT_CATEGORIES.map((spec) => {
            const enabled = (satCatBitmask & (1 << spec.code)) !== 0;
            const count = satCounts[spec.code] ?? 0;
            return (
              <label key={spec.code} className="sat-catalog__row" data-active={enabled || undefined}>
                <input
                  type="checkbox"
                  checked={enabled}
                  onChange={() => onToggleCat(spec.code)}
                />
                <span
                  className="sat-catalog__glyph"
                  style={{ background: spec.color }}
                  aria-hidden="true"
                />
                <span className="sat-catalog__name">{spec.label}</span>
                <span className="sat-catalog__shape">{spec.shape}</span>
                <span className="sat-catalog__qty">{count.toLocaleString()}</span>
              </label>
            );
          })}
        </div>
        <div className="sat-catalog__opacity">
          <label htmlFor="sat-opacity">Opacity</label>
          <input
            id="sat-opacity"
            type="range"
            min={0}
            max={100}
            value={Math.round(satOpacity * 100)}
            onChange={(e) => setSatOpacity(parseInt(e.target.value, 10) / 100)}
          />
          <span>{Math.round(satOpacity * 100)}%</span>
        </div>
      </div>
    </DockPanel>
  );
}
