/**
 * Tab 06 — ALTYP Altyapı.
 *
 * Four utility flow networks rendered as node-link diagrams: TEİAŞ
 * electric, İGDAŞ gas, İSKİ water, Telecom. Failed edges drawn dashed in
 * klaxon. Each network carries 3 KPI tiles in its footer.
 *
 * Phase 8 of the spatial-intelligence ultraplan. Real provider feeds are
 * non-public, so the topology is synthesized and evolved live by the utilities
 * feed (src/feeds/utilities.ts) — node statuses fail and recover over time and
 * cascade down the network, driven from the Zustand store.
 */

import { useStore } from '../../store';
import { NetworkPanel } from '../utility/NetworkPanel';

export function Altyapi() {
  const networks = useStore((s) => s.utilityNetworks);

  const totalDown = networks
    .flatMap((n) => n.nodes)
    .filter((n) => n.status === 'down').length;

  return (
    <div className="hud-pane altyp-tab">
      <header className="altyp-tab__head glass-panel glass-panel--float">
        <span className="altyp-tab__title">ALTYAPI · AKIŞ AĞI</span>
        <span className="altyp-tab__sub">TEİAŞ · İGDAŞ · İSKİ · TELEKOM</span>
        <span className="altyp-tab__spacer" />
        <span className="altyp-tab__chip altyp-tab__chip--klaxon">
          ▲ KAYIP · {totalDown}
        </span>
      </header>
      <div className="altyp-grid">
        {networks.map((net) => (
          <NetworkPanel key={net.kind} net={net} />
        ))}
      </div>
    </div>
  );
}
