/**
 * Incident hover preview — shows incident info when hovering an incident dot
 * on the map. Reads `hoveredIncident` from the store, looks up the feature
 * and renders a compact tooltip card.
 */
import { useMemo } from 'react';
import { useStore } from '../../store';

const CARD_W = 260;
const OFFSET = 16;

const TYPE_LABEL: Record<string, string> = {
  mascal: 'MASCAL',
  collapse: 'Çöküntü',
  fire: 'Yangın',
  flood: 'Sel',
  leak: 'Gaz Kaçağı',
  hazmat: 'HAZMAT',
};

const TYPE_RGB: Record<string, [number, number, number]> = {
  mascal: [230, 57, 70],
  collapse: [230, 57, 70],
  fire: [255, 138, 0],
  flood: [107, 182, 255],
  leak: [255, 220, 100],
  hazmat: [200, 180, 255],
};

function rgbCss(triple: [number, number, number]): string {
  return `rgb(${triple[0]}, ${triple[1]}, ${triple[2]})`;
}

export function IncidentHoverPreview(): React.ReactNode {
  const hovered = useStore((s) => s.hoveredIncident);
  const incidents = useStore((s) => s.incidents);

  const incident = useMemo(() => {
    if (!hovered) return null;
    return incidents.find((i) => i.properties.id === hovered.incidentId) ?? null;
  }, [hovered, incidents]);

  const pos = useMemo(() => {
    if (!hovered) return null;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let x = hovered.x + OFFSET;
    let y = hovered.y + OFFSET;
    if (x + CARD_W > vw) x = hovered.x - CARD_W - OFFSET;
    if (y + 130 > vh) y = vh - 130 - 8;
    if (y < 8) y = 8;
    return { x: Math.max(8, x), y };
  }, [hovered]);

  const visible = !!(hovered && incident && pos);

  const props = incident?.properties;
  const typeLabel = props ? (TYPE_LABEL[props.type] ?? props.type) : '';
  const rgb = props ? (TYPE_RGB[props.type] ?? [120, 130, 150] as [number, number, number]) : [120, 130, 150] as [number, number, number];

  return (
    <div
      role="tooltip"
      aria-hidden={!visible}
      data-testid="incident-hover-preview"
      style={{
        position: 'fixed',
        left: 0,
        top: 0,
        width: CARD_W,
        zIndex: 1400,
        pointerEvents: 'none',
        transform: pos ? `translate(${pos.x}px, ${pos.y}px)` : 'translate(-9999px,-9999px)',
        opacity: visible ? 1 : 0,
        transition: 'opacity 90ms ease-out',
        willChange: 'transform, opacity',
        background: 'rgba(8, 13, 22, 0.92)',
        border: '1px solid rgba(56, 189, 248, 0.55)',
        borderRadius: 6,
        boxShadow: '0 8px 28px rgba(0,0,0,0.55)',
        overflow: 'hidden',
        fontFamily: 'var(--font-mono, monospace)',
      }}
    >
      {incident && props && (
        <>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '7px 10px',
              borderBottom: '1px solid rgba(56,189,248,0.22)',
              background: 'rgba(56,189,248,0.12)',
            }}
          >
            <span
              style={{
                width: 10,
                height: 10,
                borderRadius: '50%',
                background: rgbCss(rgb),
                flex: '0 0 auto',
              }}
            />
            <span
              style={{
                fontSize: 12,
                fontWeight: 600,
                color: '#e2e8f0',
                letterSpacing: '0.05em',
              }}
            >
              {props.label}
            </span>
            <span style={{ flex: 1 }} />
            <span style={{ color: '#94a3b8', fontSize: 10 }}>{props.id}</span>
          </div>
          <div
            style={{
              padding: '6px 10px',
              fontSize: 10.5,
              color: '#cbd5e1',
              display: 'flex',
              flexDirection: 'column',
              gap: 3,
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>Tip</span>
              <span style={{ color: rgbCss(rgb) }}>{typeLabel}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>Şiddet</span>
              <span>{'★'.repeat(props.severity)}{'☆'.repeat(5 - props.severity)}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>İlçe</span>
              <span>{props.district}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>Yarıçap</span>
              <span>{props.radius_m} m</span>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
