/**
 * Satellite catalog loader — Phase 9-E.
 *
 * Reads /public/data/sats.json (written by scripts/build-sats.mjs) and
 * hydrates the short-keyed entries. Memoized per page lifetime.
 *
 * The SGP4 propagation worker (src/satellites/sat.worker.ts, deferred) reads
 * the same JSON in its own scope; this module is for the main thread (the
 * dock-panel category counts and search-by-NORAD UI).
 */

import type { SatCategoryCode } from './symbology';
import { dataUrl } from '../lib/paths';

export interface SatRaw {
  /** NORAD catalog ID. */
  readonly n: number;
  /** Category code 0..9 (see symbology.SAT_CATEGORIES). */
  readonly c: number;
  /** TLE line 1 (69 chars + checksum). */
  readonly l1: string;
  /** TLE line 2. */
  readonly l2: string;
  /** Display name. */
  readonly nm: string;
}

export interface SatSnapshot {
  readonly generated: string;
  readonly source: string;
  readonly groupsHit: number;
  readonly groupsFailed: number;
  readonly count: number;
  readonly sats: ReadonlyArray<SatRaw>;
}

export interface SatRecord {
  readonly noradId: number;
  readonly category: SatCategoryCode;
  readonly line1: string;
  readonly line2: string;
  readonly name: string;
}

let cached: SatRecord[] | null = null;
let inFlight: Promise<SatRecord[]> | null = null;

/**
 * Load and hydrate the satellite catalog. Returns `[]` on fetch failure.
 */
export async function loadSatCatalog(): Promise<SatRecord[]> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = (async () => {
    try {
      const res = await fetch(dataUrl('sats.json'));
      if (!res.ok) {
        cached = [];
        return cached;
      }
      const snap = (await res.json()) as SatSnapshot;
      cached = snap.sats.map((s) => ({
        noradId: s.n,
        category: (s.c as SatCategoryCode) ?? (9 as SatCategoryCode),
        line1: s.l1,
        line2: s.l2,
        name: s.nm,
      }));
      return cached;
    } catch {
      cached = [];
      return cached;
    } finally {
      inFlight = null;
    }
  })();
  return inFlight;
}

/** Filter the catalog to a single category. */
export function filterByCategory(cat: SatCategoryCode, all: ReadonlyArray<SatRecord>): SatRecord[] {
  return all.filter((s) => s.category === cat);
}

/** Find a satellite by NORAD ID. */
export function findByNorad(noradId: number, all: ReadonlyArray<SatRecord>): SatRecord | undefined {
  return all.find((s) => s.noradId === noradId);
}

/** Counts per category — the dock-panel UI consumes this. */
export function countsByCategory(all: ReadonlyArray<SatRecord>): Record<number, number> {
  const counts: Record<number, number> = {};
  for (let i = 0; i < 10; i++) counts[i] = 0;
  for (const s of all) counts[s.category] = (counts[s.category] ?? 0) + 1;
  return counts;
}
