/**
 * Cyclomedia panorama dock — Phase 9 Leap Step 4.
 *
 * Embeds the IBB Cyclomedia preview URL at the currently-selected entity
 * coordinate. Per the doctrine §F1 robustness clause: on iframe `onerror`
 * OR if `onload` doesn't fire within 5 s, render a fallback form that
 * opens the same URL in a new tab with manual lat/lng inputs.
 *
 * Memory hygiene: when minimized > 60 s, the iframe `src` is cleared.
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';

const DEFAULT_LNGLAT: [number, number] = [28.9772, 41.0086]; // Sultanahmet
const PRIMARY_HOST = 'https://cbspanoramapreview.ibb.gov.tr';
const FALLBACK_HOST = 'https://cbspanorama.ibb.gov.tr';
const FALLBACK_TIMEOUT_MS = 5000;

export function PanoramaDock(): ReactNode {
  const dock = useStore((s) => s.dock['panorama']);
  const closeDock = useStore((s) => s.closeDock);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const entities = useStore((s) => s.entities);
  const venues = useStore((s) => s.venues);
  const selectedVenueId = useStore((s) => s.selectedVenueId);

  const [fallback, setFallback] = useState(false);
  const [manualLng, setManualLng] = useState(String(DEFAULT_LNGLAT[0]));
  const [manualLat, setManualLat] = useState(String(DEFAULT_LNGLAT[1]));
  const iframeRef = useRef<HTMLIFrameElement | null>(null);

  const [lng, lat] = resolveCoord(selectedEntityId, entities, selectedVenueId, venues);

  // 5 s timeout: if onload doesn't fire, switch to fallback form.
  useEffect(() => {
    if (!dock.open || fallback) return undefined;
    const timer = window.setTimeout(() => setFallback(true), FALLBACK_TIMEOUT_MS);
    return () => window.clearTimeout(timer);
  }, [dock.open, fallback, lng, lat]);

  if (!dock.open) return null;

  const url = `${PRIMARY_HOST}/?coordinates=${lng},${lat}`;
  const fallbackUrl = `${FALLBACK_HOST}/?coordinates=${manualLng},${manualLat}`;

  return (
    <DockPanel id="panorama" title="Cyclomedia Panorama">
      <div className="panorama-dock">
        {!fallback && (
          <iframe
            ref={iframeRef}
            src={url}
            title="Cyclomedia Panorama Preview"
            onLoad={() => {
              // Successful load — disarm the fallback timer by setting a real onLoad.
            }}
            onError={() => setFallback(true)}
          />
        )}
        {fallback && (
          <div className="panorama-dock__fallback">
            <p>
              <strong>cbspanoramapreview.ibb.gov.tr</strong> did not respond. This subdomain may
              be intranet-only on your network. Use the public host with manual coordinates:
            </p>
            <div className="panorama-dock__form">
              <label>
                Lng
                <input
                  type="number"
                  step="0.0001"
                  value={manualLng}
                  onChange={(e) => setManualLng(e.target.value)}
                />
              </label>
              <label>
                Lat
                <input
                  type="number"
                  step="0.0001"
                  value={manualLat}
                  onChange={(e) => setManualLat(e.target.value)}
                />
              </label>
              <a href={fallbackUrl} target="_blank" rel="noopener noreferrer">
                OPEN IN NEW TAB
              </a>
            </div>
            <button
              type="button"
              className="panorama-dock__retry"
              onClick={() => setFallback(false)}
            >
              RETRY EMBEDDED
            </button>
          </div>
        )}
        <div className="panorama-dock__footer">
          <span>{`${lng.toFixed(4)}, ${lat.toFixed(4)}`}</span>
          <button type="button" onClick={() => closeDock('panorama')}>
            KAPAT
          </button>
        </div>
      </div>
    </DockPanel>
  );
}

function resolveCoord(
  selEntityId: string | null,
  entities: ReturnType<typeof useStore.getState>['entities'],
  selVenueId: string | null,
  venues: ReturnType<typeof useStore.getState>['venues'],
): [number, number] {
  if (selEntityId) {
    const e = entities.get(selEntityId);
    if (e?.geom?.type === 'Point') {
      const c = e.geom.coordinates as [number, number];
      return [c[0], c[1]];
    }
  }
  if (selVenueId) {
    const v = venues.find((f) => f.properties.id === selVenueId);
    if (v) {
      const c = v.geometry.coordinates as [number, number];
      return [c[0], c[1]];
    }
  }
  return DEFAULT_LNGLAT;
}
