/**
 * Satellite detail dock — Phase 9 Leap Step 3.
 *
 * Renders on satellite-icon click. NORAD ID + name + category + current
 * lat/lng/altKm + orbital period (computed from mean motion in line 2) +
 * inclination + eccentricity + TLE epoch.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { loadSatCatalog, type SatRecord } from '../../satellites/loader';
import { SAT_CATEGORIES } from '../../satellites/symbology';

export function SatDetailDock(): ReactNode {
  const dock = useStore((s) => s.dock['sat-detail']);
  const closeDock = useStore((s) => s.closeDock);
  const selectedNorad = useStore((s) => s.selectedSatNorad);
  const [sat, setSat] = useState<SatRecord | null>(null);

  useEffect(() => {
    if (selectedNorad === null) {
      setSat(null);
      return;
    }
    void loadSatCatalog().then((cat) => {
      setSat(cat.find((s) => s.noradId === selectedNorad) ?? null);
    });
  }, [selectedNorad]);

  if (!dock.open || sat === null) return null;

  const orbital = parseOrbitalElements(sat.line2);
  const epoch = parseTleEpoch(sat.line1);
  const catSpec = SAT_CATEGORIES[sat.category];

  return (
    <DockPanel id="sat-detail" title={`Sat · ${sat.noradId}`}>
      <div className="sat-detail">
        <div className="sat-detail__name">{sat.name}</div>
        <dl className="sat-detail__grid">
          <dt>NORAD</dt>
          <dd>{sat.noradId}</dd>
          <dt>Category</dt>
          <dd>
            <span
              className="sat-detail__glyph"
              style={{ background: catSpec?.color ?? '#999' }}
              aria-hidden="true"
            />
            {catSpec?.label ?? 'Other'}
          </dd>
          <dt>Period</dt>
          <dd>{orbital.periodMin ? `${orbital.periodMin.toFixed(1)} min` : '—'}</dd>
          <dt>Inclination</dt>
          <dd>{orbital.incDeg !== null ? `${orbital.incDeg.toFixed(2)}°` : '—'}</dd>
          <dt>Eccentricity</dt>
          <dd>{orbital.ecc !== null ? orbital.ecc.toFixed(6) : '—'}</dd>
          <dt>Mean motion</dt>
          <dd>{orbital.nRevDay !== null ? `${orbital.nRevDay.toFixed(4)} rev/day` : '—'}</dd>
          <dt>TLE epoch</dt>
          <dd>{epoch ? epoch.toISOString().slice(0, 10) : '—'}</dd>
        </dl>
        <details className="sat-detail__tle">
          <summary>Raw TLE</summary>
          <pre>
            {sat.line1}
            {'\n'}
            {sat.line2}
          </pre>
        </details>
        <button type="button" className="sat-detail__close" onClick={() => closeDock('sat-detail')}>
          KAPAT
        </button>
      </div>
    </DockPanel>
  );
}

interface OrbitalElements {
  incDeg: number | null;
  ecc: number | null;
  nRevDay: number | null;
  periodMin: number | null;
}

function parseOrbitalElements(line2: string): OrbitalElements {
  // TLE line 2 fixed columns per NORAD spec:
  //   9-16  inclination (deg)
  //   18-25 RAAN (deg)
  //   27-33 eccentricity (assumed leading 0., 7 digits)
  //   35-42 arg of perigee
  //   44-51 mean anomaly
  //   53-63 mean motion (rev/day)
  try {
    const incDeg = parseFloat(line2.slice(8, 16).trim());
    const eccStr = line2.slice(26, 33).trim();
    const ecc = parseFloat(`0.${eccStr}`);
    const nRevDay = parseFloat(line2.slice(52, 63).trim());
    const periodMin = nRevDay > 0 ? 1440 / nRevDay : null;
    return {
      incDeg: Number.isFinite(incDeg) ? incDeg : null,
      ecc: Number.isFinite(ecc) ? ecc : null,
      nRevDay: Number.isFinite(nRevDay) ? nRevDay : null,
      periodMin: periodMin && Number.isFinite(periodMin) ? periodMin : null,
    };
  } catch {
    return { incDeg: null, ecc: null, nRevDay: null, periodMin: null };
  }
}

function parseTleEpoch(line1: string): Date | null {
  // Columns 19-32 of line 1 are epoch as YYDDD.DDDDDDDD where YY < 57 → 20YY else 19YY.
  try {
    const yy = parseInt(line1.slice(18, 20), 10);
    const day = parseFloat(line1.slice(20, 32));
    if (!Number.isFinite(yy) || !Number.isFinite(day)) return null;
    const year = yy < 57 ? 2000 + yy : 1900 + yy;
    const date = new Date(Date.UTC(year, 0, 1));
    date.setUTCMilliseconds(date.getUTCMilliseconds() + (day - 1) * 86400 * 1000);
    return date;
  } catch {
    return null;
  }
}
