/**
 * Boot splash — a point-cloud globe that rotates while its points oscillate
 * (breathe along their radius), with "ertugrul kulak" set below in bold sans.
 * Honors the flat-tactical doctrine: NO glow, NO blur. Holds for 1.3 s, then
 * fades out and unmounts via {@link onDone}.
 */

import { useEffect, useRef, useState } from 'react';

const HOLD_MS = 1300;
const FADE_MS = 320;
const POINT_COUNT = 720;

interface Pt {
  x: number;
  y: number;
  z: number;
  phase: number;
}

/** Even point distribution on a unit sphere (Fibonacci spiral). */
function fibonacciSphere(n: number): Pt[] {
  const pts: Pt[] = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i++) {
    const y = 1 - (i / (n - 1)) * 2; // 1 → -1
    const r = Math.sqrt(1 - y * y);
    const theta = golden * i;
    pts.push({ x: Math.cos(theta) * r, y, z: Math.sin(theta) * r, phase: (i % 32) / 32 });
  }
  return pts;
}

export function IntroGlobe({ onDone }: { onDone: () => void }) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [fading, setFading] = useState(false);

  // The parent (App) re-renders ~10×/s from its pulse clock, so `onDone` is a
  // fresh closure every render. Keep it in a ref and run the boot/teardown
  // effect EXACTLY once — otherwise the hold/fade timers reset each render and
  // the splash never dismisses.
  const onDoneRef = useRef(onDone);
  onDoneRef.current = onDone;

  useEffect(() => {
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    let raf = 0;

    if (canvas && ctx) {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const size = Math.min(window.innerWidth, window.innerHeight) * 0.42;
      canvas.width = size * dpr;
      canvas.height = size * dpr;
      canvas.style.width = `${size}px`;
      canvas.style.height = `${size}px`;
      ctx.scale(dpr, dpr);

      const pts = fibonacciSphere(POINT_COUNT);
      const cx = size / 2;
      const cy = size / 2;
      const R = size * 0.4;
      const t0 = performance.now();

      const ink = '#18181b'; // --ink-strong
      const accent = '#3b82f6'; // --accent (blue-500)

      const frame = (now: number) => {
        const t = (now - t0) / 1000;
        const ay = reduce ? 0.6 : t * 1.7; // yaw
        const ax = 0.42; // fixed tilt
        const cosY = Math.cos(ay);
        const sinY = Math.sin(ay);
        const cosX = Math.cos(ax);
        const sinX = Math.sin(ax);

        ctx.clearRect(0, 0, size, size);

        for (const p of pts) {
          // Radial oscillation — points breathe in and out around the shell.
          const osc = reduce ? 1 : 1 + 0.05 * Math.sin(t * 3.4 + p.phase * Math.PI * 2);
          const px = p.x * osc;
          const py = p.y * osc;
          const pz = p.z * osc;

          // Rotate Y then X.
          const x1 = px * cosY - pz * sinY;
          const z1 = px * sinY + pz * cosY;
          const y2 = py * cosX - z1 * sinX;
          const z2 = py * sinX + z1 * cosX;

          const depth = (z2 + 1.4) / 2.4; // 0 (back) → ~1 (front)
          const sx = cx + x1 * R;
          const sy = cy + y2 * R;
          const radius = 0.5 + depth * 1.7;
          ctx.globalAlpha = 0.18 + depth * 0.82;
          ctx.fillStyle = depth > 0.82 ? accent : ink;
          ctx.beginPath();
          ctx.arc(sx, sy, radius, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
        raf = requestAnimationFrame(frame);
      };
      raf = requestAnimationFrame(frame);
    }

    const fadeTimer = window.setTimeout(() => setFading(true), HOLD_MS);
    const doneTimer = window.setTimeout(() => {
      cancelAnimationFrame(raf);
      onDoneRef.current();
    }, HOLD_MS + FADE_MS);

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(fadeTimer);
      window.clearTimeout(doneTimer);
    };
    // Run once on mount — never re-run, or the timers reset (see ref note above).
  }, []);

  return (
    <div
      aria-hidden="true"
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 26,
        background: 'var(--bg-void, #ffffff)',
        opacity: fading ? 0 : 1,
        transition: `opacity ${FADE_MS}ms ease-out`,
        pointerEvents: fading ? 'none' : 'auto',
      }}
    >
      <canvas ref={canvasRef} />
      <span
        style={{
          fontFamily: 'var(--font-ui, system-ui, sans-serif)',
          fontWeight: 700,
          fontSize: 'clamp(20px, 3.4vw, 34px)',
          letterSpacing: '0.02em',
          color: 'var(--ink-strong, #18181b)',
          textShadow: 'none',
        }}
      >
        ertugrul kulak
      </span>
    </div>
  );
}
