/**
 * SGP4 worker proxy — Phase 9 Leap Step 3.
 * Lazy-loads the worker via Vite's `new Worker(new URL(...))` idiom and
 * wraps it with Comlink.
 */
import * as Comlink from 'comlink';
import type { SatAPI } from './sat.worker';

let cached: { worker: Worker; api: Comlink.Remote<SatAPI> } | null = null;

export function getSatWorker(): Comlink.Remote<SatAPI> {
  if (cached) return cached.api;
  const worker = new Worker(new URL('./sat.worker.ts', import.meta.url), { type: 'module' });
  const api = Comlink.wrap<SatAPI>(worker);
  cached = { worker, api };
  return api;
}

export function terminateSatWorker(): void {
  if (!cached) return;
  cached.worker.terminate();
  cached = null;
}
