/**
 * OSM road snapshot loader — Phase 9 Leap Step 7.
 *
 * Reads /public/data/osm-roads.json (written by scripts/build-osm-roads.mjs)
 * and exposes a FeatureCollection of LineStrings to:
 *   - src/lib/fov.ts:presetBearingsFromOsm (snap-to-road FOV bearings)
 *   - src/map/layers/roadsLayer.ts (debug PathLayer for visual verification)
 *
 * Memoized per page lifetime. Returns null on fetch failure so callers can
 * gracefully fall back to seed bearings.
 */
import type { FeatureCollection, LineString, Feature } from 'geojson';
import { dataUrl } from '../lib/paths';

export type RoadFeature = Feature<LineString, { id: number; highway: string; name?: string | null; ref?: string | null }>;
export type RoadFc = FeatureCollection<LineString, RoadFeature['properties']>;

let cached: RoadFc | null = null;
let inFlight: Promise<RoadFc | null> | null = null;

export async function loadOsmRoads(): Promise<RoadFc | null> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = (async () => {
    try {
      const res = await fetch(dataUrl('osm-roads.json'));
      if (!res.ok) return null;
      const fc = (await res.json()) as RoadFc & { empty?: boolean };
      if (fc.empty || fc.features.length === 0) return null;
      cached = fc;
      return cached;
    } catch {
      return null;
    } finally {
      inFlight = null;
    }
  })();
  return inFlight;
}
