/**
 * Map event legend — a side-of-map key for the C2 / OSINT event markers the
 * map paints, with truthful colour codes.
 *
 * The swatch colours below are the SAME literal RGB triples the deck.gl layers
 * use (`map/layers/incidentsPulseLayer.ts` TYPE_COLOR + `map/layers/osintLayer.ts`
 * CATEGORY_COLOR). They are intrinsic data encodings (red = collapse, orange =
 * fire, …) — identical in both themes — so the swatches are inline rgb() to
 * mirror the markers exactly. The panel chrome is themed via `glass-panel`
 * tokens, so it harmonises with the pristine / tactical themes.
 *
 * Togglable: collapses to a compact pill (state in the store, `legendEnabled`).
 */
import { Layers, Minus } from 'lucide-react';
import { useStore } from '../../store';
import { REAL_SYMBOL_LEGEND } from '../../lib/realSymbols';

interface LegendRow {
  /** rgb triple matching the on-map marker fill. */
  rgb: [number, number, number];
  /** Turkish label(s) sharing this colour code. */
  label: string;
}

/** Event classes, grouped by the colour the map actually renders. */
const EVENT_ROWS: ReadonlyArray<LegendRow> = [
  { rgb: [230, 57, 70], label: 'Çöküntü · MASCAL · Mahsur' },
  { rgb: [255, 138, 0], label: 'Yangın' },
  { rgb: [107, 182, 255], label: 'Sel · Su Baskını' },
  { rgb: [255, 220, 100], label: 'Gaz Kaçağı · Sızıntı' },
  { rgb: [200, 180, 255], label: 'HAZMAT' },
];

function rgbCss([r, g, b]: [number, number, number]): string {
  return `rgb(${r}, ${g}, ${b})`;
}

export function MapLegend() {
  const open = useStore((s) => s.legendEnabled);
  const toggle = useStore((s) => s.toggleLegend);

  if (!open) {
    return (
      <button
        type="button"
        data-testid="legend-toggle"
        className="map-legend__pill glass-panel glass-panel--float glass-panel--pill glass-panel--interactive"
        onClick={toggle}
        aria-label="Olay lejantını göster"
      >
        <Layers size={12} />
        LEJANT
      </button>
    );
  }

  return (
    <aside className="map-legend glass-panel glass-panel--float" data-testid="map-legend">
      <header className="map-legend__head">
        <Layers size={12} />
        <span className="map-legend__title">OLAY KATMANI</span>
        <span className="map-legend__spacer" />
        <button
          type="button"
          data-testid="legend-toggle"
          className="map-legend__collapse"
          onClick={toggle}
          aria-label="Olay lejantını gizle"
        >
          <Minus size={12} />
        </button>
      </header>
      <ul className="map-legend__list">
        {EVENT_ROWS.map((row) => (
          <li key={row.label} className="map-legend__row">
            <span
              className="map-legend__swatch"
              style={{ background: rgbCss(row.rgb) }}
              aria-hidden="true"
            />
            <span className="map-legend__label">{row.label}</span>
          </li>
        ))}
      </ul>
      <div className="map-legend__symbols">
        <span className="map-legend__section-label">BİRİM SEMBOLLERİ</span>
        <ul className="map-legend__symbol-grid">
          {REAL_SYMBOL_LEGEND.map((s) => (
            <li key={s.key} className="map-legend__symbol-row">
              <span className="map-legend__symbol-chip" aria-hidden="true">
                <img src={s.file} alt="" width={18} height={18} loading="lazy" />
              </span>
              <span className="map-legend__symbol-label">{s.label}</span>
            </li>
          ))}
        </ul>
      </div>

      <div className="map-legend__damage">
        <span className="map-legend__damage-label">HASAR YOĞUNLUĞU</span>
        <span className="map-legend__damage-bar" aria-hidden="true" />
        <div className="map-legend__damage-scale">
          <span>düşük</span>
          <span>yüksek</span>
        </div>
      </div>
    </aside>
  );
}
