/**
 * Routable road graph for first-responder patrolling.
 *
 * Wraps the baked IBB road-graph (nodes + undirected weighted edges) with:
 *   • a grid spatial index for O(1)-ish nearest-node queries,
 *   • connected-component labelling (routing is restricted to the largest
 *     component so a unit never gets stranded on an island),
 *   • A* shortest-path routing (haversine heuristic),
 *   • patrol-waypoint sampling within a radius.
 *
 * Pure data structure — no React, no DOM. Built once from RoadGraphData.
 */
import type { RoadGraphData } from '../feeds/roadGraph';

interface AdjEntry {
  to: number;
  w: number;
}

const EARTH_R = 6371000;
function haversine(lng1: number, lat1: number, lng2: number, lat2: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_R * Math.asin(Math.min(1, Math.sqrt(a)));
}

export class RoadGraph {
  private readonly nodes: number[]; // flat [lng,lat,...]
  private readonly adj: AdjEntry[][];
  private readonly comp: Int32Array;
  private readonly largestComp: number;
  /** Grid spatial index: cellKey -> node ids (largest component only). */
  private readonly grid = new Map<string, number[]>();
  private readonly cell = 0.005; // ~500 m cells
  readonly nodeCount: number;

  constructor(data: RoadGraphData) {
    this.nodes = data.nodes;
    this.nodeCount = data.nodes.length / 2;
    this.adj = Array.from({ length: this.nodeCount }, () => [] as AdjEntry[]);
    for (let e = 0; e < data.edges.length; e += 3) {
      const a = data.edges[e]!;
      const b = data.edges[e + 1]!;
      const w = data.edges[e + 2]!;
      this.adj[a]!.push({ to: b, w });
      this.adj[b]!.push({ to: a, w });
    }
    // Connected components (iterative DFS).
    this.comp = new Int32Array(this.nodeCount).fill(-1);
    const sizes: number[] = [];
    let nComp = 0;
    for (let s = 0; s < this.nodeCount; s++) {
      if (this.comp[s] !== -1) continue;
      let size = 0;
      const stack = [s];
      this.comp[s] = nComp;
      while (stack.length) {
        const u = stack.pop()!;
        size++;
        for (const { to } of this.adj[u]!) {
          if (this.comp[to] === -1) {
            this.comp[to] = nComp;
            stack.push(to);
          }
        }
      }
      sizes.push(size);
      nComp++;
    }
    this.largestComp = sizes.indexOf(Math.max(...sizes));
    // Spatial index over routable (largest-component) nodes only.
    for (let i = 0; i < this.nodeCount; i++) {
      if (this.comp[i] !== this.largestComp) continue;
      const key = this.cellKey(this.nodes[i * 2]!, this.nodes[i * 2 + 1]!);
      const arr = this.grid.get(key);
      if (arr) arr.push(i);
      else this.grid.set(key, [i]);
    }
  }

  private cellKey(lng: number, lat: number): string {
    return `${Math.floor(lng / this.cell)},${Math.floor(lat / this.cell)}`;
  }

  /** Cached list of routable grid cells, for uniform spawn sampling. */
  private gridCells: number[][] | null = null;

  /**
   * A uniformly-sampled routable node (largest component only). Picks a grid
   * cell uniformly first, then a node within it — this avoids clustering toward
   * dense cells that a flat node-list sample would produce. `rand` is an
   * injected RNG so generation is deterministic.
   */
  randomRoutableNode(rand: () => number): number {
    if (!this.gridCells) this.gridCells = Array.from(this.grid.values());
    const cells = this.gridCells;
    if (cells.length === 0) return 0;
    const cell = cells[Math.floor(rand() * cells.length)]!;
    return cell[Math.floor(rand() * cell.length)]!;
  }

  coord(node: number): [number, number] {
    return [this.nodes[node * 2]!, this.nodes[node * 2 + 1]!];
  }

  isRoutable(node: number): boolean {
    return this.comp[node] === this.largestComp;
  }

  /** Nearest routable node to a lng/lat, expanding the grid search ring. */
  nearestNode(lng: number, lat: number): number {
    const cx = Math.floor(lng / this.cell);
    const cy = Math.floor(lat / this.cell);
    let best = -1;
    let bestD = Infinity;
    for (let ring = 0; ring <= 40; ring++) {
      for (let dx = -ring; dx <= ring; dx++) {
        for (let dy = -ring; dy <= ring; dy++) {
          // Only scan the new outer ring cells.
          if (ring > 0 && Math.abs(dx) !== ring && Math.abs(dy) !== ring) continue;
          const arr = this.grid.get(`${cx + dx},${cy + dy}`);
          if (!arr) continue;
          for (const i of arr) {
            const d = haversine(lng, lat, this.nodes[i * 2]!, this.nodes[i * 2 + 1]!);
            if (d < bestD) {
              bestD = d;
              best = i;
            }
          }
        }
      }
      // Once we have a hit and searched one extra ring beyond it, stop.
      if (best !== -1 && ring >= 2) break;
    }
    return best;
  }

  /** A* shortest path (node-index list, inclusive of start & goal). Empty on failure. */
  route(start: number, goal: number, maxExpand = 200_000): number[] {
    if (start === goal) return [start];
    if (this.comp[start] !== this.comp[goal]) return [];
    const gScore = new Map<number, number>();
    const came = new Map<number, number>();
    const [glng, glat] = this.coord(goal);
    const h = (n: number) => haversine(this.nodes[n * 2]!, this.nodes[n * 2 + 1]!, glng, glat);
    // Binary-heap open set.
    const heap = new MinHeap();
    gScore.set(start, 0);
    heap.push(start, h(start));
    let expanded = 0;
    while (heap.size > 0) {
      const current = heap.pop()!;
      if (current === goal) return this.reconstruct(came, current);
      if (++expanded > maxExpand) break;
      const gc = gScore.get(current)!;
      for (const { to, w } of this.adj[current]!) {
        const tentative = gc + w;
        if (tentative < (gScore.get(to) ?? Infinity)) {
          came.set(to, current);
          gScore.set(to, tentative);
          heap.push(to, tentative + h(to));
        }
      }
    }
    return [];
  }

  private reconstruct(came: Map<number, number>, current: number): number[] {
    const path = [current];
    while (came.has(current)) {
      current = came.get(current)!;
      path.push(current);
    }
    path.reverse();
    return path;
  }

  /** A routable node within [minM, maxM] of an origin node, else the nearest. */
  randomWaypointNear(origin: number, minM = 800, maxM = 3500): number {
    const [olng, olat] = this.coord(origin);
    const candidates: number[] = [];
    const rings = Math.ceil(maxM / 1000 / (this.cell * 111)) + 1;
    const cx = Math.floor(olng / this.cell);
    const cy = Math.floor(olat / this.cell);
    for (let dx = -rings; dx <= rings; dx++) {
      for (let dy = -rings; dy <= rings; dy++) {
        const arr = this.grid.get(`${cx + dx},${cy + dy}`);
        if (!arr) continue;
        for (const i of arr) {
          const d = haversine(olng, olat, this.nodes[i * 2]!, this.nodes[i * 2 + 1]!);
          if (d >= minM && d <= maxM) candidates.push(i);
        }
      }
    }
    if (candidates.length === 0) return origin;
    return candidates[Math.floor(Math.random() * candidates.length)]!;
  }
}

/** Tiny binary min-heap keyed by priority; stores node ids. */
class MinHeap {
  private ids: number[] = [];
  private pri: number[] = [];
  get size(): number {
    return this.ids.length;
  }
  push(id: number, p: number): void {
    this.ids.push(id);
    this.pri.push(p);
    let i = this.ids.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.pri[parent]! <= this.pri[i]!) break;
      this.swap(i, parent);
      i = parent;
    }
  }
  pop(): number | undefined {
    if (this.ids.length === 0) return undefined;
    const top = this.ids[0]!;
    const lastId = this.ids.pop()!;
    const lastPri = this.pri.pop()!;
    if (this.ids.length > 0) {
      this.ids[0] = lastId;
      this.pri[0] = lastPri;
      let i = 0;
      const n = this.ids.length;
      for (;;) {
        const l = 2 * i + 1;
        const r = 2 * i + 2;
        let smallest = i;
        if (l < n && this.pri[l]! < this.pri[smallest]!) smallest = l;
        if (r < n && this.pri[r]! < this.pri[smallest]!) smallest = r;
        if (smallest === i) break;
        this.swap(i, smallest);
        i = smallest;
      }
    }
    return top;
  }
  private swap(a: number, b: number): void {
    [this.ids[a], this.ids[b]] = [this.ids[b]!, this.ids[a]!];
    [this.pri[a], this.pri[b]] = [this.pri[b]!, this.pri[a]!];
  }
}
