import { useC2, type C2Column as Col } from '../../store/c2';
import type { C2Card as Card } from '../../store/c2';
import { C2CardView } from './Card';
import { useDnd } from './useDnd';

interface ColumnProps {
  col: Col;
  cards: Card[];
}

const COLUMN_LABELS_TR: Record<Col, { short: string; long: string }> = {
  DELIBERATE: { short: 'DELIBERATE', long: 'Önceden Planlı' },
  DYNAMIC: { short: 'DYNAMIC', long: 'Acil Tetik' },
  PENDING: { short: 'PENDING', long: 'Eşleşme Bekliyor' },
  PAIRED: { short: 'PAIRED', long: 'Eşleşti' },
  EXECUTION: { short: 'EXECUTION', long: 'Müdahale Sürüyor' },
  COMPLETE: { short: 'COMPLETE', long: 'Tamamlandı' },
};

export function C2ColumnView({ col, cards }: ColumnProps) {
  const moveCard = useC2((s) => s.moveCard);
  const { draggingId, onDragStart, onDragEnd, onDragOver, onDrop } = useDnd();

  const handleDrop = (e: React.DragEvent) =>
    onDrop(e, col, (cardId) => moveCard(cardId, col));

  const labels = COLUMN_LABELS_TR[col];

  return (
    <div
      className="c2-col glass-panel glass-panel--deep"
      onDragOver={onDragOver}
      onDrop={handleDrop}
    >
      <header className="c2-col__head">
        <span className="c2-col__name">{labels.short}</span>
        <span className="c2-col__sub">{labels.long}</span>
        <span className="c2-col__count">{cards.length}</span>
      </header>
      <div className="c2-col__body">
        {cards.length === 0 ? (
          <div className="c2-col__empty">— boş —</div>
        ) : (
          cards.map((c) => (
            <C2CardView
              key={c.id}
              card={c}
              draggable
              onDragStart={onDragStart}
              onDragEnd={onDragEnd}
            />
          ))
        )}
      </div>
      {draggingId && <div className="c2-col__dropzone-hint" aria-hidden />}
    </div>
  );
}
