/**
 * Selectors for the entity store. Keep filtering logic out of components and
 * out of layer builders so it stays cheap and consistent.
 */

import type { Entity, EntityKind } from '../types/entity';
import type { EntityMap } from './entities';

/** Filter entities by kind, returning a plain array. */
export function entitiesByKind(map: EntityMap, kind: EntityKind): Entity[] {
  const out: Entity[] = [];
  for (const e of map.values()) {
    if (e.kind === kind) out.push(e);
  }
  return out;
}

/** Filter entities by source. */
export function entitiesBySource(map: EntityMap, source: Entity['source']): Entity[] {
  const out: Entity[] = [];
  for (const e of map.values()) {
    if (e.source === source) out.push(e);
  }
  return out;
}

/** Sort entities by severity (flash → info → absent). */
const SEV_ORDER: Record<Entity['severity'], number> = {
  flash: 0,
  immediate: 1,
  priority: 2,
  routine: 3,
  info: 4,
  absent: 5,
};

export function sortBySeverity(arr: Entity[]): Entity[] {
  return [...arr].sort((a, b) => SEV_ORDER[a.severity] - SEV_ORDER[b.severity]);
}
