/**
 * Live weather overlay — floating glass panel on the OPS map (top-right, under
 * the search bar). Current İstanbul conditions + a 6-hour outlook from the
 * Open-Meteo feed. Wind + precipitation are surfaced because they drive
 * fire/HAZMAT plume spread and flood risk during a crisis.
 *
 * Hideable: collapses to a compact temperature pill (local state).
 */
import { useState, type ReactNode } from 'react';
import {
  Cloud,
  CloudDrizzle,
  CloudFog,
  CloudLightning,
  CloudRain,
  CloudSnow,
  CloudSun,
  Sun,
  Wind,
  Droplets,
  Minus,
  ChevronDown,
} from 'lucide-react';
import { useWeather, windCompass, type WeatherIcon } from '../feeds/weather';

function iconFor(icon: WeatherIcon, size = 14): ReactNode {
  switch (icon) {
    case 'clear':
      return <Sun size={size} />;
    case 'partly':
      return <CloudSun size={size} />;
    case 'cloud':
      return <Cloud size={size} />;
    case 'fog':
      return <CloudFog size={size} />;
    case 'drizzle':
      return <CloudDrizzle size={size} />;
    case 'rain':
      return <CloudRain size={size} />;
    case 'snow':
      return <CloudSnow size={size} />;
    case 'storm':
      return <CloudLightning size={size} />;
  }
}

export function WeatherOverlay(): ReactNode {
  const { data, loading, error } = useWeather();
  const [open, setOpen] = useState(true);

  if (!open) {
    return (
      <button
        type="button"
        data-testid="weather-pill"
        className="weather-overlay__pill glass-panel glass-panel--float glass-panel--pill glass-panel--interactive"
        onClick={() => setOpen(true)}
        aria-label="Hava durumunu göster"
      >
        {data ? iconFor(data.now.icon, 13) : <Cloud size={13} />}
        {data ? `${data.now.tempC}°` : 'HAVA'}
      </button>
    );
  }

  return (
    <aside className="weather-overlay glass-panel glass-panel--float" data-testid="weather-overlay">
      <header className="weather-overlay__head">
        <span className="weather-overlay__title">HAVA · İSTANBUL</span>
        <span className="weather-overlay__src">open-meteo · CANLI</span>
        <button
          type="button"
          className="weather-overlay__collapse"
          onClick={() => setOpen(false)}
          aria-label="Hava durumunu gizle"
        >
          <Minus size={12} />
        </button>
      </header>

      {loading && !data && <div className="weather-overlay__muted">Hava verisi alınıyor…</div>}
      {error && !data && <div className="weather-overlay__muted">Hava verisi yok</div>}

      {data && (
        <>
          <div className="weather-overlay__now">
            <span className="weather-overlay__now-icon">{iconFor(data.now.icon, 30)}</span>
            <span className="weather-overlay__temp">{data.now.tempC}°</span>
            <div className="weather-overlay__now-meta">
              <span className="weather-overlay__cond">{data.now.label}</span>
              <span className="weather-overlay__feels">Hissedilen {data.now.feelsC}°</span>
            </div>
          </div>

          <div className="weather-overlay__stats">
            <span className="weather-overlay__stat">
              <Wind size={11} /> {data.now.windKmh} km/s {windCompass(data.now.windDir)}
            </span>
            <span className="weather-overlay__stat">
              <Droplets size={11} /> %{data.now.humidity} nem
            </span>
          </div>

          {data.next.length > 0 && (
            <div className="weather-overlay__forecast">
              {data.next.map((h) => (
                <div key={h.time} className="weather-overlay__hour" title={`${h.label} · yağış %${h.precipPct}`}>
                  <span className="weather-overlay__hour-time">{h.hourLabel}</span>
                  <span className="weather-overlay__hour-icon">{iconFor(h.icon, 14)}</span>
                  <span className="weather-overlay__hour-temp">{h.tempC}°</span>
                  <span
                    className="weather-overlay__hour-precip"
                    style={{ opacity: h.precipPct > 5 ? 1 : 0.3 }}
                  >
                    <ChevronDown size={8} />
                    {h.precipPct}%
                  </span>
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </aside>
  );
}
