/**
 * C2 board store slice — Kanban state for the Komuta Kontrol tab.
 *
 * Each card represents a task threaded through the AKOM dispatch pipeline.
 * Cards carry an `entityId` (UUID) so dragging a card on the board moves the
 * underlying entity's pipeline stage; clicking the card selects the same
 * entity everywhere else (map, list, modal).
 *
 * Persistence: `localStorage` keyed at `akom:c2:v1` so an operator's board
 * survives reload. Versioned key — bump on shape change.
 */

import { create } from 'zustand';

/** Pipeline columns — left to right reflects time-to-execution.
 *  DELIBERATE  = pre-planned dispatch (drills, scheduled patrols)
 *  DYNAMIC     = emergent — fresh detections needing triage
 *  PENDING     = waiting for an asset to be paired
 *  PAIRED      = asset selected, awaiting approval
 *  EXECUTION   = dispatched, mission in progress
 *  COMPLETE    = closed (success or terminated) */
export const C2_COLUMNS = [
  'DELIBERATE',
  'DYNAMIC',
  'PENDING',
  'PAIRED',
  'EXECUTION',
  'COMPLETE',
] as const;
export type C2Column = (typeof C2_COLUMNS)[number];

export interface C2Card {
  id: string;
  /** Optional UUID of an entity from the unified entity store. When set, card
   *  selection mirrors entity selection across all panels. */
  entityId: string | null;
  col: C2Column;
  /** Short headline shown in card body. */
  type: string;
  /** Sub-label below the headline. */
  kind: string;
  /** Severity drives the SevGlyph in the card head. */
  severity: 'flash' | 'immediate' | 'priority' | 'routine' | 'info' | 'absent';
  /** Glyph color hint (CSS var or hex). Optional. */
  glyphColor?: string;
  /** Unix ms of last edit; rendered as relative time. */
  editedAt: number;
  /** Expired = mission window passed. Visual cue, not state. */
  expired: boolean;
  /** Urgent = needs immediate operator attention. */
  urgent: boolean;
  /** Geo location for the Konum section + "Haritada Göster". */
  location?: { lat: number; lng: number; district?: string };
  /** Paired responder unit (Eşleştirme section). */
  pairedUnitId?: string | null;
  pairedUnitLabel?: string | null;
  /** Approval chain (Onay section). */
  approvals?: { role: string; status: ApprovalStatus; ts?: number }[];
  /** Intelligence notes (İstihbarat section). */
  intelNotes?: string[];
}

export type ApprovalStatus = 'pending' | 'approved' | 'rejected';

/** localStorage key — bump on shape change. v2 added optional detail fields
 *  (location / pairing / approvals / intel) for the Maven detail drawer. */
const STORAGE_KEY = 'akom:c2:v2';

function loadCards(): C2Card[] {
  if (typeof window === 'undefined') return seedCards();
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return seedCards();
    const parsed = JSON.parse(raw) as C2Card[];
    if (!Array.isArray(parsed)) return seedCards();
    return parsed;
  } catch {
    return seedCards();
  }
}

function saveCards(cards: C2Card[]): void {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
  } catch {
    /* quota or private-mode — silently swallow */
  }
}

