interface C2State {
  cards: C2Card[];
  selectedCardId: string | null;
  moveCard(cardId: string, toCol: C2Column): void;
  selectCard(id: string | null): void;
  /** Pair a responder unit to a card; advances DYNAMIC/PENDING → PAIRED. */
  pairCard(cardId: string, unitId: string, unitLabel: string): void;
  /** Record (or replace) an approval for a role on a card. */
  addApproval(cardId: string, role: string, status: ApprovalStatus): void;
  /** Prepend a new card (e.g. spawned from an OSINT observation). */
  addCard(card: C2Card): void;
  reset(): void;
}

export const useC2 = create<C2State>((set, get) => ({
  cards: loadCards(),
  selectedCardId: null,
  moveCard: (cardId, toCol) => {
    const next = get().cards.map((c) =>
      c.id === cardId ? { ...c, col: toCol, editedAt: Date.now() } : c,
    );
    saveCards(next);
    set({ cards: next });
  },
  selectCard: (id) => set({ selectedCardId: id }),
  pairCard: (cardId, unitId, unitLabel) => {
    const next = get().cards.map((c) =>
      c.id === cardId
        ? {
            ...c,
            pairedUnitId: unitId,
            pairedUnitLabel: unitLabel,
            col: c.col === 'DYNAMIC' || c.col === 'PENDING' ? 'PAIRED' : c.col,
            editedAt: Date.now(),
          }
        : c,
    );
    saveCards(next);
    set({ cards: next });
  },
  addApproval: (cardId, role, status) => {
    const ts = Date.now();
    const next = get().cards.map((c) => {
      if (c.id !== cardId) return c;
      const others = (c.approvals ?? []).filter((a) => a.role !== role);
      return { ...c, approvals: [...others, { role, status, ts }], editedAt: ts };
    });
    saveCards(next);
    set({ cards: next });
  },
  addCard: (card) => {
    const next = [card, ...get().cards];
    saveCards(next);
    set({ cards: next, selectedCardId: card.id });
  },
  reset: () => {
    const seed = seedCards();
    saveCards(seed);
    set({ cards: seed, selectedCardId: null });
  },
}));
