/**
 * Real first-responder symbol atlas — composites the project's vector symbol
 * set (`public/symbols/*.svg` + the AFAD / HAZMAT PNGs) into a single canvas
 * sprite atlas for the deck.gl patrol IconLayer.
 *
 * Why a composited atlas instead of per-icon URLs:
 *  • Each symbol is drawn on a solid light backing disc so the (often black or
 *    multi-colour) artwork stays legible over ANY basemap — dark, light, or
 *    satellite imagery.
 *  • A single pre-built atlas renders reliably; deck.gl's on-the-fly URL packing
 *    is async and can drop frames on the first paint.
 *
 * The atlas is built once, lazily, and cached as a Promise. In non-DOM test
 * environments (no real canvas) the loader resolves to `null` and callers fall
 * back to the geometric atlas in `lib/symbology.ts`.
 */

import { assetUrl } from './paths';

/** Logical symbol keys → source file under /public/symbols. */
export type RealSymbolKey = 'amb' | 'pol' | 'fire' | 'sar' | 'heli' | 'plane' | 'hazmat' | 'afad';

const SYMBOL_FILES: Record<RealSymbolKey, string> = {
  amb: assetUrl('symbols/ambulance-healthcare-medicine-svgrepo-com.svg'),
  pol: assetUrl('symbols/police-mark-svgrepo-com.svg'),
  fire: assetUrl('symbols/fire-helmet-2-svgrepo-com.svg'),
  sar: assetUrl('symbols/us-army-helmet-svgrepo-com.svg'),
  heli: assetUrl('symbols/helicopter-svgrepo-com.svg'),
  plane: assetUrl('symbols/plane-svgrepo-com.svg'),
  hazmat: assetUrl('symbols/hazmat.png'),
  afad: assetUrl('symbols/AFAD_logo.png'),
};

/** Human labels for the on-map legend, in display order. */
export const REAL_SYMBOL_LEGEND: ReadonlyArray<{ key: RealSymbolKey; label: string; file: string }> = [
  { key: 'amb', label: 'Ambulans · UMKE', file: SYMBOL_FILES.amb },
  { key: 'pol', label: 'Polis · Kolluk', file: SYMBOL_FILES.pol },
  { key: 'fire', label: 'İtfaiye', file: SYMBOL_FILES.fire },
  { key: 'sar', label: 'Arama Kurtarma', file: SYMBOL_FILES.sar },
  { key: 'heli', label: 'Helikopter · HEMS', file: SYMBOL_FILES.heli },
  { key: 'plane', label: 'Sabit Kanat · İHA', file: SYMBOL_FILES.plane },
  { key: 'hazmat', label: 'HAZMAT · Kimyasal', file: SYMBOL_FILES.hazmat },
  { key: 'afad', label: 'AFAD', file: SYMBOL_FILES.afad },
];

/**
 * Resolve a unit's symbol key from its type, then modality as a fallback.
 * Handles both the data file's vocabulary (`ambulance` / `fire` / `patrol` /
 * `medevac` / `recon` / `cargo` / `overhead`) and the short responder codes
 * (AMB / POL / ITFK / SAR / HEMS / UAV / …).
 */
export function realSymbolForUnit(type: string, modality?: string): RealSymbolKey {
  switch (type.toLowerCase()) {
    case 'ambulance':
    case 'amb':
    case 'umke':
      return 'amb';
    case 'fire':
    case 'itfk':
    case 'tedas':
      return 'fire';
    case 'patrol':
    case 'police':
    case 'pol':
    case 'k9':
      return 'pol';
    case 'sar':
    case 'search':
    case 'rescue':
      return 'sar';
    case 'afad':
      return 'afad';
    case 'medevac':
    case 'hems':
    case 'recon':
      return 'heli';
    case 'cargo':
    case 'overhead':
    case 'uav':
      return 'plane';
    default:
      break;
  }
  switch (modality) {
    case 'heli':
      return 'heli';
    case 'fixed':
      return 'plane';
    case 'naval':
      return 'pol';
    default:
      return 'pol';
  }
}

export interface IconMapEntry {
  x: number;
  y: number;
  width: number;
  height: number;
  anchorX: number;
  anchorY: number;
  mask: boolean;
}

export interface RealSymbolAtlas {
  atlas: string;
  mapping: Record<string, IconMapEntry>;
}

const CELL = 128; // source resolution per cell — crisp at any on-map size
const KEYS = Object.keys(SYMBOL_FILES) as RealSymbolKey[];
const COLS = Math.ceil(Math.sqrt(KEYS.length));
const ROWS = Math.ceil(KEYS.length / COLS);

let _cache: Promise<RealSymbolAtlas | null> | null = null;

function loadImage(src: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

/**
 * Build (or return the cached) composited symbol atlas. Each cell is a soft
 * light disc with the symbol artwork fit to ~64% of the cell, centred.
 */
export function loadRealSymbolAtlas(): Promise<RealSymbolAtlas | null> {
  if (_cache) return _cache;
  _cache = (async () => {
    if (typeof document === 'undefined') return null;
    const canvas = document.createElement('canvas');
    canvas.width = COLS * CELL;
    canvas.height = ROWS * CELL;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    const images = await Promise.all(KEYS.map((k) => loadImage(SYMBOL_FILES[k])));
    const mapping: Record<string, IconMapEntry> = {};

    KEYS.forEach((key, i) => {
      const col = i % COLS;
      const row = Math.floor(i / COLS);
      const ox = col * CELL;
      const oy = row * CELL;
      const cx = ox + CELL / 2;
      const cy = oy + CELL / 2;

      // Backing disc — high-contrast, faint ring so artwork reads on any basemap.
      ctx.save();
      ctx.beginPath();
      ctx.arc(cx, cy, CELL * 0.46, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(248, 250, 252, 0.97)';
      ctx.fill();
      ctx.lineWidth = CELL * 0.045;
      ctx.strokeStyle = 'rgba(10, 14, 22, 0.85)';
      ctx.stroke();
      ctx.restore();

      const img = images[i];
      if (img && img.width > 0 && img.height > 0) {
        const target = CELL * 0.62;
        const scale = Math.min(target / img.width, target / img.height);
        const w = img.width * scale;
        const h = img.height * scale;
        ctx.drawImage(img, cx - w / 2, cy - h / 2, w, h);
      }

      mapping[key] = {
        x: ox,
        y: oy,
        width: CELL,
        height: CELL,
        anchorX: CELL / 2,
        anchorY: CELL / 2,
        mask: false,
      };
    });

    const url = canvas.toDataURL('image/png');
    if (!url.startsWith('data:image/png')) return null;
    return { atlas: url, mapping };
  })();
  return _cache;
}
