import type { UtilityNetwork } from '../../feeds/utilities';
import { SourceChip } from '../../lib/sourceTag';

const STATUS_COLOR: Record<string, string> = {
  ok: 'var(--okay)',
  degraded: 'var(--amber)',
  down: 'var(--klaxon)',
  warn: 'var(--amber)',
  crit: 'var(--klaxon)',
};

interface Props {
  net: UtilityNetwork;
}

/** Lay nodes out by kind (source on left, distribution middle, consumer right). */
function layout(net: UtilityNetwork) {
  const W = 460;
  const H = 220;
  const PAD = 24;
  const byKind = {
    source: net.nodes.filter((n) => n.kind === 'source'),
    distribution: net.nodes.filter((n) => n.kind === 'distribution'),
    consumer: net.nodes.filter((n) => n.kind === 'consumer'),
  };
  const xByKind = { source: PAD, distribution: W / 2, consumer: W - PAD };
  const positions = new Map<string, { x: number; y: number }>();
  for (const kind of ['source', 'distribution', 'consumer'] as const) {
    const arr = byKind[kind];
    const x = xByKind[kind];
    arr.forEach((n, i) => {
      const y = PAD + ((H - 2 * PAD) * (i + 0.5)) / arr.length;
      positions.set(n.id, { x, y });
    });
  }
  return { W, H, positions };
}

export function NetworkPanel({ net }: Props) {
  const { W, H, positions } = layout(net);

  const downCount = net.nodes.filter((n) => n.status === 'down').length;

  return (
    <section className="ops-panel glass-panel glass-panel--deep altyp-panel">
      <header className="ops-panel__title">
        {net.provider}
        <SourceChip source="SIM" />
        {downCount > 0 && (
          <span style={{ marginLeft: 'auto', color: 'var(--klaxon)' }}>
            ▲ {downCount} kayıp
          </span>
        )}
      </header>
      <div className="altyp-panel__body">
        <svg viewBox={`0 0 ${W} ${H}`} style={{ width: '100%', height: '100%' }}>
          {net.edges.map((e, i) => {
            const a = positions.get(e.from);
            const b = positions.get(e.to);
            if (!a || !b) return null;
            return (
              <g key={i}>
                <line
                  x1={a.x}
                  y1={a.y}
                  x2={b.x}
                  y2={b.y}
                  stroke={STATUS_COLOR[e.status]}
                  strokeWidth={Math.max(1, e.capacity / 60)}
                  opacity={e.status === 'down' ? 1 : 0.7}
                  strokeDasharray={e.status === 'down' ? '4 3' : undefined}
                />
              </g>
            );
          })}
          {net.nodes.map((n) => {
            const p = positions.get(n.id);
            if (!p) return null;
            return (
              <g key={n.id}>
                <circle
                  cx={p.x}
                  cy={p.y}
                  r={6}
                  fill={STATUS_COLOR[n.status]}
                  stroke="var(--bg-void)"
                  strokeWidth={1.2}
                />
                <text
                  x={p.x}
                  y={p.y + 18}
                  fontFamily="var(--font-mono)"
                  fontSize={9}
                  fill="var(--bone-mute)"
                  textAnchor="middle"
                >
                  {n.label}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      <footer className="altyp-panel__metrics">
        {net.metrics.map((m) => (
          <div key={m.label} className="hud-data-cell altyp-metric">
            <span className="altyp-metric__label">{m.label}</span>
            <span
              className="altyp-metric__value"
              style={{ color: STATUS_COLOR[m.state] }}
            >
              {m.value}
            </span>
          </div>
        ))}
      </footer>
    </section>
  );
}
