import { useEffect, useState } from 'react';
import { useStore } from '../../store';
import { entitiesByKind } from '../../store/selectors';
import { SourceChip } from '../../lib/sourceTag';
import { SevGlyph } from '../../lib/sevGlyph';

const KLAXON_AFTER_MS = 15 * 60_000;

function fmtAge(ms: number, now: number): string {
  const ageS = Math.max(0, Math.floor((now - ms) / 1000));
  if (ageS < 60) return `${ageS}s`;
  if (ageS < 3600) return `${Math.floor(ageS / 60)}d`;
  return `${Math.floor(ageS / 3600)}sa`;
}

export function EltList() {
  const entities = useStore((s) => s.entities);
  const beacons = entitiesByKind(entities, 'beacon');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), 5000);
    return () => window.clearInterval(id);
  }, []);

  return (
    <section className="ops-panel glass-panel glass-panel--deep elt-list">
      <header className="ops-panel__title">
        ELT · ACİL VERİCİ · {beacons.length}
      </header>
      {beacons.length === 0 && (
        <div className="elt-list__empty">— aktif verici yok —</div>
      )}
      {beacons.map((b) => {
        const ts = b.lastSeen;
        const isStale = now - ts > KLAXON_AFTER_MS;
        const mhz = (b.attrs.mhz as number) ?? 406;
        const type = (b.attrs.type as string) ?? 'ELT';
        const id = (b.attrs.beaconId as string) ?? b.id;
        return (
          <div
            key={b.id}
            className={`hud-data-cell hud-data-cell--hover elt-row ${isStale ? 'is-stale' : ''}`}
            style={{
              display: 'grid',
              gridTemplateColumns: '14px 1fr auto auto',
              gap: 8,
              alignItems: 'center',
            }}
          >
            <SevGlyph severity={isStale ? 'flash' : 'immediate'} pulse={isStale} />
            <span>
              {type} · {id}
            </span>
            <span style={{ color: 'var(--bone-mute)' }}>{mhz.toFixed(2)} MHz</span>
            <span style={{ color: isStale ? 'var(--klaxon)' : 'var(--bone-mute)' }}>
              {fmtAge(ts, now)}
              <SourceChip source={isStale ? 'STALE' : 'OSINT'} />
            </span>
          </div>
        );
      })}
    </section>
  );
}
