/**
 * 3D PTZ camera bodies + FOV frustums — Phase 2 (spatial-intelligence).
 *
 * Renders 632 PTZ cameras as instanced 3D meshes via deck.gl SimpleMeshLayer
 * (same WebGL context as every other layer — no Three.js, GPU picking for
 * free). Two layers are returned:
 *   • camera-bodies  — a procedural housing/lens mesh, oriented by bearing,
 *     pickable for click (open detail dock) and hover (instant preview).
 *   • camera-frustums — a translucent FOV pyramid scaled per-camera from the
 *     lens HFOV/VFOV and range, tilted down toward the ground.
 *
 * Bearing per camera comes from the OSM snap-to-road presets when available,
 * else a deterministic seed (mirrors fovLayer's SIM fallback) so orientation is
 * stable frame-to-frame.
 */
import { SimpleMeshLayer } from '@deck.gl/mesh-layers';
import type { Layer } from '@deck.gl/core';
import { cameraBodyMesh, frustumMesh } from './cameraGeometry';
import { lensProfileFromName, vfovFromHfov } from '../../lib/fov';
import type { PtzCamera, PresetBearing } from '../../types/ptz';

const DEG = Math.PI / 180;
const APEX_HEIGHT_M = 9;
/** Exaggerate the metre-scale body so it reads at city zoom. */
const BODY_SIZE_SCALE = 6;

export interface CameraMeshHover {
  camId: number;
  /** Screen-space pixel coordinates of the pointer (for the preview portal). */
  x: number;
  y: number;
}

export interface CameraMeshOpts {
  cameras: ReadonlyArray<PtzCamera>;
  /** OSM snap-to-road bearings; falls back to a deterministic seed per camera. */
  presets?: ReadonlyArray<PresetBearing> | null;
  selectedId?: number | null;
  hoveredId?: number | null;
  onClick?: (camId: number) => void;
  onHover?: (hover: CameraMeshHover | null) => void;
}

/** Representative bearing (deg, compass) for a camera's body + frustum. */
function bearingFor(camId: number, index: Map<number, number>): number {
  const b = index.get(camId);
  if (b !== undefined) return b;
  return (camId * 37) % 360; // deterministic seed (matches fovLayer SIM)
}

/** Compass bearing (CW from north) → SimpleMeshLayer yaw (CCW math angle). */
function yawFromBearing(bearingDeg: number): number {
  return 90 - bearingDeg;
}

export function buildCameraMeshLayers(opts: CameraMeshOpts): Layer[] {
  const { cameras } = opts;
  if (cameras.length === 0) return [];

  // First preset bearing per camera (lowest preset index wins).
  const bIndex = new Map<number, number>();
  for (const p of opts.presets ?? []) {
    if (!bIndex.has(p.camId)) bIndex.set(p.camId, p.bearingDeg);
  }

  const body = cameraBodyMesh();
  const frustum = frustumMesh();

  const bodies = new SimpleMeshLayer<PtzCamera>({
    id: 'camera-bodies',
    data: cameras as PtzCamera[],
    mesh: body,
    sizeScale: BODY_SIZE_SCALE,
    getPosition: (c) => [c.lng, c.lat, 0],
    getOrientation: (c) => [0, yawFromBearing(bearingFor(c.id, bIndex)), 0],
    getColor: (c) => {
      if (c.id === opts.selectedId) return [56, 189, 248, 255];
      if (c.id === opts.hoveredId) return [125, 211, 252, 255];
      return [203, 213, 225, 235];
    },
    material: false,
    pickable: true,
    onClick: opts.onClick
      ? (info) => {
          if (info.object) opts.onClick!((info.object as PtzCamera).id);
          return true;
        }
      : undefined,
    onHover: opts.onHover
      ? (info) => {
          if (info.object && info.x != null && info.y != null) {
            opts.onHover!({ camId: (info.object as PtzCamera).id, x: info.x, y: info.y });
          } else {
            opts.onHover!(null);
          }
          return true;
        }
      : undefined,
    updateTriggers: {
      getColor: [opts.selectedId, opts.hoveredId],
      getOrientation: opts.presets,
    },
  });

  const frustums = new SimpleMeshLayer<PtzCamera>({
    id: 'camera-frustums',
    data: cameras as PtzCamera[],
    mesh: frustum,
    sizeScale: 1,
    getPosition: (c) => [c.lng, c.lat, 0],
    getTranslation: [0, 0, APEX_HEIGHT_M],
    getOrientation: (c) => {
      const lens = lensProfileFromName(c.name);
      // Tilt the cone down so the far edge approaches the ground at range.
      const pitch = -Math.atan(APEX_HEIGHT_M / lens.rFarDefault) / DEG;
      return [pitch, yawFromBearing(bearingFor(c.id, bIndex)), 0];
    },
    getScale: (c) => {
      const lens = lensProfileFromName(c.name);
      const r = lens.rFarDefault;
      const halfH = (lens.hfovDeg / 2) * DEG;
      const halfV = (vfovFromHfov(lens.hfovDeg) / 2) * DEG;
      return [r, 2 * r * Math.tan(halfH), 2 * r * Math.tan(halfV)];
    },
    getColor: (c) => {
      const hot = c.id === opts.selectedId || c.id === opts.hoveredId;
      return hot ? [56, 189, 248, 90] : [59, 130, 246, 48];
    },
    material: false,
    pickable: false,
    updateTriggers: {
      getColor: [opts.selectedId, opts.hoveredId],
      getOrientation: opts.presets,
      getScale: opts.presets,
    },
  });

  return [frustums, bodies];
}
