/**
 * DataSourcesDock — dock slot 'datasources', title "Veri Kaynakları".
 *
 * A live table over the store's feedHealth map: one row per source tag with
 * its freshness (tickElapsed since lastTick), an OK/ARIZA status cell, and a
 * MOD column. The MOD cell prints MOCK for now; C3 replaces the ICAO row's
 * cell with the real OpenSky mode label + the degraded-mode note, and D1 adds
 * a SİM TICK readout. Those are left as clear seams.
 */
import { type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';
import { tickElapsed } from '../../lib/time';
import { openSkyModeLabel } from '../../feeds/opensky';
import type { SourceTag } from '../../types/entity';

export function DataSourcesDock(): ReactNode {
  const dock = useStore((s) => s.dock['datasources']);
  const feedHealth = useStore((s) => s.feedHealth);
  const simTickMs = useStore((s) => s.simTickMs);

  if (!dock.open) return null;

  const rows = Object.entries(feedHealth) as Array<
    [SourceTag, { lastTick: number; ok: boolean }]
  >;

  return (
    <DockPanel id="datasources" title="Veri Kaynakları">
      <div className="ds-dock">
        <table className="ds-dock__table">
          <thead>
            <tr>
              <th>KAYNAK</th>
              <th>TAZELİK</th>
              <th>DURUM</th>
              <th>MOD</th>
            </tr>
          </thead>
          <tbody>
            {rows.length === 0 && (
              <tr>
                <td colSpan={4} style={{ color: 'var(--ink-mute)' }}>
                  Henüz besleme yok
                </td>
              </tr>
            )}
            {rows.map(([source, health]) => (
              <tr key={source}>
                <td>
                  <SourceChip source={source} />
                </td>
                <td style={{ fontFamily: 'var(--font-mono)' }}>
                  {health.lastTick > 0 ? tickElapsed(health.lastTick) : '—'}
                </td>
                <td
                  style={{
                    color: health.ok ? 'var(--okay)' : 'var(--klaxon)',
                    fontFamily: 'var(--font-mono)',
                  }}
                >
                  {health.ok ? 'OK' : 'ARIZA'}
                </td>
                <td style={{ fontFamily: 'var(--font-mono)', color: 'var(--ink-mute)' }}>
                  {source === 'ICAO' ? openSkyModeLabel() : 'MOCK'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <div style={{ marginTop: 8, fontSize: 10, color: 'var(--ink-mute)', fontFamily: 'var(--font-mono)' }}>
          ICAO · Düşüş modu: 3 hata → SİM etiketli yedek
        </div>
        <div style={{ marginTop: 4, fontSize: 11, color: 'var(--ink-mid)', fontFamily: 'var(--font-mono)' }}>
          SİM TICK · {simTickMs.toFixed(1)} ms
          <SourceChip source="EST" />
        </div>
      </div>
    </DockPanel>
  );
}
