/**
 * Tab 07 — C2 Komuta Kontrol.
 *
 * Kanban pairing board, Maven-style. Six columns: DELIBERATE / DYNAMIC /
 * PENDING / PAIRED / EXECUTION / COMPLETE. Cards drag between columns;
 * board state persists in localStorage (akom:c2:v1).
 *
 * Maven pattern (per transcripts / docs/SPATIAL-INTELLIGENCE-ULTRAPLAN.md §2.1):
 * compress OODA loop into one screen. Each card carries an entity UUID, so
 * clicking the card selects the same entity on the map and in feed-inspector.
 */

import { useMemo } from 'react';
import { C2_COLUMNS, useC2 } from '../../store/c2';
import { C2ColumnView } from '../c2/Column';
import { C2DetailDrawer } from '../c2/DetailDrawer';

export function C2() {
  const cards = useC2((s) => s.cards);
  const reset = useC2((s) => s.reset);

  const byColumn = useMemo(() => {
    const m = new Map<(typeof C2_COLUMNS)[number], typeof cards>();
    for (const col of C2_COLUMNS) m.set(col, []);
    for (const c of cards) m.get(c.col)?.push(c);
    return m;
  }, [cards]);

  const urgentCount = cards.filter((c) => c.urgent).length;
  const flashCount = cards.filter((c) => c.severity === 'flash').length;

  return (
    <div className="hud-pane c2-tab">
      <header className="c2-toolbar glass-panel glass-panel--float">
        <span className="c2-toolbar__title">C2 · KOMUTA KONTROL</span>
        <span className="c2-toolbar__op">OP · MARMARA M7.5</span>
        <span className="c2-toolbar__spacer" />
        <span className="c2-toolbar__chip">TÜMÜ · {cards.length}</span>
        <span className="c2-toolbar__chip c2-toolbar__chip--klaxon">
          ▲ FLASH · {flashCount}
        </span>
        <span className="c2-toolbar__chip c2-toolbar__chip--amber">
          ► ACİL · {urgentCount}
        </span>
        <button type="button" className="c2-toolbar__reset" onClick={() => reset()}>
          PANO SIFIRLA
        </button>
      </header>
      <div className="c2-board">
        {C2_COLUMNS.map((col) => (
          <C2ColumnView key={col} col={col} cards={byColumn.get(col) ?? []} />
        ))}
      </div>
      <C2DetailDrawer />
    </div>
  );
}
