/**
 * Live weather feed — Open-Meteo (https://open-meteo.com).
 *
 * Free, key-less, CORS-enabled public forecast API — fits the cockpit's
 * no-backend constraint. Returns current conditions + a short hourly outlook
 * for İstanbul. Operationally relevant: wind drives fire/HAZMAT plume spread,
 * precipitation drives flood risk, so the OPS screen surfaces it live.
 *
 * Degrades gracefully: on any network/parse failure the hook returns
 * `{ data: null, error: true }` and the UI shows a muted "veri yok" state.
 */
import { useEffect, useState } from 'react';

/** İstanbul reference point (Sirkeci / historic peninsula). */
const LAT = 41.0;
const LNG = 28.97;

const ENDPOINT =
  `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LNG}` +
  `&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m,wind_direction_10m` +
  `&hourly=temperature_2m,precipitation_probability,weather_code` +
  `&timezone=Europe%2FIstanbul&forecast_days=2`;

/** Poll interval — weather changes slowly; 15 min keeps it live without spam. */
const POLL_MS = 15 * 60 * 1000;

export interface WeatherNow {
  tempC: number;
  feelsC: number;
  humidity: number;
  windKmh: number;
  windDir: number;
  code: number;
  label: string;
  icon: WeatherIcon;
}

export interface WeatherHour {
  time: string; // ISO local
  hourLabel: string; // "14:00"
  tempC: number;
  precipPct: number;
  code: number;
  label: string;
  icon: WeatherIcon;
}

export interface WeatherForecast {
  now: WeatherNow;
  next: WeatherHour[];
  fetchedAt: number;
}

export type WeatherIcon = 'clear' | 'partly' | 'cloud' | 'fog' | 'drizzle' | 'rain' | 'snow' | 'storm';

/** WMO weather interpretation codes → Turkish label + coarse icon bucket. */
export function wmoLabel(code: number): { label: string; icon: WeatherIcon } {
  if (code === 0) return { label: 'Açık', icon: 'clear' };
  if (code === 1 || code === 2) return { label: 'Az Bulutlu', icon: 'partly' };
  if (code === 3) return { label: 'Bulutlu', icon: 'cloud' };
  if (code === 45 || code === 48) return { label: 'Sisli', icon: 'fog' };
  if (code >= 51 && code <= 57) return { label: 'Çisenti', icon: 'drizzle' };
  if (code >= 61 && code <= 67) return { label: 'Yağmurlu', icon: 'rain' };
  if (code >= 71 && code <= 77) return { label: 'Kar', icon: 'snow' };
  if (code >= 80 && code <= 82) return { label: 'Sağanak', icon: 'rain' };
  if (code === 85 || code === 86) return { label: 'Kar Sağanağı', icon: 'snow' };
  if (code >= 95) return { label: 'Gök Gürültülü', icon: 'storm' };
  return { label: 'Bilinmiyor', icon: 'cloud' };
}

/** 16-point compass label for a wind bearing (degrees FROM). */
export function windCompass(deg: number): string {
  const dirs = ['K', 'KKD', 'KD', 'DKD', 'D', 'DGD', 'GD', 'GGD', 'G', 'GGB', 'GB', 'BGB', 'B', 'BKB', 'KB', 'KKB'];
  return dirs[Math.round(((deg % 360) / 22.5)) % 16] ?? 'K';
}

interface OpenMeteoResponse {
  current?: {
    temperature_2m?: number;
    apparent_temperature?: number;
    relative_humidity_2m?: number;
    weather_code?: number;
    wind_speed_10m?: number;
    wind_direction_10m?: number;
  };
  hourly?: {
    time?: string[];
    temperature_2m?: number[];
    precipitation_probability?: number[];
    weather_code?: number[];
  };
}

function hourLabel(iso: string): string {
  const t = iso.split('T')[1] ?? '';
  return t.slice(0, 5);
}

export async function fetchWeather(signal?: AbortSignal): Promise<WeatherForecast | null> {
  const res = await fetch(ENDPOINT, { signal });
  if (!res.ok) return null;
  const json = (await res.json()) as OpenMeteoResponse;
  const c = json.current;
  if (!c || typeof c.temperature_2m !== 'number') return null;

  const code = c.weather_code ?? 3;
  const nowMeta = wmoLabel(code);
  const now: WeatherNow = {
    tempC: Math.round(c.temperature_2m),
    feelsC: Math.round(c.apparent_temperature ?? c.temperature_2m),
    humidity: Math.round(c.relative_humidity_2m ?? 0),
    windKmh: Math.round(c.wind_speed_10m ?? 0),
    windDir: Math.round(c.wind_direction_10m ?? 0),
    code,
    label: nowMeta.label,
    icon: nowMeta.icon,
  };

  // Pick the next 6 hourly steps starting from the first slot >= now.
  const next: WeatherHour[] = [];
  const h = json.hourly;
  if (h?.time && h.temperature_2m) {
    const nowMs = Date.now();
    let startIdx = h.time.findIndex((iso) => Date.parse(iso) >= nowMs);
    if (startIdx < 0) startIdx = 0;
    for (let i = startIdx; i < Math.min(startIdx + 6, h.time.length); i++) {
      const hc = h.weather_code?.[i] ?? code;
      const meta = wmoLabel(hc);
      next.push({
        time: h.time[i]!,
        hourLabel: hourLabel(h.time[i]!),
        tempC: Math.round(h.temperature_2m[i] ?? now.tempC),
        precipPct: Math.round(h.precipitation_probability?.[i] ?? 0),
        code: hc,
        label: meta.label,
        icon: meta.icon,
      });
    }
  }

  return { now, next, fetchedAt: Date.now() };
}

export interface WeatherHookState {
  data: WeatherForecast | null;
  loading: boolean;
  error: boolean;
}

/** React hook — fetches on mount, then polls every 15 minutes. */
export function useWeather(): WeatherHookState {
  const [state, setState] = useState<WeatherHookState>({ data: null, loading: true, error: false });

  useEffect(() => {
    const ctrl = new AbortController();
    let timer = 0;
    let cancelled = false;

    const run = async () => {
      try {
        const data = await fetchWeather(ctrl.signal);
        if (cancelled) return;
        setState(data ? { data, loading: false, error: false } : { data: null, loading: false, error: true });
      } catch {
        if (!cancelled) setState((prev) => ({ data: prev.data, loading: false, error: true }));
      }
    };

    void run();
    timer = window.setInterval(run, POLL_MS);
    return () => {
      cancelled = true;
      ctrl.abort();
      window.clearInterval(timer);
    };
  }, []);

  return state;
}
