/**
 * Tab 09 — OSINT İzleme (geolocated civilian-impact tracker).
 *
 * Map pane reuses MapHost (so observations are pinned to real geography — the
 * OsintMapOverlay + osintLayer ride inside it). The aside is the cinematic
 * strike-card feed with a Live/Playback toggle and a source filter. Each card
 * cross-wires the OODA loop: İncele → feed inspector, Haritada → fly the map,
 * C2'ye Gönder → spawn a DYNAMIC pairing-board card.
 */
import { useMemo, useState } from 'react';
import { useStore } from '../../store';
import { useC2, type C2Card } from '../../store/c2';
import { MapHost } from '../../map/MapHost';
import { osintObservations, type OsintSourceTag } from '../../feeds/osint';
import { sortBySeverity } from '../../store/selectors';
import { SevGlyph } from '../../lib/sevGlyph';
import { SourceChip } from '../../lib/sourceTag';
import { tickElapsed } from '../../lib/time';
import type { Entity } from '../../types/entity';
import type { UnitState } from '../../types/venue';

interface OsintProps {
  unitSnapshot: UnitState[];
  pulseT: number;
}

type Filter = OsintSourceTag | 'TÜMÜ';
const FILTERS: Filter[] = ['TÜMÜ', 'GEO-OSINT', 'WITNESS', 'CCTV-CV', 'AFAD'];

const CATEGORY_TR: Record<string, string> = {
  collapse: 'Çöküntü',
  fire: 'Yangın',
  gasleak: 'Gaz Kaçağı',
  trapped: 'Mahsur',
  flood: 'Su Baskını',
};

function OsintCard({ obs }: { obs: Entity }) {
  const selectEntity = useStore((s) => s.selectEntity);
  const openDock = useStore((s) => s.openDock);
  const setFlyTarget = useStore((s) => s.setFlyTarget);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const addCard = useC2((s) => s.addCard);
  const sent = useC2((s) => s.cards.some((c) => c.entityId === obs.id));

  const [lng, lat] =
    obs.geom.type === 'Point' ? (obs.geom.coordinates as [number, number]) : [0, 0];
  const category = String(obs.attrs.category ?? '');
  const headline = String(obs.attrs.headline ?? category);
  const district = String(obs.attrs.district ?? '');
  const sourceTag = String(obs.attrs.sourceTag ?? obs.source);
  const tags = Array.isArray(obs.attrs.tags) ? (obs.attrs.tags as string[]) : [];
  const active = selectedEntityId === obs.id;

  const inspect = () => {
    selectEntity(obs.id);
    openDock('feed-inspector');
  };
  const showOnMap = () => {
    selectEntity(obs.id);
    setFlyTarget({ lng, lat, zoom: 14 });
  };
  const toC2 = () => {
    if (sent) return;
    const key = obs.id.split(':').pop() ?? obs.id;
    const card: C2Card = {
      id: `AKOM-OS-${key}`,
      entityId: obs.id,
      col: 'DYNAMIC',
      type: headline,
      kind: `OSINT · ${sourceTag}`,
      severity: obs.severity,
      editedAt: Date.now(),
      expired: false,
      urgent: obs.severity === 'flash' || obs.severity === 'immediate',
      location: { lat, lng, district },
      intelNotes: [`Kaynak: ${sourceTag}`, `Güven: %${Math.round(obs.confidence * 100)}`, ...tags],
    };
    addCard(card);
  };

  return (
    <article className="osint-card glass-panel glass-panel--card" data-active={active || undefined}>
      <div className="osint-card__strip" data-cat={category} />
      <div className="osint-card__main">
        <div className="osint-card__head">
          <SevGlyph severity={obs.severity} pulse={obs.severity === 'flash'} />
          <span className="osint-card__title">{headline}</span>
          <span className="osint-card__age">{tickElapsed(obs.firstSeen)}</span>
        </div>
        <div className="osint-card__meta">
          <span className="osint-card__cat">{CATEGORY_TR[category] ?? category}</span>
          <span>·</span>
          <span>{district}</span>
          <SourceChip source={obs.source} />
          <span className="osint-card__conf">%{Math.round(obs.confidence * 100)}</span>
        </div>
        <div className="osint-card__tags">
          {tags.map((t) => (
            <span key={t} className="osint-card__tag">
              {t}
            </span>
          ))}
        </div>
        <div className="osint-card__actions">
          <button type="button" onClick={inspect}>
            İncele
          </button>
          <button type="button" onClick={showOnMap}>
            Haritada
          </button>
          <button
            type="button"
            className="osint-card__c2"
            onClick={toC2}
            disabled={sent}
            data-sent={sent || undefined}
          >
            {sent ? 'C2’de ✓' : 'C2’ye Gönder'}
          </button>
        </div>
      </div>
    </article>
  );
}

export function Osint({ unitSnapshot, pulseT }: OsintProps) {
  const entities = useStore((s) => s.entities);
  const [mode, setMode] = useState<'live' | 'playback'>('live');
  const [filter, setFilter] = useState<Filter>('TÜMÜ');
  const [cursor, setCursor] = useState<number | null>(null);

  const all = useMemo(() => osintObservations(entities), [entities]);

  const tMin = useMemo(() => (all.length ? Math.min(...all.map((e) => e.firstSeen)) : 0), [all]);
  const tMax = useMemo(() => (all.length ? Math.max(...all.map((e) => e.firstSeen)) : 0), [all]);

  const list = useMemo(() => {
    let arr = all;
    if (filter !== 'TÜMÜ') arr = arr.filter((e) => String(e.attrs.sourceTag) === filter);
    if (mode === 'playback' && cursor != null) arr = arr.filter((e) => e.firstSeen <= cursor);
    return mode === 'live'
      ? sortBySeverity(arr)
      : [...arr].sort((a, b) => b.firstSeen - a.firstSeen);
  }, [all, filter, mode, cursor]);

  return (
    <>
      <section className="hud-pane hud-pane--map">
        <div className="map-host">
          <MapHost unitSnapshot={unitSnapshot} pulseT={pulseT} />
        </div>
      </section>
      <aside className="hud-pane hud-pane--side osint-side">
        <section className="ops-panel glass-panel glass-panel--deep">
          <div className="ops-panel__title">OSINT İzleme · Sivil Etki &middot; {all.length}</div>
          <div className="osint-controls">
            <div className="osint-mode">
              <button type="button" data-active={mode === 'live' || undefined} onClick={() => setMode('live')}>
                CANLI
              </button>
              <button
                type="button"
                data-active={mode === 'playback' || undefined}
                onClick={() => {
                  setMode('playback');
                  setCursor(tMax || Date.now());
                }}
              >
                OYNATIM
              </button>
            </div>
            {mode === 'playback' && tMax > tMin && (
              <input
                className="osint-scrub"
                type="range"
                min={tMin}
                max={tMax}
                step={1000}
                value={cursor ?? tMax}
                onChange={(e) => setCursor(Number(e.target.value))}
                aria-label="Zaman imleci"
              />
            )}
            <div className="osint-filters">
              {FILTERS.map((f) => (
                <button
                  key={f}
                  type="button"
                  data-active={filter === f || undefined}
                  onClick={() => setFilter(f)}
                >
                  {f}
                </button>
              ))}
            </div>
          </div>
        </section>

        <div className="osint-list">
          {list.length === 0 ? (
            <div className="osint-empty">Gözlem akışı bekleniyor…</div>
          ) : (
            list.map((e) => <OsintCard key={e.id} obs={e} />)
          )}
        </div>
      </aside>
    </>
  );
}
