/**
 * OsintDock — dock slot 'osint', title "OSINT Akışı".
 *
 * Top-10 live OSINT observations sorted by severity. Each row shows a SevGlyph,
 * the headline, the district, and a SourceChip for the entity's real origin.
 * Clicking a row selects the entity and flies the map to its coordinate.
 */
import { type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { osintObservations } from '../../feeds/osint';
import { sortBySeverity } from '../../store/selectors';
import { SourceChip } from '../../lib/sourceTag';
import { SevGlyph } from '../../lib/sevGlyph';

export function OsintDock(): ReactNode {
  const dock = useStore((s) => s.dock['osint']);
  const entities = useStore((s) => s.entities);
  const selectEntity = useStore((s) => s.selectEntity);
  const setFlyTarget = useStore((s) => s.setFlyTarget);

  if (!dock.open) return null;

  const top = sortBySeverity(osintObservations(entities)).slice(0, 10);

  return (
    <DockPanel id="osint" title="OSINT Akışı">
      <div className="osint-dock">
        {top.length === 0 ? (
          <div className="osint-dock__empty" style={{ color: 'var(--ink-mute)' }}>
            Aktif OSINT gözlemi yok
          </div>
        ) : (
          <ul className="osint-dock__list">
            {top.map((e) => {
              const headline = String(e.attrs.headline ?? e.attrs.category ?? e.kind);
              const district = String(e.attrs.district ?? '—');
              const onClick = () => {
                selectEntity(e.id);
                if (e.geom.type === 'Point') {
                  const lng = e.geom.coordinates[0];
                  const lat = e.geom.coordinates[1];
                  if (lng !== undefined && lat !== undefined) {
                    setFlyTarget({ lng, lat, zoom: 14 });
                  }
                }
              };
              return (
                <li key={e.id}>
                  <button
                    type="button"
                    className="osint-dock__row"
                    onClick={onClick}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 6,
                      width: '100%',
                      textAlign: 'left',
                      background: 'transparent',
                      border: 'none',
                      borderBottom: '1px solid var(--bg-rule)',
                      padding: '4px 2px',
                      color: 'var(--ink-strong)',
                      cursor: 'pointer',
                    }}
                  >
                    <SevGlyph severity={e.severity} />
                    <span style={{ flex: 1, fontSize: 12 }}>{headline}</span>
                    <span style={{ fontSize: 11, color: 'var(--ink-mute)' }}>{district}</span>
                    <SourceChip source={e.source} />
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </DockPanel>
  );
}
