import { useEffect, useMemo, useRef, useState } from 'react';
import { HudShell } from './ui/HudShell';
import { IntroGlobe } from './ui/IntroGlobe';
import { useStore } from './store';
import { loadVenues, loadUnits, loadIncidents, loadStaticGeo, loadBuildings } from './bootstrap/loadData';
import { generateRadio } from './bootstrap/seedRadio';
import { startKpiPump } from './bootstrap/seedKpis';
import { PatrolEngine } from './sim/PatrolEngine';
import { RoadGraph } from './sim/RoadGraph';
import { generateGroundUnits } from './sim/unitFactory';
import { ScenarioEngine } from './sim/ScenarioEngine';
import { loadRoadGraph } from './feeds/roadGraph';
import { dataUrl } from './lib/paths';
import { entityId } from './types/entity';
import type { IncidentFeature, UnitState } from './types/venue';
import type { FeatureCollection } from 'geojson';
import { usePatrolEngine } from './sim/usePatrolEngine';
import { startAfadFeed } from './feeds/afad';
import { startOpenSkyFeed } from './feeds/opensky';
import { startEltFeed } from './feeds/eltBeacons';
import { startUtilitiesFeed } from './feeds/utilities';
import { startOsintFeed } from './feeds/osint';
import { bindDockPersistence } from './store/dock';
import { bindBasemapPersistence } from './map/basemap';
import { applyThemeToDom, bindThemePersistence } from './lib/theme';

export function App() {
  const setVenues = useStore((s) => s.setVenues);
  const setUnits = useStore((s) => s.setUnits);
  const setIncidents = useStore((s) => s.setIncidents);
  const setStaticGeo = useStore((s) => s.setStaticGeo);
  const setBuildings = useStore((s) => s.setBuildings);
  const pushRadio = useStore((s) => s.pushRadio);
  const setReducedMotion = useStore((s) => s.setReducedMotion);
  const reducedMotion = useStore((s) => s.reducedMotion);
  const units = useStore((s) => s.units);
  const staticGeo = useStore((s) => s.staticGeo);

  const engine = useMemo(() => new PatrolEngine(), []);
  const scenario = useMemo(() => new ScenarioEngine(), []);
  const [pulseT, setPulseT] = useState(0);
  const [showIntro, setShowIntro] = useState(true);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      // 1. Cheap stuff first - HUD goes interactive in <300 ms
      const [venues, unitFeatures, incidents, geo] = await Promise.all([
        loadVenues(),
        loadUnits(),
        loadIncidents(),
        loadStaticGeo(),
      ]);
      if (cancelled) return;
      setVenues(venues);
      setUnits(unitFeatures);
      setIncidents(incidents);
      setStaticGeo(geo);

      // 2. Buildings (12 MB) lazy-loaded when the browser is idle. We don't
      //    block the first paint on this. Falls back to setTimeout when
      //    requestIdleCallback isn't available (Safari, Firefox <55).
      const startBuildings = () => {
        if (cancelled) return;
        void loadBuildings().then((b) => {
          if (!cancelled) setBuildings(b);
        });
      };
      type IdleWindow = Window & { requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => void };
      const w = window as IdleWindow;
      if (typeof w.requestIdleCallback === 'function') {
        w.requestIdleCallback(startBuildings, { timeout: 4000 });
      } else {
        setTimeout(startBuildings, 1200);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [setVenues, setUnits, setIncidents, setStaticGeo, setBuildings]);

  useEffect(() => {
    const routes = [
      ...staticGeo.airCorridors,
      ...staticGeo.seaLanes,
      ...staticGeo.groundBeats,
    ];
    if (routes.length === 0 || units.length === 0) return;
    engine.setRoutes(routes);
    engine.setUnits(units);
  }, [engine, units, staticGeo]);

  // Load the IBB real-road graph (emergency roads + main arteries) and hand it
  // to the engine so GROUND units patrol/dispatch on actual Istanbul roads.
  // ~4 MB; loaded off the critical path so first paint isn't blocked.
  useEffect(() => {
    let cancelled = false;
    void loadRoadGraph().then((data) => {
      if (cancelled || !data) return;
      const graph = new RoadGraph(data);
      engine.setRoadGraph(graph);

      // v10 P4 · optional synthetic ground fleet (?units=N or VITE_SIM_UNITS).
      // Keeps the file's non-ground units (heli/fixed/naval) and replaces the
      // ground fleet with N generated units. Guarded so StrictMode's double
      // mount does not double-apply.
      const params = new URLSearchParams(window.location.search);
      const requested = Number(params.get('units') ?? import.meta.env.VITE_SIM_UNITS ?? 0);
      if (Number.isFinite(requested) && requested > 0) {
        const current = useStore.getState().units;
        if (current.length > 0 && !current.some((u) => u.properties.id === 'u-gen-0')) {
          const nonGround = current.filter((u) => u.properties.modality !== 'ground');
          useStore.getState().setUnits([...nonGround, ...generateGroundUnits(requested, graph)]);
        }
      }
    });
    return () => {
      cancelled = true;
    };
  }, [engine]);

  // v10 P5 · load Istanbul district polygons into the scenario engine once
  // (null-tolerant: a missing file just means no choropleth).
  useEffect(() => {
    let cancelled = false;
    void fetch(dataUrl('istanbul-districts.geojson'))
      .then((r) => (r.ok ? r.json() : null))
      .then((fc) => {
        if (!cancelled) scenario.setDistricts((fc as FeatureCollection | null) ?? null);
      })
      .catch(() => {
        if (!cancelled) scenario.setDistricts(null);
      });
    return () => {
      cancelled = true;
    };
  }, [scenario]);

  // v10 P5 · drive the Mw 7.5 Marmara scenario on a 500 ms tick while running.
  const scenarioRunning = useStore((s) => s.scenario.running);
  useEffect(() => {
    if (!scenarioRunning) return;
    let lastNow = performance.now();
    const id = window.setInterval(() => {
      const now = performance.now();
      const dt = Math.min(3000, Math.max(100, now - lastNow));
      lastNow = now;
      const st = useStore.getState();
      const simMs = st.scenario.simMs + Math.round(dt * st.scenario.speed);
      st.setScenario({ simMs });
      st.setOsintSurge(scenario.surgeMultiplier(simMs));
      for (const e of scenario.tick(simMs)) {
        if (e.kind === 'quake') {
          st.upsertEntity({
            id: entityId('KRDAE', 'incident', 'marmara-mw75'),
            kind: 'incident',
            geom: { type: 'Point', coordinates: [28.95, 40.81] },
            attrs: { headline: 'Mw 7.5 Marmara Depremi', category: 'earthquake', district: 'Marmara' },
            source: 'KRDAE',
            affiliation: 'neutral',
            status: 'operational',
            severity: 'flash',
            confidence: 0.95,
            firstSeen: Date.now(),
            lastSeen: Date.now(),
            links: [],
          });
          st.pushRadio({
            ts: Date.now(),
            callsign: 'KRDAE',
            text: 'Mw 7.5 Marmara depremi — MASCAL ilan edildi',
            priority: 'flash',
          });
          const mascal: IncidentFeature = {
            type: 'Feature',
            geometry: { type: 'Point', coordinates: [28.95, 40.81] },
            properties: {
              id: 'scenario-mascal',
              label: 'Mw 7.5 Marmara',
              type: 'mascal',
              severity: 5,
              radius_m: 30_000,
              start: new Date().toISOString(),
              district: 'Marmara',
            },
          };
          const rest = st.incidents.filter((i) => i.properties.id !== 'scenario-mascal');
          st.setIncidents([...rest, mascal]);
        } else if (e.kind === 'damage-ready') {
          st.setScenarioDamage(scenario.damageByDistrict());
        } else if (e.kind === 'dispatch') {
          for (const t of scenario.dispatchTargets()) st.pushDispatch(t);
        } else if (e.kind === 'cascade') {
          const down = new Set(scenario.infraFailures());
          st.setUtilityNetworks(
            st.utilityNetworks.map((net) => ({
              ...net,
              nodes: net.nodes.map((n) => (down.has(n.id) ? { ...n, status: 'down' as const } : n)),
            })),
          );
        }
      }
      // The patrol engine consumes the dispatch queue (operator wave).
      for (const t of st.drainDispatch()) engine.dispatchNearest(t.lng, t.lat);
    }, 500);
    return () => window.clearInterval(id);
  }, [scenarioRunning, scenario, engine]);

  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReducedMotion(mq.matches);
    const h = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
    mq.addEventListener('change', h);
    return () => mq.removeEventListener('change', h);
  }, [setReducedMotion]);

  useEffect(() => {
    pushRadio(generateRadio());
    const id = window.setInterval(() => pushRadio(generateRadio()), 6000);
    return () => window.clearInterval(id);
  }, [pushRadio]);

  useEffect(() => startKpiPump(() => useStore.getState().reducedMotion), []);

  // Phase 9-B · persist dock-panel state to localStorage. The slice
  // subscribes for the lifetime of the page and silently degrades when
  // localStorage is unavailable (private mode).
  useEffect(() => bindDockPersistence(useStore), []);

  // Phase 9 Leap Step 1 · persist basemap mode (akom:basemap:v1).
  useEffect(() => bindBasemapPersistence(useStore), []);

  // v10 P2 · persist theme mode (akom:theme:v1) + keep the DOM attribute in sync.
  useEffect(() => bindThemePersistence(useStore), []);
  useEffect(() => useStore.subscribe((s) => s.themeMode, applyThemeToDom), []);

  // Live feeds (Phase 2 of the spatial-intelligence ultraplan).
  // Mock-by-default; flip VITE_FEATURE_LIVE_* env flags to hit real endpoints.
  useEffect(() => {
    const afad = startAfadFeed();
    const opensky = startOpenSkyFeed();
    const elt = startEltFeed();
    const utilities = startUtilitiesFeed();
    const osint = startOsintFeed();
    return () => {
      afad.stop();
      opensky.stop();
      elt.stop();
      utilities.stop();
      osint.stop();
    };
  }, []);

  // Klaxon pulse clock - 10 Hz so layer rebuilds stay cheap.
  const pulseRafRef = useRef(0);
  const lastPulseRef = useRef(0);
  useEffect(() => {
    const intervalMs = reducedMotion ? 1000 : 100;
    const step = (now: number) => {
      if (now - lastPulseRef.current >= intervalMs) {
        lastPulseRef.current = now;
        setPulseT(reducedMotion ? 0 : now);
      }
      pulseRafRef.current = requestAnimationFrame(step);
    };
    pulseRafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(pulseRafRef.current);
  }, [reducedMotion]);

  const enginePrimed =
    units.length > 0 &&
    staticGeo.airCorridors.length + staticGeo.seaLanes.length + staticGeo.groundBeats.length > 0;

  const snapshot = usePatrolEngine({
    engine,
    reactHz: 10,
    reducedMotion,
    enabled: enginePrimed,
  });

  // KAYIT recorder — sample one replay frame per second from live cockpit state.
  // A ref tracks the latest snapshot so the 1 Hz interval reads enroute counts
  // without re-subscribing on every 10 Hz tick.
  const snapshotRef = useRef(snapshot);
  snapshotRef.current = snapshot;
  // Latest patrol snapshot exposed globally so UnitHoverPreview can read it
  // without subscribing to the high-frequency patrol tick.
  (window as unknown as { __akomSnapshot?: UnitState[] }).__akomSnapshot = snapshot;
  // DEV-only handle so the demo driver can assert ground units are moving.
  if (import.meta.env.DEV) {
    // already set above
  }
  // v10 P4 · sample engine snapshot cost once per second for the
  // DataSourcesDock SİM TICK readout.
  const setSimTickMs = useStore((s) => s.setSimTickMs);
  useEffect(() => {
    const id = window.setInterval(() => {
      const t0 = performance.now();
      engine.snapshot();
      setSimTickMs(performance.now() - t0);
    }, 1000);
    return () => window.clearInterval(id);
  }, [engine, setSimTickMs]);

  const recordReplayFrame = useStore((s) => s.recordReplayFrame);
  useEffect(() => {
    const id = window.setInterval(() => {
      const st = useStore.getState();
      const snap = snapshotRef.current;
      recordReplayFrame({
        t: Date.now(),
        units: st.kpis.units,
        unitsEnroute: snap.filter((u) => u.status === 'enroute').length,
        incidents: st.kpis.incidents,
        etaAvgSec: st.kpis.etaAvgSec,
        bedsAvailable: st.kpis.bedsAvailable,
        roadsBlockedPct: st.kpis.roadsBlockedPct,
      });
    }, 1000);
    return () => window.clearInterval(id);
  }, [recordReplayFrame]);

  return (
    <>
      {showIntro && <IntroGlobe onDone={() => setShowIntro(false)} />}
      <HudShell unitSnapshot={snapshot} pulseT={pulseT} />
    </>
  );
}
