/**
 * Seeded ground-unit generator (v10 P4).
 *
 * Deterministically spawns N patrol units on routable nodes of the (A6-repaired)
 * road graph. Same seed → identical fleet, so benches, perf specs, and the demo
 * scenario are all reproducible.
 */
import type { RoadGraph } from './RoadGraph';
import type { UnitFeature } from '../types/venue';

/** mulberry32 — tiny deterministic PRNG. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function generateGroundUnits(
  count: number,
  graph: RoadGraph,
  seed = 1907,
): UnitFeature[] {
  const rand = mulberry32(seed);
  const out: UnitFeature[] = [];
  for (let i = 0; i < count; i++) {
    const node = graph.randomRoutableNode(rand);
    const [lng, lat] = graph.coord(node);
    const num = String(i + 1).padStart(4, '0');
    out.push({
      type: 'Feature',
      id: `u-gen-${i}`,
      properties: {
        id: `u-gen-${i}`,
        callsign: `SIM-${num}`,
        modality: 'ground',
        type: 'patrol',
        status: 'patrol',
        beat_id: `gen-${i}`,
        speed_kph: 35 + Math.floor(rand() * 25),
        offset: rand(),
        heading: 0,
        speed: 35,
      },
      geometry: { type: 'Point', coordinates: [lng, lat] },
    });
  }
  return out;
}
