import { useStore } from '../store';

// METAR-style weather labels — no emoji per flat-tactical doctrine.
// SCT = scattered cloud, BKN = broken cloud, RA = rain, FG = fog.
const WX_ROTATION = ['SCT 14°', 'BKN 13°', 'RA 12°', 'RA 11°', 'FG 10°'];

/** Ease a value a fraction of the way toward a target (frame-rate independent). */
function approach(current: number, target: number, rate: number): number {
  return current + (target - current) * rate;
}

/** Count live incidents: seeded incidents + AFAD/entity-store incident events. */
function incidentLoad(): number {
  const s = useStore.getState();
  let n = s.incidents.length;
  for (const e of s.entities.values()) {
    if (e.kind === 'incident') n += 1;
  }
  return n;
}

/** Fraction (0..1) of utility distribution nodes currently down. */
function utilityStress(): number {
  const nets = useStore.getState().utilityNetworks;
  let down = 0;
  let total = 0;
  for (const net of nets) {
    for (const node of net.nodes) {
      if (node.kind === 'distribution') {
        total += 1;
        if (node.status === 'down') down += 1;
      }
    }
  }
  return total > 0 ? down / total : 0;
}

/**
 * KPI pump. Each second it derives the operational KPIs from genuine live
 * cockpit state — the active incident load (seed + AFAD feed), unit count, and
 * utility-network stress — then eases the ribbon toward those targets so the
 * numbers move but always reflect what is actually happening on the map.
 */
export function startKpiPump(getReducedMotion: () => boolean): () => void {
  let beds = 1284;
  let eta = 252;
  let roads = 23;
  let wxIdx = 0;
  let tick = 0;

  const id = window.setInterval(() => {
    if (getReducedMotion() && tick > 0 && tick % 4 !== 0) {
      tick++;
      return;
    }
    tick++;

    const state = useStore.getState();
    const load = incidentLoad();
    const stress = utilityStress();
    const unitCount = state.units.length || 1;

    // Targets grounded in live state, with a little noise for life.
    const noise = (Math.random() - 0.5);
    const roadsTarget = Math.max(2, Math.min(72, 6 + load * 2.4 + stress * 40 + noise * 2));
    // More incidents per unit → slower dispatch; more units → faster.
    const etaTarget = Math.max(110, Math.min(620, 150 + (load / unitCount) * 900 + noise * 12));
    // Beds drain as casualties (incidents) rise.
    const bedsTarget = Math.max(420, Math.min(2200, 1500 - load * 38 + noise * 30));

    roads = approach(roads, roadsTarget, 0.25);
    eta = approach(eta, etaTarget, 0.2);
    beds = approach(beds, bedsTarget, 0.18);

    if (tick % 30 === 0) {
      wxIdx = (wxIdx + 1) % WX_ROTATION.length;
    }

    useStore.setState({
      kpis: {
        units: state.units.length,
        incidents: state.incidents.length,
        etaAvgSec: Math.round(eta),
        bedsAvailable: Math.round(beds),
        roadsBlockedPct: roads,
        wxLabel: WX_ROTATION[wxIdx] ?? '--',
      },
    });
    state.tickSparklines({
      units: [state.units.length],
      incidents: [state.incidents.length],
      eta: [eta],
      beds: [beds],
      roads: [roads],
    });
  }, 1000);

  return () => window.clearInterval(id);
}
