/**
 * OSINT impact markers — geolocated civilian-impact observations on the map.
 * Pulse ring + solid core per observation, colored by category. Driven by
 * pulseT (RAF) like the incidents layer. Click selects the entity.
 */
import { ScatterplotLayer } from '@deck.gl/layers';
import type { Entity } from '../../types/entity';

const CATEGORY_COLOR: Record<string, [number, number, number]> = {
  collapse: [230, 57, 70], // klaxon red
  trapped: [230, 57, 70],
  fire: [255, 138, 0], // amber
  gasleak: [255, 196, 0], // yellow
  flood: [59, 130, 246], // blue
};

function colorFor(e: Entity): [number, number, number] {
  const cat = String(e.attrs.category ?? '');
  return CATEGORY_COLOR[cat] ?? [120, 130, 150];
}

interface OsintBuildArgs {
  data: Entity[];
  pulseT: number;
  selectedId?: string | null;
  onClick?: (id: string) => void;
}

export function buildOsintLayers({
  data,
  pulseT,
  selectedId = null,
  onClick,
}: OsintBuildArgs): ScatterplotLayer<Entity>[] {
  const t = (pulseT / 1500) % 1;
  const ringRadius = 7 + t * 22;
  const ringAlpha = Math.round((1 - t) * 200);

  const pulse = new ScatterplotLayer<Entity>({
    id: 'osint-pulse',
    data,
    pickable: false,
    stroked: true,
    filled: false,
    radiusUnits: 'pixels',
    lineWidthUnits: 'pixels',
    getPosition: (e) => e.geom.type === 'Point' ? (e.geom.coordinates as [number, number]) : [0, 0],
    getRadius: ringRadius,
    getLineColor: (e) => {
      const c = colorFor(e);
      return [c[0], c[1], c[2], ringAlpha];
    },
    getLineWidth: 1.4,
    updateTriggers: {
      getRadius: ringRadius,
      getLineColor: ringAlpha,
    },
  });

  const core = new ScatterplotLayer<Entity>({
    id: 'osint-core',
    data,
    pickable: true,
    stroked: true,
    filled: true,
    radiusUnits: 'pixels',
    lineWidthUnits: 'pixels',
    getPosition: (e) => e.geom.type === 'Point' ? (e.geom.coordinates as [number, number]) : [0, 0],
    getRadius: (e) => (selectedId === e.id ? 8 : 5.5),
    getFillColor: (e) => {
      const c = colorFor(e);
      return [c[0], c[1], c[2], 240];
    },
    getLineColor: (e) =>
      selectedId === e.id ? [255, 255, 255, 235] : [10, 12, 16, 200],
    getLineWidth: 1.5,
    onClick: (info) => {
      const id = (info.object as Entity | undefined)?.id;
      if (id) onClick?.(id);
    },
    updateTriggers: {
      getRadius: [selectedId],
      getLineColor: [selectedId],
    },
  });

  return [pulse, core];
}
