/**
 * Tauri HLS bridge — Phase 9 Leap Step 6.
 *
 * Exposes the two reqwest-backed commands (fetch_ibb_manifest, fetch_ibb_segment)
 * from src-tauri/src/main.rs as a clean TS API. Only available in Tauri builds.
 *
 * Usage:
 *   if (isTauri()) {
 *     const manifest = await fetchManifest(camId);
 *     const seg = await fetchSegment(manifest.segments[0].url);
 *     // feed `seg` into MediaSource SourceBuffer
 *   } else {
 *     // web fallback: render 3-preset JPEG carousel
 *   }
 */
import { parseM3U8, type HlsManifest } from './parseM3U8';

const HLS_HOSTS = [
  'https://hls.ibb.gov.tr',
  'https://hls2.ibb.gov.tr',
  'https://hls4.ibb.gov.tr',
];

interface TauriManifestResponse {
  ok: boolean;
  status: number;
  body: string | null;
  error: string | null;
}

export function isTauri(): boolean {
  return typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;
}

/**
 * Lazy-import @tauri-apps/api so the web build doesn't pull it in. Returns
 * null when not running under Tauri.
 */
async function invokeTauri<T>(cmd: string, args: Record<string, unknown>): Promise<T | null> {
  if (!isTauri()) return null;
  try {
    const { invoke } = await import(/* @vite-ignore */ '@tauri-apps/api/core');
    return (await invoke(cmd, args)) as T;
  } catch (err) {
    console.warn('[tauriHls] invoke failed', cmd, err);
    return null;
  }
}

export async function fetchManifest(camId: number): Promise<HlsManifest | null> {
  // Try each HLS host until one succeeds.
  for (const host of HLS_HOSTS) {
    const url = `${host}/HLSCAM${camId}/index.m3u8`;
    const resp = await invokeTauri<TauriManifestResponse>('fetch_ibb_manifest', { url });
    if (resp?.ok && resp.body) {
      return parseM3U8(resp.body, url);
    }
  }
  return null;
}

export async function fetchSegment(url: string): Promise<Uint8Array | null> {
  const resp = await invokeTauri<number[]>('fetch_ibb_segment', { url });
  if (resp === null) return null;
  return new Uint8Array(resp);
}

export type { HlsManifest } from './parseM3U8';
