/**
 * SitrepDock — dock slot 'sitrep', title "SITREP Üretici" (v10 P6).
 *
 * Provider-driven: ŞABLON (deterministic offline template, default),
 * CLAUDE API (opt-in, operator's own key in sessionStorage, browser-direct),
 * and WEBLLM (flag-gated placeholder). Provenance always reflects the real
 * data origin and egress. The default path fires zero network.
 */
import { useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';
import type { SitrepMode, SitrepProvider, SitrepResult } from '../../lib/llm/providers';
import { templateProvider } from '../../lib/llm/templateProvider';
import {
  makeClaudeProvider,
  ANTHROPIC_KEY_STORAGE,
  DEFAULT_CLAUDE_MODEL,
} from '../../lib/llm/claudeProvider';

type Status = { kind: 'idle' | 'busy' } | { kind: 'error'; message: string };

const WEBLLM_ENABLED = Boolean(import.meta.env.VITE_FEATURE_WEBLLM);

const SEGMENTS: ReadonlyArray<{ mode: SitrepMode; label: string }> = [
  { mode: 'template', label: 'ŞABLON' },
  { mode: 'claude', label: 'CLAUDE API' },
  { mode: 'webllm', label: 'WEBLLM' },
];

export function SitrepDock(): ReactNode {
  const dock = useStore((s) => s.dock['sitrep']);
  const [mode, setMode] = useState<SitrepMode>('template');
  const [output, setOutput] = useState('');
  const [result, setResult] = useState<SitrepResult | null>(null);
  const [status, setStatus] = useState<Status>({ kind: 'idle' });
  const [model, setModel] = useState(DEFAULT_CLAUDE_MODEL);
  const [apiKey, setApiKey] = useState('');

  if (!dock.open) return null;

  const resolveProvider = (): SitrepProvider | null => {
    if (mode === 'template') return templateProvider;
    if (mode === 'claude') return makeClaudeProvider(model || DEFAULT_CLAUDE_MODEL);
    return null; // webllm: placeholder
  };

  const generate = async () => {
    const provider = resolveProvider();
    if (!provider) return;
    if (mode === 'claude') {
      try {
        sessionStorage.setItem(ANTHROPIC_KEY_STORAGE, apiKey);
      } catch {
        // sessionStorage unavailable — provider.available() will report false.
      }
      if (!provider.available()) {
        setStatus({ kind: 'error', message: 'anahtar gerekli' });
        return;
      }
    }
    setStatus({ kind: 'busy' });
    try {
      const input = (() => {
        const s = useStore.getState();
        return { entities: s.entities, kpis: s.kpis, nowMs: Date.now() };
      })();
      const res = await provider.generate(input);
      setOutput(res.text);
      setResult(res);
      setStatus({ kind: 'idle' });
    } catch (err) {
      setStatus({ kind: 'error', message: (err as Error).message });
    }
  };

  const statusLine =
    status.kind === 'busy'
      ? 'ÜRETİLİYOR'
      : status.kind === 'error'
        ? `HATA: ${status.message}`
        : 'HAZIR';

  const seg = (m: SitrepMode, label: string): ReactNode => {
    const disabled = m === 'webllm' && !WEBLLM_ENABLED;
    return (
      <button
        key={m}
        type="button"
        disabled={disabled}
        title={disabled ? 'WEBLLM · devre dışı (VITE_FEATURE_WEBLLM)' : label}
        onClick={() => !disabled && setMode(m)}
        style={{
          fontFamily: 'var(--font-mono)',
          fontSize: 10,
          background: mode === m ? 'var(--accent)' : 'var(--bg-panel-soft)',
          color: disabled ? 'var(--ink-faint)' : mode === m ? 'var(--bg-void)' : 'var(--ink-mid)',
          border: '1px solid var(--bg-rule)',
          padding: '3px 8px',
          cursor: disabled ? 'not-allowed' : 'pointer',
        }}
      >
        {label}
      </button>
    );
  };

  const inputStyle = {
    width: '100%',
    fontFamily: 'var(--font-mono)',
    fontSize: 11,
    background: 'var(--bg-panel-soft)',
    color: 'var(--ink-strong)',
    border: '1px solid var(--bg-rule)',
    padding: '3px 6px',
    marginTop: 4,
    boxSizing: 'border-box' as const,
  };

  return (
    <DockPanel id="sitrep" title="SITREP Üretici">
      <div className="sitrep-dock" style={{ fontFamily: 'var(--font-mono)' }}>
        <div style={{ display: 'flex', gap: 4 }}>{SEGMENTS.map((s) => seg(s.mode, s.label))}</div>

        {mode === 'claude' && (
          <div style={{ marginTop: 8 }}>
            <input
              type="password"
              placeholder="Anthropic API anahtarı"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              style={inputStyle}
            />
            <input
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              style={inputStyle}
            />
            <div style={{ fontSize: 9, color: 'var(--ink-mute)', marginTop: 2 }}>
              Anahtar yalnızca bu oturumda tutulur
            </div>
          </div>
        )}

        {mode === 'webllm' && (
          <div style={{ marginTop: 8, fontSize: 11, color: 'var(--ink-mute)' }}>
            WEBLLM · devre dışı (VITE_FEATURE_WEBLLM)
          </div>
        )}

        <button
          type="button"
          onClick={() => void generate()}
          disabled={mode === 'webllm' || status.kind === 'busy'}
          style={{
            marginTop: 8,
            fontFamily: 'var(--font-mono)',
            fontSize: 11,
            background: mode === 'webllm' ? 'var(--bg-panel-soft)' : 'var(--accent)',
            color: mode === 'webllm' ? 'var(--ink-faint)' : 'var(--bg-void)',
            border: 'none',
            padding: '4px 10px',
            cursor: mode === 'webllm' ? 'not-allowed' : 'pointer',
          }}
        >
          RAPOR OLUŞTUR
        </button>

        <div style={{ marginTop: 6, fontSize: 10, color: status.kind === 'error' ? 'var(--klaxon)' : 'var(--ink-mute)' }}>
          {statusLine}
        </div>

        <pre
          style={{
            marginTop: 6,
            fontFamily: 'var(--font-mono)',
            fontSize: 10,
            color: 'var(--ink-strong)',
            background: 'var(--bg-panel-soft)',
            padding: 6,
            maxHeight: 260,
            overflow: 'auto',
            whiteSpace: 'pre-wrap',
          }}
        >
          {output || 'Henüz rapor üretilmedi.'}
        </pre>

        <div style={{ marginTop: 6, fontSize: 10, color: 'var(--ink-mute)' }}>
          KAYNAK: {result?.modelLabel ?? 'ŞABLON'}
          <SourceChip source="EST" />
        </div>
        <div style={{ fontSize: 10, color: 'var(--ink-mute)' }}>AĞ: {result?.network ?? 'YOK'}</div>
      </div>
    </DockPanel>
  );
}
