/**
 * Utility infrastructure feed — TEİAŞ (electric), İGDAŞ (gas), İSKİ (water),
 * Telecom (TT/Turkcell/Vodafone). All real provider APIs are non-public; we
 * synthesize a plausible node-link topology and *evolve it live* so the ALTYAPI
 * tab shows a network that fails and recovers over time (cascading down edges),
 * instead of a frozen snapshot.
 */

import { useStore } from '../store';
import { startFeed, type FeedHandle } from './runner';

export type UtilityKind = 'electric' | 'gas' | 'water' | 'telecom';
export type UtilityStatus = 'ok' | 'degraded' | 'down';

export interface UtilityNode {
  id: string;
  label: string;
  kind: 'source' | 'distribution' | 'consumer';
  status: UtilityStatus;
}

export interface UtilityEdge {
  from: string;
  to: string;
  status: UtilityStatus;
  /** Capacity in arbitrary units; renders edge weight. */
  capacity: number;
}

export interface UtilityNetwork {
  kind: UtilityKind;
  provider: string;
  nodes: UtilityNode[];
  edges: UtilityEdge[];
  /** Free-form KPIs for the right-side ribbon. */
  metrics: { label: string; value: string; state: 'ok' | 'warn' | 'crit' }[];
}

/** Initial topology seed (statuses are re-derived live after the first tick). */
