const RANK: Record<UtilityStatus, number> = { ok: 0, degraded: 1, down: 2 };
const PROVIDER_LABELS: Record<UtilityKind, [string, string, string]> = {
  electric: ['Şebeke', 'Trafo Kayıp', 'Yedek MW'],
  gas: ['Şebeke', 'Vana Kapatma', 'Sızıntı'],
  water: ['Basınç', 'Pompa', 'Depo'],
  telecom: ['Kapsama', 'BTS', 'Gecikme'],
};

function worse(a: UtilityStatus, b: UtilityStatus): UtilityStatus {
  return RANK[a] >= RANK[b] ? a : b;
}

/** Random walk a single distribution/source node's health up or down a notch. */
function jitterNode(s: UtilityStatus, p: number): UtilityStatus {
  if (Math.random() > p) return s;
  // Bias slightly toward recovery so the network self-heals over time.
  const up = Math.random() < 0.55;
  if (s === 'ok') return up ? 'ok' : 'degraded';
  if (s === 'degraded') return up ? 'ok' : 'down';
  return up ? 'degraded' : 'down';
}

/**
 * Advance every network one tick: jitter source/distribution nodes, cascade the
 * worst upstream status down to consumers, re-derive edge statuses, recompute
 * the metric ribbon. Mutates and returns a fresh array so React re-renders.
 */
export function stepUtilityState(prev: UtilityNetwork[]): UtilityNetwork[] {
  return prev.map((net) => {
    const byId = new Map(net.nodes.map((n) => [n.id, { ...n }]));

    // 1. Jitter sources (rarely) and distribution nodes (more often).
    for (const n of byId.values()) {
      if (n.kind === 'source') n.status = jitterNode(n.status, 0.08);
      else if (n.kind === 'distribution') n.status = jitterNode(n.status, 0.22);
    }

    // 2. Cascade: a consumer is served as well as its *best* available feeder.
    for (const consumer of byId.values()) {
      if (consumer.kind !== 'consumer') continue;
      const feeders = net.edges
        .filter((e) => e.to === consumer.id)
        .map((e) => byId.get(e.from)!.status);
      if (feeders.length === 0) continue;
      // Best available feeder defines how well the consumer can be served.
      const best = feeders.reduce((acc, s) => (RANK[s] < RANK[acc] ? s : acc), 'down' as UtilityStatus);
      consumer.status = best;
    }

    // 3. Edge status = worse of its endpoints.
    const edges = net.edges.map((e) => ({
      ...e,
      status: worse(byId.get(e.from)!.status, byId.get(e.to)!.status),
    }));

    const nodes = [...byId.values()];
    const dist = nodes.filter((n) => n.kind === 'distribution');
    const distDown = dist.filter((n) => n.status === 'down').length;
    const downEdges = edges.filter((e) => e.status === 'down').length;
    const okCapacity = edges.filter((e) => e.status === 'ok').reduce((a, e) => a + e.capacity, 0);
    const totCapacity = edges.reduce((a, e) => a + e.capacity, 0);
    const servicePct = totCapacity > 0 ? Math.round((okCapacity / totCapacity) * 100) : 0;

    const [l0, l1, l2] = PROVIDER_LABELS[net.kind];
    const metrics: UtilityNetwork['metrics'] = [
      {
        label: l0,
        value: `%${servicePct}`,
        state: servicePct < 60 ? 'crit' : servicePct < 85 ? 'warn' : 'ok',
      },
      {
        label: l1,
        value: `${distDown} / ${dist.length}`,
        state: distDown > 0 ? 'crit' : 'ok',
      },
      {
        label: l2,
        value: net.kind === 'telecom' ? `${80 + downEdges * 40}ms` : `${downEdges}`,
        state: downEdges > 1 ? 'warn' : 'ok',
      },
    ];

    return { ...net, nodes, edges, metrics };
  });
}

/**
 * Live utility feed. Seeds the topology, then steps it on an interval so the
 * ALTYAPI tab animates. Tagged `IBB` in feed-health (municipal infrastructure).
 */
export function startUtilitiesFeed(): FeedHandle {
  // Seed once so the panel isn't empty before the first tick.
  useStore.getState().setUtilityNetworks(stepUtilityState(buildUtilityState()));
  return startFeed<UtilityNetwork[]>({
    source: 'IBB',
    label: 'UTILITIES',
    intervalMs: 5_000,
    fetch: () => Promise.resolve(useStore.getState().utilityNetworks),
    apply: (current) => {
      const seed = current.length > 0 ? current : buildUtilityState();
      useStore.getState().setUtilityNetworks(stepUtilityState(seed));
    },
  });
}
