import { useStore } from '../../store';
import { useC2 } from '../../store/c2';
import type { C2Card as Card } from '../../store/c2';
import { SevGlyph } from '../../lib/sevGlyph';
import { tickElapsed } from '../../lib/time';

interface C2CardProps {
  card: Card;
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export function C2CardView({ card, draggable, onDragStart, onDragEnd }: C2CardProps) {
  const selectedId = useC2((s) => s.selectedCardId);
  const selectCard = useC2((s) => s.selectCard);
  const selectEntity = useStore((s) => s.selectEntity);

  const isActive = selectedId === card.id;

  const onClick = () => {
    selectCard(isActive ? null : card.id);
    if (card.entityId) selectEntity(card.entityId);
  };

  return (
    <div
      className={`c2-card glass-panel glass-panel--card ${card.expired ? 'is-expired' : ''} ${card.urgent ? 'is-urgent' : ''} ${isActive ? 'is-active' : ''}`}
      draggable={draggable}
      onDragStart={(e) => onDragStart?.(e, card.id)}
      onDragEnd={(e) => onDragEnd?.(e)}
      onClick={onClick}
      role="button"
      tabIndex={0}
    >
      {card.expired && <div className="c2-card__expired">Müdahale penceresi doldu</div>}
      <div className="c2-card__head">
        <SevGlyph severity={card.severity} pulse={card.severity === 'flash'} />
        <span className="c2-card__id">{card.id}</span>
        <span className="c2-card__type">{card.type}</span>
      </div>
      <div className="c2-card__meta">
        <span>{card.kind}</span>
        <span className="c2-card__dot">·</span>
        <span>Düz. {tickElapsed(card.editedAt)}</span>
      </div>
    </div>
  );
}
