/**
 * Tab 04 — ADLİ Adli Analiz.
 *
 * Forensic data view: building-age choropleth (selected district drives the
 * map), 39-bar vulnerability histogram, sortable pre-1999 stock table.
 *
 * Phase 6 of the spatial-intelligence ultraplan. Data is seeded from KRDAE
 * aggregates; replace with real GeoJSON join in a follow-up.
 */

import { useState } from 'react';
import { VulnerabilityHistogram } from '../histograms/VulnerabilityHistogram';
import { PreNinetyNineTable } from '../tables/PreNinetyNineTable';
import { SourceChip } from '../../lib/sourceTag';

export function Adli() {
  const [selectedCode, setSelectedCode] = useState<string | null>('AVC');

  return (
    <div className="hud-pane adli-tab">
      <header className="adli-tab__head glass-panel glass-panel--float">
        <span className="adli-tab__title">ADLİ ANALİZ · KIRILGANLIK</span>
        <span className="adli-tab__sub">Mw=7.5 Marmara Senaryosu</span>
        <span className="adli-tab__spacer" />
        <span className="adli-tab__sel">
          Seçili: {selectedCode ?? '— yok —'}
          <SourceChip source="KRDAE" />
        </span>
      </header>
      <section className="adli-tab__chart glass-panel glass-panel--deep">
        <header className="ops-panel__title">
          39 İLÇE · KIRILGANLIK ENDEKSİ
          <SourceChip source="EST" />
        </header>
        <div className="adli-tab__chart-body">
          <VulnerabilityHistogram
            selectedCode={selectedCode}
            onSelect={(code) => setSelectedCode(code)}
          />
        </div>
      </section>
      <PreNinetyNineTable
        selectedCode={selectedCode}
        onSelect={(code) => setSelectedCode(code)}
      />
    </div>
  );
}
