/**
 * Flights layer — renders OpenSky ADS-B contacts from the entities store.
 *
 * Spatial-intelligence pattern (Bilawal Sidhu / WorldView): show every
 * live flight over the AOI; color military differently; let operators
 * click a flight to track it. Dashed when stale (last-seen > 60 s ago).
 */

import { ScatterplotLayer, PathLayer } from '@deck.gl/layers';
import type { Point } from 'geojson';
import type { Entity } from '../../types/entity';

function point(e: Entity): [number, number] {
  // Entities of kind 'flight' always carry Point geometry; narrow safely.
  return (e.geom as Point).coordinates as [number, number];
}

interface FlightsArgs {
  data: Entity[];
  selectedId?: string | null;
  onClick?: (id: string) => void;
  /** Current wall-clock for staleness comparison (passed as prop so React
   *  can drive re-render on pulse). */
  now: number;
}

const STALE_AFTER_MS = 60_000;

export function buildFlightsLayer({ data, selectedId = null, onClick, now }: FlightsArgs) {
  // Heading whisker — small line indicating direction of travel.
  const whiskers = new PathLayer<Entity>({
    id: 'flights-whisker',
    data,
    pickable: false,
    widthUnits: 'pixels',
    getPath: (e) => {
      const [lon, lat] = point(e);
      const hdg = ((e.attrs.heading as number) ?? 0) * (Math.PI / 180);
      // 0.02 deg ~ a few km at this lat; visual only, not geodesic
      const dlon = Math.sin(hdg) * 0.02;
      const dlat = Math.cos(hdg) * 0.02;
      return [
        [lon, lat],
        [lon + dlon, lat + dlat],
      ];
    },
    getColor: (e) => {
      const stale = now - e.lastSeen > STALE_AFTER_MS;
      const mil = Boolean(e.attrs.isMilitary);
      if (stale) return [255, 176, 0, 80];
      if (mil) return [230, 57, 70, 220];
      return [107, 182, 255, 220];
    },
    getWidth: 1.4,
    updateTriggers: { getColor: [now] },
  });

  const dots = new ScatterplotLayer<Entity>({
    id: 'flights-dot',
    data,
    pickable: true,
    stroked: true,
    filled: true,
    radiusUnits: 'pixels',
    lineWidthUnits: 'pixels',
    getPosition: (e) => point(e),
    getRadius: (e) => (selectedId === e.id ? 5 : 3),
    getFillColor: (e) => {
      const stale = now - e.lastSeen > STALE_AFTER_MS;
      const mil = Boolean(e.attrs.isMilitary);
      if (stale) return [232, 220, 196, 100];
      if (mil) return [230, 57, 70, 240];
      return [232, 220, 196, 240];
    },
    getLineColor: (e) => (selectedId === e.id ? [255, 176, 0, 255] : [10, 12, 16, 200]),
    getLineWidth: 1,
    onClick: (info) => {
      const id = info.object?.id;
      if (id) onClick?.(id);
    },
    updateTriggers: {
      getRadius: [selectedId],
      getLineColor: [selectedId],
      getFillColor: [now],
    },
  });

  return [whiskers, dots];
}
