/**
 * OSINT impact feed — synthetic geolocated civilian-impact observations.
 *
 * Part of the in-app "synthetic server" (no backend): each tick emits 0–2
 * geolocated observations (building collapse, fire, gas leak, trapped persons,
 * flood) across İstanbul under the Mw=7.5 Marmara scenario, pushed into the
 * unified entity store as kind:'witness' with attrs.osint=true.
 *
 * Mirrors src/feeds/afad.ts (startFeed runner). Provenance carried on every
 * observation via a per-observation sourceTag (GEO-OSINT / WITNESS / CCTV-CV /
 * AFAD) and Entity.source. The OSINT tab + map overlay read these via
 * osintObservations(). The store is capped to MAX_LIVE so a long session
 * doesn't grow unbounded.
 */

import type { Entity } from '../types/entity';
import { entityId } from '../types/entity';
import type { EntityMap } from '../store/entities';
import { useStore } from '../store';
import { startFeed, type FeedHandle } from './runner';

export type OsintCategory = 'collapse' | 'fire' | 'gasleak' | 'trapped' | 'flood';
export type OsintSourceTag = 'GEO-OSINT' | 'WITNESS' | 'CCTV-CV' | 'AFAD';

interface OsintObs {
  key: string;
  lat: number;
  lng: number;
  district: string;
  category: OsintCategory;
  sourceTag: OsintSourceTag;
  headline: string;
  tags: string[];
  hue: number;
  ts: number;
}

/** İstanbul district anchors (both sides of the Bosphorus). */
const DISTRICTS: { name: string; lat: number; lng: number }[] = [
  { name: 'Kadıköy', lat: 40.99, lng: 29.027 },
  { name: 'Üsküdar', lat: 41.024, lng: 29.013 },
  { name: 'Kartal', lat: 40.888, lng: 29.19 },
  { name: 'Maltepe', lat: 40.935, lng: 29.131 },
  { name: 'Pendik', lat: 40.876, lng: 29.234 },
  { name: 'Beşiktaş', lat: 41.043, lng: 29.007 },
  { name: 'Şişli', lat: 41.06, lng: 28.987 },
  { name: 'Beyoğlu', lat: 41.036, lng: 28.977 },
  { name: 'Fatih', lat: 41.018, lng: 28.949 },
  { name: 'Zeytinburnu', lat: 40.994, lng: 28.905 },
  { name: 'Bakırköy', lat: 40.978, lng: 28.872 },
  { name: 'Bağcılar', lat: 41.039, lng: 28.856 },
  { name: 'Esenyurt', lat: 41.034, lng: 28.673 },
  { name: 'Avcılar', lat: 40.979, lng: 28.717 },
  { name: 'Küçükçekmece', lat: 41.0, lng: 28.78 },
  { name: 'Ümraniye', lat: 41.016, lng: 29.124 },
  { name: 'Sultangazi', lat: 41.106, lng: 28.867 },
  { name: 'Eyüpsultan', lat: 41.055, lng: 28.934 },
];

const CATEGORIES: OsintCategory[] = ['collapse', 'fire', 'gasleak', 'trapped', 'flood'];
const SOURCE_TAGS: OsintSourceTag[] = ['GEO-OSINT', 'WITNESS', 'CCTV-CV', 'AFAD'];

const HEADLINE: Record<OsintCategory, string> = {
  collapse: 'Bina çöküntüsü',
  fire: 'Yapı yangını',
  gasleak: 'Doğalgaz kaçağı',
  trapped: 'Enkaz altında mahsur',
  flood: 'Su baskını',
};

function pick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)]!;
}

function severityFor(cat: OsintCategory): Entity['severity'] {
  switch (cat) {
    case 'collapse':
      return Math.random() < 0.18 ? 'flash' : 'immediate';
    case 'trapped':
      return 'immediate';
    case 'fire':
      return Math.random() < 0.2 ? 'immediate' : 'priority';
    case 'gasleak':
      return 'priority';
    case 'flood':
      return 'routine';
  }
}

function sourceFor(tag: OsintSourceTag): Entity['source'] {
  switch (tag) {
    case 'GEO-OSINT':
      return 'OSINT';
    case 'WITNESS':
      return 'WITNESS';
    case 'CCTV-CV':
      return 'IBB';
    case 'AFAD':
      return 'AFAD';
  }
}

function confidenceFor(tag: OsintSourceTag): number {
  switch (tag) {
    case 'CCTV-CV':
      return 0.82 + Math.random() * 0.12;
    case 'AFAD':
      return 0.9 + Math.random() * 0.08;
    case 'GEO-OSINT':
      return 0.55 + Math.random() * 0.2;
    case 'WITNESS':
      return 0.45 + Math.random() * 0.2;
  }
}

let seq = 0;

function makeObs(): OsintObs {
  const d = pick(DISTRICTS);
  const category = pick(CATEGORIES);
  const sourceTag = pick(SOURCE_TAGS);
  const ts = Date.now();
  seq += 1;
  return {
    key: `${ts}-${seq}`,
    lat: d.lat + (Math.random() - 0.5) * 0.02,
    lng: d.lng + (Math.random() - 0.5) * 0.02,
    district: d.name,
    category,
    sourceTag,
    headline: `${d.name} · ${HEADLINE[category]}`,
    tags: [sourceTag, 'SİVİL', category === 'trapped' ? 'KURTARMA' : 'DOĞRULANMADI'],
    hue: Math.floor(Math.random() * 360),
    ts,
  };
}

function mockOsintFetch(): Promise<OsintObs[]> {
  // Seed a few whenever the store has no OSINT observations yet, so the tab +
  // map have content immediately. Store-based (not a module flag) so it's
  // robust to React StrictMode's double-mount, which cancels the first tick's
  // apply and would otherwise consume a one-shot seed.
  if (osintObservations(useStore.getState().entities).length === 0) {
    return Promise.resolve([makeObs(), makeObs(), makeObs()]);
  }
  // The scenario surge multiplier (read live, not captured at module load)
  // scales the spawn rate; the MAX_LIVE cap in apply bounds the total.
  const surge = useStore.getState().osintSurge;
  if (surge <= 1 && Math.random() < 0.55) return Promise.resolve([]);
  const base = Math.random() < 0.7 ? 1 : 2;
  const count = Math.min(8, Math.max(1, Math.round(base * surge)));
  return Promise.resolve(Array.from({ length: count }, () => makeObs()));
}

const MAX_LIVE = 40;
const emitted: string[] = [];

export function startOsintFeed(): FeedHandle {
  return startFeed<OsintObs[]>({
    source: 'OSINT',
    label: 'OSINT',
    intervalMs: 14_000,
    fetch: () => mockOsintFetch(),
    apply: (observations) => {
      const store = useStore.getState();
      for (const o of observations) {
        const source = sourceFor(o.sourceTag);
        const id = entityId(source, 'witness', o.key);
        store.upsertEntity({
          id,
          kind: 'witness',
          geom: { type: 'Point', coordinates: [o.lng, o.lat] },
          attrs: {
            osint: true,
            type: 'osint',
            category: o.category,
            sourceTag: o.sourceTag,
            district: o.district,
            headline: o.headline,
            tags: o.tags,
            hue: o.hue,
          },
          source,
          affiliation: 'neutral',
          status: 'operational',
          severity: severityFor(o.category),
          confidence: Math.round(confidenceFor(o.sourceTag) * 100) / 100,
          firstSeen: o.ts,
          lastSeen: o.ts,
          links: [],
        });
        // Cap the live OSINT set so a long session doesn't grow unbounded.
        emitted.push(id);
        while (emitted.length > MAX_LIVE) {
          const old = emitted.shift();
          if (old) useStore.getState().removeEntity(old);
        }
      }
    },
  });
}

/** All live OSINT observations (entities tagged attrs.osint=true). */
export function osintObservations(map: EntityMap): Entity[] {
  const out: Entity[] = [];
  for (const e of map.values()) {
    if (e.attrs?.osint === true) out.push(e);
  }
  return out;
}
