export const IBB_CAMERAS: MobeseCamera[] = TOURISM.map((c) => ({
  ...c,
  streamUrl: streamUrl(c.id, 'hls'),
  streamMirror: streamUrl(c.id, 'live'),
  pageUrl: pageUrlForSlug(c.slug),
  codec: 'H.264 · 720p HLS',
  src: 'İBB · İstanbulu Seyret',
  status: 'UNVERIFIED' as const,
}));

export function findCameraById(id: string): MobeseCamera | undefined {
  return IBB_CAMERAS.find((c) => c.id === id);
}

/** Map the curated 18-camera registry to GeoJSON CameraFeature[] so the
 *  same source feeds the map-dot layer AND the GÖRÜ tile grid AND the OPS
 *  sidebar live-feed panel. Avoids the prior CameraFeature/MobeseCamera
 *  schema split. */
export function toCameraFeatures() {
  return IBB_CAMERAS.map((c) => ({
    type: 'Feature' as const,
    geometry: { type: 'Point' as const, coordinates: [c.lng, c.lat] as [number, number] },
    properties: {
      id: c.id,
      name: c.name,
      district: c.district,
      kind: c.type,
      hls: c.streamUrl,
      pageUrl: c.pageUrl,
    },
  }));
}

export { streamUrl };
