import * as turf from '@turf/turf';
import type {
  BeatFeature,
  CorridorFeature,
  Modality,
  SeaLaneFeature,
  UnitFeature,
  UnitState,
} from '../types/venue';
import { initialBearingDeg } from '../lib/geo/bearing';
import { RoadGraph } from './RoadGraph';

type RouteFeature = BeatFeature | CorridorFeature | SeaLaneFeature;

interface InternalUnit {
  id: string;
  callsign: string;
  modality: Modality;
  type: string;
  status: UnitState['status'];
  speedKph: number;
  offset: number;
  beatId: string;
  alt_m?: number;
  /** Ground units carry their spawn so they can snap onto the road graph. */
  spawn?: [number, number];
}

interface RouteCache {
  feature: RouteFeature;
  length_km: number;
}

type GroundPhase = 'patrol' | 'enroute' | 'onscene' | 'rtb';

/** Per-leg state for a ground unit travelling along real road geometry. */
interface GroundState {
  unit: InternalUnit;
  homeNode: number;
  endNode: number;
  /** Path polyline coordinates [lng,lat] for the current leg. */
  path: Array<[number, number]>;
  /** Cumulative km at each path vertex (cum[0] = 0). */
  cum: number[];
  lengthKm: number;
  startedAtMs: number;
  phase: GroundPhase;
  onsceneUntilMs: number;
}

const ONSCENE_HOLD_MS = 25_000;

const EARTH_R_KM = 6371;
/** Local haversine in km — replaces turf.distance in the hot paths. */
function haversineKm(aLng: number, aLat: number, bLng: number, bLat: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(bLat - aLat);
  const dLng = toRad(bLng - aLng);
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_R_KM * Math.asin(Math.min(1, Math.sqrt(s)));
}

/**
 * Pure kinematics engine — no React, no DOM. Caller drives it from a RAF loop.
 *
 * GROUND units patrol the real Istanbul road network (IBB emergency roads +
 * main arteries) via A* routing on {@link RoadGraph}: they pick reachable
 * waypoints, follow road geometry, and turn at real intersections. They can be
 * dispatched to an incident (patrol → enroute → onscene → rtb → patrol).
 *
 * HELI / FIXED / NAVAL units keep the legacy closed-loop behaviour: position
 * along the loop is `(offset + elapsed_hours * speed_kph / length_km) mod 1`.
 */
export class PatrolEngine {
  private units: InternalUnit[] = [];
  private routes = new Map<string, RouteCache>();
  private ground = new Map<string, GroundState>();
  private roadGraph: RoadGraph | null = null;
  private startedAt = performance.now();
  /** Ids of ground units awaiting a patrol-leg route, drained per tick. */
  private routeQueue: string[] = [];
  /** Bound on A* routes per snapshot so 3,000 units fan out across ticks. */
  private static readonly MAX_ROUTES_PER_TICK = 24;

  setRoadGraph(graph: RoadGraph | null): void {
    this.roadGraph = graph;
    // Re-initialise any ground units already loaded.
    if (graph && this.units.length) this.initGround(performance.now());
  }

  setRoutes(routes: RouteFeature[]): void {
    this.routes.clear();
    for (const f of routes) {
      if (!f.properties?.id) continue;
      const length_km = turf.length(f, { units: 'kilometers' });
      this.routes.set(f.properties.id, { feature: f, length_km: Math.max(0.01, length_km) });
    }
  }

  setUnits(units: UnitFeature[]): void {
    this.units = units.map((f) => ({
      id: f.properties.id,
      callsign: f.properties.callsign,
      modality: f.properties.modality,
      type: f.properties.type,
      status: f.properties.status,
      speedKph: f.properties.speed_kph,
      offset: f.properties.offset,
      beatId: f.properties.beat_id,
      alt_m: f.properties.alt_m,
      spawn: (f.geometry?.coordinates as [number, number]) ?? undefined,
    }));
    this.startedAt = performance.now();
    if (this.roadGraph) this.initGround(performance.now());
  }

  reseed(): void {
    this.startedAt = performance.now();
    if (this.roadGraph) this.initGround(performance.now());
  }

  /** Dispatch the nearest idle ground unit to a target; returns its id or null. */
  dispatchNearest(lng: number, lat: number): string | null {
    const g = this.roadGraph;
    if (!g) return null;
    let best: GroundState | null = null;
    let bestD = Infinity;
    for (const st of this.ground.values()) {
      if (st.phase !== 'patrol') continue;
      const pos = this.positionOf(st, performance.now());
      const d = haversineKm(pos[0], pos[1], lng, lat);
      if (d < bestD) {
        bestD = d;
        best = st;
      }
    }
    if (!best) return null;
    const target = g.nearestNode(lng, lat);
    const pos = this.positionOf(best, performance.now());
    const from = g.nearestNode(pos[0], pos[1]);
    const path = g.route(from, target);
    if (path.length < 2) return null;
    this.assignLeg(best, path, performance.now());
    best.phase = 'enroute';
    best.endNode = target;
    return best.unit.id;
  }

  private initGround(nowMs: number): void {
    const g = this.roadGraph!;
    this.ground.clear();
    this.routeQueue = [];
    for (const u of this.units) {
      if (u.modality !== 'ground' || !u.spawn) continue;
      const home = g.nearestNode(u.spawn[0], u.spawn[1]);
      if (home < 0) continue;
      // Park each unit at its home node and queue it for routing. Routes fan
      // out across ticks (MAX_ROUTES_PER_TICK) instead of all firing inline at
      // init, so spawning 3,000 units does not block on 3,000 A* searches.
      const st: GroundState = {
        unit: u,
        homeNode: home,
        endNode: home,
        path: [g.coord(home)],
        cum: [0],
        lengthKm: 0,
        startedAtMs: nowMs,
        phase: 'patrol',
        onsceneUntilMs: 0,
      };
      this.ground.set(u.id, st);
      this.routeQueue.push(u.id);
    }
  }

  /** Route up to MAX_ROUTES_PER_TICK queued patrol units. */
  private drainRouteQueue(nowMs: number): void {
    let routed = 0;
    while (routed < PatrolEngine.MAX_ROUTES_PER_TICK && this.routeQueue.length > 0) {
      const id = this.routeQueue.shift()!;
      const st = this.ground.get(id);
      // Skip if the unit was dispatched (now enroute) or already has a leg.
      if (!st || st.phase !== 'patrol' || st.lengthKm > 0) continue;
      this.startPatrolLeg(st, nowMs);
      routed++;
    }
  }

  /** Park a unit at its current leg-end and queue a fresh patrol route. */
  private parkAndQueue(st: GroundState, nowMs: number): void {
    const g = this.roadGraph!;
    st.path = [g.coord(st.endNode)];
    st.cum = [0];
    st.lengthKm = 0;
    st.startedAtMs = nowMs;
    st.phase = 'patrol';
    this.routeQueue.push(st.unit.id);
  }

  /** Route from the unit's current end node to a fresh nearby waypoint. */
  private startPatrolLeg(st: GroundState, nowMs: number): void {
    const g = this.roadGraph!;
    for (let attempt = 0; attempt < 4; attempt++) {
      const wp = g.randomWaypointNear(st.endNode);
      if (wp === st.endNode) continue;
      // Patrol legs are short; cap A* expansion so a bad pick can't stall a tick.
      const path = g.route(st.endNode, wp, 20_000);
      if (path.length >= 2) {
        this.assignLeg(st, path, nowMs);
        st.endNode = wp;
        return;
      }
    }
    // No route found — idle in place for this tick; retried next arrival.
    st.path = [g.coord(st.endNode)];
    st.cum = [0];
    st.lengthKm = 0;
    st.startedAtMs = nowMs;
  }

  private assignLeg(st: GroundState, nodePath: number[], nowMs: number): void {
    const g = this.roadGraph!;
    const coords: Array<[number, number]> = nodePath.map((n) => g.coord(n));
    const cum: number[] = [0];
    for (let i = 1; i < coords.length; i++) {
      const a = coords[i - 1]!;
      const b = coords[i]!;
      const d = haversineKm(a[0], a[1], b[0], b[1]);
      cum.push(cum[i - 1]! + d);
    }
    st.path = coords;
    st.cum = cum;
    st.lengthKm = cum[cum.length - 1]!;
    st.startedAtMs = nowMs;
    st.endNode = nodePath[nodePath.length - 1]!;
  }

  /** Interpolated [lng,lat] of a ground unit at nowMs (no phase advance). */
  private positionOf(st: GroundState, nowMs: number): [number, number] {
    if (st.lengthKm <= 0) return st.path[0]!;
    const elapsedHours = (nowMs - st.startedAtMs) / 3_600_000;
    let distKm = elapsedHours * st.unit.speedKph;
    if (distKm >= st.lengthKm) distKm = st.lengthKm;
    return this.interp(st, distKm)[0];
  }

  /** Returns [position, headingDeg] at the given arc-length. */
  private interp(st: GroundState, distKm: number): [[number, number], number] {
    const { path, cum } = st;
    if (path.length < 2) return [path[0]!, 0];
    let i = 0;
    while (i < cum.length - 2 && cum[i + 1]! < distKm) i++;
    const segLen = cum[i + 1]! - cum[i]!;
    const t = segLen > 0 ? (distKm - cum[i]!) / segLen : 0;
    const a = path[i]!;
    const b = path[i + 1]!;
    const lng = a[0] + (b[0] - a[0]) * t;
    const lat = a[1] + (b[1] - a[1]) * t;
    const heading = initialBearingDeg(a[1], a[0], b[1], b[0]);
    return [[lng, lat], Number.isFinite(heading) ? heading : 0];
  }

  snapshot(nowMs: number = performance.now()): UnitState[] {
    // Route a bounded batch of queued units first, so positions below reflect
    // any leg assigned this tick.
    if (this.roadGraph && this.routeQueue.length > 0) this.drainRouteQueue(nowMs);
    const elapsedHours = (nowMs - this.startedAt) / 3_600_000;
    const out: UnitState[] = [];
    for (const u of this.units) {
      if (u.modality === 'ground' && this.roadGraph && this.ground.has(u.id)) {
        out.push(this.snapshotGround(this.ground.get(u.id)!, nowMs));
        continue;
      }
      out.push(this.snapshotLoop(u, elapsedHours));
    }
    return out;
  }

  private snapshotGround(st: GroundState, nowMs: number): UnitState {
    const u = st.unit;
    // On-scene hold → begin return-to-base.
    if (st.phase === 'onscene' && nowMs >= st.onsceneUntilMs) {
      const g = this.roadGraph!;
      const path = g.route(st.endNode, st.homeNode);
      if (path.length >= 2) {
        this.assignLeg(st, path, nowMs);
        st.phase = 'rtb';
      } else {
        this.parkAndQueue(st, nowMs);
      }
    }

    const distKm = ((nowMs - st.startedAtMs) / 3_600_000) * u.speedKph;
    // Leg complete → advance the state machine.
    if (st.lengthKm > 0 && distKm >= st.lengthKm && st.phase !== 'onscene') {
      if (st.phase === 'enroute') {
        st.phase = 'onscene';
        st.onsceneUntilMs = nowMs + ONSCENE_HOLD_MS;
        st.path = [this.interp(st, st.lengthKm)[0]];
        st.cum = [0];
        st.lengthKm = 0;
        st.startedAtMs = nowMs;
      } else if (st.phase === 'rtb') {
        this.parkAndQueue(st, nowMs);
      } else {
        this.parkAndQueue(st, nowMs); // patrol → queue next waypoint
      }
    }

    const clamped = Math.min(distKm, st.lengthKm);
    const [pos, heading] = this.interp(st, clamped);
    return {
      id: u.id,
      callsign: u.callsign,
      modality: u.modality,
      type: u.type,
      status: st.phase,
      lon: pos[0],
      lat: pos[1],
      heading,
      speed: u.speedKph,
      alt_m: u.alt_m,
    };
  }

  private snapshotLoop(u: InternalUnit, elapsedHours: number): UnitState {
    const route = this.routes.get(u.beatId);
    if (!route) {
      return {
        id: u.id,
        callsign: u.callsign,
        modality: u.modality,
        type: u.type,
        status: u.status,
        lon: u.spawn?.[0] ?? 0,
        lat: u.spawn?.[1] ?? 0,
        heading: 0,
        speed: u.speedKph,
        alt_m: u.alt_m,
      };
    }
    const fractionDelta = (elapsedHours * u.speedKph) / route.length_km;
    let f = (u.offset + fractionDelta) % 1;
    if (f < 0) f += 1;
    const distKm = f * route.length_km;
    const point = turf.along(route.feature, distKm, { units: 'kilometers' });
    const ahead = turf.along(route.feature, Math.min(route.length_km, distKm + 0.05), {
      units: 'kilometers',
    });
    const heading = turf.bearing(point, ahead);
    const [lon, lat] = point.geometry.coordinates as [number, number];
    return {
      id: u.id,
      callsign: u.callsign,
      modality: u.modality,
      type: u.type,
      status: u.status,
      lon,
      lat,
      heading: Number.isFinite(heading) ? heading : 0,
      speed: u.speedKph,
      alt_m: u.alt_m,
    };
  }

  count(): number {
    return this.units.length;
  }
}
