import { useEffect, type ReactNode } from 'react';
import { useStore } from '../../store';
import { BASEMAP_MODES, BASEMAP_LABELS, cycleBasemap, type BasemapMode } from '../../map/basemap';

/**
 * Three-mode basemap switcher — bottom-right floating segmented control.
 *
 * Modes:
 *  • T (tactical)     — CARTO dark-matter
 *  • P (pristine)     — CARTO positron (light)
 *  • I (ibb-official) — basemap.ibb.gov.tr hosted Esri style
 *
 * Keyboard: Shift+B cycles forward, Shift+Alt+B cycles backward.
 */
export function BasemapSwitcher(): ReactNode {
  const mode = useStore((s) => s.basemapMode);
  const setMode = useStore((s) => s.setBasemapMode);

  useEffect(() => {
    function onKey(e: KeyboardEvent): void {
      if (!e.shiftKey || e.key.toLowerCase() !== 'b') return;
      // Don't hijack when an input has focus.
      const tag = (e.target as HTMLElement | null)?.tagName?.toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
      e.preventDefault();
      setMode(cycleBasemap(mode, !e.altKey));
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [mode, setMode]);

  return (
    <div
      className="basemap-switcher glass-panel glass-panel--tile glass-panel--float"
      role="tablist"
      aria-label="Basemap mode"
      title="Shift+B to cycle"
    >
      {BASEMAP_MODES.map((m: BasemapMode) => (
        <button
          key={m}
          type="button"
          role="tab"
          aria-selected={m === mode}
          data-active={m === mode || undefined}
          className="basemap-switcher__btn"
          onClick={() => setMode(m)}
          title={BASEMAP_LABELS[m]}
        >
          {m === 'tactical' ? 'T' : m === 'pristine' ? 'P' : m === 'satellite' ? 'S' : 'I'}
        </button>
      ))}
    </div>
  );
}
