/**
 * Coverage worker proxy — Phase 9 Leap Step 2/5.
 *
 * Lazy-loads the worker and wraps it via Comlink so the call site uses
 * a clean `await coverageWorker.computeCoverage(input)` API instead of
 * raw postMessage. Worker code stays in src/workers/coverage.worker.ts.
 *
 * The worker is bundled by Vite via the `new Worker(new URL(...), { type: 'module' })`
 * import.meta.url idiom — Vite picks this up and emits a real worker chunk.
 */
import * as Comlink from 'comlink';
import type { CoverageAPI } from './coverage.worker';

let cached: { worker: Worker; api: Comlink.Remote<CoverageAPI> } | null = null;

export function getCoverageWorker(): Comlink.Remote<CoverageAPI> {
  if (cached) return cached.api;
  const worker = new Worker(new URL('./coverage.worker.ts', import.meta.url), { type: 'module' });
  const api = Comlink.wrap<CoverageAPI>(worker);
  cached = { worker, api };
  return api;
}

export function terminateCoverageWorker(): void {
  if (!cached) return;
  cached.worker.terminate();
  cached = null;
}
