/**
 * Entity store slice — unified, normalized container for fused signals
 * across feeds. Used as a complementary slice alongside the existing
 * typed slices in `./index.ts` while per-layer migration happens.
 *
 * Phase 1 of the spatial-intelligence ultraplan. See
 * `.claude/plans/ultraplan-terminated-exitplanmode-never-serene-parnas.md`
 * Phase 1.
 */

import type { Entity, SourceTag } from '../types/entity';

export type EntityMap = Map<string, Entity>;

export interface EntitySlice {
  entities: EntityMap;
  selectedEntityId: string | null;
  /** Freshness telemetry per data source — drives feed-health indicator. */
  feedHealth: Record<SourceTag, { lastTick: number; ok: boolean }>;
}

export const initialEntitySlice: EntitySlice = {
  entities: new Map(),
  selectedEntityId: null,
  feedHealth: {
    KRDAE: { lastTick: 0, ok: false },
    EST: { lastTick: 0, ok: false },
    AFAD: { lastTick: 0, ok: false },
    IBB: { lastTick: 0, ok: false },
    ICAO: { lastTick: 0, ok: false },
    AIS: { lastTick: 0, ok: false },
    TLE: { lastTick: 0, ok: false },
    OSINT: { lastTick: 0, ok: false },
    WITNESS: { lastTick: 0, ok: false },
    LIVE: { lastTick: 0, ok: false },
    STALE: { lastTick: 0, ok: false },
    SIM: { lastTick: 0, ok: false },
  },
};

/**
 * Pure helpers — operate on the EntityMap and return a NEW Map. Zustand's
 * structural-equality check is shallow, so we re-construct the Map on every
 * write to drive subscribers. For volume larger than ~50K entities this gets
 * expensive; at that point swap for an immer-backed slice or use Map.set
 * directly with a manual subscriber bump.
 */
export function upsertEntity(map: EntityMap, e: Entity): EntityMap {
  const next = new Map(map);
  const prior = next.get(e.id);
  if (prior) {
    next.set(e.id, {
      ...prior,
      ...e,
      firstSeen: prior.firstSeen,
      lastSeen: e.lastSeen ?? Date.now(),
      links: Array.from(new Set([...prior.links, ...e.links])),
    });
  } else {
    next.set(e.id, {
      ...e,
      firstSeen: e.firstSeen ?? Date.now(),
      lastSeen: e.lastSeen ?? Date.now(),
    });
  }
  return next;
}

export function removeEntity(map: EntityMap, id: string): EntityMap {
  if (!map.has(id)) return map;
  const next = new Map(map);
  next.delete(id);
  return next;
}

export function linkEntities(map: EntityMap, a: string, b: string): EntityMap {
  const ea = map.get(a);
  const eb = map.get(b);
  if (!ea || !eb) return map;
  const next = new Map(map);
  next.set(a, { ...ea, links: Array.from(new Set([...ea.links, b])) });
  next.set(b, { ...eb, links: Array.from(new Set([...eb.links, a])) });
  return next;
}

/**
 * Find all entities whose lastSeen is older than `cutoffMs`. The absence-
 * layer reads from this to render "dark mahalle" / stale-camera klaxon
 * outlines. Returns ids only — caller dereferences if needed.
 */
export function staleIds(map: EntityMap, cutoffMs: number): string[] {
  const out: string[] = [];
  for (const e of map.values()) {
    if (e.lastSeen < cutoffMs) out.push(e.id);
  }
  return out;
}
