/**
 * Sortable table of pre-1999 building stock % per district. Pure HTML, no
 * library. Source: same KRDAE-derived district aggregate as the histogram
 * (currently seeded; replace with real GeoJSON join when available).
 */

import { useMemo, useState } from 'react';
import { DISTRICT_DATA } from '../histograms/VulnerabilityHistogram';
import { SourceChip } from '../../lib/sourceTag';

type SortKey = 'name' | 'vuln' | 'pre1999pct';
type SortDir = 'asc' | 'desc';

interface Props {
  selectedCode?: string | null;
  onSelect?: (code: string) => void;
}

export function PreNinetyNineTable({ selectedCode, onSelect }: Props) {
  const [key, setKey] = useState<SortKey>('pre1999pct');
  const [dir, setDir] = useState<SortDir>('desc');

  const rows = useMemo(() => {
    const sorted = [...DISTRICT_DATA].sort((a, b) => {
      const va = a[key];
      const vb = b[key];
      if (typeof va === 'string' && typeof vb === 'string') {
        return dir === 'asc' ? va.localeCompare(vb, 'tr') : vb.localeCompare(va, 'tr');
      }
      return dir === 'asc' ? (va as number) - (vb as number) : (vb as number) - (va as number);
    });
    return sorted;
  }, [key, dir]);

  const flip = (k: SortKey) => {
    if (k === key) setDir(dir === 'asc' ? 'desc' : 'asc');
    else {
      setKey(k);
      setDir(k === 'name' ? 'asc' : 'desc');
    }
  };

  const indicator = (k: SortKey) => (k === key ? (dir === 'asc' ? ' ▲' : ' ▼') : '');

  return (
    <section className="ops-panel glass-panel glass-panel--deep adli-table">
      <header className="ops-panel__title">
        PRE-1999 STOK · İLÇE TABLOSU
        <SourceChip source="KRDAE" />
      </header>
      <div className="adli-table__scroll">
        <table>
          <thead>
            <tr>
              <th onClick={() => flip('name')} style={{ cursor: 'pointer' }}>
                İlçe{indicator('name')}
              </th>
              <th onClick={() => flip('vuln')} style={{ cursor: 'pointer', textAlign: 'right' }}>
                Kırılganlık{indicator('vuln')}
              </th>
              <th
                onClick={() => flip('pre1999pct')}
                style={{ cursor: 'pointer', textAlign: 'right' }}
              >
                Pre-1999 %{indicator('pre1999pct')}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => {
              const isSel = selectedCode === r.code;
              return (
                <tr
                  key={r.code}
                  className={isSel ? 'is-selected' : ''}
                  onClick={() => onSelect?.(r.code)}
                  style={{ cursor: 'pointer' }}
                >
                  <td>
                    <span style={{ color: 'var(--bone-mute)', marginRight: 6 }}>{r.code}</span>
                    {r.name}
                  </td>
                  <td style={{ textAlign: 'right', color: 'var(--amber)' }}>{r.vuln}</td>
                  <td style={{ textAlign: 'right' }}>{r.pre1999pct}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
}
