import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './styles/globals.css';
import { App } from './App';
import { applyThemeToDom, loadThemeMode } from './lib/theme';

// Apply the persisted theme before createRoot so first paint is correct. The
// CSP forbids inline scripts and the render is JS-driven, so this is
// effectively pre-first-paint.
applyThemeToDom(loadThemeMode('pristine'));

const root = document.getElementById('root');
if (!root) {
  throw new Error('#root element missing in index.html');
}

createRoot(root).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
