/**
 * PTZ camera types — shared between the snapshot loader, the FOV layer, the
 * coverage worker, and the camera detail dock.
 *
 * The on-disk snapshot at /public/data/ptz_cameras.json uses short keys to
 * defend bundle size (228 KB raw → 24 KB gz at 632 entries). The hydrated
 * shape uses long names for readability inside the React tree.
 */

import type { LensProfile } from '../lib/fov';

/** Raw on-disk shape. Short keys; do not export to UI layers. */
export interface PtzCameraRaw {
  /** Numeric IBB camera ID. */
  readonly i: number;
  /** Display name, uppercase Turkish per IBB convention. */
  readonly n: string;
  /** Longitude (degrees, WGS-84). */
  readonly x: number;
  /** Latitude (degrees, WGS-84). */
  readonly y: number;
  /** HLS playlist URL. CORS-blocked in browser; Tauri-only. */
  readonly v: string;
  /** IBB-internal grouping ID (0 = ungrouped). */
  readonly g: number;
  /** Up to 3 PTZ preset snapshot URLs (`pno=0,1,2`). JPEG/PNG. */
  readonly p: readonly string[];
}

export interface PtzSnapshot {
  readonly generated: string;
  readonly source: string;
  readonly count: number;
  readonly cameras: readonly PtzCameraRaw[];
}

/** Hydrated camera for UI / map / coverage code. */
export interface PtzCamera {
  readonly id: number;
  readonly name: string;
  readonly lat: number;
  readonly lng: number;
  readonly streamUrl: string;
  readonly snapshotUrls: readonly string[];
  readonly groupId: number;
}

/** Preset bearing for a single PTZ position. Phase A is heuristic (from OSM
 *  road centerlines); Phase B is ORB-feature-matched against a synthetic
 *  panoramic reference; Phase C is keyframe-extracted live (deferred per
 *  doctrine §4.1). */
export interface PresetBearing {
  /** Camera ID. */
  readonly camId: number;
  /** Preset index — corresponds to `pno=0|1|2` in the snapshot URL. */
  readonly preset: 0 | 1 | 2;
  /** Bearing in degrees from true north, clockwise [0, 360). */
  readonly bearingDeg: number;
  /** Source of the bearing — `SIM` (synthetic seed, deterministic), `A` (heuristic OSM tangent), `B` (feature-match), `C` (live keyframe). */
  readonly phase: 'SIM' | 'A' | 'B' | 'C';
  /** Confidence 0..1; drives FOV polygon opacity. */
  readonly confidence: number;
}

/** FOV geometry derived from a camera + preset bearing + lens profile. */
export interface FovGeometry {
  readonly camId: number;
  readonly preset: 0 | 1 | 2;
  readonly bearingDeg: number;
  readonly lens: LensProfile;
  readonly footprint: ReadonlyArray<readonly [number, number]>;
  readonly confidence: number;
}

/** Coverage grid output of the worker (§D4). */
export interface CoverageGrid {
  /** Float32 array of cam-counts per cell (length = rows * cols). */
  readonly cells: Float32Array;
  readonly rows: number;
  readonly cols: number;
  /** SW corner of the grid, [lng, lat]. */
  readonly originLngLat: readonly [number, number];
  /** Cell size in degrees. */
  readonly cellDeg: number;
}

/** Hydrate a raw snapshot row into the UI-shape struct. */
export function hydrate(raw: PtzCameraRaw): PtzCamera {
  return {
    id: raw.i,
    name: raw.n,
    lat: raw.y,
    lng: raw.x,
    streamUrl: raw.v,
    snapshotUrls: raw.p,
    groupId: raw.g,
  };
}
