/**
 * OpenSky Network feed — live ADS-B over the Marmara bbox.
 *
 * Production: hits OpenSky's free /states/all endpoint with bbox params.
 * Free tier: rate-limited to ~10 s; treat 429 as expected and back off.
 * Dev / no network: mock returns a small swarm of plausible flights so the
 * cockpit shows motion offline.
 *
 * Each contact → Entity{kind:'flight', source:'ICAO'}. Stable id derived
 * from ICAO24 hex (which is the aircraft's hardware id, not the flight number).
 */

import { entityId, type Entity } from '../types/entity';
import { useStore } from '../store';
import { startFeed, type FeedHandle } from './runner';

/**
 * Resolve live-vs-mock from the flag and environment. An explicit
 * VITE_FEATURE_LIVE_OPENSKY wins; otherwise production goes live and
 * dev/test stay on the deterministic mock.
 */
export function resolveOpenSkyMode(
  flag: string | undefined,
  isProd: boolean,
): 'live' | 'mock' {
  if (flag === 'true') return 'live';
  if (flag === 'false') return 'mock';
  return isProd ? 'live' : 'mock';
}

/** UI label for the current OpenSky mode (used by DataSourcesDock). */
export function openSkyModeLabel(): 'CANLI' | 'MOCK' {
  return resolveOpenSkyMode(import.meta.env?.VITE_FEATURE_LIVE_OPENSKY, import.meta.env.PROD) ===
    'live'
    ? 'CANLI'
    : 'MOCK';
}

/** A flight entity is stale once it has gone 120 s without an update. */
export function isStaleFlight(e: Entity, nowMs: number): boolean {
  return e.kind === 'flight' && nowMs - (e.lastSeen ?? 0) > 120_000;
}

interface OpenSkyState {
  icao24: string;
  callsign: string;
  origin: string;
  lon: number;
  lat: number;
  alt_m: number;
  velocity_ms: number;
  heading: number;
  vrate_ms: number;
  ts: number;
  onGround: boolean;
}

// Marmara bbox
const BBOX = { lamin: 40.5, lomin: 27.5, lamax: 41.5, lomax: 30.5 };

function mockOpenSkyFetch(): Promise<OpenSkyState[]> {
  const now = Date.now();
  // Seed a small swarm of slow-moving fake flights for offline dev.
  const seeds = [
    { id: 'mock-thy631', cs: 'THY631  ', origin: 'TC', lat: 40.98, lon: 28.81 },
    { id: 'mock-pgt442', cs: 'PGT442  ', origin: 'TC', lat: 40.6, lon: 29.1 },
    { id: 'mock-uae001', cs: 'UAE001  ', origin: 'AE', lat: 41.0, lon: 29.7 },
    { id: 'mock-mil', cs: 'TUAFA1  ', origin: 'TC', lat: 40.85, lon: 28.3 },
  ];
  return Promise.resolve(
    seeds.map((s, i) => ({
      icao24: s.id,
      callsign: s.cs,
      origin: s.origin,
      lat: s.lat + Math.sin(now / 60_000 + i) * 0.04,
      lon: s.lon + Math.cos(now / 60_000 + i) * 0.06,
      alt_m: 8000 + i * 500,
      velocity_ms: 240 + i * 12,
      heading: (now / 1000 + i * 90) % 360,
      vrate_ms: 0,
      ts: Math.floor(now / 1000),
      onGround: false,
    })),
  );
}

async function liveOpenSkyFetch(signal: AbortSignal): Promise<OpenSkyState[]> {
  const url = `https://opensky-network.org/api/states/all?lamin=${BBOX.lamin}&lomin=${BBOX.lomin}&lamax=${BBOX.lamax}&lomax=${BBOX.lomax}`;
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`OpenSky ${res.status}`);
  const data = (await res.json()) as { states: unknown[][] | null; time: number };
  if (!data.states) return [];
  // OpenSky tuple positions per their schema.
  return data.states
    .map((s) => {
      const lat = s[6] as number | null;
      const lon = s[5] as number | null;
      if (lat == null || lon == null) return null;
      return {
        icao24: String(s[0] ?? ''),
        callsign: String(s[1] ?? '').trim(),
        origin: String(s[2] ?? ''),
        lon,
        lat,
        alt_m: (s[7] as number | null) ?? 0,
        velocity_ms: (s[9] as number | null) ?? 0,
        heading: (s[10] as number | null) ?? 0,
        vrate_ms: (s[11] as number | null) ?? 0,
        ts: data.time,
        onGround: Boolean(s[8]),
      } satisfies OpenSkyState;
    })
    .filter((x): x is OpenSkyState => x !== null);
}

/**
 * Build a flight entity, tagging source/confidence by the mode that produced
 * it: a live ADS-B contact carries `ICAO` + 0.9; a SIM contact carries `SIM`
 * + 0.5 so the chip always tells the truth about the data origin.
 */
export function stateToEntity(s: OpenSkyState, live: boolean): Entity {
  const id = entityId(live ? 'ICAO' : 'SIM', 'flight', s.icao24 || s.callsign);
  return {
    id,
    kind: 'flight',
    geom: { type: 'Point', coordinates: [s.lon, s.lat] },
    attrs: {
      callsign: s.callsign,
      origin: s.origin,
      alt_m: s.alt_m,
      velocity_ms: s.velocity_ms,
      heading: s.heading,
      isMilitary: s.callsign.startsWith('TUAFA') || s.callsign.startsWith('USAF'),
    },
    source: live ? 'ICAO' : 'SIM',
    affiliation: 'friend',
    status: 'operational',
    severity: 'info',
    confidence: live ? 0.9 : 0.5,
    firstSeen: s.ts * 1000,
    lastSeen: s.ts * 1000,
    links: [],
  };
}

export function startOpenSkyFeed(): FeedHandle {
  const mode = resolveOpenSkyMode(
    import.meta.env?.VITE_FEATURE_LIVE_OPENSKY,
    import.meta.env.PROD,
  );
  const live = mode === 'live';

  // Degraded-mode state lives in this closure (never module scope), so a
  // remount starts clean.
  let consecutiveFailures = 0;
  let degraded = false;
  let degradedTicks = 0;
  // Whether the most recent batch came from the live API — read by `apply`
  // so entities are tagged ICAO vs SIM honestly even mid-fallback.
  let lastBatchLive = live;

  const fetchBatch = async (signal: AbortSignal): Promise<OpenSkyState[]> => {
    if (!live) {
      lastBatchLive = false;
      return mockOpenSkyFetch();
    }
    if (degraded) {
      degradedTicks += 1;
      // Every 10th degraded tick, re-probe live and recover on success.
      if (degradedTicks % 10 === 0) {
        try {
          const states = await liveOpenSkyFetch(signal);
          degraded = false;
          consecutiveFailures = 0;
          degradedTicks = 0;
          lastBatchLive = true;
          return states;
        } catch {
          // Still down — keep serving SIM-labeled mock below.
        }
      }
      lastBatchLive = false;
      return mockOpenSkyFetch();
    }
    try {
      const states = await liveOpenSkyFetch(signal);
      consecutiveFailures = 0;
      lastBatchLive = true;
      return states;
    } catch {
      // Three consecutive live failures → degrade to SIM-labeled mock. The
      // data keeps flowing (the tick counts as success) but is honestly
      // chipped SIM, not ICAO.
      consecutiveFailures += 1;
      if (consecutiveFailures >= 3) degraded = true;
      lastBatchLive = false;
      return mockOpenSkyFetch();
    }
  };

  return startFeed<OpenSkyState[]>({
    source: 'ICAO',
    label: 'OpenSky',
    intervalMs: live ? 60_000 : 10_000,
    fetch: fetchBatch,
    apply: (states) => {
      const store = useStore.getState();
      for (const s of states) {
        if (s.onGround) continue;
        store.upsertEntity(stateToEntity(s, lastBatchLive));
      }
      // Prune flights that have stopped updating (e.g. left the bbox, or the
      // live→SIM flip orphaned the old ICAO-id contacts).
      const now = Date.now();
      for (const e of store.entities.values()) {
        if (isStaleFlight(e, now)) store.removeEntity(e.id);
      }
    },
  });
}
