/**
 * OsintMapOverlay — HTML strike-cards anchored to real geo coordinates on the
 * live map (the genuine "spatial intelligence" read, vs the mockup's fake
 * %-positioned canvas). Rendered inside MapHost so it has the MapLibre map; it
 * reprojects on every map move. Only the top-N most severe observations get an
 * anchored card (the rest are deck markers) to bound layout cost.
 *
 * Shown only on the OSINT tab so it doesn't clutter the OPS map.
 */
import { useEffect, useReducer } from 'react';
import type { Map as MapLibreMap } from 'maplibre-gl';
import { useStore } from '../../store';
import { osintObservations } from '../../feeds/osint';
import { sortBySeverity } from '../../store/selectors';
import { SevGlyph } from '../../lib/sevGlyph';
import { SourceChip } from '../../lib/sourceTag';

const MAX_ANCHORED = 4;

export function OsintMapOverlay({ map }: { map: MapLibreMap | null }) {
  const activeTab = useStore((s) => s.activeTab);
  const entities = useStore((s) => s.entities);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const selectEntity = useStore((s) => s.selectEntity);
  const openDock = useStore((s) => s.openDock);
  const [, reproject] = useReducer((x: number) => x + 1, 0);

  useEffect(() => {
    if (!map) return;
    const h = () => reproject();
    map.on('move', h);
    return () => {
      map.off('move', h);
    };
  }, [map]);

  if (!map || activeTab !== 'osint') return null;
  const top = sortBySeverity(osintObservations(entities)).slice(0, MAX_ANCHORED);
  if (top.length === 0) return null;

  return (
    <div className="osint-overlay">
      {top.map((e) => {
        if (e.geom.type !== 'Point') return null;
        const [lng, lat] = e.geom.coordinates as [number, number];
        const p = map.project([lng, lat]);
        const headline = String(e.attrs.headline ?? e.attrs.category ?? '');
        const district = String(e.attrs.district ?? '');
        const active = selectedEntityId === e.id;
        return (
          <button
            key={e.id}
            type="button"
            className="osint-pin"
            data-active={active || undefined}
            style={{ left: `${p.x}px`, top: `${p.y}px` }}
            onClick={() => {
              selectEntity(e.id);
              openDock('feed-inspector');
            }}
          >
            <span className="osint-pin__head">
              <SevGlyph severity={e.severity} pulse={e.severity === 'flash'} />
              <span className="osint-pin__title">{headline}</span>
            </span>
            <span className="osint-pin__sub">
              <span>{district}</span>
              <SourceChip source={e.source} />
              <span className="osint-pin__conf">%{Math.round(e.confidence * 100)}</span>
            </span>
            <span className="osint-pin__stem" aria-hidden="true" />
          </button>
        );
      })}
    </div>
  );
}
