import { useEffect, useMemo, useRef, useState } from 'react';
import type { Map as MapLibreMap } from 'maplibre-gl';
import type { Layer } from '@deck.gl/core';
import { createGlobeMap, flyToRegion, GLOBE_HOME, GLOBE_INITIAL_ZOOM } from './globeController';
import { DeckOverlay } from './deckOverlay';
import { buildHeliPadsLayer } from './layers/heliPadsLayer';
import { buildPortsLayer } from './layers/portsLayer';
import { buildAirfieldsLayer } from './layers/airfieldsLayer';
import { buildIncidentsLayers } from './layers/incidentsPulseLayer';
import { buildPatrolsLayer } from './layers/patrolsLayer';
import { buildCamerasLayer } from './layers/camerasLayer';
import { buildOsintLayers } from './layers/osintLayer';
import { buildSatLayer, decodeSatPositions, type SatDatum } from './layers/satLayer';
import { useStore } from '../store';
import type { UnitState } from '../types/venue';
import { loadSatCatalog } from '../satellites/loader';
import { getSatWorker } from '../workers/satProxy';
import { osintObservations } from '../feeds/osint';
import { SatCatalogDock } from '../ui/dock/SatCatalogDock';
import { SatDetailDock } from '../ui/dock/SatDetailDock';
import { CameraHoverPreview } from '../ui/cameras/CameraHoverPreview';
import { UnitHoverPreview } from '../ui/cameras/UnitHoverPreview';
import { IncidentHoverPreview } from '../ui/cameras/IncidentHoverPreview';
import { SatHoverPreview } from '../ui/cameras/SatHoverPreview';
import { CameraDetailDock } from '../ui/cameras/CameraDetailDock';
import { OsintMapOverlay } from '../ui/osint/OsintMapOverlay';

interface GlobeHostProps {
  unitSnapshot: UnitState[];
  pulseT: number;
}

interface GlobePreset {
  id: string;
  label: string;
  center: [number, number];
  zoom: number;
}

const PRESETS: GlobePreset[] = [
  { id: 'globe',  label: 'Küre',        center: GLOBE_HOME,     zoom: GLOBE_INITIAL_ZOOM },
  { id: 'avrasya',label: 'Avrasya',     center: [40, 45],       zoom: 3.0 },
  { id: 'tr',     label: 'Türkiye',     center: [35.3, 39.0],   zoom: 5.2 },
  { id: 'marmara',label: 'Marmara',     center: [28.5, 40.7],   zoom: 7.4 },
  { id: 'ist',    label: 'İstanbul',    center: [28.98, 41.04], zoom: 10.4 },
];

/**
 * Küre tab map: MapLibre v5 globe projection with NASA GIBS BlueMarble
 * basemap, AWS terrain, atmosphere/sky, and the same deck.gl operational
 * overlay (heli pads, ports, airfields, incidents, patrols, cameras, OSINT)
 * projected onto the sphere.
 */
export function GlobeHost({ unitSnapshot, pulseT }: GlobeHostProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [mapReady, setMapReady] = useState<MapLibreMap | null>(null);
  const [activePreset, setActivePreset] = useState<string>('globe');

  const incidents = useStore((s) => s.incidents);
  const entities = useStore((s) => s.entities);
  const staticGeo = useStore((s) => s.staticGeo);
  const selectIncident = useStore((s) => s.selectIncident);
  const selectUnit = useStore((s) => s.selectUnit);
  const selectCamera = useStore((s) => s.selectCamera);
  const selectEntity = useStore((s) => s.selectEntity);
  const selectedIncidentId = useStore((s) => s.selectedIncidentId);
  const selectedUnitId = useStore((s) => s.selectedUnitId);
  const selectedCameraId = useStore((s) => s.selectedCameraId);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const camerasEnabled = useStore((s) => s.camerasEnabled);
  const incidentsEnabled = useStore((s) => s.incidentsEnabled);
  const patrolsEnabled = useStore((s) => s.patrolsEnabled);
  const osintEnabled = useStore((s) => s.osintEnabled);
  const satCatBitmask = useStore((s) => s.satCatBitmask);
  const satOpacity = useStore((s) => s.satOpacity);
  const setSatCounts = useStore((s) => s.setSatCounts);
  const selectSatByNorad = useStore((s) => s.selectSatByNorad);
  const openDock = useStore((s) => s.openDock);
  const setHoveredCamera = useStore((s) => s.setHoveredCamera);
  const setHoveredUnit = useStore((s) => s.setHoveredUnit);
  const setHoveredIncident = useStore((s) => s.setHoveredIncident);
  const setHoveredSat = useStore((s) => s.setHoveredSat);

  const [satData, setSatData] = useState<SatDatum[]>([]);

  useEffect(() => {
    if (!containerRef.current) return undefined;
    const map = createGlobeMap({ container: containerRef.current });
    mapRef.current = map;
    map.once('load', () => setMapReady(map));
    return () => {
      map.remove();
      mapRef.current = null;
      setMapReady(null);
    };
  }, []);

  // SGP4 worker — init once with the catalog, then propagate at 1.5 Hz.
  useEffect(() => {
    let cancelled = false;
    let intervalId: number | null = null;
    void (async () => {
      const catalog = await loadSatCatalog();
      if (cancelled || catalog.length === 0) return;
      const worker = getSatWorker();
      await worker.init(
        catalog.map((s) => ({ n: s.noradId, c: s.category, l1: s.line1, l2: s.line2, nm: s.name })),
        satCatBitmask,
      );
      const counts = await worker.countsByCategory();
      if (!cancelled) setSatCounts(counts);
      const tick = async () => {
        if (cancelled) return;
        try {
          const out = await worker.propagate(Date.now());
          if (cancelled) return;
          setSatData(decodeSatPositions(out.positions, out.noradIds));
        } catch (err) {
          console.warn('[sat] propagate failure', err);
        }
      };
      await tick();
      intervalId = window.setInterval(() => void tick(), 666); // 1.5 Hz
    })();
    return () => {
      cancelled = true;
      if (intervalId !== null) window.clearInterval(intervalId);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Expose the latest sat data for SatHoverPreview to access without store subscriptions.
  useEffect(() => {
    (window as unknown as { __akomSatData?: typeof satData }).__akomSatData = satData;
  }, [satData]);

  // Push bitmask changes to the worker.
  useEffect(() => {
    const worker = getSatWorker();
    void worker.setCategoryBitmask(satCatBitmask);
  }, [satCatBitmask]);

  const layers = useMemo<Layer[]>(() => {
    const out: Layer[] = [];
    out.push(buildHeliPadsLayer(staticGeo.pads));
    out.push(buildPortsLayer(staticGeo.ports));
    out.push(buildAirfieldsLayer(staticGeo.airfields));
    if (camerasEnabled && staticGeo.cameras.length > 0) {
      out.push(
        ...buildCamerasLayer({
          data: staticGeo.cameras,
          selectedId: selectedCameraId,
          onClick: selectCamera,
          onHover: (h) =>
            setHoveredCamera(
              h ? { camId: h.camId, x: h.x, y: h.y } : null,
            ),
        }),
      );
    }
    if (incidentsEnabled) {
      out.push(
        ...buildIncidentsLayers({
          data: incidents,
          pulseT,
          selectedId: selectedIncidentId,
          onClick: selectIncident,
          onHover: (h) =>
            setHoveredIncident(
              h ? { incidentId: h.incidentId, x: h.x, y: h.y } : null,
            ),
        }),
      );
    }
    if (patrolsEnabled) {
      out.push(
        ...buildPatrolsLayer({
          data: unitSnapshot,
          selectedId: selectedUnitId,
          onClick: selectUnit,
          onHover: (h) =>
            setHoveredUnit(
              h ? { unitId: h.unitId, x: h.x, y: h.y } : null,
            ),
        }),
      );
    }
    // OSINT geolocated impact observations.
    if (osintEnabled) {
      const osintEntities = osintObservations(entities);
      if (osintEntities.length > 0) {
        out.push(
          ...buildOsintLayers({
            data: osintEntities,
            pulseT,
            selectedId: selectedEntityId,
            onClick: (id) => {
              selectEntity(id);
              openDock('feed-inspector');
            },
          }),
        );
      }
    }
    // Phase 9 Leap Step 3 — 15,457-satellite catalog overlay.
    const sat = buildSatLayer({
      data: satData,
      opacity: satOpacity,
      onClick: (d) => {
        selectSatByNorad(d.noradId);
        openDock('sat-detail');
      },
      onHover: (h) => {
        if (h) {
          setHoveredSat({ noradId: h.noradId, x: h.x, y: h.y });
        } else {
          setHoveredSat(null);
        }
      },
    });
    if (sat) out.push(sat);
    return out;
  }, [
    staticGeo,
    camerasEnabled,
    incidentsEnabled,
    patrolsEnabled,
    osintEnabled,
    selectedCameraId,
    selectCamera,
    setHoveredCamera,
    incidents,
    pulseT,
    selectedIncidentId,
    selectIncident,
    setHoveredIncident,
    unitSnapshot,
    selectedUnitId,
    selectUnit,
    setHoveredUnit,
    entities,
    selectedEntityId,
    selectEntity,
    openDock,
    satData,
    satOpacity,
    selectSatByNorad,
    setHoveredSat,
  ]);

  const handlePreset = (preset: GlobePreset) => {
    setActivePreset(preset.id);
    if (mapReady) flyToRegion(mapReady, preset.center, preset.zoom);
  };

  return (
    <section className="hud-pane hud-pane--map" style={{ gridColumn: '1 / -1' }}>
      <div className="map-host">
        <div ref={containerRef} className="map-canvas" />
        <DeckOverlay map={mapReady} layers={layers} />

        <div className="map-toolbar" style={{ display: 'flex', gap: 8 }}>
          {PRESETS.map((p) => (
            <button
              key={p.id}
              type="button"
              className={`map-toolbar__btn glass-panel glass-panel--float glass-panel--pill glass-panel--interactive ${activePreset === p.id ? 'is-active glass-panel--amber' : ''}`}
              onClick={() => handlePreset(p)}
              aria-pressed={activePreset === p.id}
            >
              {p.label}
            </button>
          ))}
        </div>

        <div
          className="glass-panel glass-panel--float glass-panel--pill"
          style={{
            position: 'absolute',
            top: 14,
            right: 14,
            padding: '8px 14px',
            fontFamily: 'var(--font-mono)',
            fontSize: 'var(--t-tiny)',
            letterSpacing: '0.12em',
            textTransform: 'uppercase',
            color: 'var(--bone-mute)',
          }}
        >
          NASA · BlueMarble · GIBS · {staticGeo.cameras.length} Kamera · {satData.length} Sat
        </div>

        <button
          type="button"
          className="glass-panel glass-panel--float glass-panel--pill glass-panel--interactive"
          style={{
            position: 'absolute',
            top: 14,
            right: 220,
            padding: '6px 12px',
            fontFamily: 'var(--font-mono)',
            fontSize: 'var(--t-tiny)',
            letterSpacing: '0.08em',
            cursor: 'pointer',
          }}
          onClick={() => openDock('sat-catalog')}
        >
          SAT CATALOG
        </button>

        <SatCatalogDock />
        <SatDetailDock />
        <CameraDetailDock context={null} />
        <CameraHoverPreview />
        <UnitHoverPreview />
        <IncidentHoverPreview />
        <SatHoverPreview />
        <OsintMapOverlay map={mapReady} />

        <div className="map-watermark">
          AKOM · MAPLIBRE V5 · GLOBE · {unitSnapshot.length} BİRİM ·{' '}
          {staticGeo.cameras.length} KAMERA · {satData.length} SAT
        </div>
      </div>
    </section>
  );
}
