/**
 * DockPanel — generic floating panel chrome for the Phase-9 dock system.
 *
 * Header-drag, bottom-right corner resize, minimize-to-launcher, close,
 * bring-to-front on pointer-down. Position / size / open-state / z-order
 * persist via the dock slice → localStorage.
 *
 * Bespoke implementation (no react-rnd dep) — keeps the bundle defended.
 * The drag and resize hooks below are ~120 lines combined and have zero
 * dependencies beyond React 19's pointer events.
 *
 * Usage:
 *   <DockPanel id="sat-catalog" title="Satellite Catalog">
 *     <SatCatalogBody />
 *   </DockPanel>
 *
 * Panels render via `dock[id].open` — the parent shell renders the panel
 * unconditionally; the panel returns `null` when closed. This keeps React
 * tree position stable so animations don't restart on toggle.
 */

import { useCallback, useEffect, useRef, type ReactNode } from 'react';
import { useStore } from '../../store';
import type { DockId } from '../../store/dock';

export interface DockPanelProps {
  readonly id: DockId;
  readonly title: string;
  readonly children: ReactNode;
  /** Minimum width in px; defaults to 240. */
  readonly minW?: number;
  /** Minimum height in px; defaults to 160. */
  readonly minH?: number;
}

const VIEWPORT_PAD = 4; // px — keep at least this much of the title bar on screen

export function DockPanel({
  id,
  title,
  children,
  minW = 240,
  minH = 160,
}: DockPanelProps): ReactNode {
  const dockEntry = useStore((s) => s.dock[id]);
  const setDock = useStore((s) => s.setDock);
  const closeDock = useStore((s) => s.closeDock);
  const bringToFront = useStore((s) => s.bringToFront);

  const panelRef = useRef<HTMLDivElement | null>(null);
  const dragState = useRef<{
    pointerId: number;
    startX: number;
    startY: number;
    origX: number;
    origY: number;
  } | null>(null);
  const resizeState = useRef<{
    pointerId: number;
    startX: number;
    startY: number;
    origW: number;
    origH: number;
  } | null>(null);

  // Pointer-up handler installed at window scope while drag/resize is active.
  const stopGestures = useCallback(() => {
    dragState.current = null;
    resizeState.current = null;
  }, []);

  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      const dr = dragState.current;
      if (dr && e.pointerId === dr.pointerId) {
        const dx = e.clientX - dr.startX;
        const dy = e.clientY - dr.startY;
        const vw = window.innerWidth;
        const vh = window.innerHeight;
        const nextX = clamp(dr.origX + dx, -dockEntry.w + VIEWPORT_PAD * 8, vw - VIEWPORT_PAD * 8);
        const nextY = clamp(dr.origY + dy, 0, vh - VIEWPORT_PAD * 4);
        setDock(id, { x: nextX, y: nextY });
      }
      const rs = resizeState.current;
      if (rs && e.pointerId === rs.pointerId) {
        const dx = e.clientX - rs.startX;
        const dy = e.clientY - rs.startY;
        const vw = window.innerWidth;
        const vh = window.innerHeight;
        const nextW = clamp(rs.origW + dx, minW, vw - dockEntry.x - VIEWPORT_PAD);
        const nextH = clamp(rs.origH + dy, minH, vh - dockEntry.y - VIEWPORT_PAD);
        setDock(id, { w: nextW, h: nextH });
      }
    };
    const onUp = () => stopGestures();
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
    };
  }, [dockEntry.w, dockEntry.h, dockEntry.x, dockEntry.y, id, minH, minW, setDock, stopGestures]);

  if (!dockEntry.open) return null;

  const onHeaderPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    bringToFront(id);
    dragState.current = {
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      origX: dockEntry.x,
      origY: dockEntry.y,
    };
    (e.target as Element).setPointerCapture?.(e.pointerId);
  };

  const onResizePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    bringToFront(id);
    resizeState.current = {
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      origW: dockEntry.w,
      origH: dockEntry.h,
    };
    (e.target as Element).setPointerCapture?.(e.pointerId);
  };

  return (
    <div
      ref={panelRef}
      className="dock-panel"
      role="dialog"
      aria-label={title}
      onPointerDown={() => bringToFront(id)}
      style={{
        position: 'fixed',
        left: dockEntry.x,
        top: dockEntry.y,
        width: dockEntry.w,
        height: dockEntry.h,
        zIndex: 100 + dockEntry.z,
      }}
    >
      <div className="dock-panel__header" onPointerDown={onHeaderPointerDown}>
        <span className="dock-panel__title">{title}</span>
        <div className="dock-panel__actions">
          <button
            type="button"
            className="dock-panel__btn"
            aria-label={`Minimize ${title}`}
            onClick={(e) => {
              e.stopPropagation();
              closeDock(id);
            }}
          >
            —
          </button>
          <button
            type="button"
            className="dock-panel__btn"
            aria-label={`Close ${title}`}
            onClick={(e) => {
              e.stopPropagation();
              closeDock(id);
            }}
          >
            ×
          </button>
        </div>
      </div>
      <div className="dock-panel__body">{children}</div>
      <div
        className="dock-panel__resize"
        onPointerDown={onResizePointerDown}
        aria-hidden="true"
      />
    </div>
  );
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}
