/**
 * Coverage union layer — Phase 9 Leap Step 2.
 * Renders the polygon-union of all active FOV cones as a translucent blue
 * GeoJsonLayer. Feed produced by the coverage Worker (Comlink-wrapped).
 */
import { GeoJsonLayer } from '@deck.gl/layers';
import type { FeatureCollection } from 'geojson';

export interface CoverageLayerOpts {
  data: FeatureCollection;
  opacity?: number;
}

export function buildCoverageLayer(opts: CoverageLayerOpts): GeoJsonLayer | null {
  if (opts.data.features.length === 0) return null;
  const opacity = opts.opacity ?? 0.35;
  return new GeoJsonLayer({
    id: 'fov-coverage',
    data: opts.data,
    getFillColor: [59, 130, 246, Math.floor(255 * opacity)],
    getLineColor: [59, 130, 246, 200],
    getLineWidth: 1,
    lineWidthUnits: 'pixels',
    stroked: true,
    filled: true,
    pickable: false,
  });
}
