/**
 * Procedural meshes for the 3D PTZ camera bodies and FOV frustums.
 *
 * Both meshes live in a local right-handed frame where the camera *looks down
 * +X*, +Z is up, +Y is left. SimpleMeshLayer positions each instance at the
 * camera lng/lat and rotates it by `getOrientation = [pitch, yaw, roll]`
 * (degrees). We convert a compass bearing (clockwise from north) to yaw with
 * `yaw = 90 - bearing` so bearing 0 (north) points the mesh +Y-ish — verified
 * visually in the browser.
 *
 * Meshes are unlit (material:false on the layer) so we don't need normals.
 */

/** SimpleMeshLayer-compatible mesh (loaders.gl MeshAttributes shape). */
export interface Mesh {
  attributes: { positions: { value: Float32Array; size: 3 } };
  indices: { value: Uint16Array; size: 1 };
}

function toMesh(pos: number[], idx: number[]): Mesh {
  return {
    attributes: { positions: { value: new Float32Array(pos), size: 3 } },
    indices: { value: new Uint16Array(idx), size: 1 },
  };
}

/** Append a box [cx±hx, cy±hy, cz±hz] into the running vertex/index arrays. */
function pushBox(
  pos: number[],
  idx: number[],
  cx: number,
  cy: number,
  cz: number,
  hx: number,
  hy: number,
  hz: number,
): void {
  const base = pos.length / 3;
  const corners: Array<[number, number, number]> = [
    [cx - hx, cy - hy, cz - hz],
    [cx + hx, cy - hy, cz - hz],
    [cx + hx, cy + hy, cz - hz],
    [cx - hx, cy + hy, cz - hz],
    [cx - hx, cy - hy, cz + hz],
    [cx + hx, cy - hy, cz + hz],
    [cx + hx, cy + hy, cz + hz],
    [cx - hx, cy + hy, cz + hz],
  ];
  for (const c of corners) pos.push(c[0], c[1], c[2]);
  const faces = [
    [0, 1, 2, 3], // bottom
    [4, 5, 6, 7], // top
    [0, 1, 5, 4], // front (-Y)
    [2, 3, 7, 6], // back (+Y)
    [1, 2, 6, 5], // right (+X)
    [0, 3, 7, 4], // left (-X)
  ];
  for (const f of faces) {
    idx.push(base + f[0]!, base + f[1]!, base + f[2]!);
    idx.push(base + f[0]!, base + f[2]!, base + f[3]!);
  }
}

/**
 * Camera body: a housing box mounted on a short pole, with a lens barrel that
 * protrudes along +X (the look direction). Dimensions are in metres; the layer
 * applies a global sizeScale so they read at city zoom.
 */
export function cameraBodyMesh(): Mesh {
  const pos: number[] = [];
  const idx: number[] = [];
  // Mounting pole (thin vertical box from ground to housing).
  pushBox(pos, idx, 0, 0, 3, 0.6, 0.6, 3);
  // Housing — the main camera box, centred at z=6.
  pushBox(pos, idx, 0, 0, 6.2, 2.4, 1.8, 1.6);
  // Lens barrel — a flatter box jutting out along +X (look direction).
  pushBox(pos, idx, 2.8, 0, 6.2, 1.4, 1.0, 1.0);
  return toMesh(pos, idx);
}

/**
 * Unit FOV frustum: apex at the origin, opening along +X to a far rectangle at
 * x=1, y∈[-0.5,0.5], z∈[-0.5,0.5]. Per-instance `getScale` stretches it to real
 * metres: scale = [rFar, 2·rFar·tan(hfov/2), 2·rFar·tan(vfov/2)]. The layer
 * elevates the apex (getTranslation z) and tilts it down (getOrientation pitch)
 * so the far edge rests near the ground.
 */
export function frustumMesh(): Mesh {
  const far: Array<[number, number, number]> = [
    [1, -0.5, -0.5],
    [1, 0.5, -0.5],
    [1, 0.5, 0.5],
    [1, -0.5, 0.5],
  ];
  const pos: number[] = [0, 0, 0]; // apex
  for (const f of far) pos.push(f[0], f[1], f[2]);
  // Four side triangles (apex=0 → far ring 1..4) + the far quad (1,2,3,4).
  const idx = [
    0, 1, 2,
    0, 2, 3,
    0, 3, 4,
    0, 4, 1,
    1, 2, 3,
    1, 3, 4,
  ];
  return toMesh(pos, idx);
}
