/**
 * Building-occluded camera viewshed (2.5-D isovist).
 *
 * Given a camera (position, bearing, FOV, range, mount height) and the
 * building footprints near it, this casts a fan of rays across the FOV sector
 * and clips each ray at the first building face that rises above the camera's
 * line of sight at that distance. The result is the *lit* ground polygon —
 * exactly what the operator sees — with streets shadowed by buildings left
 * outside the polygon (rendered dark by the map beneath).
 *
 * This is the geometric foundation for the citywide CCTV viewshed network:
 * footprint + height occlusion today, upgradeable to full 3-D mesh later. The
 * math is a flat-ground / vertical-wall model in a local east-north metric
 * frame centred on the camera — accurate to the building scale at city zoom.
 *
 * No deck.gl, no IO — pure geometry, unit-tested in tests/unit/viewshed.test.ts.
 */

import { DEG_TO_RAD, EARTH_RADIUS_M } from './geo/constants';

export interface ViewshedCamera {
  readonly lat: number;
  readonly lng: number;
  /** Look bearing, degrees clockwise from north. */
  readonly bearingDeg: number;
  /** Horizontal field of view in degrees. */
  readonly hfovDeg: number;
  /** Near clip in metres (default 6). */
  readonly rNearM?: number;
  /** Far range in metres. */
  readonly rFarM: number;
  /** Mast/mount height in metres (default 8). */
  readonly mountHeightM?: number;
  /** Number of rays across the sector. Default ≈ 1 ray / 0.6°, clamped 24..360. */
  readonly rayCount?: number;
}

export interface ViewshedObstacle {
  /** Footprint outer ring in [lng, lat] order (open or closed). */
  readonly ring: ReadonlyArray<readonly [number, number]>;
  /** Building height in metres. */
  readonly heightM: number;
}

const DEFAULT_NEAR_M = 6;
const DEFAULT_MOUNT_M = 8;

/** A building segment in the local metric frame, carrying its height. */
interface LocalSeg {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  h: number;
}

/** Metres per degree of latitude (and, scaled by cos φ, of longitude). */
function metresPerDegLat(): number {
  return DEG_TO_RAD * EARTH_RADIUS_M;
}

/**
 * Camera-centred east-north projection. Returns a pair of converters between
 * geographic [lng,lat] and local metres (x = east, y = north).
 */
function localFrame(originLat: number, originLng: number) {
  const mLat = metresPerDegLat();
  const mLng = mLat * Math.cos(originLat * DEG_TO_RAD);
  return {
    toXY(lng: number, lat: number): [number, number] {
      return [(lng - originLng) * mLng, (lat - originLat) * mLat];
    },
    toLngLat(x: number, y: number): [number, number] {
      return [originLng + x / mLng, originLat + y / mLat];
    },
  };
}

/**
 * Distance along a ray (origin at 0,0, unit direction d) to its first crossing
 * of segment (p1→p2), or `Infinity` if it does not cross ahead of the origin.
 */
function raySegT(dx: number, dy: number, x1: number, y1: number, x2: number, y2: number): number {
  const ex = x2 - x1;
  const ey = y2 - y1;
  const denom = dx * ey - dy * ex;
  if (Math.abs(denom) < 1e-9) return Infinity; // parallel
  // Solve O + t·d = p1 + u·e  →  t, u.
  const t = (x1 * ey - y1 * ex) / denom;
  const u = (x1 * dy - y1 * dx) / denom;
  if (t <= 0 || u < 0 || u > 1) return Infinity;
  return t;
}

/**
 * Height of the camera's line of sight, at horizontal distance `s`, when aimed
 * at a ground target at horizontal distance `target`. The sightline drops
 * linearly from the mast height at the camera to 0 at the target.
 */
function sightlineHeight(mountM: number, s: number, target: number): number {
  if (target <= 0) return mountM;
  return mountM * (1 - s / target);
}

/**
 * Compute the lit viewshed ring for a camera against nearby buildings.
 *
 * Returns a closed polygon ring in [lng,lat] order (first === last vertex),
 * suitable as a deck.gl `PolygonLayer.getPolygon` value. With no obstacles it
 * degenerates to the plain FOV fan (a circular sector).
 */
export function computeViewshed(
  cam: ViewshedCamera,
  obstacles: ReadonlyArray<ViewshedObstacle>,
): Array<[number, number]> {
  const near = cam.rNearM ?? DEFAULT_NEAR_M;
  const far = cam.rFarM;
  const mount = cam.mountHeightM ?? DEFAULT_MOUNT_M;
  const half = cam.hfovDeg / 2;
  const rays = cam.rayCount ?? clamp(Math.ceil(cam.hfovDeg / 0.6), 24, 360);

  const frame = localFrame(cam.lat, cam.lng);

  // Flatten obstacle rings into local segments, pre-filtered to the far range
  // bounding box (cheap reject before the per-ray scan).
  const segs: LocalSeg[] = [];
  for (const o of obstacles) {
    const r = o.ring;
    if (r.length < 2) continue;
    for (let i = 0; i < r.length - 1; i++) {
      const a = r[i]!;
      const b = r[i + 1]!;
      const [ax, ay] = frame.toXY(a[0], a[1]);
      const [bx, by] = frame.toXY(b[0], b[1]);
      // Reject segments wholly outside the ±far box.
      if (Math.min(ax, bx) > far || Math.max(ax, bx) < -far) continue;
      if (Math.min(ay, by) > far || Math.max(ay, by) < -far) continue;
      segs.push({ x1: ax, y1: ay, x2: bx, y2: by, h: o.heightM });
    }
    // Close the ring if the source left it open.
    const first = r[0]!;
    const last = r[r.length - 1]!;
    if (first[0] !== last[0] || first[1] !== last[1]) {
      const [ax, ay] = frame.toXY(last[0], last[1]);
      const [bx, by] = frame.toXY(first[0], first[1]);
      segs.push({ x1: ax, y1: ay, x2: bx, y2: by, h: o.heightM });
    }
  }

  const ring: Array<[number, number]> = [];
  // Fan apex at the camera (near edge collapses to origin at this scale).
  ring.push(frame.toLngLat(0, 0));

  for (let k = 0; k <= rays; k++) {
    const aDeg = cam.bearingDeg - half + (cam.hfovDeg * k) / rays;
    const aRad = aDeg * DEG_TO_RAD;
    // Bearing is clockwise from north: east = sin, north = cos.
    const dx = Math.sin(aRad);
    const dy = Math.cos(aRad);

    let visible = far;
    for (const s of segs) {
      const t = raySegT(dx, dy, s.x1, s.y1, s.x2, s.y2);
      if (t >= visible || t <= near) continue;
      // Height gate: the wall only occludes ground beyond it if its top rises
      // above the line of sight aimed at the current far horizon.
      if (s.h > sightlineHeight(mount, t, far)) {
        visible = t;
      }
    }

    const d = Math.max(near, visible);
    ring.push(frame.toLngLat(dx * d, dy * d));
  }

  ring.push(frame.toLngLat(0, 0)); // close
  return ring;
}

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

/** Planar (shoelace) area in m² of a ring expressed in [lng,lat], near a given
 *  latitude. Handy for tests and coverage metrics. */
export function ringAreaM2(ring: ReadonlyArray<readonly [number, number]>, atLat: number): number {
  if (ring.length < 4) return 0;
  const mLat = metresPerDegLat();
  const mLng = mLat * Math.cos(atLat * DEG_TO_RAD);
  let acc = 0;
  for (let i = 0; i < ring.length - 1; i++) {
    const a = ring[i]!;
    const b = ring[i + 1]!;
    acc += a[0] * mLng * (b[1] * mLat) - b[0] * mLng * (a[1] * mLat);
  }
  return Math.abs(acc) / 2;
}
