/**
 * C2 DetailDrawer — Maven-style nested-nav detail panel for the selected
 * pairing-board card. Opens when `selectedCardId` is set.
 *
 * Sections (civilianized — disaster coordination, NOT targeting): Genel /
 * Konum / İstihbarat / Eşleştirme / Onay / Değerlendirme. The Eşleştirme
 * section pairs a responder unit (DYNAMIC/PENDING → PAIRED); Konum flies the
 * OPS map to the card location; Değerlendirme closes the card.
 *
 * Reference: claude_akom_design/c2-board.jsx detail panel.
 */
import { useState } from 'react';
import { ExternalLink, X } from 'lucide-react';
import { useC2, type C2Card, type C2Column } from '../../store/c2';
import { useStore } from '../../store';
import { SevGlyph } from '../../lib/sevGlyph';
import { tickElapsed } from '../../lib/time';

type Section = 'genel' | 'konum' | 'istihbarat' | 'eslestirme' | 'onay' | 'degerlendirme';

const SECTIONS: { id: Section; label: string }[] = [
  { id: 'genel', label: 'Genel' },
  { id: 'konum', label: 'Konum' },
  { id: 'istihbarat', label: 'İstihbarat' },
  { id: 'eslestirme', label: 'Eşleştirme' },
  { id: 'onay', label: 'Onay' },
  { id: 'degerlendirme', label: 'Değerlendirme' },
];

const COLUMN_LONG: Record<C2Column, string> = {
  DELIBERATE: 'Önceden Planlı',
  DYNAMIC: 'Acil Tetik',
  PENDING: 'Eşleşme Bekliyor',
  PAIRED: 'Eşleşti',
  EXECUTION: 'Müdahale Sürüyor',
  COMPLETE: 'Tamamlandı',
};

const APPROVAL_ROLES = ['KOMUTA', 'AFAD', 'SAĞLIK'];

export function C2DetailDrawer() {
  const selectedCardId = useC2((s) => s.selectedCardId);
  const card = useC2((s) => s.cards.find((c) => c.id === s.selectedCardId));
  const selectCard = useC2((s) => s.selectCard);
  const [section, setSection] = useState<Section>('genel');

  if (!selectedCardId || !card) return null;

  return (
    <aside className="c2-detail glass-panel glass-panel--float" role="dialog" aria-label="Görev detayı">
      <header className="c2-detail__head">
        <SevGlyph severity={card.severity} pulse={card.severity === 'flash'} />
        <span className="c2-detail__id">{card.id}</span>
        <span className="c2-detail__type">{card.type}</span>
        <button
          type="button"
          className="c2-detail__close"
          aria-label="Kapat"
          onClick={() => selectCard(null)}
        >
          <X size={14} />
        </button>
      </header>

      <nav className="c2-detail__nav" aria-label="Detay bölümleri">
        {SECTIONS.map((s) => (
          <button
            key={s.id}
            type="button"
            className="c2-detail__navbtn"
            data-active={section === s.id || undefined}
            onClick={() => setSection(s.id)}
          >
            {s.label}
          </button>
        ))}
      </nav>

      <div className="c2-detail__body">
        {section === 'genel' && <GenelSection card={card} />}
        {section === 'konum' && <KonumSection card={card} />}
        {section === 'istihbarat' && <IstihbaratSection card={card} />}
        {section === 'eslestirme' && <EslestirmeSection card={card} />}
        {section === 'onay' && <OnaySection card={card} />}
        {section === 'degerlendirme' && <DegerlendirmeSection card={card} />}
      </div>
    </aside>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="c2-detail__row">
      <dt>{k}</dt>
      <dd>{v}</dd>
    </div>
  );
}

function GenelSection({ card }: { card: C2Card }) {
  return (
    <dl className="c2-detail__rows">
      <Row k="Görev" v={card.type} />
      <Row k="Tür" v={card.kind} />
      <Row k="Durum" v={COLUMN_LONG[card.col]} />
      <Row
        k="Önem"
        v={
          <>
            <SevGlyph severity={card.severity} /> {card.severity.toUpperCase()}
          </>
        }
      />
      <Row k="Aciliyet" v={card.urgent ? 'ACİL' : 'Normal'} />
      <Row k="Son Düzenleme" v={tickElapsed(card.editedAt)} />
      {card.pairedUnitLabel && <Row k="Atanan" v={card.pairedUnitLabel} />}
    </dl>
  );
}

function KonumSection({ card }: { card: C2Card }) {
  const setActiveTab = useStore((s) => s.setActiveTab);
  const setFlyTarget = useStore((s) => s.setFlyTarget);
  const selectEntity = useStore((s) => s.selectEntity);

  if (!card.location) {
    return <div className="c2-detail__empty">Konum verisi yok.</div>;
  }
  const { lat, lng, district } = card.location;

  const showOnMap = () => {
    if (card.entityId) selectEntity(card.entityId);
    setFlyTarget({ lng, lat, zoom: 15 });
    setActiveTab('operasyon');
  };

  return (
    <dl className="c2-detail__rows">
      {district && <Row k="İlçe" v={district} />}
      <Row k="Enlem" v={lat.toFixed(5)} />
      <Row k="Boylam" v={lng.toFixed(5)} />
      <div className="c2-detail__actions">
        <button type="button" className="c2-detail__btn c2-detail__btn--accent" onClick={showOnMap}>
          <ExternalLink size={12} /> Haritada Göster
        </button>
      </div>
    </dl>
  );
}

function IstihbaratSection({ card }: { card: C2Card }) {
  const notes = card.intelNotes ?? [];
  if (notes.length === 0) {
    return <div className="c2-detail__empty">İstihbarat notu yok.</div>;
  }
  return (
    <ul className="c2-detail__intel">
      {notes.map((n, i) => (
        <li key={i}>{n}</li>
      ))}
    </ul>
  );
}

function EslestirmeSection({ card }: { card: C2Card }) {
  const units = useStore((s) => s.units);
  const pairCard = useC2((s) => s.pairCard);
  const [unitId, setUnitId] = useState('');

  const pair = () => {
    const u = units.find((f) => f.properties.id === unitId);
    if (!u) return;
    const label = `${u.properties.callsign} · ${u.properties.type}`;
    pairCard(card.id, u.properties.id, label);
  };

  return (
    <div className="c2-detail__pair">
      {card.pairedUnitLabel ? (
        <div className="c2-detail__paired">
          Eşleşti: <strong>{card.pairedUnitLabel}</strong>
        </div>
      ) : (
        <div className="c2-detail__empty">Henüz birim eşleşmedi.</div>
      )}
      <label className="c2-detail__field">
        <span>Birim seç</span>
        <select value={unitId} onChange={(e) => setUnitId(e.target.value)}>
          <option value="">— birim —</option>
          {units.slice(0, 60).map((u) => (
            <option key={u.properties.id} value={u.properties.id}>
              {u.properties.callsign} · {u.properties.type} · {u.properties.status}
            </option>
          ))}
        </select>
      </label>
      <div className="c2-detail__actions">
        <button
          type="button"
          className="c2-detail__btn c2-detail__btn--accent"
          disabled={!unitId}
          onClick={pair}
        >
          {card.pairedUnitLabel ? 'Yeniden Eşleştir' : 'Eşleştir'}
        </button>
      </div>
    </div>
  );
}

function OnaySection({ card }: { card: C2Card }) {
  const addApproval = useC2((s) => s.addApproval);
  const approvals = card.approvals ?? [];

  return (
    <div className="c2-detail__approve">
      {approvals.length === 0 ? (
        <div className="c2-detail__empty">Onay kaydı yok.</div>
      ) : (
        <ul className="c2-detail__approvals">
          {approvals.map((a) => (
            <li key={a.role} data-status={a.status}>
              <span className="c2-detail__approle">{a.role}</span>
              <span className="c2-detail__apstatus">
                {a.status === 'approved'
                  ? 'ONAYLANDI'
                  : a.status === 'rejected'
                    ? 'REDDEDİLDİ'
                    : 'BEKLİYOR'}
              </span>
              {a.ts && <span className="c2-detail__aptime">{tickElapsed(a.ts)}</span>}
            </li>
          ))}
        </ul>
      )}
      <div className="c2-detail__actions">
        {APPROVAL_ROLES.map((role) => (
          <button
            key={role}
            type="button"
            className="c2-detail__btn"
            onClick={() => addApproval(card.id, role, 'approved')}
          >
            {role} Onayla
          </button>
        ))}
      </div>
    </div>
  );
}

function DegerlendirmeSection({ card }: { card: C2Card }) {
  const moveCard = useC2((s) => s.moveCard);
  const selectCard = useC2((s) => s.selectCard);

  const complete = () => {
    moveCard(card.id, 'COMPLETE');
    selectCard(null);
  };

  return (
    <div className="c2-detail__assess">
      <p className="c2-detail__assess-note">
        Müdahale sonrası değerlendirme. Görev tamamlandığında kapatın; KAYIT zaman çizelgesinde
        arşivlenir.
      </p>
      <dl className="c2-detail__rows">
        <Row k="Mevcut Durum" v={COLUMN_LONG[card.col]} />
        <Row k="Atanan" v={card.pairedUnitLabel ?? '—'} />
      </dl>
      <div className="c2-detail__actions">
        <button
          type="button"
          className="c2-detail__btn c2-detail__btn--accent"
          disabled={card.col === 'COMPLETE'}
          onClick={complete}
        >
          Tamamlandı İşaretle
        </button>
      </div>
    </div>
  );
}
