/**
 * PTZ camera registry loader — Phase 9-C.
 *
 * Loads the 632-camera snapshot baked into the repo at
 * /public/data/ptz_cameras.json (written by scripts/fetch-ptz-registry.mjs).
 *
 * Hydrates the short-keyed snapshot into the UI-shape PtzCamera struct,
 * caches at module scope (single load per page lifetime), and exposes
 * convenience lookups by ID and by district (via the GeoJSON mahalle
 * polygons loaded elsewhere, when available).
 */

import { hydrate, type PtzCamera, type PtzCameraRaw, type PtzSnapshot } from '../types/ptz';
import { dataUrl } from '../lib/paths';

let cached: PtzCamera[] | null = null;
let inFlight: Promise<PtzCamera[]> | null = null;

/**
 * Load the PTZ camera registry. Memoized — repeat calls return the same array.
 * Returns an empty array (not null) on fetch failure so callers can render
 * an empty-state without conditional unwrapping.
 */
export async function loadPtzCameras(): Promise<PtzCamera[]> {
  if (cached) return cached;
  if (inFlight) return inFlight;
  inFlight = (async () => {
    try {
      const res = await fetch(dataUrl('ptz_cameras.json'));
      if (!res.ok) {
        cached = [];
        return cached;
      }
      const snap = (await res.json()) as PtzSnapshot;
      cached = snap.cameras.map((r: PtzCameraRaw) => hydrate(r));
      return cached;
    } catch {
      cached = [];
      return cached;
    } finally {
      inFlight = null;
    }
  })();
  return inFlight;
}

/** Find a hydrated camera by numeric IBB ID. */
export function findPtzCamera(cameras: ReadonlyArray<PtzCamera>, id: number): PtzCamera | undefined {
  return cameras.find((c) => c.id === id);
}

/** Filter cameras to those whose name matches a case-insensitive substring. */
export function searchPtzCameras(
  cameras: ReadonlyArray<PtzCamera>,
  needle: string,
): PtzCamera[] {
  const n = needle.trim().toLocaleLowerCase('tr');
  if (n.length === 0) return cameras.slice();
  return cameras.filter((c) => c.name.toLocaleLowerCase('tr').includes(n));
}
