/**
 * Claude API SITREP provider (v10 P6 / F3) — opt-in, browser-direct.
 *
 * Uses the operator's own API key from sessionStorage (session-only by
 * design — never persisted across restarts). No network fires until a key is
 * present and generate is called; the default SITREP mode stays the offline
 * template. Sends no sampling knobs (temperature/top_p/top_k/thinking).
 */
import Anthropic from '@anthropic-ai/sdk';
import { buildSitrepPrompt, type SitrepInputs } from './sitrepPrompt';
import type { SitrepProvider, SitrepResult } from './providers';

export const ANTHROPIC_KEY_STORAGE = 'akom:llm:anthropic-key';
export const DEFAULT_CLAUDE_MODEL = 'claude-fable-5';

function readKey(): string {
  try {
    return sessionStorage.getItem(ANTHROPIC_KEY_STORAGE) ?? '';
  } catch {
    return '';
  }
}

interface StatusError {
  status?: number;
}

function mapError(err: unknown): string {
  const status = (err as StatusError)?.status;
  if (status === 401) return 'anahtar geçersiz';
  if (status === 429) return 'hız sınırı';
  if (typeof status === 'number') return `HATA: ${status}`;
  return `HATA: ${(err as Error)?.message ?? 'bilinmeyen'}`;
}

/** Build a Claude provider bound to a model id (defaults to claude-fable-5). */
export function makeClaudeProvider(model: string = DEFAULT_CLAUDE_MODEL): SitrepProvider {
  return {
    mode: 'claude',
    label: 'CLAUDE API',
    available: () => readKey().length > 0,
    async generate(input: SitrepInputs): Promise<SitrepResult> {
      const apiKey = readKey();
      const client = new Anthropic({ apiKey, dangerouslyAllowBrowser: true });
      const { system, user } = buildSitrepPrompt(input);
      try {
        const res = await client.messages.create({
          model,
          max_tokens: 1024,
          system,
          messages: [{ role: 'user', content: user }],
        });
        if (res.stop_reason === 'refusal') throw new Error('Model reddetti');
        const block = res.content.find((b) => b.type === 'text');
        const text = block && block.type === 'text' ? block.text : '';
        return { text, modelLabel: model, network: 'api.anthropic.com' };
      } catch (err) {
        if (err instanceof Error && err.message === 'Model reddetti') throw err;
        throw new Error(mapError(err));
      }
    },
  };
}

export const claudeProvider = makeClaudeProvider();
