/**
 * Tab 05 — KAYIT / Replay.
 *
 * Time-machine over the live cockpit telemetry. App.tsx records one
 * {@link ReplayFrame} per second into the store ring buffer; this tab lets the
 * operator scrub backwards through that window and read the exact incident /
 * dispatch / utility state at any past second, with a playhead that can run the
 * recording forward. Genuinely live — empty until the recorder has ticked.
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';

function fmtClock(ts: number): string {
  const d = new Date(ts);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

interface StatProps {
  label: string;
  value: string | number;
  accent?: string;
}
function Stat({ label, value, accent }: StatProps) {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 4,
        padding: '10px 14px',
        border: '1px solid var(--bg-rule)',
        borderRadius: 4,
        minWidth: 96,
      }}
    >
      <span style={{ fontSize: 'var(--t-tiny)', letterSpacing: '0.1em', color: 'var(--bone-faint)' }}>
        {label}
      </span>
      <span style={{ fontSize: 'var(--t-h3, 18px)', color: accent ?? 'var(--bone)' }}>{value}</span>
    </div>
  );
}

export function Kayit() {
  const frames = useStore((s) => s.replayFrames);
  const [idx, setIdx] = useState(0);
  const [playing, setPlaying] = useState(false);
  // Track whether the scrubber sits at the live edge so new frames keep it there.
  const atLiveEdge = useRef(true);

  const count = frames.length;
  const clampedIdx = count > 0 ? Math.min(idx, count - 1) : 0;

  // Keep the playhead pinned to the newest frame unless the operator scrubs back.
  useEffect(() => {
    if (atLiveEdge.current && count > 0) setIdx(count - 1);
  }, [count]);

  // Playback clock: advance one frame per 250 ms (4× real time).
  useEffect(() => {
    if (!playing || count === 0) return;
    const id = window.setInterval(() => {
      setIdx((i) => {
        if (i >= count - 1) {
          atLiveEdge.current = true;
          return count - 1;
        }
        atLiveEdge.current = false;
        return i + 1;
      });
    }, 250);
    return () => window.clearInterval(id);
  }, [playing, count]);

  const frame = frames[clampedIdx];

  // Bar-chart geometry for the incident-load history (normalised per metric).
  const chart = useMemo(() => {
    if (count === 0) return null;
    const maxRoads = Math.max(1, ...frames.map((f) => f.roadsBlockedPct));
    const maxInc = Math.max(1, ...frames.map((f) => f.incidents + f.unitsEnroute));
    return { maxRoads, maxInc };
  }, [frames, count]);

  const onScrub = (v: number) => {
    setIdx(v);
    atLiveEdge.current = v >= count - 1;
  };

  return (
    <div className="hud-pane" style={{ gridColumn: '1 / -1', padding: 20, overflow: 'auto' }}>
      <div style={{ maxWidth: 1040, margin: '0 auto', fontFamily: 'var(--font-mono)' }}>
        <header
          className="glass-panel glass-panel--float"
          style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '12px 16px' }}
        >
          <span style={{ letterSpacing: '0.16em', color: 'var(--amber)', textTransform: 'uppercase' }}>
            KAYIT · ZAMAN TÜNELİ
          </span>
          <SourceChip source="LIVE" />
          <span style={{ flex: 1 }} />
          <span style={{ color: 'var(--bone-faint)', fontSize: 'var(--t-tiny)' }}>
            {count} KARE · {count}s
          </span>
        </header>

        {count === 0 ? (
          <div
            style={{
              marginTop: 16,
              padding: 28,
              textAlign: 'center',
              color: 'var(--bone-faint)',
              border: '1px dashed var(--bg-rule)',
              borderRadius: 6,
            }}
          >
            Kayıt başlatılıyor — telemetri tamponu doluyor…
          </div>
        ) : (
          <>
            <section
              className="glass-panel glass-panel--deep"
              style={{ marginTop: 16, padding: 16 }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
                <button
                  type="button"
                  onClick={() => setPlaying((p) => !p)}
                  style={{
                    background: playing ? 'var(--amber)' : 'transparent',
                    color: playing ? '#05080d' : 'var(--amber)',
                    border: '1px solid var(--amber)',
                    borderRadius: 4,
                    padding: '6px 16px',
                    cursor: 'pointer',
                    letterSpacing: '0.1em',
                    fontFamily: 'inherit',
                  }}
                >
                  {playing ? '❚❚ DURDUR' : '▶ OYNAT'}
                </button>
                <span style={{ color: 'var(--amber)', fontSize: 'var(--t-h3, 18px)' }}>
                  {frame ? fmtClock(frame.t) : '--:--:--'}
                </span>
                <span style={{ color: 'var(--bone-faint)', fontSize: 'var(--t-tiny)' }}>
                  T-{count - 1 - clampedIdx}s
                  {clampedIdx >= count - 1 ? ' · CANLI' : ''}
                </span>
              </div>

              <input
                type="range"
                min={0}
                max={Math.max(0, count - 1)}
                value={clampedIdx}
                onChange={(e) => onScrub(Number(e.target.value))}
                style={{ width: '100%', accentColor: 'var(--amber)' }}
                aria-label="Replay scrubber"
              />

              {frame && (
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, marginTop: 16 }}>
                  <Stat label="BİRİM" value={frame.units} />
                  <Stat label="SEVKTE" value={frame.unitsEnroute} accent="var(--amber)" />
                  <Stat label="OLAY" value={frame.incidents} accent="var(--klaxon, #ff5a5a)" />
                  <Stat label="ETA" value={`${frame.etaAvgSec}s`} />
                  <Stat label="YATAK" value={frame.bedsAvailable} />
                  <Stat label="YOL KAPALI" value={`%${frame.roadsBlockedPct.toFixed(1)}`} />
                </div>
              )}
            </section>

            {chart && (
              <section
                className="glass-panel glass-panel--deep"
                style={{ marginTop: 16, padding: 16 }}
              >
                <header className="ops-panel__title" style={{ marginBottom: 10 }}>
                  YOL KAPANMA % · GEÇMİŞ
                </header>
                <div
                  style={{
                    display: 'flex',
                    alignItems: 'flex-end',
                    gap: 1,
                    height: 96,
                    cursor: 'pointer',
                  }}
                  onClick={(e) => {
                    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                    const ratio = (e.clientX - rect.left) / rect.width;
                    onScrub(Math.round(ratio * (count - 1)));
                  }}
                >
                  {frames.map((f, i) => {
                    const h = (f.roadsBlockedPct / chart.maxRoads) * 100;
                    const isHead = i === clampedIdx;
                    return (
                      <div
                        key={f.t}
                        style={{
                          flex: 1,
                          minWidth: 1,
                          height: `${Math.max(2, h)}%`,
                          background: isHead
                            ? 'var(--amber)'
                            : f.roadsBlockedPct > 40
                              ? 'var(--klaxon, #ff5a5a)'
                              : 'var(--bone-faint)',
                          opacity: isHead ? 1 : 0.7,
                        }}
                      />
                    );
                  })}
                </div>
              </section>
            )}
          </>
        )}
      </div>
    </div>
  );
}
