/**
 * <SourceChip source="AFAD" /> — 9 px mono badge per design-brief Rule 11
 * ("source-tag every numeric: KRDAE deterministic vs EST synthesized").
 *
 * Renders inline after any number, e.g.:
 *   4,231 <SourceChip source="AFAD" />
 *   12.7 km <SourceChip source="EST" />
 *
 * Flat tactical doctrine: no background, no glow, just letterforms.
 * Color cues only secondary — the letters carry the meaning so this still
 * works for color-blind operators.
 */

import type { SourceTag } from '../types/entity';

const COLOR_BY_SOURCE: Record<SourceTag, string> = {
  KRDAE: 'var(--amber)', // deterministic seismic — high trust
  EST: 'var(--bone-mute)', // estimated/synthesized — caveat
  AFAD: 'var(--amber)', // official dispatch
  IBB: 'var(--info)', // municipal feed
  ICAO: 'var(--info)', // aviation transponder
  AIS: 'var(--info)', // maritime transponder
  TLE: 'var(--info)', // orbital propagation
  OSINT: 'var(--bone)', // open-source aggregate
  WITNESS: 'var(--bone-mute)', // human-reported
  LIVE: 'var(--okay)', // live feed marker
  STALE: 'var(--klaxon)', // last-known, expired
  SIM: 'var(--bone-faint)', // synthetic seed
};

export interface SourceChipProps {
  source: SourceTag;
  /** Optional title override (defaults to a static glossary). */
  title?: string;
  className?: string;
}

const TITLE_BY_SOURCE: Record<SourceTag, string> = {
  KRDAE: 'Boğaziçi Kandilli — deterministic',
  EST: 'Estimated / synthesized',
  AFAD: 'AFAD official feed',
  IBB: 'İBB municipal feed',
  ICAO: 'ADS-B aviation transponder',
  AIS: 'AIS maritime transponder',
  TLE: 'CelesTrak orbital propagation',
  OSINT: 'Open-source aggregate',
  WITNESS: 'Human-reported (112 / social)',
  LIVE: 'Live feed',
  STALE: 'Last-known, refresh lapsed',
  SIM: 'Synthetic seed',
};

export function SourceChip({ source, title, className }: SourceChipProps) {
  return (
    <span
      className={className}
      title={title ?? TITLE_BY_SOURCE[source]}
      style={{
        display: 'inline-block',
        marginLeft: 4,
        padding: '0 4px',
        fontFamily: 'var(--font-mono)',
        fontSize: 9,
        letterSpacing: '0.08em',
        fontWeight: 600,
        color: COLOR_BY_SOURCE[source],
        borderLeft: `2px solid ${COLOR_BY_SOURCE[source]}`,
        verticalAlign: 'baseline',
      }}
    >
      {source}
    </span>
  );
}
