/**
 * AFAD seismic feed.
 *
 * Production: polls AFAD's open earthquake API (rate-limited, JSON list).
 * Dev / air-gap: synthetic generator below produces plausible Marmara-region
 * micro-quakes every 30 s so the cockpit has motion without a network.
 *
 * Per docs/SPATIAL-INTELLIGENCE-ULTRAPLAN.md §6.1 — provenance carried on
 * every event via Entity.source = 'AFAD'. Severity ≥ 5.5 escalates to the
 * MASCAL banner.
 */

import type { Entity } from '../types/entity';
import { entityId } from '../types/entity';
import { useStore } from '../store';
import { startFeed, type FeedHandle } from './runner';

interface AfadEvent {
  eventId: string;
  lat: number;
  lon: number;
  mag: number;
  depth_km: number;
  ts: number;
  district: string;
}

// Marmara fault line approximation — used to seed plausible mock epicenters.
const FAULT_POINTS: { lat: number; lon: number; name: string }[] = [
  { lat: 40.78, lon: 28.95, name: 'Marmara Ereğlisi' },
  { lat: 40.81, lon: 29.15, name: 'Tuzla off-shore' },
  { lat: 40.85, lon: 29.45, name: 'Kartal off-shore' },
  { lat: 40.7, lon: 28.6, name: 'Tekirdağ off-shore' },
  { lat: 40.93, lon: 28.65, name: 'Avcılar' },
  { lat: 40.99, lon: 28.95, name: 'Üsküdar' },
];

function mockAfadFetch(): Promise<AfadEvent[]> {
  // 70% of ticks return nothing; 30% spawn 1-2 events. Magnitudes biased low.
  if (Math.random() < 0.7) return Promise.resolve([]);
  const count = Math.random() < 0.85 ? 1 : 2;
  const events: AfadEvent[] = [];
  for (let i = 0; i < count; i++) {
    const p = FAULT_POINTS[Math.floor(Math.random() * FAULT_POINTS.length)]!;
    // Magnitude distribution: most are <3.0, occasional 4-5, rare 5.5+.
    const r = Math.random();
    let mag: number;
    if (r < 0.7) mag = 1.5 + Math.random() * 1.5;
    else if (r < 0.95) mag = 3.0 + Math.random() * 2.0;
    else mag = 5.0 + Math.random() * 1.5;
    events.push({
      eventId: `mock-${Date.now()}-${i}`,
      lat: p.lat + (Math.random() - 0.5) * 0.08,
      lon: p.lon + (Math.random() - 0.5) * 0.08,
      mag: Math.round(mag * 10) / 10,
      depth_km: Math.round((5 + Math.random() * 15) * 10) / 10,
      ts: Date.now(),
      district: p.name,
    });
  }
  return Promise.resolve(events);
}

/**
 * Real AFAD fetch — disabled by default; flip `VITE_FEATURE_LIVE_AFAD` to
 * enable. We keep the function present so the call site is identical.
 */
async function liveAfadFetch(signal: AbortSignal): Promise<AfadEvent[]> {
  const url = 'https://deprem.afad.gov.tr/apiv2/event/filter?start=now-30m&end=now&minmag=1.0&format=json';
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`AFAD ${res.status}`);
  const data = (await res.json()) as Array<{
    eventID: string;
    latitude: string;
    longitude: string;
    magnitude: string;
    depth: string;
    date: string;
    location: string;
  }>;
  return data.map((d) => ({
    eventId: d.eventID,
    lat: Number(d.latitude),
    lon: Number(d.longitude),
    mag: Number(d.magnitude),
    depth_km: Number(d.depth),
    ts: Date.parse(d.date),
    district: d.location,
  }));
}

function severityFor(mag: number): Entity['severity'] {
  if (mag >= 6.5) return 'flash';
  if (mag >= 5.5) return 'immediate';
  if (mag >= 4.5) return 'priority';
  if (mag >= 3.5) return 'routine';
  return 'info';
}

export function startAfadFeed(): FeedHandle {
  const live = import.meta.env?.VITE_FEATURE_LIVE_AFAD === 'true';
  return startFeed<AfadEvent[]>({
    source: 'AFAD',
    label: 'AFAD',
    intervalMs: 30_000,
    fetch: live ? liveAfadFetch : () => mockAfadFetch(),
    apply: (events) => {
      const store = useStore.getState();
      for (const e of events) {
        const id = entityId('AFAD', 'incident', e.eventId);
        const sev = severityFor(e.mag);
        store.upsertEntity({
          id,
          kind: 'incident',
          geom: { type: 'Point', coordinates: [e.lon, e.lat] },
          attrs: {
            magnitude: e.mag,
            depth_km: e.depth_km,
            district: e.district,
            type: 'earthquake',
          },
          source: 'AFAD',
          affiliation: 'neutral',
          status: 'operational',
          severity: sev,
          confidence: 0.95,
          firstSeen: e.ts,
          lastSeen: e.ts,
          links: [],
        });
      }
    },
  });
}
