/**
 * Symbology mapper — picks a sprite id from the 2525D civilian-subset atlas
 * given an entity's kind, sub-type, affiliation, and status.
 *
 * Phase 1 of the spatial-intelligence ultraplan. The atlas lives at
 * `/public/symbology/2525d.svg` and is loaded via SVG `<use href>` references.
 */

import type { Affiliation, EntityKind, EntityStatus } from '../types/entity';
import { assetUrl } from './paths';

/** Sprite ids present in /public/symbology/2525d.svg today. */
export type SpriteId =
  | 'amb'
  | 'fire'
  | 'hems'
  | 'k9'
  | 'pol'
  | 'sar'
  | 'uav'
  | 'flight'
  | 'vessel'
  | 'satellite'
  | 'beacon'
  | 'blockage';

/** Color a sprite gets via `currentColor` (the SVGs use currentColor in
 *  this codebase). */
export function spriteColor(affiliation: Affiliation, status: EntityStatus): string {
  if (status === 'destroyed') return 'var(--klaxon)';
  if (status === 'damaged') return 'var(--amber-edge)';
  switch (affiliation) {
    case 'friend':
      return 'var(--info)';
    case 'neutral':
      return 'var(--okay)';
    case 'unknown':
      return 'var(--amber)';
    case 'hostile':
      return 'var(--klaxon)';
  }
}

/**
 * Resolve the sprite id for an entity. `subType` is a free-form discriminator
 * pulled from `entity.attrs.subType` if present (e.g. for kind='unit',
 * subType could be 'amb' | 'fire' | 'sar' | 'pol' | 'hems' | 'uav' | 'k9').
 *
 * Falls back gracefully when subType is unknown.
 */
export function resolveSprite(kind: EntityKind, subType?: string): SpriteId {
  switch (kind) {
    case 'unit': {
      const t = (subType ?? '').toLowerCase();
      if (t === 'amb' || t === 'fire' || t === 'hems' || t === 'k9' || t === 'pol' || t === 'sar' || t === 'uav') {
        return t as SpriteId;
      }
      return 'pol';
    }
    case 'flight':
      return 'flight';
    case 'vessel':
      return 'vessel';
    case 'satellite':
      return 'satellite';
    case 'beacon':
      return 'beacon';
    case 'blockage':
      return 'blockage';
    case 'incident':
      return 'fire';
    case 'camera':
      return 'pol';
    case 'building':
    case 'witness':
    default:
      return 'beacon';
  }
}

/** Convenience: returns the href to feed into `<svg><use href= /></svg>`. */
export function spriteHref(id: SpriteId): string {
  return `${assetUrl("symbology/2525d.svg")}#${id}`;
}

/* ── Sprite atlas (canvas) for deck.gl IconLayer ── */

const SPRITE_IDS: SpriteId[] = ['amb', 'fire', 'hems', 'k9', 'pol', 'sar', 'uav', 'flight', 'vessel', 'satellite', 'beacon', 'blockage'];

// Slightly smaller for the map overlay — less visually dominant than the SVG original.
const SPRITE_SIZE = 32; // px per sprite cell
const ATLAS_COLS = Math.ceil(Math.sqrt(SPRITE_IDS.length));
const ATLAS_ROWS = Math.ceil(SPRITE_IDS.length / ATLAS_COLS);
const ATLAS_W = ATLAS_COLS * SPRITE_SIZE;
const ATLAS_H = ATLAS_ROWS * SPRITE_SIZE;

/**
 * Build a 2525D sprite atlas (raster canvas) and icon mapping for use with
 * deck.gl IconLayer. Each symbol is rendered in the given fill color at
 * the fixed cell size. The atlas is a square-ish grid of cells; the mapping
 * dictionary maps each SpriteId to { x, y, width, height }.
 *
 * Called once at module level — the result is cached for the process lifetime.
 */
let _cachedAtlas: { atlas: string; mapping: Record<string, { x: number; y: number; width: number; height: number }> } | null = null;

export function getSpriteAtlas(): { atlas: string; mapping: Record<string, { x: number; y: number; width: number; height: number }> } {
  if (_cachedAtlas) return _cachedAtlas;

  // We need to render each SVG symbol to a canvas cell. Since we can't access SVG
  // files synchronously at module level, we use an offscreen canvas and render
  // simple geometric symbols directly. These are faithful geometric equivalents
  // of the 2525d.svg symbols rendered in the chosen fill color.

  const canvas = document.createElement('canvas');
  canvas.width = ATLAS_W;
  canvas.height = ATLAS_H;
  const ctx = canvas.getContext('2d')!;

  const mapping: Record<string, { x: number; y: number; width: number; height: number }> = {};

  SPRITE_IDS.forEach((id, i) => {
    const col = i % ATLAS_COLS;
    const row = Math.floor(i / ATLAS_COLS);
    const x = col * SPRITE_SIZE;
    const y = row * SPRITE_SIZE;

    mapping[id] = { x, y, width: SPRITE_SIZE, height: SPRITE_SIZE };

    ctx.save();
    ctx.translate(x, y);

    // Draw the frame (MIL-STD-2525D bounding box)
    ctx.strokeStyle = '#FFB000';
    ctx.lineWidth = 1.2;
    ctx.strokeRect(2, 2, SPRITE_SIZE - 4, SPRITE_SIZE - 4);

    // Draw the symbol fill
    ctx.fillStyle = '#FFB000';
    ctx.strokeStyle = '#FFB000';
    ctx.lineWidth = 1.2;
    ctx.lineCap = 'square';
    ctx.lineJoin = 'miter';

    switch (id) {
      case 'amb': {
        // Plus cross
        const cx = SPRITE_SIZE / 2;
        const cy = SPRITE_SIZE / 2;
        ctx.beginPath();
        ctx.moveTo(cx - 6, cy);
        ctx.lineTo(cx + 6, cy);
        ctx.moveTo(cx, cy - 6);
        ctx.lineTo(cx, cy + 6);
        ctx.lineWidth = 2;
        ctx.stroke();
        break;
      }
      case 'fire': {
        // Flame shape — simplified pentagon
        ctx.beginPath();
        ctx.moveTo(SPRITE_SIZE / 2, 7);
        ctx.lineTo(SPRITE_SIZE - 7, SPRITE_SIZE - 7);
        ctx.lineTo(SPRITE_SIZE / 2, SPRITE_SIZE - 4);
        ctx.lineTo(7, SPRITE_SIZE - 7);
        ctx.closePath();
        ctx.fill();
        break;
      }
      case 'hems': {
        // Circle with cross
        const cx = SPRITE_SIZE / 2, cy = SPRITE_SIZE / 2;
        ctx.beginPath();
        ctx.arc(cx, cy, 4, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx, cy - 7);
        ctx.lineTo(cx, cy - 4);
        ctx.moveTo(cx, cy + 4);
        ctx.lineTo(cx, cy + 7);
        ctx.moveTo(cx - 7, cy);
        ctx.lineTo(cx - 4, cy);
        ctx.moveTo(cx + 4, cy);
        ctx.lineTo(cx + 7, cy);
        ctx.stroke();
        break;
      }
      case 'k9': {
        // Dog silhouette — simplified
        ctx.beginPath();
        ctx.moveTo(9, 24);
        ctx.lineTo(9, 16);
        ctx.lineTo(11, 12);
        ctx.lineTo(16, 12);
        ctx.lineTo(17, 14);
        ctx.lineTo(22, 14);
        ctx.lineTo(23, 16);
        ctx.lineTo(25, 16);
        ctx.lineTo(25, 24);
        ctx.closePath();
        ctx.fill();
        // Eye
        ctx.beginPath();
        ctx.arc(14, 23, 1.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(22, 23, 1.2, 0, Math.PI * 2);
        ctx.fill();
        break;
      }
      case 'pol': {
        // Person/shield figure
        const cx = SPRITE_SIZE / 2;
        ctx.beginPath();
        ctx.arc(cx, 13, 2.5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(cx - 5, 24);
        ctx.quadraticCurveTo(cx - 4, 18, cx, 18);
        ctx.quadraticCurveTo(cx + 4, 18, cx + 5, 24);
        ctx.stroke();
        break;
      }
      case 'sar': {
        // Magnifying glass (search)
        ctx.beginPath();
        ctx.arc(SPRITE_SIZE / 2 - 1, SPRITE_SIZE / 2 - 1, 4.5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(SPRITE_SIZE / 2 + 2, SPRITE_SIZE / 2 + 2);
        ctx.lineTo(SPRITE_SIZE / 2 + 5, SPRITE_SIZE / 2 + 5);
        ctx.stroke();
        break;
      }
      case 'uav': {
        // Drone — central circle + 4 rotors
        const cx = SPRITE_SIZE / 2, cy = SPRITE_SIZE / 2;
        ctx.beginPath();
        ctx.arc(cx, cy, 2, 0, Math.PI * 2);
        ctx.fill();
        [{ x: -6, y: -6 }, { x: 6, y: -6 }, { x: -6, y: 6 }, { x: 6, y: 6 }].forEach(({ x: rx, y: ry }) => {
          ctx.beginPath();
          ctx.arc(cx + rx, cy + ry, 2, 0, Math.PI * 2);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(cx + rx * 0.4, cy + ry * 0.4);
          ctx.lineTo(cx + rx * 0.75, cy + ry * 0.75);
          ctx.stroke();
        });
        break;
      }
      case 'flight': {
        // Aircraft planform
        ctx.beginPath();
        ctx.moveTo(SPRITE_SIZE / 2, 6);
        ctx.lineTo(SPRITE_SIZE - 4, SPRITE_SIZE / 2);
        ctx.lineTo(SPRITE_SIZE / 2, SPRITE_SIZE - 6);
        ctx.lineTo(4, SPRITE_SIZE / 2);
        ctx.closePath();
        ctx.fill();
        break;
      }
      case 'vessel': {
        // Ship hull
        ctx.beginPath();
        ctx.moveTo(6, SPRITE_SIZE - 6);
        ctx.lineTo(SPRITE_SIZE - 6, SPRITE_SIZE - 6);
        ctx.lineTo(SPRITE_SIZE - 4, SPRITE_SIZE - 3);
        ctx.lineTo(4, SPRITE_SIZE - 3);
        ctx.closePath();
        ctx.fill();
        // Mast
        ctx.beginPath();
        ctx.moveTo(SPRITE_SIZE / 2, SPRITE_SIZE - 6);
        ctx.lineTo(SPRITE_SIZE / 2, 8);
        ctx.stroke();
        break;
      }
      case 'satellite': {
        // Satellite with solar panels
        const cx = SPRITE_SIZE / 2, cy = SPRITE_SIZE / 2;
        ctx.fillStyle = '#FFB000';
        ctx.fillRect(cx - 2, cy - 2, 4, 4);
        ctx.strokeStyle = '#FFB000';
        ctx.lineWidth = 1;
        ctx.strokeRect(cx - 5, cy - 5, 10, 10);
        // Antenna lines
        ctx.beginPath();
        ctx.moveTo(cx - 5, cy - 5);
        ctx.lineTo(cx - 9, cy - 9);
        ctx.moveTo(cx + 5, cy - 5);
        ctx.lineTo(cx + 9, cy - 9);
        ctx.moveTo(cx - 5, cy + 5);
        ctx.lineTo(cx - 9, cy + 9);
        ctx.moveTo(cx + 5, cy + 5);
        ctx.lineTo(cx + 9, cy + 9);
        ctx.stroke();
        break;
      }
      case 'beacon': {
        // Diamond
        ctx.beginPath();
        ctx.moveTo(SPRITE_SIZE / 2, 6);
        ctx.lineTo(SPRITE_SIZE - 6, SPRITE_SIZE / 2);
        ctx.lineTo(SPRITE_SIZE / 2, SPRITE_SIZE - 6);
        ctx.lineTo(6, SPRITE_SIZE / 2);
        ctx.closePath();
        ctx.fill();
        break;
      }
      case 'blockage': {
        // X mark inside frame
        ctx.beginPath();
        ctx.moveTo(8, 8);
        ctx.lineTo(SPRITE_SIZE - 8, SPRITE_SIZE - 8);
        ctx.moveTo(SPRITE_SIZE - 8, 8);
        ctx.lineTo(8, SPRITE_SIZE - 8);
        ctx.lineWidth = 1.8;
        ctx.stroke();
        break;
      }
    }

    ctx.restore();
  });

  const dataUrl = canvas.toDataURL('image/png');
  _cachedAtlas = { atlas: dataUrl, mapping };
  return _cachedAtlas;
}
