import type { MobeseCamera } from '../../feeds/ibb-mobese';
import { SourceChip } from '../../lib/sourceTag';
import { useCameraMedia, cameraMediaUrl } from '../../lib/cameraMedia';

interface CameraTileProps {
  camera: MobeseCamera;
  selected: boolean;
  /** Unix ms of last frame fetch. -1 = never fetched. */
  lastFrameTs: number;
  /** Current wall-clock for staleness display. */
  now: number;
  onSelect(): void;
}

const STALE_AFTER_MS = 5 * 60_000;

function ageLabel(ms: number, now: number): string {
  if (ms < 0) return '— sn';
  const ageS = Math.max(0, Math.floor((now - ms) / 1000));
  if (ageS < 60) return `${ageS} sn`;
  if (ageS < 3600) return `${Math.floor(ageS / 60)} dk`;
  return `${Math.floor(ageS / 3600)} sa`;
}

export function CameraTile({ camera, selected, lastFrameTs, now, onSelect }: CameraTileProps) {
  const media = useCameraMedia();
  const rec = media[camera.id];
  const isStandIn = rec?.provenance === 'stand-in';
  const isStale = lastFrameTs >= 0 && now - lastFrameTs > STALE_AFTER_MS;
  const hasFrame = lastFrameTs > 0;

  return (
    <a
      href={camera.pageUrl}
      target="_blank"
      rel="noopener noreferrer"
      className={`camera-tile glass-panel glass-panel--card ${selected ? 'is-selected' : ''} ${isStale ? 'is-stale' : ''}`}
      onClick={onSelect}
      title={`${camera.name} — İBB canlı yayın sayfasını yeni sekmede aç`}
    >
      <div className="camera-tile__frame">
        {rec ? (
          <>
            <img
              className="camera-tile__img"
              src={cameraMediaUrl(rec.image)}
              alt={`${camera.name} — kayıtlı kare`}
              loading="lazy"
            />
            <span className="camera-tile__rec">{isStandIn ? 'TEMSİLİ' : 'KAYIT'}</span>
          </>
        ) : !hasFrame ? (
          <span className="camera-tile__placeholder">— görüntü yok —</span>
        ) : (
          <span className="camera-tile__placeholder">
            {camera.type} · {camera.codec.split(' ')[0]}
          </span>
        )}
        <span className="camera-tile__open" aria-hidden="true">CANLI ↗</span>
      </div>
      <div className="camera-tile__meta">
        <div className="camera-tile__name">{camera.name}</div>
        <div className="camera-tile__sub">
          <span>{camera.district}</span>
          <SourceChip source={isStale ? 'STALE' : 'IBB'} />
          <span className="camera-tile__age">{ageLabel(lastFrameTs, now)}</span>
        </div>
      </div>
    </a>
  );
}
