/**
 * Satellite catalog layer — Phase 9 Leap Step 3.
 *
 * Renders the propagated positions from sat.worker as a deck.gl IconLayer
 * over the GlobeHost map. Uses the 64x64 sprite atlas from
 * src/satellites/symbology.ts (one per MIL shape).
 *
 * LOD: at zoom < 1 only stations/gnss/geo are shown (the user's catBitmask
 * gates the worker's `propagate` call); above zoom 3 the full subset.
 */
import { ScatterplotLayer } from '@deck.gl/layers';
import { SAT_CATEGORIES, hexToRgba } from '../../satellites/symbology';

export interface SatDatum {
  position: [number, number, number]; // lng, lat, altKm
  noradId: number;
  cat: number;
}

export interface SatLayerOpts {
  data: ReadonlyArray<SatDatum>;
  opacity?: number;
  onClick?: (datum: SatDatum) => void;
  /** Fires on hover with the Norad id and screen coords. */
  onHover?: (h: { noradId: number; x: number; y: number } | null) => void;
}

/**
 * Satellites as a ScatterplotLayer of colour-coded dots. Rendered at the
 * sub-satellite surface point ([lng, lat], altitude dropped) with
 * radiusMinPixels so they are reliably visible at any globe zoom — the
 * IconLayer/atlas path did not render under MapLibre's globe projection.
 */
export function buildSatLayer(opts: SatLayerOpts): ScatterplotLayer<SatDatum> | null {
  if (opts.data.length === 0) return null;
  const alpha = Math.floor(255 * (opts.opacity ?? 0.95));

  return new ScatterplotLayer<SatDatum>({
    id: 'sat-catalog',
    data: [...opts.data],
    // Sub-satellite ground point — drop the altitude so dots sit on the globe.
    getPosition: (d) => [d.position[0], d.position[1]],
    radiusUnits: 'pixels',
    getRadius: 3.2,
    radiusMinPixels: 2.5,
    radiusMaxPixels: 7,
    stroked: true,
    filled: true,
    lineWidthUnits: 'pixels',
    getLineWidth: 0.6,
    getLineColor: [255, 255, 255, Math.min(220, alpha)],
    getFillColor: (d): [number, number, number, number] => {
      const spec = SAT_CATEGORIES[d.cat];
      return spec ? hexToRgba(spec.color, alpha) : [150, 160, 180, alpha];
    },
    pickable: !!(opts.onClick || opts.onHover),
    onClick: opts.onClick
      ? (info) => {
          if (info.object) opts.onClick!(info.object as SatDatum);
        }
      : undefined,
    onHover: opts.onHover
      ? (info) => {
          if (info.object && info.object.position) {
            const d = info.object as SatDatum;
            opts.onHover!({ noradId: d.noradId, x: info.x, y: info.y });
          } else {
            opts.onHover!(null);
          }
        }
      : undefined,
    updateTriggers: { getFillColor: [opts.opacity] },
  });
}

/**
 * Decode the packed Float32Array from the SGP4 worker into typed SatDatum
 * objects. Cheap; one Float32Array.subarray per record.
 */
export function decodeSatPositions(
  positions: ArrayBuffer,
  noradIds: Int32Array,
): SatDatum[] {
  const f32 = new Float32Array(positions);
  const out: SatDatum[] = new Array(noradIds.length);
  for (let i = 0; i < noradIds.length; i++) {
    const base = i * 4;
    out[i] = {
      position: [f32[base]!, f32[base + 1]!, f32[base + 2]!],
      noradId: noradIds[i]!,
      cat: Math.floor(f32[base + 3]!),
    };
  }
  return out;
}
