/**
 * ELT (Emergency Locator Transmitter) beacons — mock generator for Phase 7.
 *
 * Real ELT integration would tap COSPAS-SARSAT feeds (Sentinel/AFAD CSPF
 * channels), which require credentials we don't have in this codebase. The
 * mock generates plausible beacon activations within Marmara bbox so the
 * Haberleşme tab and the absence-layer mechanisms have something to react to.
 */

import { entityId } from '../types/entity';
import { useStore } from '../store';
import { startFeed, type FeedHandle } from './runner';

interface MockBeacon {
  beaconId: string;
  lat: number;
  lon: number;
  mhz: number;
  type: 'ELT' | 'EPIRB' | 'PLB';
  ts: number;
}

const TYPES: MockBeacon['type'][] = ['ELT', 'EPIRB', 'PLB'];
// 406 MHz is the legal beacon frequency; jitter slightly for visual variety.
function pickFreq(): number {
  return 406.0 + Math.round(Math.random() * 50) / 100;
}

const SEEDS: Array<{ id: string; lat: number; lon: number; mins: number }> = [
  { id: 'TC-ELT-001', lat: 41.05, lon: 28.95, mins: 2 },
  { id: 'TC-ELT-002', lat: 40.97, lon: 29.13, mins: 18 },
  { id: 'TC-EPIRB-003', lat: 40.91, lon: 28.92, mins: 7 },
  { id: 'TC-PLB-004', lat: 41.08, lon: 29.04, mins: 31 }, // intentionally past 15 min → klaxon
];

let activated = false;
function mockFetch(): Promise<MockBeacon[]> {
  if (activated) return Promise.resolve([]);
  activated = true;
  const now = Date.now();
  return Promise.resolve(
    SEEDS.map((s, i) => ({
      beaconId: s.id,
      lat: s.lat,
      lon: s.lon,
      mhz: pickFreq(),
      type: TYPES[i % TYPES.length]!,
      ts: now - s.mins * 60_000,
    })),
  );
}

export function startEltFeed(): FeedHandle {
  return startFeed<MockBeacon[]>({
    source: 'OSINT',
    label: 'ELT',
    intervalMs: 60_000,
    fetch: () => mockFetch(),
    apply: (beacons) => {
      const store = useStore.getState();
      for (const b of beacons) {
        store.upsertEntity({
          id: entityId('OSINT', 'beacon', b.beaconId),
          kind: 'beacon',
          geom: { type: 'Point', coordinates: [b.lon, b.lat] },
          attrs: { type: b.type, mhz: b.mhz, beaconId: b.beaconId },
          source: 'OSINT',
          affiliation: 'neutral',
          status: 'operational',
          severity: 'immediate',
          confidence: 0.85,
          firstSeen: b.ts,
          lastSeen: b.ts,
          links: [],
        });
      }
    },
  });
}
