/**
 * Tab 03 — HBR Haberleşme.
 *
 * Three-pane comms console: full radio log feed + ELT beacon list + cell
 * tower outage minimap.
 *
 * Phase 7 of the spatial-intelligence ultraplan.
 */

import { useEffect, useRef } from 'react';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';
import { SevGlyph } from '../../lib/sevGlyph';
import { EltList } from '../comms/EltList';
import { OutageMinimap } from '../comms/OutageMinimap';

function fmtTime(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}:${String(d.getUTCSeconds()).padStart(2, '0')}`;
}

const PRI_TO_SEV: Record<string, 'flash' | 'immediate' | 'routine'> = {
  flash: 'flash',
  immediate: 'immediate',
  routine: 'routine',
};

function RadioLogFull() {
  const log = useStore((s) => s.radioLog);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (ref.current) ref.current.scrollTop = ref.current.scrollHeight;
  }, [log.length]);

  return (
    <section className="ops-panel glass-panel glass-panel--deep radio-log-full">
      <header className="ops-panel__title">
        TELSİZ LOG · {log.length}
        <SourceChip source="LIVE" />
      </header>
      <div className="radio-log-full__body" ref={ref}>
        {log.length === 0 && <div className="radio-log-full__empty">— sessiz —</div>}
        {log.map((m) => (
          <div
            key={`${m.ts}-${m.callsign}`}
            className="hud-data-cell hud-data-cell--hover"
            style={{
              display: 'grid',
              gridTemplateColumns: '14px 70px 90px 1fr',
              gap: 8,
              alignItems: 'baseline',
            }}
          >
            <SevGlyph severity={PRI_TO_SEV[m.priority] ?? 'routine'} />
            <span style={{ color: 'var(--amber)' }}>{fmtTime(m.ts)}</span>
            <span style={{ color: 'var(--bone)' }}>{m.callsign}</span>
            <span style={{ color: 'var(--bone-mute)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {m.text}
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

export function Haberlesme() {
  return (
    <div className="hud-pane haberlesme-tab">
      <RadioLogFull />
      <div className="haberlesme-tab__right">
        <EltList />
        <OutageMinimap />
      </div>
    </div>
  );
}
