/**
 * IBB Zaman Makinesi (Time Machine) dock — Phase 9 Leap Step 4.
 *
 * Embeds the IBB photogrammetric time-machine app at the currently-selected
 * entity coordinate. Hash-route shape `#/{lat}/{lng}/{zoom}` verified live
 * 2026-05-18. If embed fails, falls back to a new-tab link.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';

const DEFAULT_LNGLAT: [number, number] = [28.9772, 41.0086];
const TM_HOST = 'https://zamanmakinesi.ibb.gov.tr';
const DEFAULT_ZOOM = 15;
const FALLBACK_TIMEOUT_MS = 5000;

export function TimeMachineDock(): ReactNode {
  const dock = useStore((s) => s.dock['time-machine']);
  const closeDock = useStore((s) => s.closeDock);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const entities = useStore((s) => s.entities);
  const venues = useStore((s) => s.venues);
  const selectedVenueId = useStore((s) => s.selectedVenueId);
  const [fallback, setFallback] = useState(false);

  const [lng, lat] = resolveCoord(selectedEntityId, entities, selectedVenueId, venues);

  useEffect(() => {
    if (!dock.open || fallback) return undefined;
    const timer = window.setTimeout(() => setFallback(true), FALLBACK_TIMEOUT_MS);
    return () => window.clearTimeout(timer);
  }, [dock.open, fallback, lng, lat]);

  if (!dock.open) return null;
  const url = `${TM_HOST}/#/${lat}/${lng}/${DEFAULT_ZOOM}`;

  return (
    <DockPanel id="time-machine" title="Zaman Makinesi · IBB">
      <div className="time-machine-dock">
        {!fallback && (
          <iframe
            src={url}
            title="IBB Zaman Makinesi"
            onError={() => setFallback(true)}
          />
        )}
        {fallback && (
          <div className="time-machine-dock__fallback">
            <p>Embed failed. Open in new tab:</p>
            <a href={url} target="_blank" rel="noopener noreferrer">
              {url}
            </a>
            <button type="button" onClick={() => setFallback(false)}>
              RETRY EMBEDDED
            </button>
          </div>
        )}
        <div className="time-machine-dock__footer">
          <span>{`${lng.toFixed(4)}, ${lat.toFixed(4)} · z${DEFAULT_ZOOM}`}</span>
          <button type="button" onClick={() => closeDock('time-machine')}>
            KAPAT
          </button>
        </div>
      </div>
    </DockPanel>
  );
}

function resolveCoord(
  selEntityId: string | null,
  entities: ReturnType<typeof useStore.getState>['entities'],
  selVenueId: string | null,
  venues: ReturnType<typeof useStore.getState>['venues'],
): [number, number] {
  if (selEntityId) {
    const e = entities.get(selEntityId);
    if (e?.geom?.type === 'Point') {
      const c = e.geom.coordinates as [number, number];
      return [c[0], c[1]];
    }
  }
  if (selVenueId) {
    const v = venues.find((f) => f.properties.id === selVenueId);
    if (v) {
      const c = v.geometry.coordinates as [number, number];
      return [c[0], c[1]];
    }
  }
  return DEFAULT_LNGLAT;
}
