/**
 * Redundancy heatmap — Phase 9 Leap Step 2.
 *
 * Renders the per-cell cone-count grid from the coverage Worker as a
 * deck.gl BitmapLayer. Colormap: green (0-1) → amber (2-3) → red (4+).
 *
 * The grid is converted to an RGBA PNG data URL once and passed as the
 * BitmapLayer image source. ~256×256 cells = 65 KB PNG. Updates rarely
 * (only when the cone set changes).
 */
import { BitmapLayer } from '@deck.gl/layers';

export interface RedundancyGrid {
  cells: Uint8Array;
  rows: number;
  cols: number;
  originLngLat: [number, number];
  cellDegLng: number;
  cellDegLat: number;
}

export interface RedundancyLayerOpts {
  grid: RedundancyGrid;
  opacity?: number;
}

export function buildRedundancyLayer(opts: RedundancyLayerOpts): BitmapLayer | null {
  const { grid } = opts;
  if (grid.rows === 0 || grid.cols === 0) return null;
  const opacity = opts.opacity ?? 0.45;

  const imageData = gridToImageData(grid, opacity);
  if (!imageData) return null;

  const [originLng, originLat] = grid.originLngLat;
  const bounds: [number, number, number, number] = [
    originLng,
    originLat,
    originLng + grid.cellDegLng * grid.cols,
    originLat + grid.cellDegLat * grid.rows,
  ];

  return new BitmapLayer({
    id: 'fov-redundancy',
    bounds,
    image: imageData,
    pickable: false,
  });
}

function gridToImageData(grid: RedundancyGrid, opacity: number): ImageData | null {
  if (typeof OffscreenCanvas === 'undefined' && typeof document === 'undefined') return null;
  const { cells, rows, cols } = grid;
  const buf = new Uint8ClampedArray(rows * cols * 4);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      // Flip y so the image origin matches deck.gl's bitmap bounds convention.
      const srcIdx = (rows - 1 - r) * cols + c;
      const v = cells[srcIdx]!;
      const [red, green, blue, alpha] = redundancyColor(v, opacity);
      const dstIdx = (r * cols + c) * 4;
      buf[dstIdx] = red;
      buf[dstIdx + 1] = green;
      buf[dstIdx + 2] = blue;
      buf[dstIdx + 3] = alpha;
    }
  }
  return new ImageData(buf, cols, rows);
}

function redundancyColor(count: number, opacity: number): [number, number, number, number] {
  if (count === 0) return [0, 0, 0, 0];
  const a = Math.floor(255 * opacity);
  if (count === 1) return [16, 185, 129, a]; // emerald
  if (count === 2) return [132, 204, 22, a]; // lime
  if (count === 3) return [234, 179, 8, a]; // amber-400
  if (count === 4) return [249, 115, 22, a]; // orange-500
  return [220, 38, 38, a]; // red-600
}
