/**
 * <SevGlyph severity="flash" /> — six-glyph severity ladder, replaces
 * Unicode emoji severity indicators under the flat-tactical / no-emoji
 * doctrine. Spec: docs/SPATIAL-INTELLIGENCE-ULTRAPLAN.md §4.3.
 *
 *   ▲   FLASH        klaxon-red, klaxon pulse 880 ms
 *   ►   IMMEDIATE    amber
 *   ◆   PRIORITY     amber-dim
 *   ■   ROUTINE      bone
 *   ○   INFO         bone-mute
 *   ─   ABSENT       bone-faint  (expected-but-missing telemetry — absence signal)
 *
 * Geometric Unicode shapes are not emoji and stay rendered as letterforms in
 * a mono font (JetBrains Mono); they are safe under the no-emoji lint.
 */

import type { Severity } from '../types/entity';

const SHAPE_BY_SEVERITY: Record<Severity, string> = {
  flash: '▲', // BLACK UP-POINTING TRIANGLE
  immediate: '►', // BLACK RIGHT-POINTING POINTER
  priority: '◆', // BLACK DIAMOND
  routine: '■', // BLACK SQUARE
  info: '○', // WHITE CIRCLE
  absent: '─', // BOX DRAWINGS LIGHT HORIZONTAL
};

const COLOR_BY_SEVERITY: Record<Severity, string> = {
  flash: 'var(--klaxon)',
  immediate: 'var(--amber)',
  priority: 'var(--amber-edge)',
  routine: 'var(--bone)',
  info: 'var(--bone-mute)',
  absent: 'var(--bone-faint)',
};

const TITLE_BY_SEVERITY: Record<Severity, string> = {
  flash: 'FLASH · highest priority',
  immediate: 'IMMEDIATE',
  priority: 'PRIORITY',
  routine: 'ROUTINE',
  info: 'INFO',
  absent: 'ABSENT · expected-but-missing telemetry',
};

export interface SevGlyphProps {
  severity: Severity;
  /** When `true`, the FLASH glyph pulses. Off by default to avoid runaway
   *  motion on a list of 100 entries. */
  pulse?: boolean;
  className?: string;
}

export function SevGlyph({ severity, pulse = false, className }: SevGlyphProps) {
  const shape = SHAPE_BY_SEVERITY[severity];
  const color = COLOR_BY_SEVERITY[severity];
  return (
    <span
      className={className}
      title={TITLE_BY_SEVERITY[severity]}
      aria-label={TITLE_BY_SEVERITY[severity]}
      style={{
        display: 'inline-block',
        width: 12,
        textAlign: 'center',
        fontFamily: 'var(--font-mono)',
        fontSize: 11,
        color,
        animation:
          pulse && severity === 'flash'
            ? 'klaxon-pulse var(--motion-klaxon-ms) ease-in-out infinite'
            : undefined,
      }}
    >
      {shape}
    </span>
  );
}
