/**
 * Cell-tower outage minimap — provider × district heatmap.
 *
 * Mocked for now; real data would come from TT / Turkcell / Vodafone outage
 * APIs (none of which are public). The viz is a 39 × 3 grid: rows = İstanbul
 * districts (abbreviated), columns = providers, cell color = outage %.
 *
 * Absence-as-signal: clusters of high outage in adjacent districts mean
 * a cascading infrastructure failure, not just a per-tower fault.
 */

import { useMemo } from 'react';
import { SourceChip } from '../../lib/sourceTag';

const DISTRICTS = [
  'ADL', 'ARN', 'ATŞ', 'AVC', 'BAĞ', 'BAH', 'BAK', 'BAŞ', 'BAY', 'BEŞ',
  'BEY', 'BEYL', 'BÜK', 'ÇAT', 'ÇEK', 'EYÜ', 'ESN', 'EYP', 'FAT', 'GAZ',
  'GÜN', 'KAĞ', 'KAR', 'KAD', 'MAL', 'PEN', 'SAR', 'SİL', 'SUL', 'ŞİL',
  'ŞİŞ', 'SUT', 'TUZ', 'ÜMR', 'ÜSK', 'ZEY', 'KÜÇ', 'SNC', 'TAK',
];

const PROVIDERS = ['TT', 'TRC', 'VOD'];

function seededOutage(districtIdx: number, providerIdx: number): number {
  // Cluster outage around Avcılar / Beylikdüzü / Bakırköy (west) so the
  // cascading-failure pattern is visible. Otherwise low background noise.
  const cluster = [3, 6, 11].includes(districtIdx); // AVC, BAK, BEYL
  const base = cluster ? 35 : 6;
  const jitter = ((districtIdx * 7 + providerIdx * 17) % 11) - 5;
  return Math.max(0, base + jitter);
}

function colorFor(pct: number): string {
  if (pct >= 30) return 'var(--klaxon)';
  if (pct >= 15) return 'var(--amber)';
  if (pct >= 5) return 'var(--amber-edge)';
  return 'var(--bg-rule)';
}

export function OutageMinimap() {
  const grid = useMemo(() => {
    return DISTRICTS.map((d, i) => ({
      district: d,
      cells: PROVIDERS.map((p, j) => ({ provider: p, pct: seededOutage(i, j) })),
    }));
  }, []);

  const totalOutages = grid.flatMap((d) => d.cells).filter((c) => c.pct >= 15).length;

  return (
    <section className="ops-panel glass-panel glass-panel--deep outage-mini">
      <header className="ops-panel__title">
        HÜCRESEL · KESİNTİ HARİTASI · {totalOutages} ALARM
        <SourceChip source="SIM" />
      </header>
      <div className="outage-mini__grid">
        <div className="outage-mini__col-head">
          <span />
          {PROVIDERS.map((p) => (
            <span key={p} className="outage-mini__provider">
              {p}
            </span>
          ))}
        </div>
        <div className="outage-mini__body">
          {grid.map((row) => (
            <div key={row.district} className="outage-mini__row">
              <span className="outage-mini__district">{row.district}</span>
              {row.cells.map((cell, i) => (
                <span
                  key={i}
                  className="outage-mini__cell"
                  title={`${row.district} · ${cell.provider} · %${cell.pct}`}
                  style={{ background: colorFor(cell.pct) }}
                >
                  {cell.pct >= 15 ? cell.pct : ''}
                </span>
              ))}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
