/**
 * CoverageDock — dock slot 'coverage', title "Kapsama Analizi".
 *
 * Four buttons flip the GÖRÜ view mode and switch to the GÖRÜ tab so the map
 * view is showing when the mode changes. Below them, a PTZ-count readout.
 */
import { type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';
import type { GoruntuMode } from '../../store';

const MODES: ReadonlyArray<{ mode: GoruntuMode; label: string }> = [
  { mode: 'tiles', label: 'KAMERA DÖŞEME' },
  { mode: 'coverage', label: 'KAPSAMA' },
  { mode: 'blind-spots', label: 'KÖR NOKTA' },
  { mode: 'redundancy', label: 'YEDEKLİLİK' },
];

export function CoverageDock(): ReactNode {
  const dock = useStore((s) => s.dock['coverage']);
  const goruntuMode = useStore((s) => s.goruntuMode);
  const setGoruntuMode = useStore((s) => s.setGoruntuMode);
  const setActiveTab = useStore((s) => s.setActiveTab);

  if (!dock.open) return null;

  return (
    <DockPanel id="coverage" title="Kapsama Analizi">
      <div className="coverage-dock">
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {MODES.map(({ mode, label }) => (
            <button
              key={mode}
              type="button"
              onClick={() => {
                setGoruntuMode(mode);
                setActiveTab('goruntuleme');
              }}
              style={{
                fontFamily: 'var(--font-mono)',
                fontSize: 11,
                textAlign: 'left',
                background: goruntuMode === mode ? 'var(--accent)' : 'var(--bg-panel-soft)',
                color: goruntuMode === mode ? 'var(--bg-void)' : 'var(--ink-mid)',
                border: '1px solid var(--bg-rule)',
                padding: '4px 10px',
                cursor: 'pointer',
              }}
            >
              {label}
            </button>
          ))}
        </div>
        <div style={{ marginTop: 10, fontFamily: 'var(--font-mono)', fontSize: 11, color: 'var(--ink-mid)' }}>
          632 PTZ
          <SourceChip source="IBB" />
        </div>
      </div>
    </DockPanel>
  );
}
