/**
 * Deterministic offline SITREP template provider (v10 P6 / F1).
 *
 * Renders a three-section Turkish briefing from SitrepInputs using only the
 * input data (and input.nowMs for time text). No network, no clock reads —
 * the same input always yields the same output, so it snapshot-tests cleanly.
 */
import type { Entity } from '../../types/entity';
import type { SitrepInputs } from './sitrepPrompt';
import type { SitrepProvider, SitrepResult } from './providers';

const SEV_ORDER: Record<Entity['severity'], number> = {
  flash: 0,
  immediate: 1,
  priority: 2,
  routine: 3,
  info: 4,
  absent: 5,
};

function dtg(nowMs: number): string {
  return new Date(nowMs).toISOString().replace('T', ' ').slice(0, 16) + 'Z';
}

function renderTemplate(input: SitrepInputs): string {
  const { kpis, nowMs } = input;
  const lines: string[] = [];

  lines.push(`# AKOM SITREP · ${dtg(nowMs)}`);
  lines.push('');
  lines.push('## ÖZET');
  lines.push(
    `${kpis.units} birim sahada, ${kpis.incidents} aktif olay. ` +
      `Ortalama sevk süresi ${kpis.etaAvgSec.toFixed(0)} sn. ` +
      `Boş yatak ${kpis.bedsAvailable}. Yol kapalı %${kpis.roadsBlockedPct.toFixed(1)}. ` +
      `Hava: ${kpis.wxLabel}.`,
  );
  lines.push('');

  lines.push('## KRİTİK');
  const critical = Array.from(input.entities.values())
    .filter((e) => e.severity === 'flash' || e.severity === 'immediate')
    .sort((a, b) => SEV_ORDER[a.severity] - SEV_ORDER[b.severity] || a.id.localeCompare(b.id))
    .slice(0, 10);
  if (critical.length === 0) {
    lines.push('- Kritik önem taşıyan gözlem yok.');
  } else {
    for (const e of critical) {
      const headline = String(e.attrs.headline ?? e.attrs.category ?? e.kind);
      const district = String(e.attrs.district ?? '—');
      lines.push(`- [${e.severity.toUpperCase()}] ${headline} · ${district} · ${e.source}`);
    }
  }
  lines.push('');

  lines.push('## EĞİLİM');
  const total = input.entities.size;
  const flash = Array.from(input.entities.values()).filter((e) => e.severity === 'flash').length;
  lines.push(`Toplam ${total} izlenen varlık, ${flash} FLASH önem. ${critical.length} kritik kalem raporlandı.`);

  return lines.join('\n');
}

export const templateProvider: SitrepProvider = {
  mode: 'template',
  label: 'ŞABLON',
  available: () => true,
  generate: (input: SitrepInputs): Promise<SitrepResult> =>
    Promise.resolve({ text: renderTemplate(input), modelLabel: 'ŞABLON', network: 'YOK' }),
};
