/**
 * ScenarioDock — dock slot 'scenario', title "Senaryo · Mw 7.5 Marmara".
 *
 * Controls the deterministic earthquake scenario: phase + T+ clock readout,
 * BAŞLAT / DURAKLAT / SIFIRLA, speed (1x/4x/16x), and a top-5 district damage
 * table (EST-chipped). The engine itself lives in App; this dock only drives
 * the scenario store slice.
 */
import { type ReactNode } from 'react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { SourceChip } from '../../lib/sourceTag';

const PHASES: ReadonlyArray<[number, string]> = [
  [300_000, 'KARARLI'],
  [150_000, 'KASKAT ARIZA'],
  [90_000, 'SEVK DALGASI'],
  [30_000, 'TALEP ARTIŞI'],
  [5_000, 'HASAR DEĞERLENDİRME'],
  [0, 'DEPREM'],
];

function phaseLabel(simMs: number): string {
  for (const [t, label] of PHASES) if (simMs >= t) return label;
  return 'BEKLEMEDE';
}

function clock(simMs: number): string {
  const s = Math.floor(simMs / 1000);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `T+${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
}

export function ScenarioDock(): ReactNode {
  const dock = useStore((s) => s.dock['scenario']);
  const scenario = useStore((s) => s.scenario);
  const setScenario = useStore((s) => s.setScenario);
  const setScenarioDamage = useStore((s) => s.setScenarioDamage);
  const setOsintSurge = useStore((s) => s.setOsintSurge);
  const damage = useStore((s) => s.scenarioDamage);

  if (!dock.open) return null;

  const reset = () => {
    setScenario({ running: false, simMs: 0 });
    setScenarioDamage([]);
    setOsintSurge(1);
  };

  const top5 = [...damage].sort((a, b) => b.damage - a.damage).slice(0, 5);

  const btn = (label: string, onClick: () => void, active = false): ReactNode => (
    <button
      type="button"
      onClick={onClick}
      style={{
        fontFamily: 'var(--font-mono)',
        fontSize: 11,
        background: active ? 'var(--accent)' : 'var(--bg-panel-soft)',
        color: active ? 'var(--bg-void)' : 'var(--ink-mid)',
        border: '1px solid var(--bg-rule)',
        padding: '4px 10px',
        cursor: 'pointer',
      }}
    >
      {label}
    </button>
  );

  return (
    <DockPanel id="scenario" title="Senaryo · Mw 7.5 Marmara">
      <div className="scenario-dock" style={{ fontFamily: 'var(--font-mono)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, color: 'var(--ink-strong)' }}>
          <span>SAFHA · {phaseLabel(scenario.simMs)}</span>
          <span>{clock(scenario.simMs)}</span>
        </div>
        <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
          {btn('BAŞLAT', () => setScenario({ running: true }), scenario.running)}
          {btn('DURAKLAT', () => setScenario({ running: false }), !scenario.running)}
          {btn('SIFIRLA', reset)}
        </div>
        <div style={{ display: 'flex', gap: 6, marginTop: 6 }}>
          {btn('1x', () => setScenario({ speed: 1 }), scenario.speed === 1)}
          {btn('4x', () => setScenario({ speed: 4 }), scenario.speed === 4)}
          {btn('16x', () => setScenario({ speed: 16 }), scenario.speed === 16)}
        </div>
        <div style={{ marginTop: 10, fontSize: 11, color: 'var(--ink-mid)' }}>
          EN AĞIR HASAR
          <SourceChip source="EST" />
        </div>
        <table style={{ width: '100%', marginTop: 4, fontSize: 11, color: 'var(--ink-strong)' }}>
          <tbody>
            {top5.length === 0 ? (
              <tr>
                <td style={{ color: 'var(--ink-mute)' }}>Henüz hasar verisi yok</td>
              </tr>
            ) : (
              top5.map((d) => (
                <tr key={d.name}>
                  <td>{d.name}</td>
                  <td style={{ textAlign: 'right' }}>%{Math.round(d.damage * 100)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </DockPanel>
  );
}
