/**
 * FeedInspectorDock — multi-sensor feed inspector (Phase 9-B dock slot
 * 'feed-inspector', wired here for the first time).
 *
 * Resolves the current selection to one sensor and renders its readout:
 *   - selectedEntityId → flight (ADS-B) / vessel (AIS·SIM) / OSINT observation
 *   - selectedCameraId → İBB CCTV (SIM preview via CctvFeed)
 * Entity selection takes priority because OSINT cards and the C2 board drive
 * the unified entity store; a plain camera-dot click is the fallback.
 *
 * Reference shape: claude_akom_design/feed-inspector.jsx (civilianized,
 * ported to the pristine token skin).
 */
import { type ReactNode } from 'react';
import { Plane, Radio, Ship, Waypoints } from 'lucide-react';
import { DockPanel } from './DockPanel';
import { useStore } from '../../store';
import { findCameraById } from '../../feeds/ibb-mobese';
import { CctvFeed } from '../cameras/CctvFeed';
import { SourceChip } from '../../lib/sourceTag';
import { SevGlyph } from '../../lib/sevGlyph';
import { tickElapsed } from '../../lib/time';
import type { Entity } from '../../types/entity';

export function FeedInspectorDock(): ReactNode {
  const dock = useStore((s) => s.dock['feed-inspector']);
  const selectedCameraId = useStore((s) => s.selectedCameraId);
  const selectedEntityId = useStore((s) => s.selectedEntityId);
  const entities = useStore((s) => s.entities);

  if (!dock.open) return null;

  const entity = selectedEntityId ? entities.get(selectedEntityId) : undefined;
  const camera = selectedCameraId ? findCameraById(selectedCameraId) : undefined;

  return (
    <DockPanel id="feed-inspector" title="Besleme İnceleme">
      <div className="fi">
        {entity ? (
          <EntityBody entity={entity} />
        ) : camera ? (
          <CctvBody camera={camera} />
        ) : (
          <div className="fi__empty">
            <Waypoints size={16} />
            <span>Sensör seçilmedi</span>
            <span className="fi__empty-sub">
              Haritada bir kamera/uçak veya OSINT kartı seçin.
            </span>
          </div>
        )}
      </div>
    </DockPanel>
  );
}

function CctvBody({ camera }: { camera: ReturnType<typeof findCameraById> }) {
  if (!camera) return null;
  return (
    <>
      <FiHead icon={<Radio size={12} />} title={`CCTV · ${camera.name}`} source="SIM" />
      <CctvFeed camera={camera} />
      <dl className="fi-meta">
        <MetaRow k="Konum" v={camera.name} />
        <MetaRow k="İlçe" v={camera.district} />
        <MetaRow k="Tip" v={camera.type} />
        <MetaRow k="Codec" v={camera.codec} />
        <MetaRow k="Kaynak" v={camera.src} />
      </dl>
    </>
  );
}

function EntityBody({ entity }: { entity: Entity }) {
  switch (entity.kind) {
    case 'flight':
      return <AircraftReadout entity={entity} />;
    case 'vessel':
      return <VesselReadout entity={entity} />;
    case 'camera': {
      const cam = findCameraById(String(entity.attrs.id ?? ''));
      return cam ? <CctvBody camera={cam} /> : <ObservationReadout entity={entity} />;
    }
    default:
      return <ObservationReadout entity={entity} />;
  }
}

function AircraftReadout({ entity }: { entity: Entity }) {
  const a = entity.attrs;
  const callsign = String(a.callsign ?? '').trim() || '—';
  const heading = Number(a.heading ?? 0);
  const altM = Number(a.alt_m ?? 0);
  const velMs = Number(a.velocity_ms ?? 0);
  const isMil = a.isMilitary === true;
  const cls = isMil
    ? 'ASKERİ'
    : callsign.startsWith('HEMS') || callsign.startsWith('AMB')
      ? 'HEMS'
      : 'SİVİL';
  const fl = Math.round((altM * 3.28084) / 100);
  const kt = Math.round(velMs * 1.94384);

  return (
    <>
      <FiHead
        icon={<Plane size={12} />}
        title={`HAVA · ${callsign}`}
        source={entity.source}
        sim={entity.source === 'SIM'}
      />
      <div className="fi-track">
        <svg viewBox="-20 -20 40 40" className="fi-track__svg" aria-hidden="true">
          <g transform={`rotate(${heading})`}>
            <polygon
              points="14,0 -8,8 -2,0 -8,-8"
              fill={isMil ? 'var(--klaxon)' : 'var(--accent)'}
            />
          </g>
        </svg>
        <span className="fi-track__tag">{cls}</span>
      </div>
      <dl className="fi-meta">
        <MetaRow k="Çağrı" v={callsign} />
        <MetaRow k="Sınıf" v={cls} />
        <MetaRow k="İrtifa" v={`${Math.round(altM)} m · FL${fl}`} />
        <MetaRow k="Hız" v={`${kt} kt`} />
        <MetaRow k="Yön" v={`${Math.round(heading)}°`} />
        <MetaRow k="Menşe" v={String(a.origin ?? '—')} />
      </dl>
    </>
  );
}

function VesselReadout({ entity }: { entity: Entity }) {
  const a = entity.attrs;
  const heading = Number(a.heading ?? 0);
  return (
    <>
      <FiHead icon={<Ship size={12} />} title={`DENİZ · ${String(a.name ?? 'Bilinmiyor')}`} source="AIS" sim />
      <div className="fi-track">
        <svg viewBox="-20 -20 40 40" className="fi-track__svg" aria-hidden="true">
          <g transform={`rotate(${heading})`}>
            <polygon points="14,0 -8,7 -8,-7" fill="var(--accent)" />
          </g>
        </svg>
        <span className="fi-track__tag">AIS · SİM</span>
      </div>
      <dl className="fi-meta">
        <MetaRow k="Ad" v={String(a.name ?? '—')} />
        <MetaRow k="Tip" v={String(a.kind ?? '—')} />
        <MetaRow k="Yön" v={`${Math.round(heading)}°`} />
        <MetaRow k="Not" v="Canlı AIS beslemesi yok" />
      </dl>
    </>
  );
}

const CATEGORY_TR: Record<string, string> = {
  collapse: 'Bina Çöküntüsü',
  fire: 'Yangın',
  gasleak: 'Doğalgaz Kaçağı',
  trapped: 'Enkaz Altında',
  flood: 'Su Baskını',
  earthquake: 'Deprem',
};

function ObservationReadout({ entity }: { entity: Entity }) {
  const a = entity.attrs;
  const category = String(a.category ?? a.type ?? entity.kind);
  const headline = String(a.headline ?? CATEGORY_TR[category] ?? category);
  const sourceTag = String(a.sourceTag ?? entity.source);
  const district = String(a.district ?? '—');

  return (
    <>
      <FiHead icon={<Radio size={12} />} title={`ETKİ · ${headline}`} source={entity.source} />
      <dl className="fi-meta">
        <MetaRow
          k="Önem"
          v={
            <>
              <SevGlyph severity={entity.severity} /> {entity.severity.toUpperCase()}
            </>
          }
        />
        <MetaRow k="Tür" v={CATEGORY_TR[category] ?? category} />
        <MetaRow k="İlçe" v={district} />
        <MetaRow k="Kaynak" v={sourceTag} />
        <MetaRow k="Güven" v={`%${Math.round(entity.confidence * 100)}`} />
        <MetaRow k="İlk Görülme" v={tickElapsed(entity.firstSeen)} />
      </dl>
    </>
  );
}

function FiHead({
  icon,
  title,
  source,
  sim = false,
}: {
  icon: ReactNode;
  title: string;
  source: Parameters<typeof SourceChip>[0]['source'];
  sim?: boolean;
}) {
  return (
    <div className="fi-head">
      <span className="fi-head__icon">{icon}</span>
      <span className="fi-head__title">{title}</span>
      <span className="fi-head__src">
        <SourceChip source={source} />
        {sim && source !== 'SIM' && <SourceChip source="SIM" />}
      </span>
    </div>
  );
}

function MetaRow({ k, v }: { k: string; v: ReactNode }) {
  return (
    <div className="fi-meta__row">
      <dt>{k}</dt>
      <dd>{v}</dd>
    </div>
  );
}
