/**
 * Unit hover preview — shows unit info when hovering a patrol dot on the map.
 *
 * Reads `hoveredUnit` from the store, looks up the unit snapshot and C2 pairing
 * state, then renders a compact tooltip card.
 */
import { useMemo } from 'react';
import { useStore } from '../../store';
import { useC2 } from '../../store/c2';
import type { UnitState } from '../../types/venue';

const CARD_W = 240;
const OFFSET = 16;

/** Simple MIL-STD type symbol mapping from unit type string. */
const MIL_SYMBOL: Record<string, string> = {
  AMB: '⚕',
  POL: '♜',
  ITFK: '♨',
  SAR: '♞',
  UAV: '✈',
  HEMS: '✚',
  UMKE: '✙',
  TEDAS: '⚡',
  AFAD: '⬟',
  K9: '◇',
};

function milSymbol(type: string): string {
  return MIL_SYMBOL[type] ?? '●';
}

const STATUS_LABEL: Record<UnitState['status'], string> = {
  patrol: 'DEVRİYE',
  enroute: 'YOLDA',
  onscene: 'OLAY YERİNDE',
  rtb: 'DÖNÜŞ',
  standby: 'BEKLEMEDE',
};

const MODALITY_LABEL: Record<UnitState['modality'], string> = {
  ground: 'KARA',
  heli: 'HELİ',
  fixed: 'SABİT',
  naval: 'DENİZ',
};

export function UnitHoverPreview(): React.ReactNode {
  const hovered = useStore((s) => s.hoveredUnit);
  const cards = useC2((s) => s.cards);

  // Read static units (UnitFeature[]) from the store as fallback
  // when the live snapshot is unavailable.
  const units = useStore((s) => s.units);

  // Read the live snapshot from the global ref (set by App on every patrol tick).
  // Re-evaluated whenever the hover target changes so we get the freshest state.
  const latestSnapshot = useMemo(() => {
    void hovered; // trigger recompute when hover changes
    const win = window as unknown as { __akomSnapshot?: UnitState[] };
    return win.__akomSnapshot ?? [];
  }, [hovered]);

  const unit = useMemo(() => {
    if (!hovered) return null;
    const snap = latestSnapshot;
    // Prefer live snapshot, fall back to static unit features.
    if (snap.length > 0) {
      return snap.find((u) => u.id === hovered.unitId) ?? null;
    }
    const uf = units.find((u) => u.properties.id === hovered.unitId);
    if (!uf) return null;
    return {
      id: uf.properties.id,
      callsign: uf.properties.callsign,
      modality: uf.properties.modality,
      type: uf.properties.type,
      status: uf.properties.status,
      lon: (uf.geometry.coordinates as [number, number])[0],
      lat: (uf.geometry.coordinates as [number, number])[1],
      heading: uf.properties.heading,
      speed: uf.properties.speed,
    } satisfies UnitState;
  }, [hovered, latestSnapshot, units]);

  // Find C2 card paired with this unit.
  const pairedCard = useMemo(() => {
    if (!hovered) return null;
    return cards.find((c) => c.pairedUnitId === hovered.unitId) ?? null;
  }, [hovered, cards]);

  const pos = useMemo(() => {
    if (!hovered) return null;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let x = hovered.x + OFFSET;
    let y = hovered.y + OFFSET;
    if (x + CARD_W > vw) x = hovered.x - CARD_W - OFFSET;
    if (y + 120 > vh) y = vh - 120 - 8;
    if (y < 8) y = 8;
    return { x: Math.max(8, x), y };
  }, [hovered]);

  const visible = !!(hovered && unit && pos);

  return (
    <div
      role="tooltip"
      aria-hidden={!visible}
      style={{
        position: 'fixed',
        left: 0,
        top: 0,
        width: CARD_W,
        zIndex: 1400,
        pointerEvents: 'none',
        transform: pos
          ? `translate(${pos.x}px, ${pos.y}px)`
          : 'translate(-9999px,-9999px)',
        opacity: visible ? 1 : 0,
        transition: 'opacity 90ms ease-out',
        willChange: 'transform, opacity',
        background: 'rgba(8, 13, 22, 0.92)',
        border: '1px solid rgba(56, 189, 248, 0.55)',
        borderRadius: 6,
        boxShadow: '0 8px 28px rgba(0,0,0,0.55)',
        overflow: 'hidden',
        fontFamily: 'var(--font-mono, monospace)',
      }}
    >
      {unit && (
        <>
          {/* Header */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '7px 10px',
              borderBottom: '1px solid rgba(56,189,248,0.22)',
              background: 'rgba(56,189,248,0.12)',
            }}
          >
            <span style={{ fontSize: 18, lineHeight: 1 }}>
              {milSymbol(unit.type)}
            </span>
            <span
              style={{
                fontSize: 12,
                fontWeight: 600,
                color: '#e2e8f0',
                letterSpacing: '0.05em',
              }}
            >
              {unit.callsign}
            </span>
            <span style={{ flex: 1 }} />
            <span style={{ color: '#94a3b8', fontSize: 10 }}>{unit.id}</span>
          </div>
          {/* Body */}
          <div
            style={{
              padding: '6px 10px',
              fontSize: 10.5,
              color: '#cbd5e1',
              display: 'flex',
              flexDirection: 'column',
              gap: 3,
            }}
          >
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
              }}
            >
              <span style={{ color: '#94a3b8' }}>Tip</span>
              <span>
                {unit.type} · {MODALITY_LABEL[unit.modality]}
              </span>
            </div>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
              }}
            >
              <span style={{ color: '#94a3b8' }}>Durum</span>
              <span
                style={{
                  color:
                    unit.status === 'enroute'
                      ? '#fbbf24'
                      : unit.status === 'onscene'
                        ? '#ef4444'
                        : '#94a3b8',
                }}
              >
                {STATUS_LABEL[unit.status]}
              </span>
            </div>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
              }}
            >
              <span style={{ color: '#94a3b8' }}>Hız</span>
              <span>{unit.speed} km/s</span>
            </div>
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
              }}
            >
              <span style={{ color: '#94a3b8' }}>İstikamet</span>
              <span>{unit.heading.toFixed(0)}°</span>
            </div>
            {pairedCard && (
              <>
                <div
                  style={{
                    marginTop: 4,
                    borderTop: '1px solid rgba(56,189,248,0.18)',
                    paddingTop: 4,
                  }}
                />
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                  }}
                >
                  <span style={{ color: '#94a3b8' }}>Görev</span>
                  <span style={{ color: '#38bdf8' }}>{pairedCard.type}</span>
                </div>
                {pairedCard.location && (
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                    }}
                  >
                    <span style={{ color: '#94a3b8' }}>Hedef</span>
                    <span>
                      {pairedCard.location.district ??
                        `${pairedCard.location.lat.toFixed(3)}, ${pairedCard.location.lng.toFixed(3)}`}
                    </span>
                  </div>
                )}
              </>
            )}
          </div>
        </>
      )}
    </div>
  );
}
