/**
 * Scenario time bar — sits directly below the OPS map toolbar.
 *
 * A horizontal mission clock for the deterministic Mw 7.5 Marmara scenario:
 *  • A pre-event T-minus countdown (10 s hold) before the quake fires.
 *  • A T-plus elapsed clock + phase label once the scenario is running.
 *  • Transport controls (start / pause / resume / reset) and a speed selector
 *    (1× / 4× / 16×) that drive the same `scenario` store slice the engine in
 *    App reads on its 500 ms tick.
 *
 * The countdown is purely presentational — it holds, then flips `running` true
 * so the existing engine fires the quake at T+0.
 */
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Play, Pause, RotateCcw, Gauge } from 'lucide-react';
import { useStore } from '../store';

/** Scenario phase thresholds (ms since quake) → label. Mirrors ScenarioDock. */
const PHASES: ReadonlyArray<[number, string]> = [
  [300_000, 'KARARLI'],
  [150_000, 'KASKAT ARIZA'],
  [90_000, 'SEVK DALGASI'],
  [30_000, 'TALEP ARTIŞI'],
  [5_000, 'HASAR DEĞERLENDİRME'],
  [0, 'DEPREM'],
];

const FULL_MS = 300_000; // progress track spans T+0 → T+5:00
const COUNTDOWN_S = 10;

function phaseLabel(simMs: number): string {
  for (const [t, label] of PHASES) if (simMs >= t) return label;
  return 'BEKLEMEDE';
}

function mmss(totalSec: number): string {
  const s = Math.max(0, Math.floor(totalSec));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

export function ScenarioTimeBar(): ReactNode {
  const scenario = useStore((s) => s.scenario);
  const setScenario = useStore((s) => s.setScenario);
  const setScenarioDamage = useStore((s) => s.setScenarioDamage);
  const setOsintSurge = useStore((s) => s.setOsintSurge);

  // Pre-event countdown (seconds remaining); null when not arming.
  const [countdown, setCountdown] = useState<number | null>(null);
  const tickRef = useRef(0);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown <= 0) {
      setCountdown(null);
      setScenario({ running: true });
      return;
    }
    tickRef.current = window.setTimeout(() => setCountdown((c) => (c === null ? null : c - 1)), 1000);
    return () => window.clearTimeout(tickRef.current);
  }, [countdown, setScenario]);

  const arming = countdown !== null;
  const running = scenario.running;
  const elapsed = scenario.simMs / 1000;

  // Readout: T-minus while arming, T-plus once the clock is live.
  const readout = arming ? `T-${mmss(countdown ?? 0)}` : `T+${mmss(elapsed)}`;
  const phase = arming ? 'GERİ SAYIM' : phaseLabel(scenario.simMs);

  // Progress: fills backwards during countdown, forwards while running.
  const progress = arming
    ? 1 - (countdown ?? 0) / COUNTDOWN_S
    : Math.min(1, scenario.simMs / FULL_MS);

  const reset = () => {
    window.clearTimeout(tickRef.current);
    setCountdown(null);
    setScenario({ running: false, simMs: 0 });
    setScenarioDamage([]);
    setOsintSurge(1);
  };

  const onPrimary = () => {
    if (arming) {
      // Cancel the countdown.
      window.clearTimeout(tickRef.current);
      setCountdown(null);
      return;
    }
    if (running) {
      setScenario({ running: false });
      return;
    }
    // Paused mid-run → resume immediately; fresh → arm the countdown.
    if (scenario.simMs > 0) setScenario({ running: true });
    else setCountdown(COUNTDOWN_S);
  };

  const primaryLabel = arming ? 'İPTAL' : running ? 'DURAKLAT' : scenario.simMs > 0 ? 'DEVAM' : 'BAŞLAT';
  const live = arming || running;

  return (
    <div className="scenario-timebar glass-panel glass-panel--float" data-testid="scenario-timebar">
      <button
        type="button"
        className="scenario-timebar__play"
        onClick={onPrimary}
        data-testid="scenario-play"
        aria-label={primaryLabel}
      >
        {running || arming ? <Pause size={13} /> : <Play size={13} />}
        <span>{primaryLabel}</span>
      </button>

      <button
        type="button"
        className="scenario-timebar__reset"
        onClick={reset}
        aria-label="Senaryoyu sıfırla"
        title="Sıfırla"
      >
        <RotateCcw size={12} />
      </button>

      <div className="scenario-timebar__clock-wrap">
        <span
          className={`scenario-timebar__clock${live ? ' is-live' : ''}${arming ? ' is-arming' : ''}`}
          data-testid="scenario-clock"
        >
          {readout}
        </span>
        <span className="scenario-timebar__phase">{phase}</span>
        <span className="scenario-timebar__track" aria-hidden="true">
          <span
            className={`scenario-timebar__fill${arming ? ' is-arming' : ''}`}
            style={{ width: `${Math.round(progress * 100)}%` }}
          />
        </span>
      </div>

      <div className="scenario-timebar__speed" role="group" aria-label="Senaryo hızı">
        <Gauge size={11} className="scenario-timebar__speed-icon" />
        {([1, 4, 16] as const).map((sp) => (
          <button
            key={sp}
            type="button"
            className={`scenario-timebar__speed-btn${scenario.speed === sp ? ' is-active' : ''}`}
            onClick={() => setScenario({ speed: sp })}
            aria-pressed={scenario.speed === sp}
          >
            {sp}×
          </button>
        ))}
      </div>
    </div>
  );
}
