/**
 * Satellite hover preview — shows satellite info when hovering a satellite
 * icon on the globe. Reads `hoveredSat` from the store and renders a compact
 * tooltip card with the NORAD id, category, and name.
 */
import { useMemo } from 'react';
import { useStore } from '../../store';
import { SAT_CATEGORIES } from '../../satellites/symbology';

const CARD_W = 220;
const OFFSET = 16;

export function SatHoverPreview(): React.ReactNode {
  const hovered = useStore((s) => s.hoveredSat);

  // We read the satellite data from a module-level reference set by GlobeHost
  const satData = useMemo(() => {
    const win = window as unknown as { __akomSatData?: Array<{ noradId: number; cat: number; position: [number, number, number] }> };
    return win.__akomSatData ?? [];
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hovered]);

  const sat = useMemo(() => {
    if (!hovered) return null;
    return satData.find((s) => s.noradId === hovered.noradId) ?? null;
  }, [hovered, satData]);

  const pos = useMemo(() => {
    if (!hovered) return null;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let x = hovered.x + OFFSET;
    let y = hovered.y + OFFSET;
    if (x + CARD_W > vw) x = hovered.x - CARD_W - OFFSET;
    if (y + 100 > vh) y = vh - 100 - 8;
    if (y < 8) y = 8;
    return { x: Math.max(8, x), y };
  }, [hovered]);

  const visible = !!(hovered && pos);

  const catSpec = sat ? SAT_CATEGORIES[sat.cat] : undefined;
  const catColor = catSpec?.color ?? '#888';
  const catName = catSpec?.name ?? `Kategori ${sat?.cat ?? ''}`;

  return (
    <div
      role="tooltip"
      aria-hidden={!visible}
      data-testid="sat-hover-preview"
      style={{
        position: 'fixed',
        left: 0,
        top: 0,
        width: CARD_W,
        zIndex: 1400,
        pointerEvents: 'none',
        transform: pos ? `translate(${pos.x}px, ${pos.y}px)` : 'translate(-9999px,-9999px)',
        opacity: visible ? 1 : 0,
        transition: 'opacity 90ms ease-out',
        willChange: 'transform, opacity',
        background: 'rgba(8, 13, 22, 0.92)',
        border: '1px solid rgba(56, 189, 248, 0.55)',
        borderRadius: 6,
        boxShadow: '0 8px 28px rgba(0,0,0,0.55)',
        overflow: 'hidden',
        fontFamily: 'var(--font-mono, monospace)',
      }}
    >
      {sat && (
        <>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              padding: '7px 10px',
              borderBottom: '1px solid rgba(56,189,248,0.22)',
              background: 'rgba(56,189,248,0.12)',
            }}
          >
            <span
              style={{
                width: 10,
                height: 10,
                borderRadius: '50%',
                background: catColor,
                flex: '0 0 auto',
              }}
            />
            <span
              style={{
                fontSize: 12,
                fontWeight: 600,
                color: '#e2e8f0',
                letterSpacing: '0.05em',
              }}
            >
              SAT #{sat.noradId}
            </span>
          </div>
          <div
            style={{
              padding: '6px 10px',
              fontSize: 10.5,
              color: '#cbd5e1',
              display: 'flex',
              flexDirection: 'column',
              gap: 3,
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>NORAD</span>
              <span>{sat.noradId}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>Kategori</span>
              <span style={{ color: catColor }}>{catName}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>İrtifa</span>
              <span>{sat.position[2].toFixed(0)} km</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ color: '#94a3b8' }}>Konum</span>
              <span>{sat.position[1].toFixed(2)}°, {sat.position[0].toFixed(2)}°</span>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
